def _candidate_spans_from_assignment(assignment: dict[str, object]) -> tuple[TimingTokenSpan, ...]:
    raw_spans = assignment.get("ctc_token_spans")
    if not isinstance(raw_spans, list):
        return ()
    spans: list[TimingTokenSpan] = []
    for raw in raw_spans:
        if not isinstance(raw, dict):
            continue
        try:
            start = float(raw.get("start"))
            end = float(raw.get("end"))
            score = _finite_unit_confidence(raw.get("score", 0.0))
        except (TypeError, ValueError):
            continue
        if not (math.isfinite(start) and math.isfinite(end) and end >= start):
            continue
        spans.append(TimingTokenSpan(start, end, score, str(raw.get("char") or raw.get("token") or "")))
    return tuple(spans)


def _nearest_local_maximum(
    features: AudioFeatures,
    center: float,
    radius: float,
) -> tuple[float, float, float] | None:
    if features.onset_strength.size == 0 or features.frame_times.size == 0:
        return None
    mask = (features.frame_times >= center - radius) & (features.frame_times <= center + radius)
    indices = np.flatnonzero(mask)
    if indices.size == 0:
        return None
    best_index = int(indices[np.argmax(features.onset_strength[indices])])
    strength = float(features.onset_strength[best_index])
    context = np.flatnonzero(
        (features.frame_times >= center - 0.80) & (features.frame_times <= center + 0.80)
    )
    baseline = float(np.median(features.onset_strength[context])) if context.size else 0.0
    return float(features.frame_times[best_index]), strength, strength - baseline



def _strong_vocal_onset_near(
    features: AudioFeatures | None,
    center: float,
) -> tuple[float, float, float] | None:
    """Return the existing production-grade vocal onset observation near a time."""
    if features is None or not math.isfinite(center):
        return None
    peak = _nearest_local_maximum(features, center, VOCAL_ONSET_CONFIRM_RADIUS_SECONDS)
    if peak is None:
        return None
    peak_time, strength, prominence = peak
    if (
        strength < VOCAL_ONSET_CONFIRM_MIN_STRENGTH
        or prominence < VOCAL_ONSET_CONFIRM_MIN_PROMINENCE
    ):
        return None
    return peak_time, strength, prominence


def _vocal_activity_reentry_for_time(
    features: AudioFeatures,
    current_time: float,
) -> dict[str, float | int] | None:
    """Return a conservative isolated-vocal activity re-entry near a boundary.

    ``analyze_audio`` merges activity separated by <=450 ms, so a surviving
    segment boundary is already evidence of a substantial non-vocal interval.
    The detector never moves a timestamp: it only certifies the existing CTC
    boundary when the isolated vocal stem independently re-enters there.
    """
    if not features.segments:
        return None
    matches: list[dict[str, float | int]] = []
    for segment_index, (segment_start, segment_end) in enumerate(features.segments):
        if abs(float(segment_start) - float(current_time)) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS:
            continue
        previous_end = (
            float(features.segments[segment_index - 1][1])
            if segment_index > 0
            else 0.0
        )
        gap = float(segment_start) - previous_end
        if gap + HOP_SECONDS * 0.51 < VOCAL_ACTIVITY_REENTRY_MIN_GAP_SECONDS:
            continue
        matches.append({
            "segment_index": segment_index,
            "segment_start": float(segment_start),
            "segment_end": float(segment_end),
            "previous_segment_end": previous_end,
            "gap_seconds": gap,
            "distance_seconds": abs(float(segment_start) - float(current_time)),
        })
    if not matches:
        return None
    return min(
        matches,
        key=lambda row: (
            float(row["distance_seconds"]),
            -float(row["gap_seconds"]),
            int(row["segment_index"]),
        ),
    )


def apply_vocal_onset_confirmation_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
    *,
    features: AudioFeatures | None = None,
) -> list[dict[str, object]]:
    """Confirm an existing coherent CTC onset with independent vocal acoustics.

    This producer never moves a timestamp.  It only publishes a challenger for
    the exact current timestamp when the current full-line CTC path is already
    internally coherent and a strong, locally-prominent vocal onset is bound to
    the written boundary.  It therefore resolves ownership uncertainty without
    converting a weak or fractured CTC path into trusted timing.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    if features is None:
        try:
            features = analyze_vocal_onsets(alignment_audio_path, duration)
        except LrcError:
            return []
    audio_revision = hashlib.sha256(Path(alignment_audio_path).read_bytes()).hexdigest()
    generated: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        spans = _candidate_spans_from_assignment(assignment)
        if len(spans) < 4:
            continue
        try:
            current_time = float(assignment.get("timestamp", timestamps[index]) or timestamps[index])
        except (TypeError, ValueError):
            continue
        current_candidate = make_timing_candidate(
            entry_index=index,
            entry_text=entry_sung_text(entries[index]),
            source="ctc-current-geometry-probe",
            raw_time=current_time,
            spans=spans,
            confidence=_candidate_confidence(assignment),
            identity_support="supported",
            sequence_support="supported",
            current=False,
            right_edge_pileup=bool(assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(assignment.get("ctc_right_edge_truncation")),
            source_artifact={"geometry_probe": True},
        )
        regions = analyze_candidate_regions(current_candidate)
        coherent_opening = bool(
            regions.temporal_coherence == "coherent"
            and regions.onset_proof_end is not None
        )
        direct_onset_resolvable_opening = bool(
            regions.temporal_coherence == "ambiguous"
            and not regions.severe_gap_indexes
            and spans[0].score >= 0.08
            and regions.reliable_support_count >= 8
            and regions.prefix_duration is not None
            and regions.prefix_duration >= 3.0
        )
        if not (coherent_opening or direct_onset_resolvable_opening):
            continue
        peak = _nearest_local_maximum(features, current_time, VOCAL_ONSET_CONFIRM_RADIUS_SECONDS)
        if peak is None:
            continue
        peak_time, strength, prominence = peak
        if strength < VOCAL_ONSET_CONFIRM_MIN_STRENGTH or prominence < VOCAL_ONSET_CONFIRM_MIN_PROMINENCE:
            continue
        evidence_window = {
            "start": round(current_time - VOCAL_ONSET_CONFIRM_RADIUS_SECONDS, 3),
            "end": round(current_time + VOCAL_ONSET_CONFIRM_RADIUS_SECONDS, 3),
            "audio_sha256": audio_revision,
            "audio_duration_seconds": round(float(duration), 6),
            "feature_revision": "vocal-consonant-onset-v1",
            "peak_strength": round(strength, 8),
            "peak_prominence": round(prominence, 8),
        }
        hypothesis = record_alignment_hypothesis(
            assignment,
            source="ctc-vocal-onset-confirmed",
            stage="independent-vocal-onset-confirmation",
            raw_time=current_time,
            confidence=max(_candidate_confidence(assignment), strength),
            spans=assignment.get("ctc_token_spans"),
            identity_support="supported",
            sequence_support="supported",
            acoustic_support="supported",
            direct_onset_support="supported",
            acoustic_strength=strength,
            acoustic_onset_time=peak_time,
            acoustic_evidence_producer="consonant-onset-detector",
            acoustic_evidence_kind="vocal-onset",
            direct_onset_time=peak_time,
            direct_onset_evidence_producer="consonant-onset-detector",
            direct_onset_evidence_kind="vocal-onset",
            parent_source=str(report.get("backend") or "unknown") + "-current",
            parent_time=current_time,
            window=evidence_window,
            mode="coherent-ctc-plus-bound-vocal-onset",
            right_edge_pileup=bool(assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(assignment.get("ctc_right_edge_truncation")),
        )
        generated.append({
            "entry": index + 1,
            "timestamp": round(current_time, 3),
            "peak_time": round(peak_time, 3),
            "strength": round(strength, 6),
            "prominence": round(prominence, 6),
            "hypothesis_id": hypothesis.get("hypothesis_id"),
        })
    report["vocal_onset_confirmation_hypotheses"] = generated
    report["vocal_onset_confirmation_count"] = len(generated)
    report["vocal_onset_confirmation_authoritative"] = False
    report["vocal_onset_confirmation_mutates_baseline"] = False
    return generated


def apply_vocal_activity_reentry_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> list[dict[str, object]]:
    """Publish boundary-grade evidence only for a real vocal re-entry.

    This is intentionally stricter than ``ctc-vocal-onset-confirmed``. A
    consonant/energy peak can occur inside the predecessor's held syllable, so
    generic vocal onset remains non-boundary-grade. Here the isolated vocal
    activity itself must have stopped long enough to form a separate activity
    segment and then restart at the current CTC boundary. That negative
    evidence about the predecessor tail is independent of the current CTC
    candidate and may therefore resolve UNKNOWN ownership without weakening
    the central invariant.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    try:
        activity = analyze_audio(alignment_audio_path, duration)
        audio_revision = _path_sha256(alignment_audio_path)
    except (LrcError, OSError):
        return []
    generated: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        spans = _candidate_spans_from_assignment(assignment)
        if len(spans) < 4:
            continue
        try:
            current_time = float(assignment.get("timestamp", timestamps[index]) or timestamps[index])
        except (TypeError, ValueError):
            continue
        probe = make_timing_candidate(
            entry_index=index,
            entry_text=entry_sung_text(entries[index]),
            source="ctc-current-reentry-geometry-probe",
            raw_time=current_time,
            spans=spans,
            confidence=_candidate_confidence(assignment),
            identity_support="supported",
            sequence_support="supported",
            current=False,
            right_edge_pileup=bool(assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(assignment.get("ctc_right_edge_truncation")),
            source_artifact={"reentry_geometry_probe": True},
        )
        regions = analyze_candidate_regions(probe)
        geometry_ok = bool(
            regions.temporal_coherence == "coherent"
            and not regions.severe_gap_indexes
            and regions.reliable_support_count >= 3
        )
        if not geometry_ok:
            continue
        reentry = _vocal_activity_reentry_for_time(activity, current_time)
        if reentry is None:
            continue
        segment_start = float(reentry["segment_start"])
        evidence_window = {
            "audio_sha256": audio_revision,
            "audio_duration_seconds": round(float(duration), 6),
            "feature_revision": VOCAL_ACTIVITY_REENTRY_FEATURE_REVISION,
            "segment_index": int(reentry["segment_index"]),
            "segment_start": round(segment_start, 6),
            "segment_end": round(float(reentry["segment_end"]), 6),
            "previous_segment_end": round(float(reentry["previous_segment_end"]), 6),
            "gap_seconds": round(float(reentry["gap_seconds"]), 6),
            "current_time": round(current_time, 6),
        }
        hypothesis = record_alignment_hypothesis(
            assignment,
            source="ctc-vocal-activity-reentry",
            stage="independent-vocal-activity-reentry",
            raw_time=current_time,
            confidence=_candidate_confidence(assignment),
            spans=assignment.get("ctc_token_spans"),
            identity_support="supported",
            sequence_support="supported",
            acoustic_support="unavailable",
            direct_onset_support="supported",
            direct_onset_time=segment_start,
            direct_onset_evidence_producer="vocal-activity-detector",
            direct_onset_evidence_kind="vocal-activity-reentry",
            parent_source=str(report.get("backend") or "unknown") + "-current",
            parent_time=current_time,
            window=evidence_window,
            mode="coherent-ctc-plus-isolated-vocal-reentry",
            right_edge_pileup=bool(assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(assignment.get("ctc_right_edge_truncation")),
        )
        generated.append({
            "entry": index + 1,
            "timestamp": round(current_time, 3),
            "segment_start": round(segment_start, 3),
            "gap_seconds": round(float(reentry["gap_seconds"]), 3),
            "hypothesis_id": hypothesis.get("hypothesis_id"),
        })
    report["vocal_activity_reentry_hypotheses"] = generated
    report["vocal_activity_reentry_count"] = len(generated)
    report["vocal_activity_reentry_authoritative"] = False
    report["vocal_activity_reentry_mutates_baseline"] = False
    return generated


def _mel_filterbank(n_fft: int, n_mels: int = 40) -> np.ndarray:
    def hz_to_mel(value: float) -> float:
        return 2595.0 * math.log10(1.0 + value / 700.0)
    def mel_to_hz(value: float) -> float:
        return 700.0 * (10.0 ** (value / 2595.0) - 1.0)
    mel_points = np.linspace(hz_to_mel(80.0), hz_to_mel(7600.0), n_mels + 2)
    hz_points = np.array([mel_to_hz(float(value)) for value in mel_points])
    bins = np.floor((n_fft + 1) * hz_points / SAMPLE_RATE).astype(int)
    max_bin = n_fft // 2
    bank = np.zeros((n_mels, max_bin + 1), dtype=np.float32)
    for index in range(n_mels):
        left = max(0, int(bins[index]))
        center = max(left + 1, int(bins[index + 1]))
        right = max(center + 1, int(bins[index + 2]))
        center = min(center, max_bin)
        right = min(right, max_bin + 1)
        if center > left:
            bank[index, left:center] = (
                np.arange(left, center, dtype=np.float32) - float(left)
            ) / float(center - left)
        if right > center:
            bank[index, center:right] = (
                float(right) - np.arange(center, right, dtype=np.float32)
            ) / float(right - center)
    return bank


def acoustic_recurrence_features(audio_path: Path) -> np.ndarray:
    """Return deterministic MFCC-like full-song features using only NumPy."""
    cache_key = _audio_feature_cache_key("acoustic-recurrence-features-v1", audio_path)
    cached = _audio_feature_cache.get(cache_key) if cache_key is not None else None
    if isinstance(cached, np.ndarray):
        return cached.copy()

    audio = decode_audio(audio_path)
    n_fft = 1024
    hop = int(round(HOP_SECONDS * SAMPLE_RATE))
    if audio.size < n_fft:
        audio = np.pad(audio, (0, n_fft - audio.size))
    frame_count = 1 + (audio.size - n_fft) // hop
    frames = np.lib.stride_tricks.as_strided(
        np.ascontiguousarray(audio),
        shape=(frame_count, n_fft),
        strides=(audio.strides[0] * hop, audio.strides[0]),
    )
    window = np.hanning(n_fft).astype(np.float32)
    power = np.abs(np.fft.rfft(frames * window, axis=1)).astype(np.float32) ** 2
    log_mel = np.log(np.maximum(power @ _mel_filterbank(n_fft).T, 1e-8)).T
    mel_count = log_mel.shape[0]
    coeff_count = 20
    mel_index = np.arange(mel_count, dtype=np.float32) + 0.5
    coeff_index = np.arange(coeff_count, dtype=np.float32)[:, None]
    dct = np.cos((math.pi / mel_count) * coeff_index * mel_index[None, :]).astype(np.float32)
    cepstral = (dct @ log_mel)[1:]
    delta = np.zeros_like(cepstral)
    if cepstral.shape[1] >= 3:
        delta[:, 1:-1] = 0.5 * (cepstral[:, 2:] - cepstral[:, :-2])
    result = np.vstack([cepstral, delta]).astype(np.float32)
    if cache_key is not None:
        _audio_feature_cache_store(cache_key, result.copy())
    return result


def _recurrence_segment(features: np.ndarray, start: float, end: float) -> np.ndarray:
    start_frame = max(0, int(round(start / HOP_SECONDS)))
    end_frame = min(features.shape[1], int(round(end / HOP_SECONDS)))
    return features[:, start_frame:end_frame]


def acoustic_recurrence_similarity(left: np.ndarray, right: np.ndarray) -> float:
    frame_count = min(left.shape[1], right.shape[1])
    if frame_count < 8:
        return -1.0
    left = left[:, :frame_count].astype(np.float64, copy=True)
    right = right[:, :frame_count].astype(np.float64, copy=True)
    left = (left - left.mean(axis=1, keepdims=True)) / (left.std(axis=1, keepdims=True) + 1e-6)
    right = (right - right.mean(axis=1, keepdims=True)) / (right.std(axis=1, keepdims=True) + 1e-6)
    denominator = float(np.linalg.norm(left) * np.linalg.norm(right))
    if denominator <= 1e-12:
        return -1.0
    return float(np.sum(left * right) / denominator)


def _search_recurrence_start(
    features: np.ndarray,
    template_start: float,
    template_end: float,
    search_start: float,
    search_end: float,
) -> dict[str, float] | None:
    duration = template_end - template_start
    if not (RECURRENCE_MIN_TEMPLATE_SECONDS <= duration <= RECURRENCE_MAX_TEMPLATE_SECONDS):
        return None
    if search_end - search_start < duration + 0.20:
        return None
    template = _recurrence_segment(features, template_start, template_end)
    if template.shape[1] < 8:
        return None
    coarse: list[tuple[float, float]] = []
    step = 0.10
    start = search_start
    latest = search_end - duration
    while start <= latest + 1e-9:
        segment = _recurrence_segment(features, start, start + duration)
        coarse.append((acoustic_recurrence_similarity(template, segment), start))
        start += step
    if not coarse:
        return None
    coarse.sort(reverse=True)
    coarse_best_score, coarse_best_start = coarse[0]
    refine_start = max(search_start, coarse_best_start - 0.16)
    refine_end = min(latest, coarse_best_start + 0.16)
    refined: list[tuple[float, float]] = []
    start = refine_start
    while start <= refine_end + 1e-9:
        segment = _recurrence_segment(features, start, start + duration)
        refined.append((acoustic_recurrence_similarity(template, segment), start))
        start += HOP_SECONDS
    refined.sort(reverse=True)
    best_score, best_start = refined[0] if refined else (coarse_best_score, coarse_best_start)
    separation = max(2.0, duration * 0.30)
    distinct = next(
        ((score, candidate_start) for score, candidate_start in coarse if abs(candidate_start - best_start) >= separation),
        None,
    )
    runner_score = float(distinct[0]) if distinct is not None else -1.0
    return {
        "start": round(float(best_start), 3),
        "score": round(float(best_score), 8),
        "runner_score": round(runner_score, 8),
        "margin": round(float(best_score - runner_score), 8),
        "template_duration": round(duration, 3),
    }


def _project_recurrence_spans_from_geometry(
    spans: tuple[TimingTokenSpan, ...],
    reference_start: float,
    candidate_start: float,
    recurrence_score: float,
) -> list[dict[str, object]]:
    if not spans:
        return []
    projected: list[dict[str, object]] = []
    for span in spans:
        projected.append({
            "char": span.token,
            "start": round(candidate_start + (span.start - reference_start), 3),
            "end": round(candidate_start + (span.end - reference_start), 3),
            "score": round(min(span.score, max(0.08, recurrence_score)), 6),
        })
    return projected


def _project_recurrence_spans(
    reference: TimingCandidate,
    candidate_start: float,
    recurrence_score: float,
) -> list[dict[str, object]]:
    return _project_recurrence_spans_from_geometry(
        reference.spans, reference.written_time.seconds, candidate_start, recurrence_score
    )




def acoustic_pitchclass_recurrence_features(audio_path: Path) -> np.ndarray:
    """Return a dependency-free pitch-class recurrence representation.

    This representation is intentionally independent from the MMS posterior
    path.  Short-time spectral energy is accumulated by pitch class, then
    temporally smoothed to suppress transient/percussive dominance.  A delta
    stream preserves phrase-shape changes.  It is used only as recurrence
    evidence; it never writes a timestamp directly.
    """
    audio = decode_audio(audio_path)
    n_fft = 2048
    hop = int(round(HOP_SECONDS * SAMPLE_RATE))
    if audio.size < n_fft:
        audio = np.pad(audio, (0, n_fft - audio.size))
    frame_count = 1 + (audio.size - n_fft) // hop
    frames = np.lib.stride_tricks.as_strided(
        np.ascontiguousarray(audio),
        shape=(frame_count, n_fft),
        strides=(audio.strides[0] * hop, audio.strides[0]),
    )
    window = np.hanning(n_fft).astype(np.float32)
    power = np.abs(np.fft.rfft(frames * window, axis=1)).astype(np.float32) ** 2
    frequencies = np.fft.rfftfreq(n_fft, 1.0 / SAMPLE_RATE)
    valid = (frequencies >= 80.0) & (frequencies <= 5000.0)
    valid_frequencies = frequencies[valid]
    midi = 69.0 + 12.0 * np.log2(np.maximum(valid_frequencies, 1e-6) / 440.0)
    pitch_classes = np.mod(np.rint(midi).astype(np.int16), 12)
    compressed = np.log1p(power[:, valid] * 1000.0)
    chroma = np.zeros((12, frame_count), dtype=np.float32)
    for pitch_class in range(12):
        bins = pitch_classes == pitch_class
        if np.any(bins):
            chroma[pitch_class] = compressed[:, bins].sum(axis=1)

    # ~300 ms temporal mean: long enough to attenuate drum transients while
    # keeping sung phrase contours.  Implemented with a cumulative sum so the
    # production path remains NumPy-only.
    smoothing_frames = 15
    pad = smoothing_frames // 2
    padded = np.pad(chroma, ((0, 0), (pad, pad)), mode="edge")
    cumulative = np.cumsum(
        np.pad(padded, ((0, 0), (1, 0)), mode="constant"), axis=1, dtype=np.float64
    )
    smoothed = (
        (cumulative[:, smoothing_frames:] - cumulative[:, :-smoothing_frames])
        / float(smoothing_frames)
    ).astype(np.float32)
    delta = np.zeros_like(smoothed)
    if smoothed.shape[1] >= 3:
        delta[:, 1:-1] = 0.5 * (smoothed[:, 2:] - smoothed[:, :-2])
    return np.vstack([smoothed, delta]).astype(np.float32)


def _local_onset_candidates(
    features: AudioFeatures,
    start: float,
    end: float,
    *,
    min_strength: float,
    min_prominence: float,
    min_separation: float = 0.18,
) -> list[dict[str, float]]:
    if end <= start or features.frame_times.size == 0:
        return []
    indices = np.flatnonzero(
        (features.frame_times >= start) & (features.frame_times <= end)
    )
    raw: list[dict[str, float]] = []
    for index in indices:
        strength = float(features.onset_strength[index])
        if strength < min_strength:
            continue
        left = float(features.onset_strength[index - 1]) if index > 0 else -1.0
        right = (
            float(features.onset_strength[index + 1])
            if index + 1 < features.onset_strength.size else -1.0
        )
        if strength < left or strength < right:
            continue
        time = float(features.frame_times[index])
        context = np.flatnonzero(
            (features.frame_times >= time - 0.80)
            & (features.frame_times <= time + 0.80)
        )
        baseline = float(np.median(features.onset_strength[context])) if context.size else 0.0
        prominence = strength - baseline
        if prominence < min_prominence:
            continue
        raw.append({"time": time, "strength": strength, "prominence": prominence})
    raw.sort(key=lambda item: (-item["strength"], -item["prominence"], item["time"]))
    selected: list[dict[str, float]] = []
    for item in raw:
        if all(abs(item["time"] - kept["time"]) >= min_separation for kept in selected):
            selected.append(item)
    return sorted(selected, key=lambda item: item["time"])


def _strongest_local_onset(
    features: AudioFeatures,
    start: float,
    end: float,
    *,
    min_strength: float,
    min_prominence: float,
) -> dict[str, float] | None:
    candidates = _local_onset_candidates(
        features,
        start,
        end,
        min_strength=min_strength,
        min_prominence=min_prominence,
    )
    if not candidates:
        return None
    return max(candidates, key=lambda item: (item["prominence"], item["strength"], -item["time"]))


def _first_post_tail_cluster_onset(
    features: AudioFeatures,
    tail_end: float,
    search_end: float,
    *,
    min_strength: float,
    min_prominence: float,
) -> dict[str, float] | None:
    """Return the first strong onset that begins a new post-tail onset cluster.

    A reliable-tail boundary may still contain several high-energy sub-onsets
    from the predecessor's final syllable/instrumental accent.  Picking the
    strongest peak in the release window systematically biases late.  Instead,
    retain temporal structure: a candidate must be the first qualifying peak
    after ``tail_end`` that follows a genuine quiet separation from the prior
    qualifying peak.  If no cluster break is observable, fail closed.
    """
    context_start = max(0.0, tail_end - TAIL_RELEASE_CONTEXT_SECONDS)
    candidates = _local_onset_candidates(
        features,
        context_start,
        search_end,
        min_strength=min_strength,
        min_prominence=min_prominence,
        min_separation=0.04,
    )
    previous: dict[str, float] | None = None
    for candidate in candidates:
        if candidate["time"] < tail_end:
            previous = candidate
            continue
        if previous is not None:
            gap = candidate["time"] - previous["time"]
            if gap >= TAIL_RELEASE_CLUSTER_BREAK_SECONDS:
                return {
                    **candidate,
                    "previous_onset_time": previous["time"],
                    "cluster_gap": gap,
                    "context_start": context_start,
                }
        previous = candidate
    return None


def _self_bound_hypothesis_record(hypothesis: object) -> bool:
    if not isinstance(hypothesis, dict):
        return False
    hypothesis_id = hypothesis.get("hypothesis_id")
    if not isinstance(hypothesis_id, str) or not hypothesis_id:
        return False
    payload = copy.deepcopy(hypothesis)
    payload.pop("hypothesis_id", None)
    return _timing_content_digest(payload) == hypothesis_id


def _bound_local_occurrence_identity(assignment: dict[str, object]) -> dict[str, object] | None:
    """Return immutable whole-line local CTC identity evidence for an occurrence.

    Mutual recurrence may locate the boundary acoustically, but it must not
    bootstrap lyric identity from recurrence similarity alone.  Each side is
    therefore required to have a self-bound local CTC hypothesis that
    independently supports the full lyric identity and sequence.  In addition
    to the ordinary local-window producer, a completed bounded retry may
    contribute an *identity-only* row.  That retry row is never itself a timing
    candidate and is rejected here when its helper window was truncated or
    piled up at the right edge.  Temporal incoherence is allowed because this
    evidence establishes occurrence identity only; the recurrence candidate
    must still satisfy central onset/ownership proof separately.
    """
    hypotheses = assignment.get("alignment_hypotheses")
    if not isinstance(hypotheses, list):
        return None
    eligible: list[dict[str, object]] = []
    identity_sources = {"ctc-local-window", "ctc-opening-local-retry-identity"}
    for hypothesis in hypotheses:
        if (
            not isinstance(hypothesis, dict)
            or hypothesis.get("source") not in identity_sources
            or hypothesis.get("authoritative") is not False
            or hypothesis.get("identity_support") != "supported"
            or hypothesis.get("sequence_support") != "supported"
            or not _self_bound_hypothesis_record(hypothesis)
        ):
            continue
        if (
            hypothesis.get("source") == "ctc-opening-local-retry-identity"
            and (
                bool(hypothesis.get("window_truncated"))
                or bool(hypothesis.get("right_edge_pileup"))
            )
        ):
            continue
        spans = hypothesis.get("spans")
        if not isinstance(spans, list) or len(spans) < 4:
            continue
        try:
            raw_time = float(hypothesis.get("raw_candidate_time"))
            confidence = float(hypothesis.get("confidence", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(raw_time):
            continue
        eligible.append({
            "hypothesis_id": hypothesis["hypothesis_id"],
            "source": str(hypothesis.get("source")),
            "raw_candidate_time": round(raw_time, 6),
            "confidence": round(_finite_unit_confidence(confidence), 8),
            "span_digest": _timing_content_digest(spans),
        })
    if not eligible:
        return None
    return max(eligible, key=lambda row: (float(row["confidence"]), str(row["hypothesis_id"])))


def _candidate_seed_rows(assignment: dict[str, object]) -> list[dict[str, object]]:
    """Return non-authoritative phonetic seeds with explicit provenance.

    Seeds locate a broad occurrence neighborhood only.  They cannot themselves
    satisfy central timing proof and are never copied into the final timestamp
    without independent acoustic evidence.
    """
    rows: list[dict[str, object]] = []

    def semantic_rank(row: dict[str, object]) -> tuple[float, float, int, float]:
        kind_priority = {
            "ctc-local-first-token": 3,
            "ctc-local-retry-first-token": 2,
            "ctc-detached-second-token": 1,
            "ctc-first-token-posterior": 0,
        }
        return (
            float(row.get("strength", 0.0)),
            float(row.get("first_token_score", 0.0)),
            kind_priority.get(str(row.get("kind")), -1),
            -float(row.get("time", 0.0)),
        )
    hypotheses = assignment.get("alignment_hypotheses")
    if isinstance(hypotheses, list):
        for hypothesis in hypotheses:
            if (
                not isinstance(hypothesis, dict)
                or hypothesis.get("source") not in {
                    "ctc-local-window",
                    "ctc-opening-local-retry-identity",
                }
            ):
                continue
            if (
                hypothesis.get("source") == "ctc-opening-local-retry-identity"
                and (
                    bool(hypothesis.get("window_truncated"))
                    or bool(hypothesis.get("right_edge_pileup"))
                )
            ):
                continue
            spans = hypothesis.get("spans")
            if not isinstance(spans, list) or not spans or not isinstance(spans[0], dict):
                continue
            try:
                seed_time = float(spans[0].get("start"))
                first_score = float(spans[0].get("score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(seed_time):
                continue
            rows.append({
                "time": seed_time,
                "strength": 0.55 + min(0.44, max(0.0, first_score)),
                "kind": (
                    "ctc-local-retry-first-token"
                    if hypothesis.get("source") == "ctc-opening-local-retry-identity"
                    else "ctc-local-first-token"
                ),
                "evidence_id": str(hypothesis.get("hypothesis_id") or ""),
                "first_token_score": first_score,
            })

    legacy = assignment.get("candidates")
    if isinstance(legacy, list):
        for candidate in legacy:
            if not isinstance(candidate, dict) or candidate.get("source") != "ctc_detached_initial_token_recovery":
                continue
            try:
                seed_time = float(candidate.get("time"))
            except (TypeError, ValueError):
                continue
            rows.append({
                "time": seed_time,
                "strength": 0.82,
                "kind": "ctc-detached-second-token",
                "evidence_id": _timing_content_digest(candidate),
                "first_token_score": 0.0,
            })

    peaks = assignment.get("ctc_first_token_candidates")
    if isinstance(peaks, list):
        for peak in peaks:
            if not isinstance(peak, dict):
                continue
            try:
                seed_time = float(peak.get("time"))
                score = float(peak.get("score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            if score <= 0.0 or not math.isfinite(seed_time):
                continue
            rows.append({
                "time": seed_time,
                "strength": 0.50 + min(0.30, math.sqrt(max(0.0, score)) * 0.75),
                "kind": "ctc-first-token-posterior",
                "evidence_id": _timing_content_digest(peak),
                "first_token_score": score,
            })

    # Keep only seeds in the same broad neighborhood as a local-window result
    # when such a result exists.  This prevents a whole-song first-token echo
    # from becoming a mutual-recurrence anchor.
    local_seed_kinds = {"ctc-local-first-token", "ctc-local-retry-first-token"}
    local_times = [
        float(row["time"]) for row in rows if row.get("kind") in local_seed_kinds
    ]
    if local_times:
        local_time = max(
            (row for row in rows if row.get("kind") in local_seed_kinds),
            key=semantic_rank,
        )["time"]
        filtered = [
            row for row in rows
            if row.get("kind") == "ctc-detached-second-token"
            or row.get("kind") in local_seed_kinds
            or abs(float(row["time"]) - float(local_time)) <= 1.25
        ]
        if filtered:
            rows = filtered
    return sorted(
        rows,
        key=lambda row: (
            -semantic_rank(row)[0],
            -semantic_rank(row)[1],
            -semantic_rank(row)[2],
            -semantic_rank(row)[3],
            str(row.get("evidence_id")),
        ),
    )


def _best_mutual_recurrence_pair(
    features: np.ndarray,
    onset_features: AudioFeatures,
    left_seed: dict[str, object],
    right_seed: dict[str, object],
    *,
    left_bounds: tuple[float, float],
    right_bounds: tuple[float, float],
) -> dict[str, float] | None:
    left_seed_time = float(left_seed["time"])
    right_seed_time = float(right_seed["time"])
    left_is_anchor = float(left_seed.get("strength", 0.0)) >= float(right_seed.get("strength", 0.0))
    left_radius = MUTUAL_RECURRENCE_ANCHOR_RADIUS_SECONDS if left_is_anchor else MUTUAL_RECURRENCE_PEER_RADIUS_SECONDS
    right_radius = MUTUAL_RECURRENCE_PEER_RADIUS_SECONDS if left_is_anchor else MUTUAL_RECURRENCE_ANCHOR_RADIUS_SECONDS
    left_onsets = _local_onset_candidates(
        onset_features,
        max(left_bounds[0], left_seed_time - left_radius),
        min(left_bounds[1], left_seed_time + left_radius),
        min_strength=0.45,
        min_prominence=0.10,
    )
    right_onsets = _local_onset_candidates(
        onset_features,
        max(right_bounds[0], right_seed_time - right_radius),
        min(right_bounds[1], right_seed_time + right_radius),
        min_strength=0.45,
        min_prominence=0.10,
    )
    if not left_onsets or not right_onsets:
        return None
    candidates: list[dict[str, float]] = []
    durations = (4.0, 4.5, 5.0, 5.5, 6.0, 6.5, 7.0, 7.5, 8.0)
    for left in left_onsets:
        for right in right_onsets:
            for template_duration in durations:
                if left["time"] + template_duration > left_bounds[1] + 0.25:
                    continue
                if right["time"] + template_duration > right_bounds[1] + 0.25:
                    continue
                score = acoustic_recurrence_similarity(
                    _recurrence_segment(features, left["time"], left["time"] + template_duration),
                    _recurrence_segment(features, right["time"], right["time"] + template_duration),
                )
                candidates.append({
                    "score": score,
                    "left": left["time"],
                    "right": right["time"],
                    "duration": template_duration,
                    "left_strength": left["strength"],
                    "left_prominence": left["prominence"],
                    "right_strength": right["strength"],
                    "right_prominence": right["prominence"],
                })
    if not candidates:
        return None
    candidates.sort(key=lambda row: (-row["score"], row["left"], row["right"], row["duration"]))
    best = candidates[0]
    runner = next(
        (
            row for row in candidates[1:]
            if abs(row["left"] - best["left"]) >= MUTUAL_RECURRENCE_DISTINCT_SECONDS
            or abs(row["right"] - best["right"]) >= MUTUAL_RECURRENCE_DISTINCT_SECONDS
        ),
        None,
    )
    runner_score = float(runner["score"]) if runner is not None else -1.0
    best = dict(best)
    best["runner_score"] = runner_score
    best["margin"] = float(best["score"] - runner_score)
    return best


def _trusted_bounds_for_entry(
    evaluated: EvaluatedBackendTiming,
    index: int,
    duration: float,
) -> tuple[float, float]:
    trusted = [bool(audit.timing_trusted) for audit in evaluated.state.audits]
    lower = next(
        (
            evaluated.state.decisions[position].written_time.seconds + 0.20
            for position in range(index - 1, -1, -1)
            if trusted[position]
        ),
        0.0,
    )
    upper = next(
        (
            evaluated.state.decisions[position].written_time.seconds - 0.20
            for position in range(index + 1, len(trusted))
            if trusted[position]
        ),
        duration,
    )
    return max(0.0, lower), min(duration, upper)


def apply_phonetic_onset_fusion_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    evaluated: EvaluatedBackendTiming,
    duration: float,
) -> list[dict[str, object]]:
    """Fuse a coherent CTC first-token posterior with independent audio onset.

    This is not a threshold relaxation of the existing CTC candidate.  It emits
    a span-free challenger only when the whole-line CTC path is coherent, the
    assignment content is already trusted, a first-token posterior is strong,
    and original-program audio independently places an onset within the strict
    association radius.  The baseline timestamp is never changed here.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    try:
        onset_features = analyze_vocal_onsets(alignment_audio_path, duration)
        audio_sha = _path_sha256(alignment_audio_path)
    except (LrcError, OSError):
        return []
    generated: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict) or evaluated.state.audits[index].timing_trusted:
            continue
        if not assignment_content_is_trusted(assignment):
            continue
        current = evaluated.state.decisions[index].candidate
        regions = analyze_candidate_regions(current)
        if (
            current.source not in {"ctc-current", "ctc-vocal-onset-confirmed"}
            or current.identity_support != "supported"
            or not current.spans
            or regions.temporal_coherence != "coherent"
            or current.right_edge_pileup
            or current.window_truncated
        ):
            continue
        peaks = assignment.get("ctc_first_token_candidates")
        if not isinstance(peaks, list):
            continue
        parsed: list[tuple[float, float, dict[str, object]]] = []
        for peak in peaks:
            if not isinstance(peak, dict):
                continue
            try:
                peak_time = float(peak.get("time"))
                peak_score = float(peak.get("score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            if (
                peak_score >= PHONETIC_ONSET_MIN_POSTERIOR
                and abs(peak_time - current.written_time.seconds) <= 0.50
            ):
                parsed.append((peak_score, peak_time, peak))
        if not parsed:
            continue
        peak_score, peak_time, peak_row = max(parsed, key=lambda item: (item[0], -abs(item[1] - current.written_time.seconds)))
        acoustic = _nearest_local_maximum(onset_features, peak_time, PHONETIC_ONSET_RADIUS_SECONDS)
        if acoustic is None:
            continue
        onset_time, onset_strength, onset_prominence = acoustic
        if onset_strength < PHONETIC_ONSET_MIN_STRENGTH or onset_prominence < PHONETIC_ONSET_MIN_PROMINENCE:
            continue
        if abs(onset_time - peak_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS:
            continue
        window = {
            "audio_sha256": audio_sha,
            "audio_duration_seconds": round(float(duration), 6),
            "current_candidate_id": current.candidate_id,
            "current_raw_time": round(current.raw_time, 6),
            "current_written_centiseconds": current.written_time.centiseconds,
            "current_time": round(current.written_time.seconds, 6),
            "ctc_peak_time": round(peak_time, 6),
            "ctc_peak_score": round(peak_score, 8),
            "ctc_peak_digest": _timing_content_digest(peak_row),
            "onset_time": (round(onset_time, 6) if onset_time is not None else None),
            "onset_strength": round(onset_strength, 8),
            "onset_prominence": round(onset_prominence, 8),
            "feature_revision": PHONETIC_ONSET_FEATURE_REVISION,
        }
        before = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else 0
        hypothesis = record_alignment_hypothesis(
            assignment,
            source="ctc-phonetic-onset-fusion",
            stage="independent-phonetic-onset-fusion",
            raw_time=peak_time,
            confidence=min(1.0, 0.70 + peak_score),
            spans=[],
            identity_support="supported",
            sequence_support="supported",
            acoustic_support="supported",
            direct_onset_support="unavailable",
            acoustic_strength=onset_strength,
            acoustic_onset_time=onset_time,
            acoustic_evidence_producer="phonetic-onset-fusion",
            acoustic_evidence_kind="phonetic-onset",
            direct_onset_time=onset_time,
            direct_onset_evidence_producer="phonetic-onset-fusion",
            direct_onset_evidence_kind="phonetic-onset",
            parent_source=current.source,
            parent_time=current.raw_time,
            window=window,
            mode="coherent-ctc-first-token-plus-independent-onset",
        )
        after = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else before
        if after > before:
            generated.append({
                "entry": index + 1,
                "candidate": round(peak_time, 3),
                "onset": round(onset_time, 3),
                "posterior": round(peak_score, 6),
                "hypothesis_id": hypothesis.get("hypothesis_id"),
            })
    report["phonetic_onset_fusion_hypotheses"] = generated
    report["phonetic_onset_fusion_count"] = len(generated)
    report["phonetic_onset_fusion_authoritative"] = False
    report["phonetic_onset_fusion_mutates_baseline"] = False
    return generated


def apply_mutual_acoustic_recurrence_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    evaluated: EvaluatedBackendTiming,
    duration: float,
) -> list[dict[str, object]]:
    """Resolve a deadlocked exact-duplicate pair without trusting either side.

    Both occurrences must be timing-untrusted, both must have independent CTC
    seed evidence, and a reciprocal raw-audio recurrence must pass a strong
    similarity + distinct-alternative margin.  Two hypotheses with the same
    pair id are emitted together; one cannot gain independent identity without
    the reciprocal peer row being present and provenance-valid.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    try:
        features = acoustic_pitchclass_recurrence_features(alignment_audio_path)
        onset_features = analyze_vocal_onsets(alignment_audio_path, duration)
        audio_sha = _path_sha256(alignment_audio_path)
    except (LrcError, OSError):
        return []
    groups: dict[str, list[int]] = {}
    for index, entry in enumerate(entries):
        normalized = normalize_match_text(entry_sung_text(entry))
        if normalized:
            groups.setdefault(normalized, []).append(index)
    generated: list[dict[str, object]] = []
    for normalized, indexes in groups.items():
        untrusted = [index for index in indexes if not evaluated.state.audits[index].timing_trusted]
        trusted = [index for index in indexes if evaluated.state.audits[index].timing_trusted]
        # Trusted-reference recurrence owns mixed groups.  Mutual recurrence is
        # intentionally limited to an unambiguous two-occurrence deadlock.
        if trusted or len(indexes) != 2 or len(untrusted) != 2:
            continue
        left_index, right_index = sorted(untrusted)
        left_assignment = assignments[left_index]
        right_assignment = assignments[right_index]
        if not isinstance(left_assignment, dict) or not isinstance(right_assignment, dict):
            continue
        left_identity = _bound_local_occurrence_identity(left_assignment)
        right_identity = _bound_local_occurrence_identity(right_assignment)
        if left_identity is None or right_identity is None:
            continue
        left_seeds = _candidate_seed_rows(left_assignment)
        right_seeds = _candidate_seed_rows(right_assignment)
        if not left_seeds or not right_seeds:
            continue
        left_seed = left_seeds[0]
        right_seed = right_seeds[0]
        left_bounds = _trusted_bounds_for_entry(evaluated, left_index, duration)
        right_bounds = _trusted_bounds_for_entry(evaluated, right_index, duration)
        if not (left_bounds[0] < float(left_seed["time"]) < left_bounds[1]):
            continue
        if not (right_bounds[0] < float(right_seed["time"]) < right_bounds[1]):
            continue
        result = _best_mutual_recurrence_pair(
            features,
            onset_features,
            left_seed,
            right_seed,
            left_bounds=left_bounds,
            right_bounds=right_bounds,
        )
        if result is None:
            continue
        score = float(result["score"])
        margin = float(result["margin"])
        if score < MUTUAL_RECURRENCE_MIN_SIMILARITY or margin < MUTUAL_RECURRENCE_MIN_DISTINCT_MARGIN:
            continue
        pair_payload = {
            "audio_sha256": audio_sha,
            "feature_revision": MUTUAL_RECURRENCE_FEATURE_REVISION,
            "normalized_lyric_sha256": hashlib.sha256(normalized.encode("utf-8")).hexdigest(),
            "left_entry": left_index + 1,
            "right_entry": right_index + 1,
            "left_seed": left_seed,
            "right_seed": right_seed,
            "left_identity_evidence": left_identity,
            "right_identity_evidence": right_identity,
            "left_bounds": [round(left_bounds[0], 3), round(left_bounds[1], 3)],
            "right_bounds": [round(right_bounds[0], 3), round(right_bounds[1], 3)],
            "left_candidate": round(float(result["left"]), 6),
            "right_candidate": round(float(result["right"]), 6),
            "template_duration": round(float(result["duration"]), 3),
            "similarity": round(score, 8),
            "runner_similarity": round(float(result["runner_score"]), 8),
            "distinct_margin": round(margin, 8),
        }
        pair_id = _timing_content_digest(pair_payload)
        pair_payload["pair_id"] = pair_id
        emitted: list[dict[str, object]] = []
        for target_index, peer_index, candidate_key, peer_key, strength_key, prominence_key in (
            (left_index, right_index, "left_candidate", "right_candidate", "left_strength", "left_prominence"),
            (right_index, left_index, "right_candidate", "left_candidate", "right_strength", "right_prominence"),
        ):
            assignment = assignments[target_index]
            assert isinstance(assignment, dict)
            candidate_time = float(pair_payload[candidate_key])
            onset_strength = float(result[strength_key])
            onset_prominence = float(result[prominence_key])
            window = {
                **pair_payload,
                "target_entry": target_index + 1,
                "peer_entry": peer_index + 1,
                "peer_candidate": float(pair_payload[peer_key]),
                "onset_strength": round(onset_strength, 8),
                "onset_prominence": round(onset_prominence, 8),
            }
            before = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else 0
            hypothesis = record_alignment_hypothesis(
                assignment,
                source="mutual-acoustic-recurrence",
                stage="occurrence-level-mutual-recurrence-search",
                raw_time=candidate_time,
                confidence=min(1.0, score),
                spans=[],
                identity_support="supported",
                sequence_support="supported",
                acoustic_support="supported",
                direct_onset_support="supported",
                acoustic_strength=onset_strength,
                acoustic_onset_time=candidate_time,
                acoustic_evidence_producer="mutual-recurrence-search",
                acoustic_evidence_kind="recurrence-onset",
                direct_onset_time=candidate_time,
                direct_onset_evidence_producer="mutual-recurrence-search",
                direct_onset_evidence_kind="recurrence-onset",
                parent_source="reciprocal-untrusted-duplicate-pair",
                parent_time=float(left_seed["time"] if target_index == left_index else right_seed["time"]),
                window=window,
                mode="reciprocal-exact-duplicate-pitchclass-recurrence",
            )
            after = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else before
            if after > before:
                emitted.append({
                    "entry": target_index + 1,
                    "peer_entry": peer_index + 1,
                    "candidate": round(candidate_time, 3),
                    "similarity": round(score, 6),
                    "distinct_margin": round(margin, 6),
                    "pair_id": pair_id,
                    "hypothesis_id": hypothesis.get("hypothesis_id"),
                })
        # A reciprocal pair is atomic.  If only one side was new because the
        # other already exists, retaining the existing peer is valid; if neither
        # row exists there is nothing to report.  Provenance validation later
        # requires both reciprocal rows in the ledger.
        generated.extend(emitted)
    report["mutual_acoustic_recurrence_hypotheses"] = generated
    report["mutual_acoustic_recurrence_count"] = len(generated)
    report["mutual_acoustic_recurrence_authoritative"] = False
    report["mutual_acoustic_recurrence_mutates_baseline"] = False
    return generated


def apply_trusted_tail_release_onset_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    evaluated: EvaluatedBackendTiming,
    duration: float,
) -> list[dict[str, object]]:
    """Recover a content-trusted line whose current onset invades a trusted tail.

    This producer is deliberately unavailable when the predecessor tail is
    invalid/unknown.  It therefore does not resurrect the historical
    "fractured predecessor retry" behavior.  A candidate is published only
    from a strong independent onset inside the already-proven tail release
    region; central ownership still decides whether that onset can be trusted.
    """
    tail_evidence_context = _tail_evidence_context_from_report(
        report, entries=entries
    )
    independent_tail_evidence = runtime_independent_tail_evidence(
        report, len(entries), tail_evidence_context
    )
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    try:
        onset_features = analyze_vocal_onsets(alignment_audio_path, duration)
        audio_sha = _path_sha256(alignment_audio_path)
    except (LrcError, OSError):
        return []
    generated: list[dict[str, object]] = []
    for index in range(1, len(entries)):
        assignment = assignments[index]
        if not isinstance(assignment, dict) or evaluated.state.audits[index].timing_trusted:
            continue
        if not assignment_content_is_trusted(assignment):
            continue
        previous_decision = evaluated.state.decisions[index - 1]
        previous_audit = evaluated.state.audits[index - 1]
        if not previous_audit.timing_trusted:
            continue
        previous_tail = resolve_reliable_tail(
            previous_decision.candidate,
            independent_tail_evidence[index - 1]
            if independent_tail_evidence is not None
            else None,
            tail_evidence_context=tail_evidence_context,
        )
        if previous_tail.validity != "valid" or previous_tail.reliable_tail_end is None:
            continue
        current = evaluated.state.decisions[index].candidate
        if not current.current:
            continue
        if current.written_time.seconds > previous_tail.reliable_tail_end:
            # This producer only repairs an actual tail invasion.  Release-zone
            # uncertainty without overlap is handled by phonetic-onset fusion.
            continue
        uncertainty = float(previous_tail.uncertainty_seconds or 0.0)
        search_start = previous_tail.reliable_tail_end
        search_end = min(duration, search_start + max(0.65, min(1.20, uncertainty + 0.30)))
        next_trusted = next(
            (
                evaluated.state.decisions[position].written_time.seconds - 0.20
                for position in range(index + 1, len(entries))
                if evaluated.state.audits[position].timing_trusted
            ),
            duration,
        )
        search_end = min(search_end, next_trusted)
        onset = _first_post_tail_cluster_onset(
            onset_features,
            search_start,
            search_end,
            min_strength=TAIL_RELEASE_ONSET_MIN_STRENGTH,
            min_prominence=TAIL_RELEASE_ONSET_MIN_PROMINENCE,
        )
        if onset is None:
            continue
        candidate_time = float(onset["time"])
        window = {
            "audio_sha256": audio_sha,
            "feature_revision": TAIL_RELEASE_FEATURE_REVISION,
            "previous_candidate_id": previous_decision.candidate.candidate_id,
            "previous_tail_revision": previous_tail.tail_evidence_revision,
            "previous_tail_end": round(previous_tail.reliable_tail_end, 6),
            "previous_tail_uncertainty": round(uncertainty, 6),
            "search_start": round(search_start, 6),
            "search_end": round(search_end, 6),
            "onset_strength": round(float(onset["strength"]), 8),
            "onset_prominence": round(float(onset["prominence"]), 8),
            "previous_onset_time": round(float(onset["previous_onset_time"]), 6),
            "cluster_gap": round(float(onset["cluster_gap"]), 6),
            "context_start": round(float(onset["context_start"]), 6),
            "old_candidate_raw_time": round(current.raw_time, 6),
            "old_candidate_centiseconds": current.written_time.centiseconds,
            "old_candidate_time": round(current.written_time.seconds, 6),
        }
        before = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else 0
        hypothesis = record_alignment_hypothesis(
            assignment,
            source="trusted-tail-release-onset",
            stage="trusted-tail-release-onset-search",
            raw_time=candidate_time,
            confidence=min(1.0, 0.70 + float(onset["prominence"]) * 0.30),
            spans=[],
            identity_support="supported",
            sequence_support="supported",
            acoustic_support="supported",
            direct_onset_support="supported",
            acoustic_strength=float(onset["strength"]),
            acoustic_onset_time=candidate_time,
            acoustic_evidence_producer="tail-release-acoustic-search",
            acoustic_evidence_kind="generic-acoustic",
            direct_onset_time=candidate_time,
            direct_onset_evidence_producer="tail-release-acoustic-search",
            direct_onset_evidence_kind="generic-onset",
            parent_source="central-trusted-predecessor-tail",
            parent_time=previous_tail.reliable_tail_end,
            window=window,
            mode="strong-onset-inside-centrally-trusted-tail-release",
        )
        after = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else before
        if after > before:
            generated.append({
                "entry": index + 1,
                "candidate": round(candidate_time, 3),
                "previous_entry": index,
                "previous_tail_end": round(previous_tail.reliable_tail_end, 3),
                "hypothesis_id": hypothesis.get("hypothesis_id"),
            })
    report["trusted_tail_release_onset_hypotheses"] = generated
    report["trusted_tail_release_onset_count"] = len(generated)
    report["trusted_tail_release_onset_authoritative"] = False
    report["trusted_tail_release_onset_mutates_baseline"] = False
    return generated


def vocal_onset_confirmation_provenance_is_valid(
    hypothesis: dict[str, object],
    assignment: dict[str, object],
    evidence_audio_path: Path,
    *,
    recomputed_features: AudioFeatures | None = None,
    evidence_audio_sha256: str | None = None,
) -> bool:
    """Recompute whether a CTC + consonant-onset hypothesis is independently bound.

    The serialized source label is never sufficient.  The row must bind to the
    actual assignment CTC spans and to the audio artifact used by the onset
    producer.  This prevents a candidate timestamp from manufacturing its own
    direct-onset certificate.
    """
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if (
        hypothesis.get("source") != "ctc-vocal-onset-confirmed"
        or hypothesis.get("stage") != "independent-vocal-onset-confirmation"
        or hypothesis.get("mode") != "coherent-ctc-plus-bound-vocal-onset"
        or hypothesis.get("authoritative") is not False
        or hypothesis.get("identity_support") != "supported"
        or hypothesis.get("sequence_support") != "supported"
        or hypothesis.get("acoustic_support") != "supported"
        or hypothesis.get("direct_onset_support") != "supported"
    ):
        return False
    window = hypothesis.get("window")
    parent = hypothesis.get("parent")
    if not isinstance(window, dict) or not isinstance(parent, dict):
        return False
    if window.get("feature_revision") != "vocal-consonant-onset-v1":
        return False
    spans = hypothesis.get("spans")
    assignment_spans = assignment.get("ctc_token_spans")
    if not isinstance(spans, list) or not spans or spans != assignment_spans:
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        parent_time = float(parent.get("raw_candidate_time"))
        onset_time = float(hypothesis.get("direct_onset_time"))
        acoustic_time = float(hypothesis.get("acoustic_onset_time"))
        strength = float(hypothesis.get("acoustic_strength"))
        window_strength = float(window.get("peak_strength"))
        prominence = float(window.get("peak_prominence"))
    except (TypeError, ValueError):
        return False
    if not all(math.isfinite(value) for value in (raw_time, parent_time, onset_time, acoustic_time, strength, window_strength, prominence)):
        return False
    if (
        not _serialized_seconds_equal(raw_time, parent_time)
        or not _serialized_seconds_equal(onset_time, acoustic_time)
        or abs(strength - window_strength) > 1e-6
        or abs(onset_time - canonicalize_lrc_time(raw_time).seconds) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
        or strength < VOCAL_ONSET_CONFIRM_MIN_STRENGTH
        or prominence < VOCAL_ONSET_CONFIRM_MIN_PROMINENCE
    ):
        return False
    try:
        audio_sha = evidence_audio_sha256 or _path_sha256(evidence_audio_path)
        evidence_duration = float(window.get("audio_duration_seconds"))
    except (OSError, LrcError, TypeError, ValueError):
        return False
    if not math.isfinite(evidence_duration) or evidence_duration <= 0.0:
        return False
    if window.get("audio_sha256") != audio_sha:
        return False
    try:
        recomputed = recomputed_features or analyze_vocal_onsets(
            evidence_audio_path, evidence_duration
        )
        peak = _nearest_local_maximum(recomputed, raw_time, VOCAL_ONSET_CONFIRM_RADIUS_SECONDS)
    except (LrcError, OSError):
        return False
    if peak is None:
        return False
    recomputed_time, recomputed_strength, recomputed_prominence = peak
    return bool(
        abs(recomputed_time - onset_time) <= HOP_SECONDS * 0.51
        and abs(recomputed_strength - strength) <= 1e-5
        and abs(recomputed_prominence - prominence) <= 1e-5
        and recomputed_strength >= VOCAL_ONSET_CONFIRM_MIN_STRENGTH
        and recomputed_prominence >= VOCAL_ONSET_CONFIRM_MIN_PROMINENCE
    )



def ctc_opening_vocal_fusion_is_valid(
    hypothesis: dict[str, object],
    assignment: dict[str, object],
    evidence_audio_path: Path,
    *,
    vocal_provenance_validated: bool = False,
    recomputed_features: AudioFeatures | None = None,
    evidence_audio_sha256: str | None = None,
) -> bool:
    """Bind lyric-specific CTC opening geometry to independent vocal acoustics.

    A generic vocal peak is not boundary-grade by itself.  It becomes a
    phonetic boundary only when the immutable baseline CTC row independently
    supplies a coherent first-mora geometry at the same canonical start.  The
    fusion never accepts local-retry geometry, fractured openings, truncation,
    or right-edge pileup.
    """
    if not vocal_provenance_validated and not vocal_onset_confirmation_provenance_is_valid(
        hypothesis, assignment, evidence_audio_path,
        recomputed_features=recomputed_features,
        evidence_audio_sha256=evidence_audio_sha256,
    ):
        return False
    try:
        assignment_time = float(assignment.get("timestamp"))
        hypothesis_time = float(hypothesis.get("raw_candidate_time"))
    except (TypeError, ValueError):
        return False
    if (
        not math.isfinite(assignment_time)
        or not math.isfinite(hypothesis_time)
        or canonicalize_lrc_time(assignment_time).centiseconds
        != canonicalize_lrc_time(hypothesis_time).centiseconds
        or bool(assignment.get("ctc_right_edge_pileup"))
        or bool(assignment.get("ctc_right_edge_truncation"))
    ):
        return False
    spans = _candidate_spans_from_assignment(assignment)
    if not spans:
        return False
    probe = make_timing_candidate(
        entry_index=0,
        entry_text="ctc-opening-geometry",
        source="ctc-current-geometry-probe",
        raw_time=assignment_time,
        spans=spans,
        confidence=_candidate_confidence(assignment),
        identity_support="supported",
        sequence_support="supported",
        current=False,
        right_edge_pileup=False,
        window_truncated=False,
        source_artifact={"geometry_only": True},
    )
    regions = analyze_candidate_regions(probe)
    return bool(
        regions.temporal_coherence == "coherent"
        and regions.onset_proof_end is not None
        and regions.fracture_region == "none"
        and not regions.severe_gap_indexes
        and abs(spans[0].start - canonicalize_lrc_time(assignment_time).seconds)
        <= HOP_SECONDS
    )


def vocal_activity_reentry_provenance_is_valid(
    hypothesis: dict[str, object],
    assignment: dict[str, object],
    evidence_audio_path: Path,
) -> bool:
    """Recompute isolated-vocal re-entry evidence from the bound audio.

    Serialized segment metadata is descriptive only. The validator must obtain
    the same activity segmentation from the actual vocal artifact before the
    direct-onset claim can become boundary-grade.
    """
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if (
        hypothesis.get("source") != "ctc-vocal-activity-reentry"
        or hypothesis.get("stage") != "independent-vocal-activity-reentry"
        or hypothesis.get("mode") != "coherent-ctc-plus-isolated-vocal-reentry"
        or hypothesis.get("authoritative") is not False
        or hypothesis.get("identity_support") != "supported"
        or hypothesis.get("sequence_support") != "supported"
        or hypothesis.get("direct_onset_support") != "supported"
    ):
        return False
    window = hypothesis.get("window")
    parent = hypothesis.get("parent")
    if not isinstance(window, dict) or not isinstance(parent, dict):
        return False
    if window.get("feature_revision") != VOCAL_ACTIVITY_REENTRY_FEATURE_REVISION:
        return False
    spans = hypothesis.get("spans")
    assignment_spans = assignment.get("ctc_token_spans")
    if not isinstance(spans, list) or not spans or spans != assignment_spans:
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        parent_time = float(parent.get("raw_candidate_time"))
        onset_time = float(hypothesis.get("direct_onset_time"))
        current_time = float(window.get("current_time"))
        segment_index = int(window.get("segment_index"))
        segment_start = float(window.get("segment_start"))
        segment_end = float(window.get("segment_end"))
        previous_segment_end = float(window.get("previous_segment_end"))
        gap_seconds = float(window.get("gap_seconds"))
        evidence_duration = float(window.get("audio_duration_seconds"))
    except (TypeError, ValueError):
        return False
    numeric = (
        raw_time, parent_time, onset_time, current_time, segment_start,
        segment_end, previous_segment_end, gap_seconds, evidence_duration,
    )
    if not all(math.isfinite(value) for value in numeric):
        return False
    if (
        not _serialized_seconds_equal(raw_time, parent_time)
        or not _serialized_seconds_equal(raw_time, current_time)
        or not _serialized_seconds_equal(onset_time, segment_start)
        or abs(segment_start - current_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
        or segment_end <= segment_start
        or gap_seconds + HOP_SECONDS * 0.51 < VOCAL_ACTIVITY_REENTRY_MIN_GAP_SECONDS
        or not _serialized_delta_matches(
            segment_start, previous_segment_end, gap_seconds, tolerance_microseconds=1
        )
        or evidence_duration <= 0.0
    ):
        return False
    try:
        if window.get("audio_sha256") != _path_sha256(evidence_audio_path):
            return False
        recomputed = analyze_audio(evidence_audio_path, evidence_duration)
        reentry = _vocal_activity_reentry_for_time(recomputed, raw_time)
    except (LrcError, OSError):
        return False
    if reentry is None:
        return False
    return bool(
        int(reentry["segment_index"]) == segment_index
        and abs(float(reentry["segment_start"]) - segment_start) <= HOP_SECONDS * 0.51
        and abs(float(reentry["segment_end"]) - segment_end) <= HOP_SECONDS * 0.51
        and abs(float(reentry["previous_segment_end"]) - previous_segment_end) <= HOP_SECONDS * 0.51
        and abs(float(reentry["gap_seconds"]) - gap_seconds) <= HOP_SECONDS * 0.51
    )


def phonetic_onset_fusion_provenance_is_valid(
    hypothesis: dict[str, object],
    assignment: dict[str, object],
    alignment_audio_path: Path,
) -> bool:
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if (
        hypothesis.get("source") != "ctc-phonetic-onset-fusion"
        or hypothesis.get("stage") != "independent-phonetic-onset-fusion"
        or hypothesis.get("mode") != "coherent-ctc-first-token-plus-independent-onset"
        or hypothesis.get("authoritative") is not False
    ):
        return False
    if (
        not assignment_content_is_trusted(assignment)
        or bool(assignment.get("ctc_right_edge_pileup"))
        or bool(assignment.get("ctc_right_edge_truncation"))
        or bool(ctc_path_fracture_evidence(assignment).get("fractured"))
    ):
        return False
    parent = hypothesis.get("parent")
    if (
        not isinstance(parent, dict)
        or parent.get("source") not in {"ctc-current", "ctc-vocal-onset-confirmed"}
    ):
        return False
    window = hypothesis.get("window")
    if not isinstance(window, dict) or window.get("feature_revision") != PHONETIC_ONSET_FEATURE_REVISION:
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        peak_time = float(window.get("ctc_peak_time"))
        peak_score = float(window.get("ctc_peak_score"))
        onset_time = float(window.get("onset_time"))
        onset_strength = float(window.get("onset_strength"))
        onset_prominence = float(window.get("onset_prominence"))
    except (TypeError, ValueError):
        return False
    try:
        current_assignment_raw = float(assignment.get("timestamp"))
        current_raw_time = float(window.get("current_raw_time"))
        current_written_centiseconds = int(window.get("current_written_centiseconds"))
        parent_time = float(parent.get("raw_candidate_time"))
        window_current_time = float(window.get("current_time"))
        top_acoustic_strength = float(hypothesis.get("acoustic_strength"))
        top_acoustic_time = float(hypothesis.get("acoustic_onset_time"))
        top_direct_time = float(hypothesis.get("direct_onset_time"))
    except (TypeError, ValueError):
        return False
    if not all(math.isfinite(value) for value in (
        raw_time, peak_time, peak_score, onset_time, onset_strength, onset_prominence,
        current_assignment_raw, current_raw_time, parent_time, window_current_time,
        top_acoustic_strength, top_acoustic_time, top_direct_time,
    )):
        return False
    current_written = canonicalize_lrc_time(current_assignment_raw)
    if (
        not _serialized_seconds_equal(raw_time, peak_time)
        or peak_score < PHONETIC_ONSET_MIN_POSTERIOR
        or abs(peak_time - current_written.seconds) > 0.50
        or not _serialized_seconds_equal(current_raw_time, current_assignment_raw)
        or current_written_centiseconds != current_written.centiseconds
        or canonicalize_lrc_time(current_raw_time).centiseconds != current_written_centiseconds
        or not _serialized_seconds_equal(parent_time, current_raw_time)
        or not _serialized_seconds_equal(window_current_time, current_written.seconds)
        or not isinstance(window.get("current_candidate_id"), str)
        or not window.get("current_candidate_id")
    ):
        return False
    if (
        hypothesis.get("identity_support") != "supported"
        or hypothesis.get("sequence_support") != "supported"
        or hypothesis.get("acoustic_support") != "supported"
        or hypothesis.get("direct_onset_support") != "supported"
        or abs(top_acoustic_strength - onset_strength) > 1e-6
        or not _serialized_seconds_equal(top_acoustic_time, onset_time)
        or not _serialized_seconds_equal(top_direct_time, onset_time)
    ):
        return False
    if abs(onset_time - raw_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS:
        return False
    if onset_strength < PHONETIC_ONSET_MIN_STRENGTH or onset_prominence < PHONETIC_ONSET_MIN_PROMINENCE:
        return False
    peaks = assignment.get("ctc_first_token_candidates")
    if not isinstance(peaks, list) or not any(
        isinstance(peak, dict)
        and _timing_content_digest(peak) == window.get("ctc_peak_digest")
        and _serialized_seconds_equal(peak.get("time", -9999.0), peak_time)
        for peak in peaks
    ):
        return False
    spans = _candidate_spans_from_assignment(assignment)
    if not spans:
        return False
    current = make_timing_candidate(
        entry_index=0,
        entry_text="provenance-check",
        source="ctc-current",
        raw_time=current_assignment_raw,
        spans=spans,
        confidence=_candidate_confidence(assignment),
        identity_support="supported",
        sequence_support="supported",
        current=True,
    )
    if analyze_candidate_regions(current).temporal_coherence != "coherent":
        return False
    try:
        evidence_duration = float(window.get("audio_duration_seconds"))
        if not math.isfinite(evidence_duration) or evidence_duration <= 0.0:
            return False
        if window.get("audio_sha256") != _path_sha256(alignment_audio_path):
            return False
        recomputed = analyze_vocal_onsets(alignment_audio_path, evidence_duration)
        recomputed_peak = _nearest_local_maximum(
            recomputed, peak_time, PHONETIC_ONSET_RADIUS_SECONDS
        )
    except (OSError, LrcError, TypeError, ValueError):
        return False
    if recomputed_peak is None:
        return False
    recomputed_time, recomputed_strength, recomputed_prominence = recomputed_peak
    return bool(
        abs(recomputed_time - onset_time) <= HOP_SECONDS * 0.51
        and abs(recomputed_strength - onset_strength) <= 1e-5
        and abs(recomputed_prominence - onset_prominence) <= 1e-5
        and recomputed_strength >= PHONETIC_ONSET_MIN_STRENGTH
        and recomputed_prominence >= PHONETIC_ONSET_MIN_PROMINENCE
    )


def mutual_recurrence_hypothesis_provenance_is_valid(
    hypothesis: dict[str, object],
    entry: LyricEntry,
    alignment_audio_path: Path,
    assignments: list[object],
    entries: list[LyricEntry],
    entry_index: int,
) -> bool:
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if (
        hypothesis.get("source") != "mutual-acoustic-recurrence"
        or hypothesis.get("stage") != "occurrence-level-mutual-recurrence-search"
        or hypothesis.get("mode") != "reciprocal-exact-duplicate-pitchclass-recurrence"
        or hypothesis.get("authoritative") is not False
    ):
        return False
    window = hypothesis.get("window")
    parent = hypothesis.get("parent")
    if not isinstance(window, dict) or not isinstance(parent, dict):
        return False
    if parent.get("source") != "reciprocal-untrusted-duplicate-pair":
        return False
    if window.get("feature_revision") != MUTUAL_RECURRENCE_FEATURE_REVISION:
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        target_entry = int(window.get("target_entry"))
        peer_entry = int(window.get("peer_entry"))
        peer_candidate = float(window.get("peer_candidate"))
        score = float(window.get("similarity"))
        margin = float(window.get("distinct_margin"))
        onset_strength = float(window.get("onset_strength"))
        onset_prominence = float(window.get("onset_prominence"))
    except (TypeError, ValueError):
        return False
    if target_entry != entry_index + 1 or not (1 <= peer_entry <= len(assignments)) or peer_entry == target_entry:
        return False
    if score < MUTUAL_RECURRENCE_MIN_SIMILARITY or margin < MUTUAL_RECURRENCE_MIN_DISTINCT_MARGIN:
        return False
    if onset_strength < 0.45 or onset_prominence < 0.10:
        return False
    expected_lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entry)).encode("utf-8")
    ).hexdigest()
    if window.get("normalized_lyric_sha256") != expected_lyric_sha:
        return False
    peer_index = peer_entry - 1
    if len(entries) != len(assignments):
        return False
    peer_normalized = normalize_match_text(entry_sung_text(entries[peer_index]))
    if not peer_normalized or peer_normalized != normalize_match_text(entry_sung_text(entry)):
        return False
    if hashlib.sha256(peer_normalized.encode("utf-8")).hexdigest() != expected_lyric_sha:
        return False
    current_assignment = assignments[entry_index]
    peer_assignment = assignments[peer_index]
    if not isinstance(current_assignment, dict) or not isinstance(peer_assignment, dict):
        return False
    current_identity = _bound_local_occurrence_identity(current_assignment)
    peer_identity = _bound_local_occurrence_identity(peer_assignment)
    if current_identity is None or peer_identity is None:
        return False
    left_entry = int(window.get("left_entry", -1))
    right_entry = int(window.get("right_entry", -1))
    if {target_entry, peer_entry} != {left_entry, right_entry} or left_entry >= right_entry:
        return False
    expected_current_identity = (
        window.get("left_identity_evidence") if target_entry == left_entry
        else window.get("right_identity_evidence")
    )
    expected_peer_identity = (
        window.get("right_identity_evidence") if target_entry == left_entry
        else window.get("left_identity_evidence")
    )
    if current_identity != expected_current_identity or peer_identity != expected_peer_identity:
        return False
    try:
        expected_raw = float(window.get("left_candidate") if target_entry == left_entry else window.get("right_candidate"))
        expected_peer_candidate = float(window.get("right_candidate") if target_entry == left_entry else window.get("left_candidate"))
    except (TypeError, ValueError):
        return False
    if (
        not _serialized_seconds_equal(raw_time, expected_raw)
        or not _serialized_seconds_equal(peer_candidate, expected_peer_candidate)
    ):
        return False
    peer_hypotheses = peer_assignment.get("alignment_hypotheses")
    pair_id = window.get("pair_id")
    reciprocal = next(
        (
            row for row in peer_hypotheses
            if isinstance(row, dict)
            and row.get("source") == "mutual-acoustic-recurrence"
            and isinstance(row.get("window"), dict)
            and row["window"].get("pair_id") == pair_id
            and int(row["window"].get("peer_entry", -1)) == target_entry
        ),
        None,
    ) if isinstance(peer_hypotheses, list) else None
    if not isinstance(reciprocal, dict):
        return False
    reciprocal_window = reciprocal.get("window")
    reciprocal_parent = reciprocal.get("parent")
    if not isinstance(reciprocal_window, dict) or not isinstance(reciprocal_parent, dict):
        return False
    if (
        reciprocal.get("stage") != "occurrence-level-mutual-recurrence-search"
        or reciprocal.get("mode") != "reciprocal-exact-duplicate-pitchclass-recurrence"
        or reciprocal.get("authoritative") is not False
        or reciprocal_parent.get("source") != "reciprocal-untrusted-duplicate-pair"
        or int(reciprocal_window.get("target_entry", -1)) != peer_entry
        or int(reciprocal_window.get("peer_entry", -1)) != target_entry
    ):
        return False
    reciprocal_projection = {
        key: reciprocal_window.get(key)
        for key in (
            "audio_sha256", "feature_revision", "normalized_lyric_sha256",
            "left_entry", "right_entry", "left_seed", "right_seed",
            "left_identity_evidence", "right_identity_evidence",
            "left_bounds", "right_bounds", "left_candidate", "right_candidate",
            "template_duration", "similarity", "runner_similarity", "distinct_margin",
        )
    }
    if _timing_content_digest(reciprocal_projection) != pair_id:
        return False
    try:
        reciprocal_time = float(reciprocal.get("raw_candidate_time"))
        reciprocal_peer = float(reciprocal_window.get("peer_candidate"))
    except (TypeError, ValueError):
        return False
    if (
        not _serialized_seconds_equal(reciprocal_time, peer_candidate)
        or not _serialized_seconds_equal(reciprocal_peer, raw_time)
    ):
        return False
    # The reciprocal row must bind to an actual exact duplicate LyricEntry,
    # not merely repeat the same hash inside mutable report provenance.
    if reciprocal_window.get("normalized_lyric_sha256") != expected_lyric_sha:
        return False
    try:
        if window.get("audio_sha256") != _path_sha256(alignment_audio_path):
            return False
    except (OSError, LrcError):
        return False
    # Recompute the pair-id projection so arbitrary field edits fail closed.
    pair_projection = {
        key: window.get(key)
        for key in (
            "audio_sha256", "feature_revision", "normalized_lyric_sha256",
            "left_entry", "right_entry", "left_seed", "right_seed",
            "left_identity_evidence", "right_identity_evidence",
            "left_bounds", "right_bounds", "left_candidate", "right_candidate",
            "template_duration", "similarity", "runner_similarity", "distinct_margin",
        )
    }
    if _timing_content_digest(pair_projection) != pair_id:
        return False
    return True


def trusted_tail_release_provenance_is_valid(
    hypothesis: dict[str, object],
    alignment_audio_path: Path,
    assignments: list[object],
    entry_index: int,
) -> bool:
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if (
        hypothesis.get("source") != "trusted-tail-release-onset"
        or hypothesis.get("stage") != "trusted-tail-release-onset-search"
        or hypothesis.get("mode") != "strong-onset-inside-centrally-trusted-tail-release"
        or hypothesis.get("authoritative") is not False
    ):
        return False
    window = hypothesis.get("window")
    parent = hypothesis.get("parent")
    if not isinstance(window, dict) or not isinstance(parent, dict):
        return False
    if parent.get("source") != "central-trusted-predecessor-tail":
        return False
    if window.get("feature_revision") != TAIL_RELEASE_FEATURE_REVISION:
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        start = float(window.get("search_start"))
        end = float(window.get("search_end"))
        strength = float(window.get("onset_strength"))
        prominence = float(window.get("onset_prominence"))
        tail_end = float(window.get("previous_tail_end"))
        old_raw_time = float(window.get("old_candidate_raw_time"))
        old_centiseconds = int(window.get("old_candidate_centiseconds"))
        old_time = float(window.get("old_candidate_time"))
        previous_onset_time = float(window.get("previous_onset_time"))
        cluster_gap = float(window.get("cluster_gap"))
        context_start = float(window.get("context_start"))
    except (TypeError, ValueError):
        return False
    if not (start <= raw_time <= end and _serialized_seconds_equal(start, tail_end)):
        return False
    if old_time > tail_end:
        return False
    if previous_onset_time >= raw_time:
        return False
    if not _serialized_delta_matches(
        raw_time, previous_onset_time, cluster_gap, tolerance_microseconds=1
    ):
        return False
    if cluster_gap < TAIL_RELEASE_CLUSTER_BREAK_SECONDS:
        return False
    if context_start > tail_end or tail_end - context_start > TAIL_RELEASE_CONTEXT_SECONDS + 1e-6:
        return False
    if strength < TAIL_RELEASE_ONSET_MIN_STRENGTH or prominence < TAIL_RELEASE_ONSET_MIN_PROMINENCE:
        return False
    if not isinstance(window.get("previous_candidate_id"), str) or not isinstance(window.get("previous_tail_revision"), str):
        return False
    if entry_index <= 0 or entry_index >= len(assignments):
        return False
    current_assignment = assignments[entry_index]
    previous_assignment = assignments[entry_index - 1]
    if not isinstance(current_assignment, dict) or not isinstance(previous_assignment, dict):
        return False
    try:
        current_assignment_raw = float(current_assignment.get("timestamp"))
    except (TypeError, ValueError):
        return False
    current_written = canonicalize_lrc_time(current_assignment_raw)
    if (
        not _serialized_seconds_equal(current_assignment_raw, old_raw_time)
        or old_centiseconds != current_written.centiseconds
        or canonicalize_lrc_time(old_raw_time).centiseconds != old_centiseconds
        or not _serialized_seconds_equal(current_written.seconds, old_time)
    ):
        return False
    try:
        return window.get("audio_sha256") == _path_sha256(alignment_audio_path)
    except (OSError, LrcError):
        return False

def _trusted_recurrence_reference_geometry(
    assignment: dict[str, object],
    reference: TimingCandidate,
) -> tuple[float, tuple[TimingTokenSpan, ...], dict[str, object]] | None:
    """Return evidence-first full-line geometry for a trusted repeat reference.

    The preferred geometry is the selected central candidate itself.  A selected
    Raw/WhisperX fusion candidate may legitimately carry no token spans, however.
    In that case a self-bound local CTC identity row may provide the *template
    geometry* only when its independently observed start already agrees with the
    trusted selected boundary within the existing cross-backend consensus
    tolerance.  The CTC row is never shifted to the final timestamp, so this does
    not back-fill evidence from the answer.
    """
    if reference.spans:
        return (
            reference.written_time.seconds,
            reference.spans,
            {
                "mode": "selected-candidate-spans",
                "reference_candidate_id": reference.candidate_id,
                "reference_generation_revision": reference.generation_revision,
                "geometry_revision": _timing_content_digest([
                    {
                        "token": span.token,
                        "start": round(span.start, 6),
                        "end": round(span.end, 6),
                        "score": round(span.score, 8),
                    }
                    for span in reference.spans
                ]),
            },
        )
    hypotheses = assignment.get("alignment_hypotheses")
    if not isinstance(hypotheses, list):
        return None
    eligible: list[tuple[float, float, tuple[TimingTokenSpan, ...], dict[str, object]]] = []
    for hypothesis in hypotheses:
        if (
            not isinstance(hypothesis, dict)
            or hypothesis.get("source") not in {
                "ctc-local-window",
                "ctc-opening-local-retry-identity",
            }
            or hypothesis.get("authoritative") is not False
            or hypothesis.get("identity_support") != "supported"
            or hypothesis.get("sequence_support") != "supported"
            or bool(hypothesis.get("window_truncated"))
            or bool(hypothesis.get("right_edge_pileup"))
            or not _self_bound_hypothesis_record(hypothesis)
        ):
            continue
        spans = _timing_spans_from_value(hypothesis.get("spans"))
        if len(spans) < 4:
            continue
        try:
            raw_time = float(hypothesis.get("raw_candidate_time"))
            confidence = float(hypothesis.get("confidence", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        if (
            not math.isfinite(raw_time)
            or abs(raw_time - reference.written_time.seconds)
            > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
        ):
            continue
        provenance = {
            "mode": "self-bound-local-ctc-geometry",
            "reference_candidate_id": reference.candidate_id,
            "reference_generation_revision": reference.generation_revision,
            "geometry_hypothesis_id": hypothesis.get("hypothesis_id"),
            "geometry_source": hypothesis.get("source"),
            "geometry_start": round(raw_time, 6),
            "selected_start": round(reference.written_time.seconds, 6),
            "agreement_seconds": round(abs(raw_time - reference.written_time.seconds), 6),
            "max_agreement_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
            "geometry_revision": _timing_content_digest(hypothesis.get("spans")),
        }
        eligible.append((
            _finite_unit_confidence(confidence),
            -abs(raw_time - reference.written_time.seconds),
            spans,
            provenance,
        ))
    if not eligible:
        return None
    confidence, _neg_delta, spans, provenance = max(
        eligible, key=lambda item: (item[0], item[1], str(item[3].get("geometry_hypothesis_id")))
    )
    return float(provenance["geometry_start"]), spans, provenance


def apply_global_acoustic_recurrence_hypotheses(
    alignment_audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    evaluated: EvaluatedBackendTiming,
    duration: float,
) -> list[dict[str, object]]:
    """Search the whole song for exact repeated-lyric occurrences.

    A reference occurrence is eligible only when the central evaluator has
    already trusted its timing.  The search is independent of the target MMS
    timestamp and uses the nearest centrally-trusted lyric-order anchors only
    as broad bounds.  No match is emitted unless the full-line acoustic match
    is both strong and separated from the best distinct alternative.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    try:
        features = acoustic_recurrence_features(alignment_audio_path)
        onset_features = analyze_vocal_onsets(alignment_audio_path, duration)
    except LrcError:
        return []
    audio_revision = hashlib.sha256(Path(alignment_audio_path).read_bytes()).hexdigest()
    groups: dict[str, list[int]] = {}
    for index, entry in enumerate(entries):
        normalized = normalize_match_text(entry_sung_text(entry))
        if normalized:
            groups.setdefault(normalized, []).append(index)
    trusted = [bool(audit.timing_trusted) for audit in evaluated.state.audits]
    generated: list[dict[str, object]] = []
    for normalized, indexes in groups.items():
        if len(indexes) < 2:
            continue
        for target_index in indexes:
            if trusted[target_index]:
                continue
            reference_geometry: dict[int, tuple[float, tuple[TimingTokenSpan, ...], dict[str, object]]] = {}
            for reference_index in indexes:
                if not trusted[reference_index] or not assignment_content_is_trusted(assignments[reference_index]):
                    continue
                reference_assignment = assignments[reference_index]
                if not isinstance(reference_assignment, dict):
                    continue
                geometry = _trusted_recurrence_reference_geometry(
                    reference_assignment, evaluated.state.decisions[reference_index].candidate
                )
                if geometry is not None:
                    reference_geometry[reference_index] = geometry
            reference_indexes = sorted(reference_geometry)
            if not reference_indexes:
                continue
            reference_index = min(reference_indexes, key=lambda index: abs(index - target_index))
            reference = evaluated.state.decisions[reference_index].candidate
            template_start, template_spans, geometry_provenance = reference_geometry[reference_index]
            template_end = template_spans[-1].end
            if target_index > reference_index:
                lower = next(
                    (evaluated.state.decisions[index].written_time.seconds + 0.20
                     for index in range(target_index - 1, -1, -1) if trusted[index]),
                    template_end + 0.50,
                )
                upper = next(
                    (evaluated.state.decisions[index].written_time.seconds - 0.20
                     for index in range(target_index + 1, len(entries)) if trusted[index]),
                    duration,
                )
            else:
                lower = next(
                    (evaluated.state.decisions[index].written_time.seconds + 0.20
                     for index in range(target_index - 1, -1, -1) if trusted[index]),
                    0.0,
                )
                upper = next(
                    (evaluated.state.decisions[index].written_time.seconds - 0.20
                     for index in range(target_index + 1, len(entries)) if trusted[index]),
                    template_start - 0.50,
                )
            result = _search_recurrence_start(features, template_start, template_end, lower, upper)
            if result is None:
                continue
            score = float(result["score"])
            margin = float(result["margin"])
            candidate_start = float(result["start"])
            if score < RECURRENCE_MIN_SIMILARITY or margin < RECURRENCE_MIN_DISTINCT_MARGIN:
                continue
            peak = _nearest_local_maximum(onset_features, candidate_start, 0.22)
            if peak is None:
                continue
            peak_time, peak_strength, peak_prominence = peak
            if peak_strength < 0.55 or peak_prominence < 0.18:
                continue
            projected_spans = _project_recurrence_spans_from_geometry(
                template_spans, template_start, candidate_start, score
            )
            if len(projected_spans) < 4:
                continue
            evidence_window = {
                "search_start": round(lower, 3),
                "search_end": round(upper, 3),
                "audio_sha256": audio_revision,
                "feature_revision": RECURRENCE_FEATURE_REVISION,
                "reference_entry": reference_index + 1,
                "reference_candidate_id": reference.candidate_id,
                "reference_selected_start": round(reference.written_time.seconds, 6),
                "reference_start": round(template_start, 3),
                "reference_end": round(template_end, 3),
                "reference_geometry": geometry_provenance,
                "similarity": round(score, 8),
                "runner_similarity": result["runner_score"],
                "distinct_margin": round(margin, 8),
                "normalized_lyric_sha256": hashlib.sha256(normalized.encode("utf-8")).hexdigest(),
            }
            hypothesis = record_alignment_hypothesis(
                assignments[target_index],
                source="global-acoustic-recurrence",
                stage="occurrence-level-global-recurrence-search",
                raw_time=candidate_start,
                confidence=max(0.0, min(1.0, score)),
                spans=projected_spans,
                identity_support="supported",
                sequence_support="supported",
                acoustic_support="supported",
                direct_onset_support="supported",
                acoustic_strength=peak_strength,
                acoustic_onset_time=peak_time,
                acoustic_evidence_producer="global-recurrence-search",
                acoustic_evidence_kind="recurrence-onset",
                direct_onset_time=peak_time,
                direct_onset_evidence_producer="global-recurrence-search",
                direct_onset_evidence_kind="recurrence-onset",
                parent_source="central-trusted-repeat-reference",
                parent_time=template_start,
                window=evidence_window,
                mode="full-line-acoustic-recurrence-with-trusted-reference",
            )
            generated.append({
                "entry": target_index + 1,
                "reference_entry": reference_index + 1,
                "candidate": round(candidate_start, 3),
                "similarity": round(score, 6),
                "distinct_margin": round(margin, 6),
                "peak_time": round(peak_time, 3),
                "peak_strength": round(peak_strength, 6),
                "hypothesis_id": hypothesis.get("hypothesis_id"),
            })
    report["global_acoustic_recurrence_hypotheses"] = generated
    report["global_acoustic_recurrence_count"] = len(generated)
    report["global_acoustic_recurrence_authoritative"] = False
    report["global_acoustic_recurrence_mutates_baseline"] = False
    return generated


def recurrence_hypothesis_provenance_is_valid(
    hypothesis: dict[str, object],
    entry: LyricEntry,
    alignment_audio_path: Path,
) -> bool:
    """Re-bind recurrence authority to its immutable evidence, not its source label."""
    if not _self_bound_hypothesis_record(hypothesis):
        return False
    if hypothesis.get("source") != "global-acoustic-recurrence":
        return False
    if hypothesis.get("stage") != "occurrence-level-global-recurrence-search":
        return False
    if hypothesis.get("mode") != "full-line-acoustic-recurrence-with-trusted-reference":
        return False
    if hypothesis.get("authoritative") is not False:
        return False
    parent = hypothesis.get("parent")
    window = hypothesis.get("window")
    if not isinstance(parent, dict) or parent.get("source") != "central-trusted-repeat-reference":
        return False
    if not isinstance(window, dict):
        return False
    try:
        raw_time = float(hypothesis.get("raw_candidate_time"))
        search_start = float(window.get("search_start"))
        search_end = float(window.get("search_end"))
        similarity = float(window.get("similarity"))
        margin = float(window.get("distinct_margin"))
    except (TypeError, ValueError):
        return False
    if not all(math.isfinite(value) for value in (raw_time, search_start, search_end, similarity, margin)):
        return False
    if not (search_start <= raw_time < search_end):
        return False
    if similarity < RECURRENCE_MIN_SIMILARITY or margin < RECURRENCE_MIN_DISTINCT_MARGIN:
        return False
    if window.get("feature_revision") != RECURRENCE_FEATURE_REVISION:
        return False
    reference_candidate_id = window.get("reference_candidate_id")
    if not isinstance(reference_candidate_id, str) or not reference_candidate_id:
        return False
    expected_lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entry)).encode("utf-8")
    ).hexdigest()
    if window.get("normalized_lyric_sha256") != expected_lyric_sha:
        return False
    try:
        expected_audio_sha = _path_sha256(alignment_audio_path)
    except (OSError, LrcError):
        return False
    return bool(window.get("audio_sha256") == expected_audio_sha)


def ratio_percent(part: int, total: int) -> float:
    return round(part * 100 / max(1, total), 2)


def compact_latin(text: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", unicodedata.normalize("NFKC", text).lower())


def japanese_romaji(text: str) -> str | None:
    converter = optional_kakasi_converter()
    if converter is None:
        return None
    try:
        converted = converter.convert(text)  # type: ignore[attr-defined]
    except Exception:
        return None
    romaji = "".join(str(item.get("hepburn", "")) for item in converted if isinstance(item, dict))
    romaji = compact_latin(romaji)
    return romaji or None


def romaji_morae(romaji: str) -> list[str]:
    morae: list[str] = []
    cursor = 0
    while cursor < len(romaji):
        if romaji[cursor] == "n" and (cursor + 1 == len(romaji) or romaji[cursor + 1] not in "aeiouy"):
            morae.append("n")
            cursor += 1
            continue
        match = re.match(r"(?:[bcdfghjklmnpqrstvwxyz]*)(?:a|i|u|e|o)", romaji[cursor:])
        if match:
            morae.append(match.group(0))
            cursor += len(match.group(0))
        else:
            morae.append(romaji[cursor])
            cursor += 1
    return morae


def lyric_identity_revision(entries: list[LyricEntry]) -> str:
    """Digest the exact immutable sung-text sequence used by all timing evidence."""
    return _timing_content_digest(
        [unicodedata.normalize("NFKC", entry_sung_text(entry)) for entry in entries]
    )


def assert_lyric_identity_contract(
    entries: list[LyricEntry],
    report: dict[str, object],
    *,
    initialize: bool = False,
) -> str:
    """Fail closed if any report-side phonetic anchor no longer matches source lyrics."""
    revision = lyric_identity_revision(entries)
    existing = report.get("lyric_entry_revision")
    if existing is None:
        if initialize:
            report["lyric_entry_revision"] = revision
        else:
            raise LrcError("Missing immutable lyric-entry revision")
    elif existing != revision:
        raise LrcError("Lyric content changed after timing evidence was generated")

    suspicious = report.get("suspicious_alignments")
    if isinstance(suspicious, list):
        for row in suspicious:
            if not isinstance(row, dict):
                continue
            entry_number = row.get("entry")
            profile = row.get("anchor_profile")
            if not isinstance(entry_number, int) or not isinstance(profile, dict):
                continue
            if not 1 <= entry_number <= len(entries):
                raise LrcError(f"Anchor profile entry {entry_number} is outside lyric range")
            profile_text = profile.get("entry_text")
            if not isinstance(profile_text, str):
                continue
            expected = unicodedata.normalize("NFKC", entry_sung_text(entries[entry_number - 1]))
            observed = unicodedata.normalize("NFKC", profile_text)
            if observed != expected:
                raise LrcError(
                    f"Phonetic anchor text diverged at entry {entry_number}: "
                    f"expected {expected!r}, got {observed!r}"
                )
    return revision


def lyric_anchor_profile(entry: LyricEntry) -> dict[str, object]:
    text = entry_sung_text(entry)
    normalized = normalize_match_text(text)
    romaji = japanese_romaji(text)
    profile: dict[str, object] = {
        "entry_text": text,
        "normalized_prefix": normalized[:8],
        "normalized_suffix": normalized[-8:] if normalized else "",
    }
    if romaji:
        morae = romaji_morae(romaji)
        profile.update(
            {
                "phonetic_system": "ja-hepburn-pykakasi",
                "romaji": romaji,
                "romaji_prefix": romaji[:12],
                "romaji_suffix": romaji[-12:],
                "first_mora": morae[0] if morae else "",
                "last_mora": morae[-1] if morae else "",
            }
        )
    else:
        latin = compact_latin(text)
        if latin:
            profile.update(
                {
                    "phonetic_system": "latin-fallback",
                    "romaji": latin,
                    "romaji_prefix": latin[:12],
                    "romaji_suffix": latin[-12:],
                }
            )
        else:
            profile["phonetic_system"] = "unavailable"
    return profile


def repeated_leading_term(text: str) -> tuple[str, int]:
    """Return a visibly repeated opening term, without guessing word breaks."""
    terms = [
        normalize_match_text(term)
        for term in re.split(r"[\s\u3000,、，。！？!?・]+", unicodedata.normalize("NFKC", text).strip())
    ]
    terms = [term for term in terms if term]
    if len(terms) < 2 or len(terms[0]) < 2:
        return "", 0
    first = terms[0]
    repeated = 1
    for term in terms[1:]:
        if term.startswith(first):
            repeated += 1
        else:
            break
    return (first, repeated) if repeated >= 2 else ("", 0)


def has_ambiguous_lyric_prefix(entries: list[LyricEntry], index: int) -> bool:
    """Detect long shared prefixes that make raw-ASR line matching ambiguous."""
    if not (0 <= index < len(entries)):
        return False
    target = normalize_match_text(entry_sung_text(entries[index]))
    if len(target) < 12:
        return False
    for other_index, other_entry in enumerate(entries):
        if other_index == index:
            continue
        other = normalize_match_text(entry_sung_text(other_entry))
        if len(other) < 12:
            continue
        shared = 0
        for left, right in zip(target, other):
            if left != right:
                break
            shared += 1
        # Twelve shared characters (or most of a shorter long phrase) makes a
        # raw segment match non-unique. It may identify the right *phrase*
        # while still selecting the wrong occurrence in the song.
        required = min(12, max(8, min(len(target), len(other)) // 2))
        if shared >= required:
            return True
    return False


def has_short_duplicate_context(entries: list[LyricEntry], index: int, window: int = 8) -> bool:
    """Return true when a short line can be confused with a nearby longer line."""
    if not (0 <= index < len(entries)):
        return False
    target = normalize_match_text(entry_sung_text(entries[index]))
    if len(target) < 4 or len(target) > 12:
        return False
    start = max(0, index - window)
    end = min(len(entries), index + window + 1)
    for other_index in range(start, end):
        if other_index == index:
            continue
        other = normalize_match_text(entry_sung_text(entries[other_index]))
        if len(other) <= len(target):
            continue
        if target in other:
            return True
    return False


def infer_spoken_language(entries: list[LyricEntry]) -> str:
    sample = "".join(entry_sung_text(entry) for entry in entries[:12])
    if not sample:
        return "ja"
    latin_count = sum(1 for ch in sample if ("A" <= ch <= "Z") or ("a" <= ch <= "z"))
    kana_count = sum(1 for ch in sample if "\u3040" <= ch <= "\u30ff")
    cjk_count = sum(1 for ch in sample if "\u3400" <= ch <= "\u9fff")
    total_text = max(1, latin_count + kana_count + cjk_count)
    if latin_count / total_text >= 0.55:
        return "en"
    if kana_count > 0:
        return "ja"
    if cjk_count > 0:
        return "zh"
    return "ja"


def sequence_ratio(left: str, right: str) -> float:
    if not left or not right:
        return 0.0
    # difflib is good enough here because Japanese lyrics are short and ordered.
    import difflib

    return difflib.SequenceMatcher(None, left, right).ratio()


def lyric_segment_score(entry_text: str, segment_text: str) -> float:
    if not entry_text or not segment_text:
        return 0.0
    score = sequence_ratio(entry_text, segment_text)
    if entry_text in segment_text:
        score = max(score, 0.96)
    elif segment_text in entry_text and len(segment_text) >= 4:
        score = max(score, 0.72)
    return score


def suffix_char_time(entry_text: str, segment: AsrSegment) -> float | None:
    if not entry_text or not segment.chars:
        return None
    segment_text = "".join(char for char, _ in segment.chars)
    if not segment_text.endswith(entry_text):
        return None

    import difflib

    matcher = difflib.SequenceMatcher(None, entry_text, segment_text, autojunk=False)
    if matcher.ratio() < 0.75:
        return None
    blocks = [block for block in matcher.get_matching_blocks() if block.size > 0]
    if not blocks or blocks[0].b <= 0:
        return None
    char_time = segment.chars[blocks[0].b][1]
    if not (segment.start - 0.10 <= char_time <= segment.end + 0.10):
        return None
    if char_time - segment.start > 1.0:
        return None
    return char_time


def segment_char_time(entry_text: str, segment: AsrSegment) -> float | None:
    if not entry_text or not segment.chars:
        return None
    segment_text = "".join(char for char, _ in segment.chars)
    exact_index = segment_text.find(entry_text)
    if exact_index >= 0:
        char_time = segment.chars[exact_index][1]
        if segment.start - 0.10 <= char_time <= segment.end + 0.10:
            return char_time
        return None
    return suffix_char_time(entry_text, segment)


def _aligned_exact_target_matches(
    entry_text: str,
    segments: list[AsrSegment],
) -> tuple[dict[str, object], ...]:
    """Return exact WhisperX character-stream matches for one immutable lyric.

    Unlike :func:`segment_char_time`, this stream may cross adjacent WhisperX
    segments.  Every returned onset is still a real forced-character timestamp;
    no interpolation or candidate-time proximity is used.  A match containing a
    severe internal time fracture is rejected rather than bridged.
    """
    target = normalize_match_text(entry_text)
    if not target:
        return ()
    stream: list[tuple[str, float, int]] = []
    for segment_index, segment in enumerate(segments):
        for char, raw_time in segment.chars:
            normalized = normalize_match_text(char)
            if not normalized:
                continue
            try:
                char_time = float(raw_time)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(char_time):
                continue
            for item in normalized:
                stream.append((item, char_time, segment_index))
    if len(stream) < len(target):
        return ()
    stream_text = "".join(item[0] for item in stream)
    matches: list[dict[str, object]] = []
    search_at = 0
    while True:
        start = stream_text.find(target, search_at)
        if start < 0:
            break
        end = start + len(target)
        observed = stream[start:end]
        times = [item[1] for item in observed]
        segment_indexes = [item[2] for item in observed]
        search_at = start + 1
        if (
            any(left > right for left, right in zip(times, times[1:]))
            or any(
                right - left >= CTC_SEVERE_INTERNAL_GAP_SECONDS
                for left, right in zip(times, times[1:])
            )
            or any(left > right for left, right in zip(segment_indexes, segment_indexes[1:]))
        ):
            continue
        payload = {
            "target_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
            "start_char_index": start,
            "end_char_index": end,
            "onset_time": round(times[0], 6),
            "last_char_time": round(times[-1], 6),
            "start_segment_index": segment_indexes[0],
            "end_segment_index": segment_indexes[-1],
            "char_count": len(observed),
        }
        matches.append({**payload, "match_revision": _timing_content_digest(payload)})
    return tuple(matches)


def _occurrence_binding_time_bounds(
    binding: object,
    entry_index: int,
) -> tuple[float | None, float | None]:
    """Return proven left/right timing bounds around a context-bound target."""
    if not isinstance(binding, dict):
        return None, None
    mode = binding.get("mode")
    if mode == "sequence-bracket":
        try:
            return float(binding.get("left_timestamp")), float(binding.get("right_timestamp"))
        except (TypeError, ValueError):
            return None, None
    if mode != "sparse-sequence-bracket":
        return None, None
    indexes = binding.get("anchor_entry_indexes")
    timestamps = binding.get("anchor_timestamps")
    if not isinstance(indexes, list) or not isinstance(timestamps, list) or len(indexes) != len(timestamps):
        return None, None
    left_values: list[tuple[int, float]] = []
    right_values: list[tuple[int, float]] = []
    for raw_index, raw_time in zip(indexes, timestamps):
        try:
            anchor_index = int(raw_index)
            anchor_time = float(raw_time)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(anchor_time):
            continue
        if anchor_index < entry_index:
            left_values.append((anchor_index, anchor_time))
        elif anchor_index > entry_index:
            right_values.append((anchor_index, anchor_time))
    left_time = max(left_values, key=lambda item: item[0])[1] if left_values else None
    right_time = min(right_values, key=lambda item: item[0])[1] if right_values else None
    return left_time, right_time


def _select_unique_aligned_target_match(
    entry_text: str,
    segments: list[AsrSegment],
    *,
    occurrence_binding: object = None,
    entry_index: int,
    preferred_segment_number: int | None = None,
) -> dict[str, object] | None:
    """Select an exact char-stream match only when evidence makes it unique.

    Context timing bounds and an already observed target segment are filters, not
    nearest-neighbour selectors.  If more than one exact match survives, timing
    evidence remains unavailable.
    """
    matches = list(_aligned_exact_target_matches(entry_text, segments))
    if not matches:
        return None
    left_time, right_time = _occurrence_binding_time_bounds(occurrence_binding, entry_index)
    if left_time is not None:
        matches = [item for item in matches if float(item["onset_time"]) > left_time - HOP_SECONDS]
    if right_time is not None:
        matches = [item for item in matches if float(item["onset_time"]) < right_time + HOP_SECONDS]
    if preferred_segment_number is not None and preferred_segment_number >= 1:
        preferred_index = preferred_segment_number - 1
        preferred = [
            item for item in matches
            if int(item["start_segment_index"]) <= preferred_index <= int(item["end_segment_index"])
        ]
        if len(preferred) == 1:
            return preferred[0]
        if preferred:
            matches = preferred
    return matches[0] if len(matches) == 1 else None


def _aligned_target_prefix_matches(
    entry_text: str,
    segments: list[AsrSegment],
) -> tuple[dict[str, object], ...]:
    """Return forced-character matches for a strong immutable lyric prefix.

    This is a target-opening proof, not a replacement for occurrence identity.
    It is consumed only after a full/sparse sequence binding has independently
    established which lyric occurrence is in the local window.  For long lines
    the first six normalized characters are required exactly; shorter lines
    require the entire normalized text.  Every onset is a real WhisperX forced
    character timestamp and internally fractured matches are rejected.
    """
    target = normalize_match_text(entry_text)
    if not target:
        return ()
    prefix_length = min(len(target), 6)
    if prefix_length < 2:
        return ()
    prefix = target[:prefix_length]
    stream: list[tuple[str, float, int]] = []
    for segment_index, segment in enumerate(segments):
        for char, raw_time in segment.chars:
            normalized = normalize_match_text(char)
            if not normalized:
                continue
            try:
                char_time = float(raw_time)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(char_time):
                continue
            for item in normalized:
                stream.append((item, char_time, segment_index))
    if len(stream) < prefix_length:
        return ()
    stream_text = "".join(item[0] for item in stream)
    matches: list[dict[str, object]] = []
    search_at = 0
    while True:
        start = stream_text.find(prefix, search_at)
        if start < 0:
            break
        end = start + prefix_length
        observed = stream[start:end]
        times = [item[1] for item in observed]
        segment_indexes = [item[2] for item in observed]
        search_at = start + 1
        if (
            any(left > right for left, right in zip(times, times[1:]))
            or any(
                right - left >= CTC_SEVERE_INTERNAL_GAP_SECONDS
                for left, right in zip(times, times[1:])
            )
            or any(left > right for left, right in zip(segment_indexes, segment_indexes[1:]))
        ):
            continue
        payload = {
            "target_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
            "prefix_sha256": hashlib.sha256(prefix.encode("utf-8")).hexdigest(),
            "prefix_char_count": prefix_length,
            "start_char_index": start,
            "end_char_index": end,
            "onset_time": round(times[0], 6),
            "last_char_time": round(times[-1], 6),
            "start_segment_index": segment_indexes[0],
            "end_segment_index": segment_indexes[-1],
        }
        matches.append({**payload, "match_revision": _timing_content_digest(payload)})
    return tuple(matches)



def _aligned_exact_phonetic_target_matches(
    entry_text: str,
    segments: list[AsrSegment],
) -> tuple[dict[str, object], ...]:
    """Return exact phonetic identity matches across aligned segment text.

    This is *content identity only*.  Whisper may spell the same Japanese sound
    with kana/kanji variants that defeat exact Unicode character matching even
    though the recognized phonetic sequence is exact.  We therefore compare a
    compact romanized stream, but never convert a segment start into direct-onset
    evidence.  Any later timing proof still needs real forced-character or
    independent acoustic onset evidence.
    """
    target = compact_latin(japanese_romaji(entry_text) or entry_text)
    if len(target) < 4:
        return ()

    stream: list[tuple[str, int]] = []
    segment_phonetics: list[str] = []
    for segment_index, segment in enumerate(segments):
        phonetic = compact_latin(japanese_romaji(segment.text) or segment.text)
        segment_phonetics.append(phonetic)
        for item in phonetic:
            stream.append((item, segment_index))
    if len(stream) < len(target):
        return ()

    stream_text = "".join(item[0] for item in stream)
    matches: list[dict[str, object]] = []
    search_at = 0
    while True:
        start = stream_text.find(target, search_at)
        if start < 0:
            break
        end = start + len(target)
        observed = stream[start:end]
        search_at = start + 1
        segment_indexes = [item[1] for item in observed]
        if any(left > right for left, right in zip(segment_indexes, segment_indexes[1:])):
            continue
        start_segment = segment_indexes[0]
        end_segment = segment_indexes[-1]
        fractured = False
        for left_index in range(start_segment, end_segment):
            try:
                gap = float(segments[left_index + 1].start) - float(segments[left_index].end)
            except (TypeError, ValueError, IndexError):
                fractured = True
                break
            if not math.isfinite(gap) or gap >= CTC_SEVERE_INTERNAL_GAP_SECONDS:
                fractured = True
                break
        if fractured:
            continue
        payload = {
            "target_phonetic_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
            "start_phonetic_index": start,
            "end_phonetic_index": end,
            "start_segment_index": start_segment,
            "end_segment_index": end_segment,
            "phonetic_char_count": len(target),
            "phonetic_score": round(lyric_segment_score(target, target), 6),
        }
        matches.append({**payload, "match_revision": _timing_content_digest(payload)})
    return tuple(matches)


def _select_unique_aligned_target_prefix_match(
    entry_text: str,
    segments: list[AsrSegment],
    *,
    occurrence_binding: object,
    entry_index: int,
    preferred_segment_number: int | None = None,
) -> dict[str, object] | None:
    """Select one context-bound forced prefix onset without nearest-time voting."""
    if not _occurrence_binding_has_strong_context(occurrence_binding):
        return None
    matches = list(_aligned_target_prefix_matches(entry_text, segments))
    if not matches:
        return None
    left_time, right_time = _occurrence_binding_time_bounds(occurrence_binding, entry_index)
    if left_time is not None:
        matches = [item for item in matches if float(item["onset_time"]) > left_time - HOP_SECONDS]
    if right_time is not None:
        matches = [item for item in matches if float(item["onset_time"]) < right_time + HOP_SECONDS]
    if preferred_segment_number is not None and preferred_segment_number >= 1:
        preferred_index = preferred_segment_number - 1
        preferred = [
            item for item in matches
            if int(item["start_segment_index"]) <= preferred_index <= int(item["end_segment_index"])
        ]
        if len(preferred) == 1:
            return preferred[0]
        if preferred:
            matches = preferred
    return matches[0] if len(matches) == 1 else None


def estimated_segment_text_time(entry_text: str, raw_entry_text: str, segment: AsrSegment) -> float | None:
    if not entry_text:
        return None
    segment_text = normalize_match_text(segment.text)
    if not segment_text:
        return None

    match_index = segment_text.find(entry_text)
    match_basis_length = len(segment_text)
    if match_index < 0:
        raw_entry_romaji = japanese_romaji(raw_entry_text) or compact_latin(raw_entry_text)
        segment_romaji = japanese_romaji(segment.text) or compact_latin(segment.text)
        if not raw_entry_romaji or not segment_romaji:
            return None
        for prefix_length in range(min(len(raw_entry_romaji), 18), 4, -1):
            prefix = raw_entry_romaji[:prefix_length]
            match_index = segment_romaji.find(prefix)
            if match_index >= 0:
                match_basis_length = len(segment_romaji)
                break
        else:
            return None

    if match_index <= 0:
        return segment.start
    segment_duration = max(0.0, segment.end - segment.start)
    if segment_duration <= 0.05 or match_basis_length <= 0:
        return None
    fraction = min(0.95, max(0.0, match_index / match_basis_length))
    estimated = segment.start + segment_duration * fraction
    if segment.start - 0.10 <= estimated <= segment.end + 0.10:
        return estimated
    return None


def is_instrumental_marker(entry: LyricEntry) -> bool:
    text = (entry.lines[0] if entry.lines else entry.alignment_text).strip()
    normalized = normalize_match_text(text)
    marker_text = text.strip("()[]{}").strip().lower()
    marker_words = ("instrumental", "intro", "interlude", "outro", "間奏", "イントロ", "アウトロ")
    return text == "♪" or not normalized or (text.startswith("(") and any(word in marker_text for word in marker_words))


def remove_instrumental_markers(entries: list[LyricEntry]) -> tuple[list[LyricEntry], list[dict[str, object]]]:
    kept: list[LyricEntry] = []
    skipped: list[dict[str, object]] = []
    for index, entry in enumerate(entries, 1):
        if is_instrumental_marker(entry):
            skipped.append(
                {
                    "entry": index,
                    "text": entry.lines[0] if entry.lines else entry.alignment_text,
                }
            )
        else:
            kept.append(entry)
    return kept, skipped


def default_whisper_cli() -> Path:
    return Path(__file__).resolve().parents[1] / "tools" / "whisper.cpp" / "Release" / "whisper-cli.exe"


def default_whisper_model() -> Path:
    return Path(__file__).resolve().parents[1] / "models" / "whisper.cpp" / "ggml-large-v3.bin"


def default_whisperx_python() -> Path:
    return Path(__file__).resolve().parents[1] / ".venv-asr" / "Scripts" / "python.exe"


def default_ctc_python() -> Path:
    return default_whisperx_python()


def default_whisperx_ready() -> bool:
    return default_whisper_cli().exists() and default_whisper_model().exists() and default_whisperx_python().exists()


def default_ctc_ready() -> bool:
    return default_ctc_python().exists() and (Path(__file__).resolve().parent / "ctc_align.py").exists()


def default_japanese_ctc_ready() -> bool:
    return default_ctc_python().exists() and (Path(__file__).resolve().parent / "japanese_ctc_align.py").exists()


def decode_temp_wav(audio_path: Path) -> Path:
    temp_dir = _managed_temp_dir(prefix="lrc_tools_whispercpp_")
    wav_path = temp_dir / "input.wav"
    proc = subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-v",
            "error",
            "-i",
            str(audio_path),
            "-ac",
            "1",
            "-ar",
            "16000",
            str(wav_path),
        ],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if proc.returncode != 0:
        raise LrcError(f"ffmpeg temp WAV decode failed: {proc.stderr.strip()}")
    return wav_path


def _run_whispercpp_wav(
    wav_path: Path,
    args: argparse.Namespace,
    *,
    suppress_nst: bool,
) -> list[AsrSegment]:
    """Run whisper.cpp on an already-decoded local WAV without changing its time origin."""
    cli_arg = getattr(args, "whisper_cli", None)
    cli = Path(cli_arg).expanduser().resolve() if cli_arg else default_whisper_cli()
    model_arg = getattr(args, "whisper_model", None)
    model = Path(model_arg).expanduser().resolve() if model_arg else default_whisper_model()
    if not cli.exists():
        raise LrcError(f"whisper.cpp CLI not found: {cli}")
    if not model.exists():
        raise LrcError(f"whisper.cpp model not found: {model}")

    output_base = wav_path.with_suffix("")
    command = [
        str(cli),
        "-m", str(model),
        "-l", args.whisper_language,
        "-oj", "-ojf",
        "-of", str(output_base),
    ]
    if suppress_nst:
        command.append("-sns")
    command.append(str(wav_path))
    json_path = output_base.with_suffix(".json")
    _remove_stale_output(json_path)
    proc = run_command(command)
    if proc.returncode != 0:
        raise LrcError(f"whisper.cpp failed: {proc.stderr.strip() or proc.stdout.strip()}")

    if not json_path.exists():
        raise LrcError(f"whisper.cpp did not write JSON output: {json_path}")
    payload = json.loads(json_path.read_text(encoding="utf-8"))
    segments: list[AsrSegment] = []
    for item in payload.get("transcription", []):
        offsets = item.get("offsets") or {}
        start = float(offsets.get("from", 0)) / 1000.0
        end = float(offsets.get("to", 0)) / 1000.0
        text = str(item.get("text", "")).strip()
        if text:
            segments.append(AsrSegment(start=start, end=end, text=text))
    if not segments:
        raise LrcError("whisper.cpp produced no transcription segments")
    return segments


def _parse_whispercpp_json(json_path: Path) -> list[AsrSegment]:
    payload = json.loads(json_path.read_text(encoding="utf-8"))
    segments: list[AsrSegment] = []
    for item in payload.get("transcription", []):
        offsets = item.get("offsets") or {}
        start = float(offsets.get("from", 0)) / 1000.0
        end = float(offsets.get("to", 0)) / 1000.0
        text = str(item.get("text", "")).strip()
        if text:
            segments.append(AsrSegment(start=start, end=end, text=text))
    if not segments:
        raise LrcError("whisper.cpp produced no transcription segments")
    return segments


@lru_cache(maxsize=8)
def _whispercpp_multifile_supported(cli_text: str, size: int, mtime_ns: int) -> bool:
    del size, mtime_ns
    try:
        proc = subprocess.run(
            [cli_text, "-h"], check=False,
            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
            text=True, encoding="utf-8", errors="replace", timeout=15.0,
        )
    except (OSError, subprocess.SubprocessError):
        return False
    help_text = (proc.stdout or "") + "\n" + (proc.stderr or "")
    return "file0 file1" in help_text or "file0 file1 ..." in help_text


def _run_whispercpp_wav_batch(
    items: list[tuple[str, Path]],
    args: argparse.Namespace,
    *,
    suppress_nst: bool,
) -> tuple[dict[str, list[AsrSegment]], dict[str, str]]:
    """Transcribe many already-decoded WAVs while loading ggml weights once per chunk.

    Modern whisper-cli accepts file0 file1 ... and initializes one whisper context
    before iterating the files.  If the installed binary does not support this or
    a chunk fails, that chunk falls back to the legacy one-file path.
    """
    results: dict[str, list[AsrSegment]] = {}
    errors: dict[str, str] = {}
    if not items:
        return results, errors
    cli_arg = getattr(args, "whisper_cli", None)
    cli = Path(cli_arg).expanduser().resolve() if cli_arg else default_whisper_cli()
    model_arg = getattr(args, "whisper_model", None)
    model = Path(model_arg).expanduser().resolve() if model_arg else default_whisper_model()
    if not cli.is_file() or not model.is_file():
        message = "whisper.cpp CLI/model unavailable"
        return results, {key: message for key, _ in items}
    try:
        stat = cli.stat()
        multi = _whispercpp_multifile_supported(str(cli), stat.st_size, stat.st_mtime_ns)
    except OSError:
        multi = False
    if not multi or len(items) == 1:
        for key, wav_path in items:
            try:
                results[key] = _run_whispercpp_wav(wav_path, args, suppress_nst=suppress_nst)
            except (LrcError, OSError, ValueError, json.JSONDecodeError) as exc:
                errors[key] = f"{type(exc).__name__}:{exc}"
        return results, errors

    chunks = [items[index:index + WHISPERCPP_LOCAL_BATCH_SIZE] for index in range(0, len(items), WHISPERCPP_LOCAL_BATCH_SIZE)]
    progress_log(
        f"local Whisper raw batch: files={len(items)} chunks={len(chunks)} "
        f"max_chunk={WHISPERCPP_LOCAL_BATCH_SIZE}"
    )
    for chunk_number, chunk in enumerate(chunks, start=1):
        command = [str(cli), "-m", str(model), "-l", args.whisper_language, "-oj", "-ojf"]
        if suppress_nst:
            command.append("-sns")
        for _key, wav_path in chunk:
            command.extend(["-of", str(wav_path.with_suffix(""))])
            _remove_stale_output(wav_path.with_suffix(".json"))
        command.extend(str(wav_path) for _key, wav_path in chunk)
        progress_log(
            f"local Whisper raw batch: chunk={chunk_number}/{len(chunks)} files={len(chunk)}"
        )
        try:
            proc = run_command(command)
        except (LrcError, OSError, subprocess.SubprocessError):
            proc = None
        chunk_ok = proc is not None and proc.returncode == 0
        if chunk_ok:
            for key, wav_path in chunk:
                json_path = wav_path.with_suffix(".json")
                if not json_path.is_file():
                    chunk_ok = False
                    break
        if not chunk_ok:
            progress_log(
                f"local Whisper raw batch: chunk={chunk_number} fallback=one-shot"
            )
            for key, wav_path in chunk:
                try:
                    results[key] = _run_whispercpp_wav(wav_path, args, suppress_nst=suppress_nst)
                except (LrcError, OSError, ValueError, json.JSONDecodeError) as exc:
                    errors[key] = f"{type(exc).__name__}:{exc}"
            continue
        for key, wav_path in chunk:
            try:
                results[key] = _parse_whispercpp_json(wav_path.with_suffix(".json"))
            except (LrcError, OSError, ValueError, json.JSONDecodeError) as exc:
                errors[key] = f"{type(exc).__name__}:{exc}"
    return results, errors


def run_whispercpp(audio_path: Path, args: argparse.Namespace, suppress_nst: bool | None = None) -> list[AsrSegment]:
    wav_path = decode_temp_wav(audio_path)
    use_suppress_nst = bool(args.whisper_suppress_nst) if suppress_nst is None else suppress_nst
    return _run_whispercpp_wav(wav_path, args, suppress_nst=bool(use_suppress_nst))


def decode_temp_wav_window(audio_path: Path, start: float, end: float) -> Path:
    """Decode an exact bounded audio window to local-time mono 16 kHz WAV."""
    if not all(math.isfinite(value) for value in (start, end)) or start < 0.0 or end <= start:
        raise LrcError("Invalid local Whisper audio window")
    temp_dir = _managed_temp_dir(prefix="lrc_tools_whisper_local_")
    wav_path = temp_dir / "input.wav"
    proc = subprocess.run(
        [
            "ffmpeg", "-y", "-v", "error",
            "-i", str(audio_path),
            "-ss", f"{start:.6f}",
            "-t", f"{end - start:.6f}",
            "-ac", "1", "-ar", "16000",
            str(wav_path),
        ],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    if proc.returncode != 0 or not wav_path.exists():
        raise LrcError(f"ffmpeg local Whisper decode failed: {proc.stderr.strip()}")
    return wav_path


def run_whisperx_alignment(
    audio_path: Path,
    transcript: list[dict[str, object]],
    args: argparse.Namespace,
    *,
    predecoded_wav: bool = False,
) -> dict[str, object]:
    python_arg = getattr(args, "whisperx_python", None)
    python_exe = Path(python_arg).expanduser().resolve() if python_arg else default_whisperx_python()
    helper = Path(__file__).resolve().parent / "whisperx_refine.py"
    if not python_exe.exists():
        raise LrcError(
            f"WhisperX Python environment not found: {python_exe}. "
            "Create .venv-asr and install whisperx, or pass --whisperx-python."
        )
    if not helper.exists():
        raise LrcError(f"WhisperX helper not found: {helper}")

    wav_path = audio_path if predecoded_wav else decode_temp_wav(audio_path)
    temp_dir = wav_path.parent
    transcript_path = temp_dir / "transcript.json"
    output_path = temp_dir / "whisperx-aligned.json"
    transcript_path.write_text(
        json.dumps(transcript, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    _remove_stale_output(output_path)
    proc = _run_model_helper_command(
        [
            str(python_exe),
            str(helper),
            "--audio",
            str(wav_path),
            "--transcript",
            str(transcript_path),
            "--output",
            str(output_path),
            "--language",
            args.whisper_language,
            "--device",
            args.whisperx_device,
        ],
        mode="whisperx",
    )
    if proc.returncode != 0:
        raise LrcError(f"WhisperX alignment failed: {proc.stderr.strip() or proc.stdout.strip()}")
    if not output_path.exists():
        raise LrcError(f"WhisperX helper did not write output: {output_path}")
    payload = json.loads(output_path.read_text(encoding="utf-8"))
    metadata = payload.get(_RUNTIME_WHISPERX_ALIGNMENT_METADATA_KEY)
    if isinstance(metadata, dict):
        output_payload = {
            key: value
            for key, value in payload.items()
            if key != _RUNTIME_WHISPERX_ALIGNMENT_METADATA_KEY
        }
        payload[_RUNTIME_WHISPERX_ALIGNMENT_METADATA_KEY] = {
            **metadata,
            "alignment_wav_sha256": _path_sha256(wav_path),
            "input_transcript_revision": _timing_content_digest(transcript),
            "output_revision": _timing_content_digest(output_payload),
        }
    return payload


def run_ctc_alignment(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
) -> tuple[list[float], dict[str, object]]:
    alignment_audio, audio_source, audio_note = prepare_vocal_ctc_audio(audio_path, args)
    if getattr(args, "vocal_ctc", True) and audio_source != "vocal-stem":
        raise LrcError(
            "Vocal CTC was requested but Demucs did not produce an isolated vocal stem: "
            f"{audio_note or 'unknown failure'}. Use --no-vocal-ctc only to explicitly allow full-mix CTC."
        )
    python_exe = default_ctc_python()
    try:
        vocal_identity = vocal_cache_identity(audio_path, python_exe)
    except OSError:
        vocal_identity = {}
    try:
        vocal_stem_sha256 = _path_sha256(alignment_audio) if alignment_audio.exists() else None
    except OSError:
        vocal_stem_sha256 = None
    helper = Path(__file__).resolve().parent / "ctc_align.py"
    if not python_exe.exists():
        raise LrcError(f"CTC Python environment not found: {python_exe}")
    if not helper.exists():
        raise LrcError(f"CTC helper not found: {helper}")

    with tempfile.TemporaryDirectory(prefix="lrc-ctc-") as temp_name:
        temp_dir = Path(temp_name)
        transcript_path = temp_dir / "transcript.json"
        output_path = temp_dir / "ctc-aligned.json"
        transcript_path.write_text(
            json.dumps([entry_sung_text(entry) for entry in entries], ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        proc = _run_model_helper_command(
            [
                str(python_exe),
                str(helper),
                "--audio",
                str(alignment_audio),
                "--transcript",
                str(transcript_path),
                "--output",
                str(output_path),
                "--device",
                args.whisperx_device,
            ],
            mode="ctc",
        )
        if proc.returncode != 0:
            raise LrcError(f"CTC forced alignment failed: {proc.stderr.strip() or proc.stdout.strip()}")
        if not output_path.exists():
            raise LrcError(f"CTC helper did not write output: {output_path}")
        payload = json.loads(output_path.read_text(encoding="utf-8"))

    rows = payload.get("entries")
    if not isinstance(rows, list) or len(rows) != len(entries):
        raise LrcError("CTC helper returned an invalid entry list")
    timestamps: list[float] = []
    assignments: list[dict[str, object]] = []
    missing: list[int] = []
    ctc_scores: list[float] = []
    low_score_entries: list[dict[str, object]] = []
    very_low_score_entries: list[dict[str, object]] = []
    low_score_entry_numbers: set[int] = set()
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            missing.append(index + 1)
            timestamps.append(timestamps[-1] + 0.10 if timestamps else 0.0)
            continue
        start = row.get("start")
        if start is None:
            missing.append(index + 1)
            timestamp = timestamps[-1] + 0.10 if timestamps else 0.0
        else:
            timestamp = float(start)
        timestamps.append(max(0.0, min(duration, timestamp)))
        raw_ctc_score = row.get("ctc_score")
        try:
            ctc_score = float(raw_ctc_score)
        except (TypeError, ValueError):
            ctc_score = 0.0
        if start is not None:
            ctc_scores.append(ctc_score)
            if ctc_score < 0.03:
                low_score_entry_numbers.add(index + 1)
                low_score_entries.append(
                    {
                        "entry": index + 1,
                        "text": entry_sung_text(entries[index]),
                        "ctc_score": round(ctc_score, 6),
                    }
                )
            if ctc_score < 0.01:
                very_low_score_entries.append(
                    {
                        "entry": index + 1,
                        "text": entry_sung_text(entries[index]),
                        "ctc_score": round(ctc_score, 6),
                    }
                )
        # A forced path always has a position, but a weak path is only a draft
        # candidate. Do not let its existence become a fake "trusted" result.
        confidence = 0.90 if ctc_score >= 0.08 else 0.70 if ctc_score >= 0.03 else 0.35
        assignments.append(
            {
                "entry": index + 1,
                "segment": None,
                "score": confidence if start is not None else 0.0,
                "ctc_score": round(ctc_score, 6),
                "romaji": row.get("romaji"),
                "ctc_token_spans": row.get("token_spans"),
                "ctc_first_token_candidates": row.get("first_token_candidates"),
                "timestamp": round(timestamps[-1], 3),
                "timing_repair": "ctc-forced-align",
                "timing_repair_source": "torchaudio-mms-fa",
            }
        )

    for index in range(1, len(timestamps)):
        timestamps[index] = max(timestamps[index], timestamps[index - 1] + 0.10)
        assignments[index]["timestamp"] = round(timestamps[index], 3)
    annotate_ctc_boundary_evidence(assignments)

    low_score_runs: list[list[int]] = []
    run: list[int] = []
    for entry_number in range(1, len(entries) + 1):
        if entry_number in low_score_entry_numbers:
            run.append(entry_number)
        else:
            if len(run) >= 4:
                low_score_runs.append(run)
            run = []
    if len(run) >= 4:
        low_score_runs.append(run)

    collapsed_entries = {entry_number for run in low_score_runs for entry_number in run}
    # A weak individual CTC path is still recorded as low confidence, but it is
    # not evidence that its timestamp is wrong by itself. Escalate only missing
    # alignments or a consecutive low-score collapse.
    ctc_review_entries = set(missing) | collapsed_entries
    suspicious_alignments: list[dict[str, object]] = []
    for entry_number in sorted(ctc_review_entries):
        entry_index = entry_number - 1
        is_missing = entry_number in missing
        is_collapsed = entry_number in collapsed_entries
        flags: list[str] = []
        if is_missing:
            flags.append("ctc_missing_alignment")
        if entry_number in low_score_entry_numbers:
            flags.append("ctc_low_path_confidence")
        if is_collapsed:
            flags.append("ctc_confidence_collapse")
        suspicious_alignments.append(
            {
                "entry": entry_number,
                "text": entry_sung_text(entries[entry_index]),
                "flags": flags,
                "severity": "high" if is_missing or is_collapsed else "medium",
                "review_required": True,
            }
        )

    report: dict[str, object] = {
        "backend": "ctc",
        "strategy": "ctc-forced-align",
        "ctc_backend": payload.get("backend", "mms_ctc"),
        "ctc_device": payload.get("device"),
        "ctc_sample_rate": payload.get("sample_rate"),
        "ctc_emission_frames": payload.get("emission_frames"),
        "ctc_audio_source": audio_source,
        "ctc_audio_path": str(alignment_audio),
        "ctc_audio_note": audio_note,
        **vocal_identity,
        "vocal_stem_sha256": vocal_stem_sha256,
        "timing_entries": len(entries),
        "assignments": assignments,
        "ctc_missing_entries": missing,
        "ctc_missing_count": len(missing),
        "ctc_score_min": round(min(ctc_scores), 6) if ctc_scores else None,
        "ctc_score_mean": round(sum(ctc_scores) / len(ctc_scores), 6) if ctc_scores else None,
        "ctc_low_score_threshold": 0.03,
        "ctc_very_low_score_threshold": 0.01,
        "ctc_low_score_count": len(low_score_entries),
        "ctc_very_low_score_count": len(very_low_score_entries),
        "ctc_low_score_entries": low_score_entries,
        "ctc_very_low_score_entries": very_low_score_entries,
        "ctc_low_score_runs": low_score_runs,
        "ctc_confidence_collapse": bool(low_score_runs),
        "suspicious_alignment_count": len(suspicious_alignments),
        "review_required_count": len(ctc_review_entries),
        "suspicious_alignment_severity_counts": {
            "high": sum(1 for item in suspicious_alignments if item["severity"] == "high"),
            "medium": sum(1 for item in suspicious_alignments if item["severity"] == "medium"),
            "low": 0,
        },
        "suspicious_alignments": suspicious_alignments,
        "review_required": bool(ctc_review_entries),
        "note": "MMS/CTC forced alignment over the known lyric order.",
    }
    capability_seed = create_bounded_retry_capability_seed(
        alignment_audio,
        audio_source,
        helper,
        sample_rate=int(payload.get("sample_rate") or SAMPLE_RATE),
        device=str(payload.get("device") or args.whisperx_device),
    )
    report["ctc_bounded_retry_capability_seed"] = capability_seed
    _attach_bounded_retry_runtime_capability(report, capability_seed)
    apply_ctc_acoustic_backtrack(alignment_audio, entries, timestamps, report, duration)
    report.update(inactive_legacy_timing_diagnostics())
    update_report_confidence_metrics(report)
    return timestamps, report


def run_japanese_ctc_alignment(
    audio_path: Path, entries: list[LyricEntry], duration: float, args: argparse.Namespace
) -> tuple[list[float], dict[str, object]]:
    python_exe = default_ctc_python()
    helper = Path(__file__).resolve().parent / "japanese_ctc_align.py"
    with tempfile.TemporaryDirectory(prefix="lrc-ja-ctc-") as temp_name:
        temp_dir = Path(temp_name)
        transcript_path = temp_dir / "transcript.json"
        output_path = temp_dir / "japanese-ctc.json"
        transcript_path.write_text(
            json.dumps([entry_sung_text(entry) for entry in entries], ensure_ascii=False), encoding="utf-8"
        )
        proc = run_command(
            [str(python_exe), str(helper), "--audio", str(audio_path), "--transcript", str(transcript_path), "--output", str(output_path), "--device", args.whisperx_device]
        )
        if proc.returncode != 0 or not output_path.exists():
            raise LrcError(f"Japanese CTC alignment failed: {proc.stderr.strip() or proc.stdout.strip()}")
        payload = json.loads(output_path.read_text(encoding="utf-8"))
    rows = payload.get("entries")
    if not isinstance(rows, list) or len(rows) != len(entries):
        raise LrcError("Japanese CTC helper returned an invalid entry list")
    timestamps = [max(0.0, min(duration, float(row.get("start", 0.0)))) for row in rows if isinstance(row, dict)]
    if len(timestamps) != len(entries):
        raise LrcError("Japanese CTC helper returned malformed timestamps")
    for index in range(1, len(timestamps)):
        timestamps[index] = max(timestamps[index], timestamps[index - 1] + 0.10)
    assignments = []
    for index, row in enumerate(rows):
        assert isinstance(row, dict)
        assignments.append(
            {
                "entry": index + 1,
                "segment": None,
                "score": 0.0,
                "ja_ctc_log_score": row.get("ja_ctc_log_score"),
                "ja_ctc_token_spans": row.get("token_spans"),
                "timestamp": round(timestamps[index], 3),
                "timing_repair": "japanese-ctc-forced-align",
                "timing_repair_source": "japanese-wav2vec2-ctc",
            }
        )
    collapse_entries = payload.get("collapse_entries") if isinstance(payload.get("collapse_entries"), list) else []
    report = {
        "backend": "jactc",
        "strategy": "japanese-ctc-forced-align-experimental",
        "ja_ctc_backend": payload.get("backend"),
        "ja_ctc_model": payload.get("model"),
        "ja_ctc_device": payload.get("device"),
        "ja_ctc_collapse_detected": bool(payload.get("collapse_detected")),
        "ja_ctc_collapse_entries": collapse_entries,
        "timing_entries": len(entries),
        "assignments": assignments,
        "review_required": bool(payload.get("collapse_detected")),
        "review_required_count": len(collapse_entries),
        "note": "Experimental Japanese Wav2Vec2 CTC candidate. Never selected by auto mode.",
    }
    update_report_confidence_metrics(report)
    return timestamps, report


def ctc_prefix_boundary_evidence(
    assignment: object, boundary_gap: float | None = None
) -> dict[str, object]:
    """Summarize multi-token evidence for a CTC line boundary."""
    empty: dict[str, object] = {
        "available": False,
        "boundary_gap_seconds": boundary_gap,
        "previous_token_score": None,
        "zero_boundary_gap": False,
        "unclear_boundary": True,
        "low_confidence_prefix": False,
        "abnormal_prefix_compression": False,
        "ghost_weak_prefix": False,
        "borrowed_tail_prefix": False,
        "near_gap_weak_prefix": False,
        "detached_weak_prefix": False,
        "unsupported_weak_prefix": False,
        "timestamp_precedes_ctc_support": False,
        "realign_required": False,
    }
    if not isinstance(assignment, dict):
        return empty
    if boundary_gap is None:
        try:
            boundary_gap = float(assignment.get("ctc_boundary_gap_seconds"))
        except (TypeError, ValueError):
            return empty
    spans = assignment.get("ctc_token_spans")
    if not isinstance(spans, list) or not spans:
        return empty
    try:
        effective_index = int(assignment.get("ctc_effective_token_start_index", 0) or 0)
    except (TypeError, ValueError):
        effective_index = 0
    effective_spans = [span for span in spans[effective_index:] if isinstance(span, dict)]
    if not effective_spans:
        return empty
    prefix_count = min(8, len(effective_spans))
    prefix = effective_spans[:prefix_count]
    try:
        starts = [float(span.get("start")) for span in prefix]
        ends = [float(span.get("end")) for span in prefix]
        scores = [float(span.get("score", 0.0) or 0.0) for span in prefix]
        ctc_score = float(assignment.get("ctc_score", 0.0) or 0.0)
    except (TypeError, ValueError):
        return empty
    if not starts or not ends or not scores:
        return empty
    prefix_span = max(ends) - min(starts)
    weak_count = sum(1 for score in scores if score < 0.05)
    prefix_mean = sum(scores) / len(scores)
    weak_ratio = weak_count / len(scores)
    reliable_index: int | None = None
    reliable_time: float | None = None
    reliable_score: float | None = None
    first_start = starts[0]
    try:
        boundary_start = float(assignment.get("timestamp", first_start))
    except (TypeError, ValueError):
        boundary_start = first_start
    for index, span in enumerate(effective_spans[:24]):
        try:
            score = float(span.get("score", 0.0) or 0.0)
            start = float(span.get("start"))
        except (TypeError, ValueError):
            continue
        if score >= 0.08:
            reliable_index = index
            reliable_time = start
            reliable_score = score
            break
    reliable_delay = reliable_time - boundary_start if reliable_time is not None else None
    timestamp_token_lead = first_start - boundary_start
    zero_gap = boundary_gap <= 0.04
    unclear = boundary_gap < 0.35 or scores[0] < 0.25
    enough_prefix = prefix_count >= 6
    low_prefix = (
        enough_prefix
        and scores[0] < 0.03
        and prefix_mean < 0.04
        and weak_ratio >= 0.625
    )
    compressed = (
        prefix_count >= 8
        and ctc_score <= 0.15
        and prefix_mean < 0.025
        and weak_ratio >= 0.875
        and prefix_span <= 0.42
    )
    delayed_reliable = reliable_delay is None or reliable_delay >= 0.70
    leading_count = min(3, len(scores))
    leading_weak_ratio = (
        sum(1 for score in scores[:leading_count] if score < 0.05) / leading_count
        if leading_count
        else 0.0
    )
    # A non-zero but very short inter-line gap can still contain one or more
    # ghost CTC characters borrowed from the previous lyric tail.
    ghost_weak_prefix = (
        boundary_gap <= 0.20
        and leading_count >= 3
        and scores[0] < 0.03
        and leading_weak_ratio >= (2.0 / 3.0)
        and (reliable_delay is None or reliable_delay >= 1.0)
    )
    # A 20-40 ms boundary with weak tail/head tokens is not an independent
    # lyric onset.  It is usually the forced path reusing the previous line's
    # release/reverb as the next line's first character.  Keep this separate
    # from ghost_weak_prefix because a genuinely supported token may appear
    # shortly afterwards (e.g. 100-200 ms) and the old delayed-reliable test
    # would otherwise incorrectly clear the boundary.
    try:
        previous_token_score = float(assignment.get("ctc_previous_token_score"))
    except (TypeError, ValueError):
        previous_token_score = 1.0
    borrowed_tail_prefix = (
        boundary_gap <= 0.06
        and scores[0] < 0.03
        and previous_token_score < 0.05
        and leading_count >= 3
        and leading_weak_ratio >= (2.0 / 3.0)
    )
    # ``zero_boundary_gap`` is intentionally very strict (<= 40 ms), but a
    # line can still steal the prior lyric tail with a nominal 60-150 ms gap.
    # Treat that boundary as suspect when almost the entire opening CTC prefix
    # is weak.  This catches the common "...again" -> next-line leak without
    # penalising a genuinely strong onset such as the recovered 02:47 line.
    near_gap_weak_prefix = (
        boundary_gap <= 0.15
        and unclear
        and enough_prefix
        and scores[0] < 0.25
        and prefix_mean < 0.08
        and weak_ratio >= 0.75
        and leading_weak_ratio >= (2.0 / 3.0)
    )
    # If a repair/backtrack moves the selected timestamp materially before
    # the first CTC token, the token score cannot be used as evidence for the
    # repaired timestamp.  Flag the mismatch so downstream validation does
    # not accidentally inherit stale first-token confidence.
    timestamp_precedes_ctc_support = timestamp_token_lead >= 0.35
    # A large inter-line gap does not make a weak opening trustworthy. Breath,
    # reverb and instrumental transients can absorb several CTC characters
    # before the first supported lyric token. Keep this separate from the
    # short-gap cross-line ghost case because the recovery must move forward,
    # not back toward the previous lyric tail.
    detached_weak_prefix = (
        boundary_gap >= 0.35
        and enough_prefix
        and scores[0] < 0.03
        and prefix_mean < 0.05
        and weak_ratio >= 0.625
        and leading_weak_ratio >= (2.0 / 3.0)
        and (reliable_delay is None or reliable_delay >= 0.70)
    )
    unsupported_weak_prefix = (
        enough_prefix
        and scores[0] < 0.03
        and prefix_mean < 0.04
        and weak_ratio >= 0.75
        and (reliable_delay is None or reliable_delay >= 0.70)
    )
    realign_required = (
        zero_gap
        and unclear
        and (compressed or (low_prefix and (ctc_score < 0.03 or delayed_reliable)))
    ) or ghost_weak_prefix or borrowed_tail_prefix or near_gap_weak_prefix or detached_weak_prefix or timestamp_precedes_ctc_support
    return {
        "available": True,
        "boundary_gap_seconds": round(boundary_gap, 3),
        "previous_token_score": assignment.get("ctc_previous_token_score"),
        "zero_boundary_gap": zero_gap,
        "unclear_boundary": unclear,
        "first_token_score": round(scores[0], 6),
        "prefix_token_count": prefix_count,
        "prefix_mean_score": round(prefix_mean, 6),
        "prefix_weak_ratio": round(weak_ratio, 3),
        "leading_three_weak_ratio": round(leading_weak_ratio, 3),
        "prefix_span_seconds": round(prefix_span, 3),
        "prefix_tokens_per_second": round(prefix_count / max(prefix_span, 0.02), 3),
        "low_confidence_prefix": low_prefix,
        "abnormal_prefix_compression": compressed,
        "ghost_weak_prefix": ghost_weak_prefix,
        "borrowed_tail_prefix": borrowed_tail_prefix,
        "near_gap_weak_prefix": near_gap_weak_prefix,
        "detached_weak_prefix": detached_weak_prefix,
        "unsupported_weak_prefix": unsupported_weak_prefix,
        "ctc_token_lead_seconds": round(timestamp_token_lead, 3),
        "timestamp_precedes_ctc_support": timestamp_precedes_ctc_support,
        "next_reliable_token_index": reliable_index,
        "next_reliable_token_time": round(reliable_time, 3) if reliable_time is not None else None,
        "next_reliable_token_score": round(reliable_score, 6) if reliable_score is not None else None,
        "reliable_token_delay_seconds": round(reliable_delay, 3) if reliable_delay is not None else None,
        "realign_required": realign_required,
    }


def has_ctc_compressed_prefix(assignment: object, boundary_gap: float | None = None) -> bool:
    evidence = ctc_prefix_boundary_evidence(assignment, boundary_gap)
    return bool(
        evidence.get("zero_boundary_gap")
        and evidence.get("abnormal_prefix_compression")
    )


def ctc_right_edge_pileup_evidence(assignment: object) -> dict[str, object]:
    """Detect a forced path that ran out of audio and packed its tail at a local window edge."""
    empty: dict[str, object] = {
        "available": False,
        "touches_window_end": False,
        "right_edge_pileup": False,
    }
    if not isinstance(assignment, dict):
        return empty
    local_window = assignment.get("ctc_local_window")
    spans = assignment.get("ctc_token_spans")
    if not isinstance(local_window, dict) or not isinstance(spans, list) or len(spans) < 8:
        return empty
    try:
        window_end = float(local_window.get("end"))
    except (TypeError, ValueError):
        return empty

    parsed_spans: list[tuple[float, float, float]] = []
    for span in spans:
        if not isinstance(span, dict):
            continue
        try:
            parsed_spans.append(
                (
                    float(span.get("start")),
                    float(span.get("end")),
                    float(span.get("score", 0.0) or 0.0),
                )
            )
        except (TypeError, ValueError):
            continue
    if len(parsed_spans) < 8:
        return empty

    tail_count = min(20, len(parsed_spans))
    tail = parsed_spans[-tail_count:]
    tail_start = min(item[0] for item in tail)
    tail_end = max(item[1] for item in tail)
    tail_span = max(0.02, tail_end - tail_start)
    scores = [item[2] for item in tail]
    tail_mean = sum(scores) / len(scores)
    weak_ratio = sum(1 for score in scores if score < 0.05) / len(scores)
    very_weak_ratio = sum(1 for score in scores if score < 0.02) / len(scores)
    tokens_per_second = tail_count / tail_span
    edge_margin = window_end - tail_end
    touches_window_end = -0.03 <= edge_margin <= 0.10
    right_edge_pileup = bool(
        touches_window_end
        and tokens_per_second >= 20.0
        and weak_ratio >= 0.80
        and very_weak_ratio >= 0.65
        and tail_mean < 0.04
    )
    return {
        "available": True,
        "window_end": round(window_end, 3),
        "tail_end": round(tail_end, 3),
        "edge_margin_seconds": round(edge_margin, 3),
        "tail_token_count": tail_count,
        "tail_span_seconds": round(tail_span, 3),
        "tail_tokens_per_second": round(tokens_per_second, 3),
        "tail_mean_score": round(tail_mean, 6),
        "tail_weak_ratio": round(weak_ratio, 3),
        "tail_very_weak_ratio": round(very_weak_ratio, 3),
        "touches_window_end": touches_window_end,
        "right_edge_pileup": right_edge_pileup,
    }


def annotate_ctc_boundary_evidence(assignments: list[object]) -> None:
    """Record sequence-level CTC boundaries so later candidates cannot steal a prior tail."""
    previous_token_end: float | None = None
    previous_token_score: float | None = None
    previous_right_edge_pileup = False
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            previous_token_end = None
            previous_token_score = None
            previous_right_edge_pileup = False
            continue
        spans = assignment.get("ctc_token_spans")
        if not isinstance(spans, list) or not spans:
            assignment.pop("ctc_boundary_gap_seconds", None)
            assignment.pop("ctc_clear_boundary", None)
            previous_token_end = None
            previous_token_score = None
            previous_right_edge_pileup = False
            continue
        try:
            effective_index = int(assignment.get("ctc_effective_token_start_index", 0) or 0)
            effective_index = max(0, min(effective_index, len(spans) - 1))
            first_span = spans[effective_index]
            first_start = float(first_span.get("start"))
            boundary_start = float(assignment.get("timestamp", first_start))
            first_score = float(first_span.get("score", 0.0) or 0.0)
        except (AttributeError, TypeError, ValueError):
            previous_token_end = None
            previous_token_score = None
            previous_right_edge_pileup = False
            continue
        token_ends: list[tuple[float, float]] = []
        for span in spans:
            if not isinstance(span, dict):
                continue
            try:
                token_ends.append(
                    (
                        float(span.get("end")),
                        float(span.get("score", 0.0) or 0.0),
                    )
                )
            except (TypeError, ValueError):
                continue
        if not token_ends:
            previous_token_end = None
            previous_token_score = None
            previous_right_edge_pileup = False
            continue
        assignment["ctc_first_token_start"] = round(first_start, 3)
        assignment["ctc_first_token_score"] = round(first_score, 6)
        assignment["ctc_boundary_start"] = round(boundary_start, 3)
        if index and previous_token_end is not None:
            gap = boundary_start - previous_token_end
            assignment["ctc_previous_token_end"] = round(previous_token_end, 3)
            assignment["ctc_previous_token_score"] = (
                round(previous_token_score, 6) if previous_token_score is not None else None
            )
            assignment["ctc_boundary_gap_seconds"] = round(gap, 3)
            evidence = ctc_prefix_boundary_evidence(assignment, gap)
            prior_edge_contamination = bool(previous_right_edge_pileup and gap <= 0.20)
            if prior_edge_contamination:
                evidence["previous_right_edge_pileup"] = True
                evidence["prior_line_truncation_contamination"] = True
                evidence["realign_required"] = True
            else:
                evidence["previous_right_edge_pileup"] = bool(previous_right_edge_pileup)
                evidence["prior_line_truncation_contamination"] = False
            assignment["ctc_clear_boundary"] = (
                gap >= 0.35
                and first_score >= 0.25
                and not evidence.get("timestamp_precedes_ctc_support")
            )
            assignment["ctc_boundary_evidence"] = evidence
            assignment["ctc_zero_boundary_gap"] = bool(evidence.get("zero_boundary_gap"))
            assignment["ctc_unclear_boundary"] = bool(evidence.get("unclear_boundary"))
            assignment["ctc_low_confidence_prefix"] = bool(evidence.get("low_confidence_prefix"))
            assignment["ctc_prefix_compressed"] = bool(evidence.get("abnormal_prefix_compression"))
            assignment["ctc_ghost_weak_prefix"] = bool(evidence.get("ghost_weak_prefix"))
            assignment["ctc_borrowed_tail_prefix"] = bool(evidence.get("borrowed_tail_prefix"))
            assignment["ctc_near_gap_weak_prefix"] = bool(evidence.get("near_gap_weak_prefix"))
            assignment["ctc_prior_line_truncation_contamination"] = bool(
                evidence.get("prior_line_truncation_contamination")
            )
            assignment["ctc_boundary_realign_required"] = bool(evidence.get("realign_required"))
        else:
            assignment["ctc_clear_boundary"] = False
            assignment["ctc_boundary_evidence"] = {"available": False, "reason": "first-entry-or-no-previous-token"}
            assignment["ctc_zero_boundary_gap"] = False
            assignment["ctc_unclear_boundary"] = True
            assignment["ctc_low_confidence_prefix"] = False
            assignment["ctc_prefix_compressed"] = False
            assignment["ctc_ghost_weak_prefix"] = False
            assignment["ctc_borrowed_tail_prefix"] = False
            assignment["ctc_near_gap_weak_prefix"] = False
            assignment["ctc_prior_line_truncation_contamination"] = False
            assignment["ctc_boundary_realign_required"] = False
        edge_evidence = ctc_right_edge_pileup_evidence(assignment)
        assignment["ctc_right_edge_evidence"] = edge_evidence
        assignment["ctc_right_edge_pileup"] = bool(edge_evidence.get("right_edge_pileup"))
        previous_token_end, previous_token_score = max(token_ends, key=lambda item: item[0])
        previous_right_edge_pileup = bool(assignment["ctc_right_edge_pileup"])


def refresh_ctc_confidence_diagnostics(entries: list[LyricEntry], report: dict[str, object]) -> None:
    """Recompute CTC trust after replacing one or more bounded alignment windows."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return
    missing = {int(value) for value in report.get("ctc_missing_entries", []) if isinstance(value, int)}
    scores: list[float] = []
    low_entries: list[dict[str, object]] = []
    very_low_entries: list[dict[str, object]] = []
    low_numbers: set[int] = set()
    for index, assignment in enumerate(assignments, start=1):
        if not isinstance(assignment, dict):
            missing.add(index)
            continue
        try:
            score = float(assignment.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            score = 0.0
        scores.append(score)
        assignment["score"] = 0.90 if score >= 0.08 else 0.70 if score >= 0.03 else 0.35
        if score < 0.03:
            low_numbers.add(index)
            item = {"entry": index, "text": entry_sung_text(entries[index - 1]), "ctc_score": round(score, 6)}
            low_entries.append(item)
            if score < 0.01:
                very_low_entries.append(item)

    runs: list[list[int]] = []
    run: list[int] = []
    for entry_number in range(1, len(entries) + 1):
        if entry_number in low_numbers:
            run.append(entry_number)
        else:
            if len(run) >= 4:
                runs.append(run)
            run = []
    if len(run) >= 4:
        runs.append(run)
    annotate_ctc_boundary_evidence(assignments)
    collapsed = {entry for run in runs for entry in run}
    right_edge_pileups = {
        index
        for index, assignment in enumerate(assignments, start=1)
        if isinstance(assignment, dict) and assignment.get("ctc_right_edge_pileup")
    }
    # Keep isolated low-score paths in the low-confidence metrics. They become
    # review-required only when the sequence collapses, an entry is missing, or
    # a local forced path demonstrably ran into its right audio boundary.
    review = collapsed | missing | right_edge_pileups
    suspicious = []
    for entry_number in sorted(review):
        flags = []
        if entry_number in missing:
            flags.append("ctc_missing_alignment")
        if entry_number in low_numbers:
            flags.append("ctc_low_path_confidence")
        if entry_number in collapsed:
            flags.append("ctc_confidence_collapse")
        if entry_number in right_edge_pileups:
            flags.extend(["ctc_right_edge_pileup", "ctc_local_window_truncated"])
        item: dict[str, object] = {
            "entry": entry_number,
            "text": entry_sung_text(entries[entry_number - 1]),
            "flags": flags,
            "severity": "high" if entry_number in missing or entry_number in collapsed or entry_number in right_edge_pileups else "medium",
            "review_required": True,
        }
        assignment = assignments[entry_number - 1]
        if isinstance(assignment, dict) and entry_number in right_edge_pileups:
            item["ctc_right_edge_evidence"] = assignment.get("ctc_right_edge_evidence")
        suspicious.append(item)
    report.update(
        {
            "ctc_missing_entries": sorted(missing),
            "ctc_missing_count": len(missing),
            "ctc_score_min": round(min(scores), 6) if scores else None,
            "ctc_score_mean": round(sum(scores) / len(scores), 6) if scores else None,
            "ctc_low_score_count": len(low_entries),
            "ctc_very_low_score_count": len(very_low_entries),
            "ctc_low_score_entries": low_entries,
            "ctc_very_low_score_entries": very_low_entries,
            "ctc_low_score_runs": runs,
            "ctc_confidence_collapse": bool(runs),
            "collapse_detected": bool(runs),
            "suspicious_alignments": suspicious,
            "suspicious_alignment_count": len(suspicious),
            "review_required_count": len(review),
            "review_required": bool(review),
            "suspicious_alignment_severity_counts": {
                "high": sum(1 for item in suspicious if item["severity"] == "high"),
                "medium": sum(1 for item in suspicious if item["severity"] == "medium"),
                "low": 0,
            },
        }
    )
    update_report_confidence_metrics(report)


def apply_ctc_local_window_realign(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    ctc_report: dict[str, object],
    raw_report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Re-run collapsed CTC ranges inside raw-ASR-bounded audio windows."""
    raw_assignments = raw_report.get("assignments")
    runs = ctc_report.get("ctc_low_score_runs")
    low_score_entries = ctc_report.get("ctc_low_score_entries")
    assignments = ctc_report.get("assignments")
    if not isinstance(raw_assignments, list) or not isinstance(runs, list) or not isinstance(assignments, list):
        return timestamps, ctc_report, []

    def raw_anchor(index: int) -> float | None:
        if not 0 <= index < len(raw_assignments):
            return None
        if has_ambiguous_lyric_prefix(entries, index):
            return None
        item = raw_assignments[index]
        if not isinstance(item, dict) or item.get("borrowed"):
            return None
        try:
            score = float(item.get("score", 0.0) or 0.0)
            timestamp = float(item.get("timestamp"))
        except (TypeError, ValueError):
            return None
        return timestamp if score >= TRUSTED_ALIGNMENT_SCORE else None

    def local_anchor(index: int) -> float | None:
        """Prefer unique raw anchors, then fall back to neighboring CTC bounds."""
        raw_time = raw_anchor(index)
        if raw_time is not None:
            return raw_time
        if 0 <= index < len(timestamps):
            timestamp = float(timestamps[index])
            if math.isfinite(timestamp):
                return timestamp
        return None

    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    errors: list[str] = []
    rejected_rows: list[dict[str, object]] = []
    window_runs = [run for run in runs if isinstance(run, list) and run]
    covered_entries = {int(entry) for run in window_runs for entry in run if isinstance(entry, int)}
    if isinstance(low_score_entries, list):
        for item in low_score_entries:
            if not isinstance(item, dict) or not isinstance(item.get("entry"), int):
                continue
            entry_number = int(item["entry"])
            if entry_number not in covered_entries:
                window_runs.append([entry_number])
                covered_entries.add(entry_number)

    # A high CTC path score does not guarantee that the path starts at the
    # intended lyric onset. Use raw ASR only to identify a bounded re-alignment
    # target; the replacement still comes from known-lyric CTC in that window.
    for index, current_time in enumerate(timestamps):
        if index >= len(raw_assignments) or not isinstance(raw_assignments[index], dict):
            continue
        raw_item = raw_assignments[index]
        try:
            raw_time = float(raw_item.get("timestamp"))
            raw_score = float(raw_item.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        borrowed = bool(raw_item.get("borrowed"))
        if has_ambiguous_lyric_prefix(entries, index):
            continue
        threshold = 0.45 if raw_score >= TRUSTED_ALIGNMENT_SCORE and not borrowed else 0.75
        if abs(raw_time - current_time) >= threshold:
            if isinstance(assignments[index], dict) and assignments[index].get("ctc_clear_boundary"):
                continue
            entry_number = index + 1
            if entry_number not in covered_entries:
                window_runs.append([entry_number])
                covered_entries.add(entry_number)

    merged_runs: list[list[int]] = []
    for raw_run in sorted(window_runs, key=lambda item: int(item[0])):
        start = int(raw_run[0])
        end = int(raw_run[-1])
        if merged_runs and start <= merged_runs[-1][-1] + 2:
            merged_runs[-1] = list(range(merged_runs[-1][0], max(merged_runs[-1][-1], end) + 1))
        else:
            merged_runs.append(list(range(start, end + 1)))
    window_runs = merged_runs
    python_exe = default_ctc_python()
    helper = Path(__file__).resolve().parent / "ctc_align.py"
    split_windows: list[dict[str, object]] = []
    with tempfile.TemporaryDirectory(prefix="lrc-ctc-window-") as temp_name:
        temp_dir = Path(temp_name)
        # A disagreement can span a full verse.  Re-aligning that whole verse
        # in one 45+ second pass is both costly and less constrained; split it
        # into adjacent windows while retaining a preceding lyric as context.
        pending_runs = [list(run) for run in window_runs]
        window_number = 0
        while pending_runs:
            raw_run = pending_runs.pop(0)
            window_number += 1
            if not isinstance(raw_run, list) or not raw_run:
                continue
            try:
                low_start = int(raw_run[0]) - 1
                low_end = int(raw_run[-1]) - 1
            except (TypeError, ValueError):
                continue
            left_index = next((idx for idx in range(low_start - 1, max(-1, low_start - 4), -1) if local_anchor(idx) is not None), None)
            right_index = next((idx for idx in range(low_end + 1, min(len(entries), low_end + 4)) if local_anchor(idx) is not None), None)
            start_index = 0 if left_index is None else left_index + 1
            end_index = len(entries) - 1 if right_index is None else right_index - 1
            # Include the preceding trusted line as CTC context. Starting the
            # audio just after its onset but omitting its text lets the target
            # line steal the preceding line's sustained vowel.
            alignment_start_index = 0 if left_index is None else left_index
            own_anchor = local_anchor(low_start)
            left_anchor = local_anchor(left_index) if left_index is not None else None
            # A large raw-ASR gap marks a section or instrumental break.  The
            # preceding lyric is not useful CTC context there; keeping it
            # makes repeated lines compete across the break.
            detached_section_start = (
                own_anchor is not None
                and left_anchor is not None
                and own_anchor - left_anchor >= 10.0
            )
            if detached_section_start:
                alignment_start_index = low_start
                start_index = low_start
                start_time = max(0.0, own_anchor - 1.00)
            elif left_index is None:
                # The first disputed lyric has no preceding ASR anchor.  Do
                # not give its local CTC pass the whole instrumental intro:
                # a reliable raw onset is a window boundary, not replacement
                # timing evidence, and prevents fragmented token paths from
                # borrowing noise before the vocal starts.
                start_time = max(0.0, own_anchor - 1.00) if own_anchor is not None else 0.0
            else:
                start_time = max(0.0, float(left_anchor or 0.0) - 0.05)
            if right_index is None:
                # A suffix window has no later lyric anchor.  The final raw/CTC
                # timestamp is only a candidate onset, not a safe audio boundary.
                # Capping the pass at ``tail_anchor + 3`` can exclude the real
                # final-line onset and force the remaining transcript into the
                # last few frames of the window.
                end_time = duration
            else:
                end_time = float(local_anchor(right_index) or duration) - 0.04
            window_duration = end_time - start_time
            if end_index < alignment_start_index or window_duration < 1.0:
                continue
            if window_duration > 45.0:
                if len(raw_run) >= 2:
                    midpoint = len(raw_run) // 2
                    left_run = raw_run[:midpoint]
                    right_run = raw_run[midpoint:]
                    pending_runs.insert(0, right_run)
                    pending_runs.insert(0, left_run)
                    split_windows.append(
                        {
                            "entries": list(raw_run),
                            "window_seconds": round(window_duration, 3),
                            "split_into": [list(left_run), list(right_run)],
                        }
                    )
                    continue
                errors.append(
                    f"window-{window_number}: skipped over-wide local CTC window ({window_duration:.1f}s)"
                )
                continue
            transcript_path = temp_dir / f"window-{window_number}.json"
            output_path = temp_dir / f"window-{window_number}.result.json"
            transcript_path.write_text(
                json.dumps([entry_sung_text(entry) for entry in entries[alignment_start_index : end_index + 1]], ensure_ascii=False),
                encoding="utf-8",
            )
            command = [
                str(python_exe), str(helper), "--audio", str(audio_path), "--transcript", str(transcript_path),
                "--output", str(output_path), "--device", args.whisperx_device,
                "--start", f"{start_time:.3f}", "--end", f"{end_time:.3f}",
            ]
            proc = _run_model_helper_command(command, mode="ctc")
            if proc.returncode != 0 or not output_path.exists():
                errors.append((proc.stderr or proc.stdout).strip()[:240])
                continue
            rows = json.loads(output_path.read_text(encoding="utf-8")).get("entries")
            if not isinstance(rows, list) or len(rows) != end_index - alignment_start_index + 1:
                errors.append(f"window-{window_number}: invalid helper output")
                continue
            window_changes = 0
            for offset, row in enumerate(rows):
                if not isinstance(row, dict) or not isinstance(row.get("start"), (int, float)):
                    continue
                index = alignment_start_index + offset
                if index < start_index:
                    continue
                timestamp = float(row["start"])
                if not start_time <= timestamp <= end_time:
                    continue
                candidate_edge_evidence = ctc_right_edge_pileup_evidence(
                    {
                        "ctc_local_window": {
                            "start": round(start_time, 3),
                            "end": round(end_time, 3),
                        },
                        "ctc_token_spans": row.get("token_spans"),
                    }
                )
                if candidate_edge_evidence.get("right_edge_pileup"):
                    rejected_rows.append(
                        {
                            "entry": index + 1,
                            "candidate": round(timestamp, 3),
                            "reason": "local-window-right-edge-pileup",
                            "window": {
                                "start": round(start_time, 3),
                                "end": round(end_time, 3),
                            },
                            "ctc_score": row.get("ctc_score"),
                            "ctc_right_edge_evidence": candidate_edge_evidence,
                        }
                    )
                    # Do not commit a forced path that visibly ran out of
                    # audio.  Keeping the pre-window timestamp is safer and
                    # lets the later boundary stage evaluate that candidate
                    # instead of propagating a truncated path into the next
                    # lyric boundary.
                    continue
                assignment = assignments[index]
                if isinstance(assignment, dict):
                    try:
                        local_score = float(row.get("ctc_score", 0.0) or 0.0)
                    except (TypeError, ValueError):
                        local_score = 0.0
                    record_alignment_hypothesis(
                        assignment,
                        source="ctc-local-window",
                        stage="ctc-local-window-realign",
                        raw_time=timestamp,
                        confidence=local_score,
                        spans=row.get("token_spans"),
                        identity_support="supported" if isinstance(row.get("token_spans"), list) and bool(row.get("token_spans")) else "unavailable",
                        sequence_support="supported",
                        parent_source="ctc-global-mms",
                        parent_time=float(timestamps[index]),
                        window={"start": round(start_time, 3), "end": round(end_time, 3)},
                        right_edge_pileup=bool(candidate_edge_evidence.get("right_edge_pileup")),
                        window_truncated=bool(candidate_edge_evidence.get("right_edge_pileup")),
                    )
                    assignment["ctc_local_window_candidate_generated"] = True
                window_changes += 1
            if window_changes:
                changes.append(
                    {
                        "entries": list(range(start_index + 1, end_index + 2)),
                        "context_entry": left_index + 1 if left_index is not None else None,
                        "start": round(start_time, 3),
                        "end": round(end_time, 3),
                    }
                )
    ctc_report["ctc_local_window_realign"] = {
        "status": "candidate-generated" if changes else "skipped",
        "authoritative": False,
        "mutates_baseline": False,
        "windows": changes,
        "split_windows": split_windows,
        "errors": errors,
        "rejected_rows": rejected_rows,
    }
    # The global MMS timestamp/spans remain the backend baseline. Local-window
    # rows are immutable alternatives consumed only by the central evaluator.
    return list(timestamps), ctc_report, changes


def apply_ctc_hybrid_window_realign(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    ctc_report: dict[str, object],
    whisperx_report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Re-align only CTC/WhisperX disagreement windows before local fusion."""
    ctc_assignments = ctc_report.get("assignments")
    whisperx_assignments = whisperx_report.get("assignments")
    if not isinstance(ctc_assignments, list) or not isinstance(whisperx_assignments, list):
        return timestamps, ctc_report, []

    target_indices: list[int] = []
    for index, (ctc_item, whisperx_item) in enumerate(zip(ctc_assignments, whisperx_assignments)):
        if not isinstance(ctc_item, dict) or not isinstance(whisperx_item, dict):
            continue
        try:
            ctc_time = float(ctc_item.get("timestamp", timestamps[index]) or timestamps[index])
            whisperx_time = float(whisperx_item.get("timestamp"))
        except (TypeError, ValueError):
            continue
        first_score = 1.0
        spans = ctc_item.get("ctc_token_spans")
        if isinstance(spans, list) and spans:
            try:
                first_score = float(spans[0].get("score", 1.0) or 0.0)
            except (AttributeError, TypeError, ValueError):
                pass
        disagreement = abs(ctc_time - whisperx_time)
        if disagreement >= 1.0 or (disagreement >= 0.45 and first_score <= 0.05):
            target_indices.append(index)
    if not target_indices:
        return timestamps, ctc_report, []

    runs: list[list[int]] = []
    for index in target_indices:
        if runs and index <= runs[-1][-1] + 1:
            runs[-1].append(index)
        else:
            runs.append([index])

    helper = Path(__file__).resolve().parent / "ctc_align.py"
    python_exe = default_ctc_python()
    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    with tempfile.TemporaryDirectory(prefix="lrc-ctc-hybrid-window-") as temp_name:
        temp_dir = Path(temp_name)
        for number, run in enumerate(runs, start=1):
            run_start, run_end = run[0], run[-1]
            context_start = max(0, run_start - 1)
            context_end = min(len(entries) - 1, run_end + 1)
            right_boundary = min(len(entries) - 1, context_end + 1)
            start_time = max(0.0, refined[context_start] - 0.08)
            end_time = duration if right_boundary == context_end else max(start_time + 1.0, refined[right_boundary] - 0.05)
            window_duration = end_time - start_time
            if window_duration < 1.0 or window_duration > 45.0:
                continue
            transcript_path = temp_dir / f"window-{number}.json"
            output_path = temp_dir / f"window-{number}.result.json"
            transcript_path.write_text(
                json.dumps([entry_sung_text(entry) for entry in entries[context_start : context_end + 1]], ensure_ascii=False),
                encoding="utf-8",
            )
            command = [
                str(python_exe), str(helper), "--audio", str(audio_path), "--transcript", str(transcript_path),
                "--output", str(output_path), "--device", args.whisperx_device,
                "--start", f"{start_time:.3f}", "--end", f"{end_time:.3f}",
            ]
            proc = _run_model_helper_command(command, mode="ctc")
            if proc.returncode != 0 or not output_path.exists():
                continue
            rows = json.loads(output_path.read_text(encoding="utf-8")).get("entries")
            if not isinstance(rows, list) or len(rows) != context_end - context_start + 1:
                continue
            indexes_to_update = list(run)
            # A disputed line can make the immediately following line lose a
            # soft initial consonant. Keep that context row only when its own
            # aligned first token is weak; otherwise leave an unflagged line
            # untouched.
            if context_end not in indexes_to_update:
                context_row = rows[context_end - context_start]
                context_spans = context_row.get("token_spans") if isinstance(context_row, dict) else None
                try:
                    context_first_score = float(context_spans[0].get("score", 1.0) or 0.0)
                except (AttributeError, TypeError, ValueError, IndexError):
                    context_first_score = 1.0
                context_start_time = float(context_row.get("start", 0.0) or 0.0) if isinstance(context_row, dict) else 0.0
                context_peaks = context_row.get("first_token_candidates") if isinstance(context_row, dict) else None
                has_strong_early_peak = any(
                    isinstance(peak, dict)
                    and isinstance(peak.get("time"), (int, float))
                    and isinstance(peak.get("score"), (int, float))
                    and float(peak["time"]) < context_start_time - 0.45
                    and float(peak["score"]) >= 0.05
                    for peak in context_peaks
                ) if isinstance(context_peaks, list) else False
                if context_first_score <= 0.05 or has_strong_early_peak:
                    indexes_to_update.append(context_end)
            updated_entries: list[int] = []
            for index in indexes_to_update:
                row = rows[index - context_start]
                if not isinstance(row, dict) or not isinstance(row.get("start"), (int, float)):
                    continue
                timestamp = float(row["start"])
                if not start_time <= timestamp <= end_time:
                    continue
                refined[index] = timestamp
                assignment = ctc_assignments[index]
                if isinstance(assignment, dict):
                    assignment["timestamp"] = round(timestamp, 3)
                    assignment["ctc_score"] = row.get("ctc_score")
                    assignment["ctc_token_spans"] = row.get("token_spans")
                    assignment["ctc_first_token_candidates"] = row.get("first_token_candidates")
                    assignment["ctc_hybrid_window_realign"] = True
                updated_entries.append(index + 1)
            if updated_entries:
                changes.append({
                    "entries": updated_entries,
                    "context_entries": [context_start + 1, context_end + 1],
                    "start": round(start_time, 3),
                    "end": round(end_time, 3),
                })
    if changes:
        ctc_report["ctc_hybrid_window_realign"] = {"status": "applied", "windows": changes}
        refresh_ctc_confidence_diagnostics(entries, ctc_report)
    return refined, ctc_report, changes


def whisperx_segments(payload: dict[str, object]) -> list[AsrSegment]:
    segments: list[AsrSegment] = []
    for item in payload.get("segments", []):
        if not isinstance(item, dict):
            continue
        text = str(item.get("text", "")).strip()
        if not text:
            continue
        start = float(item.get("start", 0.0) or 0.0)
        end = float(item.get("end", start) or start)
        chars: list[tuple[str, float]] = []
        for char_item in item.get("chars", []):
            if not isinstance(char_item, dict) or "start" not in char_item:
                continue
            char_text = str(char_item.get("char", ""))
            char_time = float(char_item.get("start", start) or start)
            for normalized in normalize_match_text(char_text):
                chars.append((normalized, char_time))
        if not chars and end - start < 0.05:
            continue
        segments.append(AsrSegment(start=start, end=end, text=text, chars=chars))
    if not segments:
        raise LrcError("WhisperX produced no aligned segments")
    return segments


def asr_transcript(segments: list[AsrSegment]) -> list[dict[str, object]]:
    return [
        {"start": segment.start, "end": segment.end, "text": segment.text}
        for segment in segments
        if segment.text.strip()
    ]


def _whispercpp_runtime_artifact_hashes(
    args: argparse.Namespace,
) -> tuple[str, str] | None:
    cli_arg = getattr(args, "whisper_cli", None)
    cli = Path(cli_arg).expanduser().resolve() if cli_arg else default_whisper_cli()
    model_arg = getattr(args, "whisper_model", None)
    model = Path(model_arg).expanduser().resolve() if model_arg else default_whisper_model()
    try:
        if not cli.is_file() or not model.is_file():
            return None
        return _path_sha256(cli), _path_sha256(model)
    except (OSError, LrcError):
        return None


def _whisperx_alignment_metadata(
    payload: dict[str, object],
) -> dict[str, str] | None:
    value = payload.get(_RUNTIME_WHISPERX_ALIGNMENT_METADATA_KEY)
    if not isinstance(value, dict):
        return None
    fields = {
        key: value.get(key)
        for key in (
            "helper_sha256",
            "helper_protocol_revision",
            "python_sha256",
            "whisperx_package_version",
            "align_model_id",
            "align_model_revision",
            "align_model_blob_sha256",
            "alignment_wav_sha256",
            "device",
            "language",
            "input_transcript_revision",
            "output_revision",
        )
    }
    if any(not isinstance(item, str) or not item.strip() for item in fields.values()):
        return None
    return {key: str(item) for key, item in fields.items()}


def _build_whisperx_runtime_provenance(
    audio_path: Path,
    args: argparse.Namespace,
    raw_segments: list[AsrSegment],
    initial_payload: dict[str, object],
    forced_payload: dict[str, object],
) -> WhisperXRuntimeProvenance | None:
    initial = _whisperx_alignment_metadata(initial_payload)
    forced = _whisperx_alignment_metadata(forced_payload)
    artifact_hashes = _whispercpp_runtime_artifact_hashes(args)
    if initial is None or forced is None or artifact_hashes is None:
        return None
    if any(initial[key] != forced[key] for key in (
        "helper_sha256",
        "helper_protocol_revision",
        "python_sha256",
        "whisperx_package_version",
        "align_model_id",
        "align_model_revision",
        "align_model_blob_sha256",
        "alignment_wav_sha256",
        "device",
        "language",
    )):
        return None
    raw_transcript_revision = _timing_content_digest(asr_transcript(raw_segments))
    if initial["input_transcript_revision"] != raw_transcript_revision:
        return None
    try:
        source_audio_sha256 = _path_sha256(audio_path)
    except (OSError, LrcError):
        return None
    payload = {
        "backend_lineage": "whisper-family",
        "raw_executable_sha256": artifact_hashes[0],
        "raw_model_sha256": artifact_hashes[1],
        "python_sha256": initial["python_sha256"],
        "helper_sha256": initial["helper_sha256"],
        "helper_protocol_revision": initial["helper_protocol_revision"],
        "whisperx_package_version": initial["whisperx_package_version"],
        "align_model_id": initial["align_model_id"],
        "align_model_revision": initial["align_model_revision"],
        "align_model_blob_sha256": initial["align_model_blob_sha256"],
        "source_audio_sha256": source_audio_sha256,
        "alignment_wav_sha256": initial["alignment_wav_sha256"],
        "device": initial["device"],
        "language": initial["language"],
        "raw_transcript_revision": raw_transcript_revision,
        "initial_aligned_output_revision": initial["output_revision"],
        "forced_output_revision": forced["output_revision"],
    }
    return WhisperXRuntimeProvenance(
        **payload,
        capability_revision=_timing_content_digest(payload),
    )


def run_whisperx_candidate(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
    suppress_nst: bool,
    *,
    predecoded_wav: Path | None = None,
    raw_segments_override: list[AsrSegment] | None = None,
) -> tuple[list[float], dict[str, object]]:
    wav_path = predecoded_wav if predecoded_wav is not None else decode_temp_wav(audio_path)
    if raw_segments_override is not None:
        if suppress_nst:
            raise LrcError("Unsuppressed raw ASR reuse cannot satisfy suppress_nst=True")
        raw_segments = list(raw_segments_override)
    else:
        raw_segments = _run_whispercpp_wav(wav_path, args, suppress_nst=suppress_nst)
    raw_transcript = asr_transcript(raw_segments)
    aligned_payload = run_whisperx_alignment(wav_path, raw_transcript, args, predecoded_wav=True)
    aligned_segments = whisperx_segments(aligned_payload)
    timestamps, report = match_whisper_segments(entries, aligned_segments, duration)
    report["backend"] = "whisperx"
    report["asr_segment_timing_source"] = "whisperx_aligned"
    report["whisperx_aligned_asr_segments"] = len(aligned_segments)
    report["whisper_suppress_nst"] = suppress_nst
    report["whisperx_device"] = aligned_payload.get("device")
    report["vocal_regions"] = []
    report["vocal_regions_available"] = False
    report["no_vocal_constraint"] = {
        "status": "placeholder",
        "enforced": False,
        "reason": "No reliable vocal-region detector is wired yet.",
    }
    report["local_window_realign"] = {
        "status": "placeholder",
        "enabled": False,
        "reason": "Disabled until a reliable vocal-region/onset constraint is available.",
    }
    if is_alignment_unusable(report):
        raise LrcError(
            "WhisperX ASR-to-lyric matching is unusable; refusing to write a fake LRC. "
            f"{unusable_alignment_reason(report)}"
        )
    timestamps, intro_changes = repair_intro_hallucination(audio_path, entries, timestamps, report, duration)
    if intro_changes:
        sync_scratch_assignment_timestamps(report, timestamps)
    timestamps, long_segment_changes = repair_long_segment_hallucinations(
        audio_path,
        entries,
        timestamps,
        report,
        aligned_segments,
        duration,
    )
    if long_segment_changes:
        sync_scratch_assignment_timestamps(report, timestamps)
    timestamps, tail_changes = repair_tail_hallucination(
        audio_path,
        entries,
        timestamps,
        report,
        aligned_segments,
        duration,
    )
    if tail_changes:
        sync_scratch_assignment_timestamps(report, timestamps)
    forced_payload = run_whisperx_alignment(
        wav_path,
        lyric_alignment_windows(entries, timestamps, duration),
        args,
        predecoded_wav=True,
    )
    forced_segments = whisperx_segments(forced_payload)
    runtime_provenance = _build_whisperx_runtime_provenance(
        audio_path,
        args,
        raw_segments,
        aligned_payload,
        forced_payload,
    )
    timestamps, refinement_changes = apply_whisperx_lyric_refinement(
        entries,
        timestamps,
        report,
        aligned_segments,
        forced_segments,
        duration,
    )
    sync_scratch_assignment_timestamps(report, timestamps)
    report["backend"] = "whisperx"
    report["strategy"] = "whisperx-hybrid-experimental"
    report["whisper_suppress_nst"] = suppress_nst
    report["whisperx_device"] = forced_payload.get("device") or aligned_payload.get("device")
    report["whisper_language"] = args.whisper_language
    report["whisperx_forced_first_times"] = [round(first_forced_char_time(segment), 3) for segment in forced_segments]
    report["whisperx_forced_rows"] = [
        {
            "segment_start": round(float(segment.start), 6),
            "segment_end": round(float(segment.end), 6),
            "first_char_time": round(float(first_forced_char_time(segment)), 6),
            "last_char_time": round(
                float(segment.chars[-1][1] if segment.chars else segment.start), 6
            ),
            "char_count": len(segment.chars),
        }
        for segment in forced_segments
    ]
    if runtime_provenance is not None:
        report[_RUNTIME_WHISPERX_EXECUTION_PROVENANCE_KEY] = runtime_provenance
    report["whisperx_refinement_count"] = len(refinement_changes)
    report["whisperx_refinements"] = refinement_changes
    timestamps, tail_blend_changes = blend_tail_repair_with_forced(
        entries,
        timestamps,
        report,
        forced_segments,
        duration,
    )
    if tail_blend_changes:
        sync_scratch_assignment_timestamps(report, timestamps)
    add_alignment_diagnostics(entries, timestamps, report, forced_segments, duration)
    if is_alignment_untrusted(report):
        raise AlignmentEvidenceRejected(
            "WhisperX alignment is untrusted after diagnostics; refusing to write a fake LRC. "
            f"{untrusted_alignment_reason(report)}",
            timestamps,
            report,
        )
    return timestamps, report


def report_quality(report: dict[str, object]) -> float:
    """Single-source ranking metric: end-to-end trust, plus global collapse.

    Low-score, unverified, and review counts are projections of the same row
    state and therefore are not charged again.  This keeps the metric useful for
    ranking instead of turning 60% trust into an arbitrary negative number.
    """
    if report.get("error"):
        return -100.0
    quality = float(
        report.get(
            "overall_trusted_percent",
            report.get("trusted_percent", report.get("matched_percent", 0.0)),
        )
        or 0.0
    )
    if report.get("collapse_detected"):
        quality -= 100.0
    return max(-100.0, min(100.0, quality))


def candidate_selection_quality(report: dict[str, object]) -> float:
    return report_quality(report)


def should_prefer_ctc_over_review_exploded_hybrid(
    hybrid_report: dict[str, object], ctc_report: dict[str, object]
) -> bool:
    """Reject a locally patched hybrid when it becomes much less auditable than CTC."""
    if ctc_report.get("collapse_detected"):
        return False
    try:
        ctc_missing = int(ctc_report.get("ctc_missing_count", 0) or 0)
        ctc_reviews = int(ctc_report.get("review_required_count", 0) or 0)
        hybrid_reviews = int(hybrid_report.get("review_required_count", 0) or 0)
    except (TypeError, ValueError):
        return False
    if ctc_missing:
        return False
    return hybrid_reviews >= max(8, ctc_reviews * 3 + 5)


def choose_onset_consensus_time(
    ctc_time: float,
    ctc_first_score: float,
    whisper_time: float,
    whisper_score: float,
    japanese_ctc_time: float,
) -> tuple[float | None, str | None]:
    """Choose a narrow onset rescue when CTC's first phoneme is unreliable."""
    ctc_whisper_gap = abs(ctc_time - whisper_time)
    whisper_japanese_gap = abs(whisper_time - japanese_ctc_time)
    if (
        ctc_first_score <= 0.01
        and whisper_score >= 0.80
        and 0.35 <= ctc_whisper_gap <= 0.80
        and 0.60 <= whisper_japanese_gap <= 1.00
    ):
        return whisper_time, "high-confidence-whisperx-over-weak-ctc-initial"
    if (
        ctc_first_score <= 0.01
        and whisper_score >= 0.50
        and ctc_whisper_gap >= 0.20
        and whisper_japanese_gap <= 0.15
    ):
        return (whisper_time + japanese_ctc_time) / 2.0, "whisperx-japanese-ctc-onset-consensus"
    if (
        0.05 <= ctc_first_score <= 0.10
        and whisper_score >= 0.80
        and whisper_japanese_gap <= 0.15
        and ctc_whisper_gap >= 0.20
    ):
        return (whisper_time + japanese_ctc_time) / 2.0, "whisperx-japanese-ctc-over-ctc-onset-consensus"
    return None, None


def apply_japanese_onset_consensus_to_ctc(
    timestamps: list[float],
    ctc_report: dict[str, object],
    whisper_timestamps: list[float],
    whisper_report: dict[str, object],
    japanese_timestamps: list[float],
    duration: float,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    assignments = ctc_report.get("assignments")
    whisper_assignments = whisper_report.get("assignments")
    if not isinstance(assignments, list) or not isinstance(whisper_assignments, list):
        return timestamps, ctc_report, []
    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if index >= len(whisper_assignments) or index >= len(whisper_timestamps) or index >= len(japanese_timestamps):
            continue
        whisper_assignment = whisper_assignments[index]
        if not isinstance(assignment, dict) or not isinstance(whisper_assignment, dict):
            continue
        spans = assignment.get("ctc_token_spans")
        if not isinstance(spans, list) or not spans:
            continue
        try:
            ctc_first_score = float(spans[0].get("score", 0.0) or 0.0)
            whisper_score = float(whisper_assignment.get("score", 0.0) or 0.0)
            ctc_time = float(refined[index])
            whisper_time = float(whisper_timestamps[index])
            japanese_time = float(japanese_timestamps[index])
        except (AttributeError, TypeError, ValueError):
            continue
        candidate, reason = choose_onset_consensus_time(
            ctc_time, ctc_first_score, whisper_time, whisper_score, japanese_time
        )
        if candidate is None or reason is None:
            continue
        previous_time = refined[index - 1] if index else 0.0
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        if not previous_time + 0.05 < candidate < next_time - 0.05:
            continue
        refined[index] = candidate
        assignment["timestamp"] = round(candidate, 3)
        assignment["ctc_onset_consensus"] = True
        assignment["ctc_onset_consensus_reason"] = reason
        assignment["ctc_onset_consensus_candidates"] = {
            "ctc": round(ctc_time, 3), "whisperx": round(whisper_time, 3), "japanese_ctc": round(japanese_time, 3),
        }
        changes.append({"entry": index + 1, "from": round(ctc_time, 3), "to": round(candidate, 3), "reason": reason})
    if changes:
        ctc_report["ctc_onset_consensus"] = changes
    return refined, ctc_report, changes


def candidate_summary(report: dict[str, object], error: str | None = None) -> dict[str, object]:
    quality = candidate_selection_quality(report)
    summary: dict[str, object] = {
        "backend": report.get("backend"),
        "strategy": report.get("strategy"),
        "quality": round(quality, 3),
        "assigned_percent": report.get("assigned_percent"),
        "trusted_percent": report.get("trusted_percent", report.get("matched_percent")),
        "low_confidence_percent": report.get("low_confidence_percent"),
        "review_required_percent": report.get("review_required_percent"),
        "collapse_detected": bool(report.get("collapse_detected")),
        "error": error or report.get("error"),
    }
    if report.get("backend") == "ctc":
        summary.update(
            {
                "ctc_device": report.get("ctc_device"),
                "ctc_score_min": report.get("ctc_score_min"),
                "ctc_score_mean": report.get("ctc_score_mean"),
                "ctc_low_score_count": report.get("ctc_low_score_count"),
                "ctc_very_low_score_count": report.get("ctc_very_low_score_count"),
                "ctc_missing_count": report.get("ctc_missing_count"),
            }
        )
    if report.get("backend") == "whisperx":
        summary.update(
            {
                "whisper_suppress_nst": report.get("whisper_suppress_nst"),
                "whisperx_device": report.get("whisperx_device"),
                "legacy_quality": round(report_quality(report), 3),
            }
        )
    return summary


def needs_suppressed_retry(report: dict[str, object]) -> bool:
    matched_percent = float(report.get("trusted_percent", report.get("matched_percent", 0.0)) or 0.0)
    timing_entries = int(report.get("timing_entries", 0) or 0)
    low_confidence_count = int(report.get("low_confidence_count", 0) or 0)
    low_limit = max(6, math.ceil(timing_entries * 0.20))
    return matched_percent < 90.0 or low_confidence_count > low_limit


def is_alignment_unusable(report: dict[str, object]) -> bool:
    timing_entries = int(report.get("timing_entries", 0) or 0)
    matched_entries = int(report.get("trusted_entries", report.get("matched_entries", 0)) or 0)
    matched_percent = float(report.get("trusted_percent", report.get("matched_percent", 0.0)) or 0.0)
    low_confidence_count = int(report.get("low_confidence_count", 0) or 0)
    if timing_entries <= 0:
        return True
    if matched_entries == 0:
        return True
    if matched_percent < 35.0:
        return True
    if timing_entries >= 6 and low_confidence_count >= math.ceil(timing_entries * 0.80):
        return True
    return False


def is_alignment_untrusted(report: dict[str, object]) -> bool:
    if is_alignment_unusable(report):
        return True
    if report.get("collapse_detected"):
        return True
    timing_entries = int(report.get("timing_entries", 0) or 0)
    trusted_percent = float(report.get("trusted_percent", report.get("matched_percent", 0.0)) or 0.0)
    low_confidence_percent = float(report.get("low_confidence_percent", 0.0) or 0.0)
    high_risk_count = 0
    max_post_long_uncertain_run = 0
    suspicious = report.get("suspicious_alignments")
    if isinstance(suspicious, list):
        high_risk_count = sum(
            1 for item in suspicious if isinstance(item, dict) and item.get("severity") == "high"
        )
        flagged_entries: set[int] = set()
        for item in suspicious:
            if not isinstance(item, dict):
                continue
            flags = item.get("flags")
            if not isinstance(flags, list) or "post_long_segment_region_uncertain" not in flags:
                continue
            try:
                flagged_entries.add(int(item.get("entry", 0)))
            except (TypeError, ValueError):
                continue
        current_run = 0
        for entry_index in range(1, timing_entries + 1):
            if entry_index in flagged_entries:
                current_run += 1
                max_post_long_uncertain_run = max(max_post_long_uncertain_run, current_run)
            else:
                current_run = 0
        report["max_post_long_uncertain_run"] = max_post_long_uncertain_run
    if timing_entries >= 8 and trusted_percent < 85.0:
        return True
    if timing_entries >= 8 and low_confidence_percent >= 50.0:
        return True
    if timing_entries >= 8 and max_post_long_uncertain_run >= 4:
        return True
    if timing_entries >= 8 and high_risk_count >= math.ceil(timing_entries * 0.25):
        return True
    return False


def unusable_alignment_reason(report: dict[str, object]) -> str:
    return (
        f"trusted_entries={report.get('trusted_entries', report.get('matched_entries'))}, "
        f"timing_entries={report.get('timing_entries')}, "
        f"trusted_percent={report.get('trusted_percent', report.get('matched_percent'))}, "
        f"assigned_percent={report.get('assigned_percent')}, "
        f"low_confidence_count={report.get('low_confidence_count')}"
    )


def untrusted_alignment_reason(report: dict[str, object]) -> str:
    segment_runs = report.get("segment_collapse_runs")
    zero_runs = report.get("alignment_collapse_runs")
    return (
        f"trusted_entries={report.get('trusted_entries', report.get('matched_entries'))}, "
        f"timing_entries={report.get('timing_entries')}, "
        f"trusted_percent={report.get('trusted_percent', report.get('matched_percent'))}, "
        f"assigned_percent={report.get('assigned_percent')}, "
        f"low_confidence_percent={report.get('low_confidence_percent')}, "
        f"review_required_percent={report.get('review_required_percent')}, "
        f"collapse_detected={report.get('collapse_detected')}, "
        f"max_post_long_uncertain_run={report.get('max_post_long_uncertain_run')}, "
        f"segment_collapse_runs={segment_runs}, "
        f"alignment_collapse_runs={zero_runs}"
    )


def try_whisperx_candidate(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
    suppress_nst: bool,
    *,
    predecoded_wav: Path | None = None,
    raw_segments_override: list[AsrSegment] | None = None,
) -> tuple[list[float], dict[str, object], str | None]:
    try:
        timestamps, report = run_whisperx_candidate(
            audio_path,
            entries,
            duration,
            args,
            suppress_nst,
            predecoded_wav=predecoded_wav,
            raw_segments_override=raw_segments_override,
        )
        return timestamps, report, None
    except AlignmentEvidenceRejected as exc:
        report = copy.deepcopy(exc.report)
        report["whisper_suppress_nst"] = suppress_nst
        report["candidate_usable"] = False
        report["candidate_rejection_reason"] = str(exc)
        return list(exc.timestamps), report, str(exc)
    except LrcError as exc:
        return [], {"whisper_suppress_nst": suppress_nst, "error": str(exc)}, str(exc)


def try_ctc_candidate(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
) -> tuple[list[float], dict[str, object], str | None]:
    try:
        timestamps, report = run_ctc_alignment(audio_path, entries, duration, args)
        return timestamps, report, None
    except LrcError as exc:
        return [], {"backend": "ctc", "error": str(exc)}, str(exc)


def ctc_alignment_audio_path(report: dict[str, object], fallback: Path) -> Path:
    candidate = report.get("ctc_audio_path")
    if isinstance(candidate, str):
        path = Path(candidate)
        if path.exists():
            return path
    return fallback


def try_whispercpp_diagnostic_candidate(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
    *,
    predecoded_wav: Path | None = None,
) -> tuple[list[float], dict[str, object], str | None, list[AsrSegment] | None]:
    raw_segments: list[AsrSegment] | None = None
    try:
        raw_segments = (
            _run_whispercpp_wav(predecoded_wav, args, suppress_nst=False)
            if predecoded_wav is not None
            else run_whispercpp(audio_path, args, suppress_nst=False)
        )
        timestamps, report = match_whisper_segments(entries, raw_segments, duration)
        report["backend"] = "whispercpp_raw"
        report["strategy"] = "whispercpp-raw-diagnostic"
        report["asr_repeated_tail_after_0s"] = has_repeated_asr_tail(raw_segments, 0.0)
        report["raw_asr_segments"] = [
            {"start": round(segment.start, 3), "end": round(segment.end, 3), "text": segment.text}
            for segment in raw_segments
        ]
        report["raw_asr_max_segment_seconds"] = round(
            max((segment.end - segment.start for segment in raw_segments), default=0.0), 3
        )
        report["diagnostic_only"] = True
        return timestamps, report, None, raw_segments
    except LrcError as exc:
        return (
            [],
            {"backend": "whispercpp_raw", "diagnostic_only": True, "error": str(exc)},
            str(exc),
            raw_segments,
        )


def run_whisperx_best_candidate(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
    *,
    predecoded_wav: Path | None = None,
    normal_raw_segments: list[AsrSegment] | None = None,
) -> tuple[list[float], dict[str, object]]:
    if args.whisper_suppress_nst is not None:
        try:
            explicit_suppress = bool(args.whisper_suppress_nst)
            return run_whisperx_candidate(
                audio_path,
                entries,
                duration,
                args,
                suppress_nst=explicit_suppress,
                predecoded_wav=predecoded_wav,
                raw_segments_override=(
                    normal_raw_segments if not explicit_suppress else None
                ),
            )
        except AlignmentEvidenceRejected as exc:
            raise WhisperXEvidenceBundleError(
                str(exc),
                [(list(exc.timestamps), copy.deepcopy(exc.report), str(exc))],
            ) from exc

    normal_timestamps, normal_report, normal_error = try_whisperx_candidate(
        audio_path,
        entries,
        duration,
        args,
        suppress_nst=False,
        predecoded_wav=predecoded_wav,
        raw_segments_override=normal_raw_segments,
    )
    candidates = [normal_report]

    # A failed normal candidate gets exactly one suppress-NST rescue.  The old
    # control flow then re-ran needs_suppressed_retry() *on the rescue report*
    # and could execute the identical rescue a third time.  Rescue is already
    # the alternate decode policy, so there is no second suppress policy to try.
    if normal_error:
        sns_timestamps, sns_report, sns_error = try_whisperx_candidate(
            audio_path,
            entries,
            duration,
            args,
            suppress_nst=True,
            predecoded_wav=predecoded_wav,
        )
        candidates.append(sns_report)
        if sns_error:
            evidence_candidates = [
                (normal_timestamps, normal_report, normal_error),
                (sns_timestamps, sns_report, sns_error),
            ]
            raise WhisperXEvidenceBundleError(
                "No usable WhisperX candidate; refusing to write a fake LRC. "
                + " | ".join(str(item) for item in (normal_error, sns_error) if item),
                [
                    (candidate_times, candidate_report, str(candidate_error))
                    for candidate_times, candidate_report, candidate_error in evidence_candidates
                    if candidate_error and isinstance(candidate_report.get("assignments"), list)
                ],
            )
        timestamps = list(sns_timestamps)
        report = sns_report
        report["candidate_reports"] = [
            candidate_summary(candidate, str(candidate.get("error")) if candidate.get("error") else None)
            for candidate in candidates
            if isinstance(candidate, dict)
        ]
        return timestamps, report

    timestamps = list(normal_timestamps)
    report = normal_report
    if needs_suppressed_retry(normal_report):
        sns_timestamps, sns_report, sns_error = try_whisperx_candidate(
            audio_path,
            entries,
            duration,
            args,
            suppress_nst=True,
            predecoded_wav=predecoded_wav,
        )
        candidates.append(sns_report)
        if not sns_error:
            collapse_start = low_confidence_run_start(normal_report)
            quality_gap = report_quality(sns_report) - report_quality(normal_report)
            if quality_gap >= 15.0:
                timestamps, report = list(sns_timestamps), sns_report
            elif collapse_start is not None and report_quality(sns_report) > report_quality(normal_report):
                timestamps = list(normal_timestamps[:collapse_start]) + list(sns_timestamps[collapse_start:])
                adopted_sns_entries: list[int] = []
                for change in sns_report.get("whisperx_refinements", []):
                    if not isinstance(change, dict):
                        continue
                    entry_number = change.get("entry")
                    if not isinstance(entry_number, int):
                        continue
                    entry_index = entry_number - 1
                    if not (0 <= entry_index < collapse_start):
                        continue
                    if change.get("reason") != "bounded-forced-asr-blend":
                        continue
                    shift = normal_timestamps[entry_index] - sns_timestamps[entry_index]
                    if not (0.40 <= shift <= 1.60):
                        continue
                    left_ok = entry_index == 0 or timestamps[entry_index - 1] + 0.10 < sns_timestamps[entry_index]
                    right_ok = (
                        entry_index + 1 >= len(timestamps)
                        or sns_timestamps[entry_index] < timestamps[entry_index + 1] - 0.10
                    )
                    if left_ok and right_ok:
                        timestamps[entry_index] = sns_timestamps[entry_index]
                        adopted_sns_entries.append(entry_index)
                report = fused_candidate_report(
                    normal_report, sns_report, timestamps, collapse_start, adopted_sns_entries
                )
            elif report_quality(sns_report) > report_quality(report):
                timestamps, report = list(sns_timestamps), sns_report

    report["candidate_reports"] = [
        candidate_summary(candidate, str(candidate.get("error")) if candidate.get("error") else None)
        for candidate in candidates
        if isinstance(candidate, dict)
    ]
    return timestamps, report


def choose_alignment_candidate(
    candidates: list[dict[str, object]],
) -> dict[str, object]:
    usable = [
        candidate
        for candidate in candidates
        if not candidate.get("error")
        and isinstance(candidate.get("timestamps"), list)
        and isinstance(candidate.get("report"), dict)
    ]
    if not usable:
        errors = [
            str(candidate.get("error"))
            for candidate in candidates
            if candidate.get("error")
        ]
        raise LrcError("No usable alignment candidate. " + " | ".join(errors))

    for candidate in usable:
        report = candidate["report"]
        assert isinstance(report, dict)
        candidate["quality"] = candidate_selection_quality(report)

    best = max(usable, key=lambda item: float(item.get("quality", -100.0) or -100.0))
    ctc = next((item for item in usable if item.get("backend") == "ctc"), None)
    if ctc is not None:
        ctc_quality = float(ctc.get("quality", -100.0) or -100.0)
        best_quality = float(best.get("quality", -100.0) or -100.0)
        if ctc_quality >= 80.0 and ctc_quality >= best_quality - 5.0:
            return ctc
    return best


def candidate_selection_reason(selected: dict[str, object], candidates: list[dict[str, object]]) -> str:
    selected_backend = str(selected.get("backend", "unknown"))
    selected_quality = float(selected.get("quality", -100.0) or -100.0)
    parts = [f"selected {selected_backend} quality={selected_quality:.1f}"]
    for candidate in candidates:
        backend = candidate.get("backend", "unknown")
        if candidate.get("error"):
            parts.append(f"{backend} error={candidate.get('error')}")
            continue
        report = candidate.get("report")
        if isinstance(report, dict):
            quality = candidate_selection_quality(report)
            if backend == "ctc":
                parts.append(
                    "ctc "
                    f"quality={quality:.1f}, "
                    f"low={report.get('ctc_low_score_count')}, "
                    f"very_low={report.get('ctc_very_low_score_count')}, "
                    f"missing={report.get('ctc_missing_count')}"
                )
            elif backend == "whisperx":
                parts.append(
                    "whisperx "
                    f"quality={quality:.1f}, "
                    f"trusted={report.get('trusted_percent', report.get('matched_percent'))}, "
                    f"review={report.get('review_required_percent')}, "
                    f"collapse={report.get('collapse_detected')}"
                )
            elif backend == "whispercpp":
                parts.append(
                    "whispercpp "
                    f"quality={quality:.1f}, "
                    f"trusted={report.get('trusted_percent', report.get('matched_percent'))}, "
                    f"review={report.get('review_required_percent')}"
                )
    if selected_backend == "ctc":
        parts.append("ctc is preferred on near-ties because it is forced to the known lyric order")
    return "; ".join(parts)


def raw_asr_is_fallback_eligible(report: dict[str, object]) -> bool:
    """Reject raw fallback when Whisper merged a large section into one segment."""
    try:
        max_segment = float(report.get("raw_asr_max_segment_seconds", 0.0) or 0.0)
    except (TypeError, ValueError):
        return False
    return 0.0 < max_segment <= 12.0


def apply_ctc_weak_prefix_recovery(
    timestamps: list[float], report: dict[str, object], duration: float
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Recover a sung prefix that CTC skipped before locking onto the line."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return timestamps, report, []

    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict) or index == 0:
            continue
        try:
            current_time = float(assignment.get("timestamp", refined[index]) or refined[index])
            ctc_score = float(assignment.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        # Whole-line confidence can be high even when only the first phoneme
        # was dropped, so gate on the weak first token and a strong earlier peak.
        if ctc_score > 0.60:
            continue
        spans = assignment.get("ctc_token_spans")
        peaks = assignment.get("ctc_first_token_candidates")
        if not isinstance(spans, list) or not spans or not isinstance(peaks, list):
            continue
        try:
            first_token_score = float(spans[0].get("score", 1.0) or 0.0)
        except (AttributeError, TypeError, ValueError):
            continue
        # A bounded hybrid window can reveal a stronger earlier onset even when
        # the eventual CTC token itself is not strictly low confidence.
        if first_token_score > 0.05 and not assignment.get("ctc_hybrid_window_realign"):
            continue

        previous_time = refined[index - 1]
        previous_token_end = previous_time
        previous_assignment = assignments[index - 1]
        if isinstance(previous_assignment, dict):
            previous_spans = previous_assignment.get("ctc_token_spans")
            if isinstance(previous_spans, list):
                for span in previous_spans:
                    if not isinstance(span, dict):
                        continue
                    try:
                        previous_token_end = max(previous_token_end, float(span.get("end")))
                    except (TypeError, ValueError):
                        continue
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        eligible: list[tuple[float, float]] = []
        for peak in peaks:
            if not isinstance(peak, dict):
                continue
            try:
                peak_time = float(peak.get("time"))
                peak_score = float(peak.get("score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            if (
                previous_token_end + 0.03 < peak_time < current_time - 0.45
                and peak_time < next_time - 0.10
                and peak_score >= 0.05
                and current_time - peak_time <= 2.25
            ):
                eligible.append((peak_time, peak_score))
        if not eligible:
            continue
        peak_time, peak_score = max(eligible, key=lambda item: item[1])
        refined[index] = peak_time
        assignment["timestamp"] = round(peak_time, 3)
        assignment["ctc_weak_prefix_recovery"] = True
        assignment["ctc_weak_prefix_recovery_from"] = round(current_time, 3)
        assignment["ctc_weak_prefix_peak_score"] = round(peak_score, 6)
        changes.append(
            {
                "entry": index + 1,
                "from": round(current_time, 3),
                "to": round(peak_time, 3),
                "shift": round(current_time - peak_time, 3),
                "ctc_score": round(ctc_score, 6),
                "first_token_score": round(first_token_score, 6),
                "prefix_peak_score": round(peak_score, 6),
                "reason": "strong-first-token-posterior-before-weak-ctc-prefix",
            }
        )
    if changes:
        report["ctc_weak_prefix_recovery_count"] = len(changes)
        report["ctc_weak_prefix_recoveries"] = changes
    return refined, report, changes


def apply_ctc_crossline_initial_recovery(
    timestamps: list[float], report: dict[str, object], duration: float
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Reject initial CTC tokens that were borrowed from the prior lyric tail."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return timestamps, report, []

    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index in range(1, len(assignments)):
        previous = assignments[index - 1]
        current = assignments[index]
        if not isinstance(previous, dict) or not isinstance(current, dict):
            continue
        if current.get("ctc_crossline_initial_recovery"):
            continue
        previous_spans = previous.get("ctc_token_spans")
        current_spans = current.get("ctc_token_spans")
        if not isinstance(previous_spans, list) or not isinstance(current_spans, list) or len(current_spans) < 2:
            continue
        try:
            previous_end = max(float(span.get("end")) for span in previous_spans if isinstance(span, dict))
            parsed_spans = [
                (
                    float(span.get("start")),
                    float(span.get("end")),
                    float(span.get("score", 0.0) or 0.0),
                )
                for span in current_spans
                if isinstance(span, dict)
            ]
        except (AttributeError, TypeError, ValueError):
            continue
        if len(parsed_spans) < 2:
            continue

        current_start = parsed_spans[0][0]
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        candidate_index: int | None = None
        recovery_mode = ""

        if current_start <= previous_end + 0.06 and parsed_spans[1][0] - current_start >= 0.70:
            candidate_index = 1
            recovery_mode = "single-overlapping-tail-token"
        else:
            evidence = ctc_prefix_boundary_evidence(current, current_start - previous_end)
            if evidence.get("borrowed_tail_prefix"):
                # Short cross-line leakage is different from a detached ghost
                # prefix: the real next-line token can arrive only 80-400 ms
                # later.  Skip only a compact run of very weak tokens and
                # require a reliable token plus downstream support, otherwise
                # leave the timestamp for review rather than guessing.
                search_limit = min(5, len(parsed_spans))
                for probe_index in range(1, search_limit):
                    candidate_start = parsed_spans[probe_index][0]
                    candidate_score = parsed_spans[probe_index][2]
                    preceding_scores = [item[2] for item in parsed_spans[:probe_index]]
                    support_scores = [item[2] for item in parsed_spans[probe_index : probe_index + 5]]
                    support_count = sum(score >= 0.08 for score in support_scores)
                    if (
                        0.08 <= candidate_start - previous_end <= 0.50
                        and 0.06 <= candidate_start - current_start <= 0.45
                        and preceding_scores
                        and all(score < 0.03 for score in preceding_scores)
                        and candidate_score >= 0.08
                        and support_count >= 2
                    ):
                        candidate_index = probe_index
                        recovery_mode = "short-borrowed-tail-prefix"
                        break
            if candidate_index is None and evidence.get("ghost_weak_prefix"):
                search_limit = min(6, len(parsed_spans))
                for probe_index in range(1, search_limit):
                    candidate_start = parsed_spans[probe_index][0]
                    preceding_scores = [item[2] for item in parsed_spans[:probe_index]]
                    inter_token_gap = candidate_start - parsed_spans[probe_index - 1][0]
                    candidate_score = parsed_spans[probe_index][2]
                    reliable_support = any(
                        later_score >= 0.08
                        and 0.0 <= later_start - candidate_start <= 1.35
                        for later_start, _later_end, later_score in parsed_spans[probe_index : probe_index + 5]
                    )
                    relative_score_floor = max(
                        0.03,
                        max(preceding_scores, default=0.0) * 1.80,
                    )
                    if (
                        inter_token_gap >= 0.55
                        and candidate_start - previous_end >= 0.50
                        and candidate_start - current_start >= 0.80
                        and preceding_scores
                        and all(score < 0.05 for score in preceding_scores)
                        and candidate_score >= relative_score_floor
                        and reliable_support
                    ):
                        candidate_index = probe_index
                        recovery_mode = "multi-token-ghost-prefix"
                        break

        if candidate_index is None:
            continue
        recovered_start = parsed_spans[candidate_index][0]
        if not previous_end + 0.05 < recovered_start < next_time - 0.10:
            continue

        old_time = refined[index]
        refined[index] = recovered_start
        current["timestamp"] = round(recovered_start, 3)
        current["ctc_crossline_initial_recovery"] = True
        current["ctc_crossline_initial_recovery_mode"] = recovery_mode
        current["ctc_crossline_initial_recovery_from"] = round(old_time, 3)
        current["ctc_crossline_initial_recovery_skipped_tokens"] = candidate_index
        ghost_span = recovered_start - current_start
        support_scores = [item[2] for item in parsed_spans[candidate_index : candidate_index + 5]]
        support_count = sum(1 for score in support_scores if score >= 0.08)
        candidate_score = parsed_spans[candidate_index][2]
        recovery_trusted = (
            recovery_mode in {"multi-token-ghost-prefix", "short-borrowed-tail-prefix"}
            or (
                recovery_mode == "single-overlapping-tail-token"
                and ghost_span >= 0.80
                and candidate_score >= 0.25
                and support_count >= 2
            )
        )
        current["ctc_crossline_initial_recovery_trusted"] = recovery_trusted
        if recovery_trusted:
            current["ctc_effective_token_start_index"] = candidate_index
        else:
            # A provisional move may be a better timestamp than the token that
            # literally overlaps the previous line, but it is not allowed to
            # rewrite which CTC token provides evidence for the line.  Keeping
            # a stale effective index here made later validators ignore a
            # usable first token and manufacture a weak-prefix failure.
            current.pop("ctc_effective_token_start_index", None)
            current["ctc_crossline_initial_recovery_provisional"] = True
        current["ctc_crossline_initial_recovery_evidence"] = {
            "previous_token_end": round(previous_end, 3),
            "candidate_score": round(candidate_score, 6),
            "candidate_support_count": support_count,
            "candidate_support_scores": [round(score, 6) for score in support_scores],
            "preceding_scores": [
                round(item[2], 6) for item in parsed_spans[:candidate_index]
            ],
            "previous_gap_seconds": round(recovered_start - previous_end, 3),
            "ghost_span_seconds": round(ghost_span, 3),
        }
        changes.append(
            {
                "entry": index + 1,
                "from": round(old_time, 3),
                "to": round(recovered_start, 3),
                "previous_token_end": round(previous_end, 3),
                "detached_initial_gap": round(recovered_start - current_start, 3),
                "skipped_tokens": candidate_index,
                "mode": recovery_mode,
                "trusted": recovery_trusted,
                "reason": (
                    "weak-ghost-prefix-before-supported-lyric-onset"
                    if recovery_mode == "multi-token-ghost-prefix"
                    else (
                        "short-weak-prefix-borrowed-from-previous-line-tail"
                        if recovery_mode == "short-borrowed-tail-prefix"
                        else "current-initial-token-overlaps-previous-line-tail"
                    )
                ),
            }
        )
    if changes:
        report["ctc_crossline_initial_recovery_count"] = len(changes)
        report["ctc_crossline_initial_recoveries"] = changes
    return refined, report, changes



def ctc_forward_supported_prefix_candidate(assignment: object) -> dict[str, object] | None:
    """Find a safely detached initial token after a breath/noise false onset.

    A run of low CTC scores is not sufficient evidence to move a timestamp
    forward: quiet consonants and vowels can be real lyric onsets.  Automatic
    correction is therefore limited to a narrow topology: one or two weak
    initial tokens, followed by a large temporal gap and a strongly supported
    token cluster.  Continuous weak prefixes remain at the original CTC time
    and are available to the audit layer for review instead of being shifted.
    """
    if not isinstance(assignment, dict):
        return None
    spans = assignment.get("ctc_token_spans")
    if not isinstance(spans, list) or len(spans) < 4:
        return None
    parsed: list[tuple[int, float, float, float]] = []
    for index, span in enumerate(spans):
        if not isinstance(span, dict):
            continue
        try:
            parsed.append(
                (
                    index,
                    float(span.get("start")),
                    float(span.get("end")),
                    float(span.get("score", 0.0) or 0.0),
                )
            )
        except (TypeError, ValueError):
            continue
    if len(parsed) < 4 or parsed[0][3] >= 0.03:
        return None

    first_start = parsed[0][1]
    search_limit = min(len(parsed), 3)
    for position in range(1, search_limit):
        original_index, candidate_start, _candidate_end, candidate_score = parsed[position]
        delay = candidate_start - first_start
        previous_end = parsed[position - 1][2]
        detached_gap = candidate_start - previous_end
        if not 0.80 <= delay <= 4.50:
            continue
        preceding_scores = [item[3] for item in parsed[:position]]
        if not preceding_scores:
            continue
        preceding_weak_ratio = sum(score < 0.05 for score in preceding_scores) / len(preceding_scores)
        preceding_mean = sum(preceding_scores) / len(preceding_scores)
        broad_support_scores = [item[3] for item in parsed[position : position + 12]]
        broad_support_count = sum(score >= 0.08 for score in broad_support_scores)

        strong_detached_initial = (
            position <= 2
            and detached_gap >= 0.55
            and preceding_weak_ratio >= 0.75
            and preceding_mean < 0.05
            and candidate_score >= 0.45
            and broad_support_count >= 4
        )
        if not strong_detached_initial:
            continue
        return {
            "token_index": original_index,
            "candidate_time": round(candidate_start, 3),
            "candidate_score": round(candidate_score, 6),
            "delay_seconds": round(delay, 3),
            "detached_gap_seconds": round(detached_gap, 3),
            "preceding_token_count": position,
            "preceding_mean_score": round(preceding_mean, 6),
            "preceding_weak_ratio": round(preceding_weak_ratio, 3),
            "support_mode": "strong-detached-initial-token",
            "support_count": broad_support_count,
            "support_scores": [round(score, 6) for score in broad_support_scores],
        }
    return None

def apply_ctc_forward_supported_prefix_recovery(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> list[dict[str, object]]:
    """Move forward from breath/noise only when later CTC tokens and acoustics agree."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return []
    try:
        features = analyze_audio(audio_path, duration)
    except LrcError:
        return []

    changes: list[dict[str, object]] = []
    probes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict) or index == 0:
            continue
        if assignment.get("ctc_boundary_realign_trusted") or assignment.get(
            "ctc_forward_supported_prefix_recovery_trusted"
        ):
            continue
        candidate = ctc_forward_supported_prefix_candidate(assignment)
        if not isinstance(candidate, dict):
            assignment.pop("ctc_forward_prefix_probe_unresolved", None)
            continue
        try:
            current_time = float(assignment.get("timestamp", timestamps[index]) or timestamps[index])
            candidate_time = float(candidate["candidate_time"])
            candidate_score = float(candidate["candidate_score"])
            candidate_index = int(candidate["token_index"])
        except (TypeError, ValueError, KeyError):
            continue
        support_mode = str(candidate.get("support_mode", "local-supported-token-cluster"))
        strong_detached_initial = support_mode == "strong-detached-initial-token"
        previous_time = timestamps[index - 1]
        next_time = timestamps[index + 1] if index + 1 < len(timestamps) else duration
        previous_end = previous_time
        previous_assignment = assignments[index - 1]
        if isinstance(previous_assignment, dict):
            previous_spans = previous_assignment.get("ctc_token_spans")
            if isinstance(previous_spans, list):
                for span in previous_spans:
                    if not isinstance(span, dict):
                        continue
                    try:
                        previous_end = max(previous_end, float(span.get("end")))
                    except (TypeError, ValueError):
                        continue
        lookback = 0.25 if strong_detached_initial else 0.90
        lookahead = 0.12 if strong_detached_initial else 0.08
        search_start = max(
            previous_end + 0.05,
            current_time + 0.15,
            candidate_time - lookback,
        )
        search_end = min(next_time - 0.10, candidate_time + lookahead)
        acoustic_onset: float | None = None
        acoustic_threshold: float | None = None
        if search_end - search_start >= 0.20:
            for threshold in (0.65, 0.55, 0.45):
                acoustic_onset = first_local_onset(
                    features,
                    search_start,
                    search_end,
                    threshold=threshold,
                    # This window is already bounded by a reliable previous
                    # tail and the independently supported CTC token.  Keeping
                    # the generic detector's anti-edge guard here would erase
                    # a legitimate onset at the exact start of that window.
                    edge_guard_seconds=0.0,
                )
                if acoustic_onset is not None:
                    acoustic_threshold = threshold
                    break

        recovery_time: float | None = None
        recovery_mode = ""
        maximum_onset_lead = 0.08 if strong_detached_initial else 0.85
        if (
            acoustic_onset is not None
            and acoustic_onset >= current_time + 0.25
            and -0.20 <= candidate_time - acoustic_onset
            and candidate_time - acoustic_onset <= maximum_onset_lead + 1e-9
        ):
            recovery_time = acoustic_onset
            recovery_mode = (
                "forward-acoustic-onset-before-strong-detached-token"
                if strong_detached_initial
                else "forward-acoustic-onset-with-ctc-support"
            )
        elif strong_detached_initial and candidate_score >= 0.45:
            # A very strong second/third token plus broad downstream support is
            # sufficient to reject a detached breath token when the onset
            # detector is conservative.
            recovery_time = candidate_time
            recovery_mode = "strong-detached-initial-ctc-token"

        probe = {
            "entry": index + 1,
            "lyric": entry_sung_text(entries[index]),
            "from": round(current_time, 3),
            "supported_token": candidate,
            "search_start": round(search_start, 3),
            "search_end": round(search_end, 3),
            "acoustic_onset": round(acoustic_onset, 3) if acoustic_onset is not None else None,
            "acoustic_threshold": acoustic_threshold,
            "accepted": recovery_time is not None,
            "mode": recovery_mode or "unresolved-weak-prefix",
        }
        probes.append(probe)
        assignment["ctc_forward_supported_prefix_probe"] = probe
        if recovery_time is None:
            assignment["ctc_forward_prefix_probe_unresolved"] = True
            continue
        if not previous_end + 0.05 < recovery_time < next_time - 0.10:
            assignment["ctc_forward_prefix_probe_unresolved"] = True
            probe["accepted"] = False
            probe["mode"] = "candidate-outside-neighbor-bounds"
            continue
        timestamps[index] = recovery_time
        assignment["timestamp"] = round(recovery_time, 3)
        assignment["ctc_forward_supported_prefix_recovery"] = True
        assignment["ctc_forward_supported_prefix_recovery_trusted"] = True
        assignment["ctc_forward_supported_prefix_recovery_mode"] = recovery_mode
        assignment["ctc_forward_supported_prefix_recovery_from"] = round(current_time, 3)
        assignment["ctc_forward_supported_prefix_recovery_token_index"] = candidate_index
        if strong_detached_initial:
            assignment["ctc_effective_token_start_index"] = candidate_index
        assignment.pop("ctc_forward_prefix_probe_unresolved", None)
        assignment["timing_repair_source"] = (
            "torchaudio-mms-fa+forward-supported-prefix-recovery"
        )
        change = {
            **probe,
            "to": round(recovery_time, 3),
            "shift": round(recovery_time - current_time, 3),
        }
        changes.append(change)

    report["ctc_forward_supported_prefix_probes"] = probes
    report["ctc_forward_supported_prefix_probe_count"] = len(probes)
    report["ctc_forward_supported_prefix_recoveries"] = changes
    report["ctc_forward_supported_prefix_recovery_count"] = len(changes)
    if changes:
        annotate_ctc_boundary_evidence(assignments)
    return changes

CTC_BOUNDARY_REVIEW_FLAGS = {
    "ctc_unresolved_boundary",
    "ctc_zero_boundary_gap",
    "ctc_low_confidence_prefix",
    "ctc_abnormal_prefix_compression",
    "ctc_ghost_weak_prefix",
    "ctc_borrowed_tail_prefix",
    "ctc_near_gap_weak_prefix",
    "ctc_prior_line_truncation_contamination",
    "ctc_timestamp_precedes_ctc_support",
    "ctc_detached_weak_prefix",
    "ctc_unsupported_weak_prefix",
    "ctc_forward_prefix_probe_unresolved",
    "ctc_final_timing_guard_unresolved",
    "ctc_right_edge_pileup",
    "ctc_local_window_truncated",
    "ctc_zero_gap_compressed_prefix",
    "ctc_path_fracture",
    "ctc_prefix_probe_failed",
}


def clear_stale_ctc_boundary_review_state(report: dict[str, object]) -> None:
    """Remove boundary reviews from an earlier validation stage before recomputing them."""
    assignments = report.get("assignments")
    if isinstance(assignments, list):
        for assignment in assignments:
            if not isinstance(assignment, dict):
                continue
            flags = assignment.get("flags")
            flag_list = list(flags) if isinstance(flags, list) else []
            removed = [flag for flag in flag_list if flag in CTC_BOUNDARY_REVIEW_FLAGS]
            had_boundary_state = bool(
                removed
                or assignment.get("ctc_unresolved_boundary")
                or assignment.get("ctc_right_edge_truncation")
            )
            if not had_boundary_state:
                continue
            remaining = [flag for flag in flag_list if flag not in CTC_BOUNDARY_REVIEW_FLAGS]
            if remaining:
                assignment["flags"] = remaining
            else:
                assignment.pop("flags", None)
                assignment["review_required"] = False
            assignment.pop("ctc_unresolved_boundary", None)
            assignment.pop("ctc_right_edge_truncation", None)
            assignment.pop("ctc_forward_prefix_probe_unresolved", None)

    suspicious = report.get("suspicious_alignments")
    if not isinstance(suspicious, list):
        return
    cleaned: list[dict[str, object]] = []
    for item in suspicious:
        if not isinstance(item, dict):
            continue
        flags = item.get("flags")
        flag_list = list(flags) if isinstance(flags, list) else []
        boundary_flags = [flag for flag in flag_list if flag in CTC_BOUNDARY_REVIEW_FLAGS]
        if not boundary_flags:
            cleaned.append(item)
            continue
        remaining = [flag for flag in flag_list if flag not in CTC_BOUNDARY_REVIEW_FLAGS]
        if not remaining:
            # Boundary-only findings are provisional and must disappear once the
            # current token spans no longer reproduce the issue.
            continue
        revised = dict(item)
        revised["flags"] = remaining
        revised.pop("ctc_boundary_evidence", None)
        revised.pop("ctc_right_edge_evidence", None)
        revised.pop("ctc_boundary_realign_attempt", None)
        cleaned.append(revised)
    report["suspicious_alignments"] = cleaned


def flag_unresolved_ctc_boundary_issues(
    entries: list[LyricEntry],
    report: dict[str, object],
    persist: bool = True,
) -> list[dict[str, object]]:
    """Fail closed only for boundary evidence that survives the final validation stage."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return []
    if persist:
        clear_stale_ctc_boundary_review_state(report)
    suspicious = report.get("suspicious_alignments")
    suspicious_items = list(suspicious) if isinstance(suspicious, list) else []
    by_entry = {
        int(item["entry"]): item
        for item in suspicious_items
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    }
    unresolved: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        evidence = assignment.get("ctc_boundary_evidence")
        if not isinstance(evidence, dict):
            evidence = {}
        edge_evidence = assignment.get("ctc_right_edge_evidence")
        if not isinstance(edge_evidence, dict):
            edge_evidence = {}
        boundary_recovery_trusted = bool(
            assignment.get("ctc_boundary_realign_trusted")
            or assignment.get("ctc_crossline_initial_recovery_trusted")
            or assignment.get("ctc_forward_supported_prefix_recovery_trusted")
            or assignment.get("ctc_final_timing_recovery_trusted")
        )
        unresolved_boundary = (
            bool(evidence.get("realign_required"))
            or bool(assignment.get("ctc_final_timing_guard_unresolved"))
        ) and not boundary_recovery_trusted
        right_edge_pileup = bool(edge_evidence.get("right_edge_pileup"))
        if not unresolved_boundary and not right_edge_pileup:
            continue
        entry_number = index + 1
        flags = ["ctc_unresolved_boundary"] if unresolved_boundary else []
        if right_edge_pileup:
            flags.extend(["ctc_right_edge_pileup", "ctc_local_window_truncated"])
        if evidence.get("zero_boundary_gap"):
            flags.append("ctc_zero_boundary_gap")
        if evidence.get("low_confidence_prefix"):
            flags.append("ctc_low_confidence_prefix")
        if evidence.get("abnormal_prefix_compression"):
            flags.append("ctc_abnormal_prefix_compression")
        if evidence.get("ghost_weak_prefix"):
            flags.append("ctc_ghost_weak_prefix")
        if evidence.get("borrowed_tail_prefix"):
            flags.append("ctc_borrowed_tail_prefix")
        if evidence.get("near_gap_weak_prefix"):
            flags.append("ctc_near_gap_weak_prefix")
        if evidence.get("prior_line_truncation_contamination"):
            flags.append("ctc_prior_line_truncation_contamination")
        if evidence.get("timestamp_precedes_ctc_support"):
            flags.append("ctc_timestamp_precedes_ctc_support")
        if evidence.get("detached_weak_prefix"):
            flags.append("ctc_detached_weak_prefix")
        if evidence.get("unsupported_weak_prefix"):
            flags.append("ctc_unsupported_weak_prefix")
        if assignment.get("ctc_forward_prefix_probe_unresolved"):
            flags.append("ctc_forward_prefix_probe_unresolved")
        fracture_evidence = assignment.get("ctc_path_fracture_evidence")
        if isinstance(fracture_evidence, dict) and fracture_evidence.get("fractured"):
            flags.append("ctc_path_fracture")
        prefix_probe_evidence = assignment.get("ctc_prefix_probe_evidence")
        if isinstance(prefix_probe_evidence, dict) and not prefix_probe_evidence.get("accepted"):
            flags.append("ctc_prefix_probe_failed")
        if assignment.get("ctc_final_timing_guard_unresolved"):
            flags.append("ctc_final_timing_guard_unresolved")
        diagnostic = {
            "entry": entry_number,
            "flags": flags,
            "evidence": evidence,
            "right_edge_evidence": edge_evidence,
        }
        unresolved.append(diagnostic)
        if not persist:
            continue

        assignment_flags = assignment.get("flags")
        assignment["flags"] = list(dict.fromkeys([
            *(assignment_flags if isinstance(assignment_flags, list) else []),
            *flags,
        ]))
        assignment["ctc_unresolved_boundary"] = unresolved_boundary
        assignment["ctc_right_edge_truncation"] = right_edge_pileup
        assignment["review_required"] = True
        # Boundary/timestamp review is a timing failure, not a lyric-content
        # failure.  Do not mutate the whole-line content score here; the audit
        # reports content_trusted and timing_trusted separately.
        if isinstance(assignment.get("confidence"), (int, float)):
            assignment["confidence"] = min(float(assignment["confidence"]), 0.45)
        for key in (
            "timing_trusted",
            "timing_trusted_reason",
            "timing_trusted_sources",
            "timing_trusted_candidate_times",
        ):
            assignment.pop(key, None)
        item = by_entry.get(entry_number)
        if item is None:
            item = {
                "entry": entry_number,
                "text": entry_sung_text(entries[index]),
            }
            suspicious_items.append(item)
            by_entry[entry_number] = item
        existing_flags = item.get("flags")
        item["flags"] = list(dict.fromkeys([
            *(existing_flags if isinstance(existing_flags, list) else []),
            *flags,
        ]))
        item["severity"] = (
            "high"
            if right_edge_pileup
            or evidence.get("abnormal_prefix_compression")
            or evidence.get("ghost_weak_prefix")
            or evidence.get("detached_weak_prefix")
            else "medium"
        )
        item["review_required"] = True
        item["ctc_boundary_evidence"] = evidence
        item["ctc_right_edge_evidence"] = edge_evidence
        item["ctc_boundary_realign_attempt"] = assignment.get("ctc_boundary_realign_attempt")

    if not persist:
        return unresolved

    report["suspicious_alignments"] = suspicious_items
    report["ctc_unresolved_boundary_count"] = sum(
        1 for item in unresolved if "ctc_unresolved_boundary" in item.get("flags", [])
    )
    report["ctc_right_edge_pileup_count"] = sum(
        1 for item in unresolved if "ctc_right_edge_pileup" in item.get("flags", [])
    )
    report["ctc_unresolved_boundaries"] = unresolved
    report["suspicious_alignment_count"] = len(suspicious_items)
    report["review_required_count"] = sum(
        1 for item in suspicious_items if isinstance(item, dict) and item.get("review_required")
    )
    report["review_required"] = bool(report["review_required_count"])
    report["suspicious_alignment_severity_counts"] = {
        severity: sum(
            1 for item in suspicious_items
            if isinstance(item, dict) and item.get("severity") == severity
        )
        for severity in ("high", "medium", "low", "resolved")
    }
    update_report_confidence_metrics(report)
    return unresolved

def apply_ctc_boundary_validation_stage(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
    stage: str,
) -> tuple[list[float], dict[str, object], dict[str, object]]:
    """Run all boundary-changing CTC helpers in one stable order."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return timestamps, report, {}
    annotate_ctc_boundary_evidence(assignments)
    zero_gap_changes = apply_ctc_zero_gap_boundary_realign(
        audio_path, entries, timestamps, report, duration, args
    )
    if zero_gap_changes:
        refresh_ctc_confidence_diagnostics(entries, report)
    else:
        annotate_ctc_boundary_evidence(assignments)
    timestamps, report, crossline_changes = apply_ctc_crossline_initial_recovery(
        timestamps, report, duration
    )
    annotate_ctc_boundary_evidence(assignments)
    forward_prefix_changes = apply_ctc_forward_supported_prefix_recovery(
        audio_path, entries, timestamps, report, duration
    )
    annotate_ctc_boundary_evidence(assignments)
    timestamps, report, weak_prefix_changes = apply_ctc_weak_prefix_recovery(
        timestamps, report, duration
    )
    annotate_ctc_boundary_evidence(assignments)
    unresolved = flag_unresolved_ctc_boundary_issues(
        entries, report, persist=(stage != "initial-ctc")
    )
    result: dict[str, object] = {
        "stage": stage,
        "zero_gap_realignments": zero_gap_changes,
        "crossline_recoveries": crossline_changes,
        "forward_supported_prefix_recoveries": forward_prefix_changes,
        "weak_prefix_recoveries": weak_prefix_changes,
        "unresolved_boundaries": unresolved,
    }
    history = report.get("ctc_boundary_validation_stages")
    report["ctc_boundary_validation_stages"] = [
        *(history if isinstance(history, list) else []),
        result,
    ]
    return timestamps, report, result


def apply_ctc_local_fusion_to_whisperx(
    whisperx_timestamps: list[float],
    whisperx_report: dict[str, object],
    ctc_report: dict[str, object],
    duration: float,
    raw_report: dict[str, object] | None = None,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    whisperx_assignments = whisperx_report.get("assignments")
    ctc_assignments = ctc_report.get("assignments")
    if not isinstance(whisperx_assignments, list) or not isinstance(ctc_assignments, list):
        return whisperx_timestamps, whisperx_report, []
    raw_assignments = raw_report.get("assignments") if isinstance(raw_report, dict) else None

    fused = list(whisperx_timestamps)
    changes: list[dict[str, object]] = []
    max_items = min(len(fused), len(whisperx_assignments), len(ctc_assignments))
    for index in range(max_items):
        whisperx_item = whisperx_assignments[index]
        ctc_item = ctc_assignments[index]
        if not isinstance(whisperx_item, dict) or not isinstance(ctc_item, dict):
            continue
        try:
            whisperx_time = float(whisperx_item.get("timestamp", fused[index]) or fused[index])
            ctc_time = float(ctc_item.get("timestamp"))
            ctc_score = float(ctc_item.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        disagreement = ctc_time - whisperx_time
        prefix_recovered = bool(ctc_item.get("ctc_weak_prefix_recovery"))
        crossline_recovered = bool(ctc_item.get("ctc_crossline_initial_recovery"))
        boundary_realign_trusted = bool(ctc_item.get("ctc_boundary_realign_trusted"))
        clear_boundary = bool(ctc_item.get("ctc_clear_boundary"))
        if abs(disagreement) < 1.10 and not (
            (prefix_recovered or crossline_recovered or boundary_realign_trusted)
            and abs(disagreement) >= 0.30
        ):
            continue
        previous_time = fused[index - 1] if index > 0 else 0.0
        next_time = fused[index + 1] if index + 1 < len(fused) else duration

        try:
            whisperx_score = float(whisperx_item.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            whisperx_score = 0.0
        previous_same_segment = False
        raw_time: float | None = None
        raw_score: float | None = None
        raw_ctc_agree = False
        if isinstance(raw_assignments, list) and index < len(raw_assignments):
            raw_item = raw_assignments[index]
            if isinstance(raw_item, dict):
                try:
                    raw_time = float(raw_item.get("timestamp"))
                    raw_score = float(raw_item.get("score", 0.0) or 0.0)
                    raw_ctc_agree = raw_score >= 0.72 and abs(raw_time - ctc_time) <= 0.75
                except (TypeError, ValueError):
                    raw_time = None
                    raw_score = None
                    raw_ctc_agree = False
        raw_between_candidates = (
            raw_time is not None
            and raw_score is not None
            and ctc_score >= 0.08
            and raw_score >= 0.82
            and abs(raw_time - whisperx_time) >= 0.25
            and min(ctc_time, whisperx_time) < raw_time < max(ctc_time, whisperx_time)
        )
        raw_high_conflict_anchor = (
            raw_time is not None
            and raw_score is not None
            and raw_score >= 0.95
            and 1.50 <= abs(raw_time - whisperx_time) <= 3.50
            and min(ctc_time, whisperx_time) < raw_time < max(ctc_time, whisperx_time)
            and previous_time + 3.00 < raw_time < next_time - 1.00
        )
        target_time = ctc_time
        target_source = "ctc"
        if boundary_realign_trusted:
            target_time = ctc_time
            target_source = "ctc_boundary_realign"
        elif raw_high_conflict_anchor:
            target_time = raw_time
            target_source = "raw_asr_conflict_anchor"
        elif raw_between_candidates and not raw_ctc_agree:
            target_time = raw_time
            target_source = "raw_asr_segment_internal"
        elif ctc_score < 0.08:
            continue
        if not (previous_time + 0.10 < target_time < next_time - 0.10):
            continue
        if index > 0 and isinstance(whisperx_assignments[index - 1], dict):
            previous_item = whisperx_assignments[index - 1]
            previous_same_segment = (
                previous_item.get("segment") is not None
                and previous_item.get("segment") == whisperx_item.get("segment")
                and float(previous_item.get("score", 0.0) or 0.0) < TRUSTED_ALIGNMENT_SCORE
            )
        reason = ""
        if target_source == "ctc_boundary_realign":
            reason = "ctc-boundary-realign-over-whisperx"
        elif target_source == "raw_asr_conflict_anchor":
            reason = "raw-high-confidence-anchor-over-whisperx"
        elif target_source == "raw_asr_segment_internal":
            reason = "raw-internal-anchor-between-ctc-and-whisperx"
        elif prefix_recovered:
            reason = "ctc-weak-prefix-recovery-over-whisperx"
        elif crossline_recovered:
            reason = "ctc-crossline-initial-recovery-over-whisperx"
        elif clear_boundary and ctc_score >= 0.08 and abs(disagreement) >= 0.45:
            reason = "ctc-clear-boundary-over-whisperx"
        elif raw_ctc_agree and abs(disagreement) >= 1.0:
            reason = "ctc-raw-consensus-over-whisperx"
        elif ctc_score >= 0.25 and abs(disagreement) >= 1.50:
            reason = "high-evidence-ctc-over-whisperx"
        elif ctc_score >= 0.18 and abs(disagreement) >= 1.10:
            reason = "moderate-evidence-ctc-over-whisperx"
        elif abs(disagreement) >= 2.0:
            reason = "large-whisperx-ctc-disagreement"
        elif previous_same_segment:
            reason = "previous-low-confidence-same-asr-segment"
        elif whisperx_score < 0.85:
            reason = "low-confidence-whisperx-with-ctc-anchor"
        if not reason:
            continue

        fused[index] = target_time
        changes.append(
            {
                "entry": index + 1,
                "from": round(whisperx_time, 3),
                "to": round(target_time, 3),
                "delta": round(disagreement, 3),
                "reason": reason,
                "target_source": target_source,
                "whisperx_score": round(whisperx_score, 3),
                "ctc_score": round(ctc_score, 6),
                "ctc_timestamp": round(ctc_time, 3),
                "ctc_token_spans": ctc_item.get("ctc_token_spans"),
                "ctc_weak_prefix_recovery": prefix_recovered,
                "ctc_crossline_initial_recovery": crossline_recovered,
                "ctc_boundary_realign_trusted": boundary_realign_trusted,
                "ctc_boundary_realign_evidence": ctc_item.get("ctc_boundary_realign_evidence"),
                "ctc_clear_boundary": clear_boundary,
                "raw_timestamp": round(raw_time, 3) if raw_time is not None else None,
                "raw_score": round(raw_score, 3) if raw_score is not None else None,
                "raw_ctc_agree": raw_ctc_agree,
            }
        )

    if not changes:
        return whisperx_timestamps, whisperx_report, []

    for index in range(1, len(fused)):
        fused[index] = max(fused[index], fused[index - 1] + 0.10)
    for index in range(len(fused)):
        fused[index] = max(0.0, min(duration, fused[index]))

    report = copy.deepcopy(whisperx_report)
    assignments = report.get("assignments")
    if isinstance(assignments, list):
        for index, timestamp in enumerate(fused):
            if index < len(assignments) and isinstance(assignments[index], dict):
                assignments[index]["timestamp"] = round(timestamp, 3)
                for change in changes:
                    if change["entry"] == index + 1:
                        assignments[index]["ctc_local_fusion"] = True
                        assignments[index]["ctc_local_fusion_reason"] = change["reason"]
                        assignments[index]["ctc_score"] = change["ctc_score"]
                        assignments[index]["ctc_token_spans"] = change.get("ctc_token_spans")
                        assignments[index]["ctc_weak_prefix_recovery"] = bool(
                            change.get("ctc_weak_prefix_recovery")
                        )
                        assignments[index]["ctc_crossline_initial_recovery"] = bool(
                            change.get("ctc_crossline_initial_recovery")
                        )
                        assignments[index]["ctc_boundary_realign_trusted"] = bool(
                            change.get("ctc_boundary_realign_trusted")
                        )
                        assignments[index]["ctc_zero_gap_boundary_realign"] = bool(
                            change.get("ctc_boundary_realign_trusted")
                        )
                        assignments[index]["ctc_boundary_realign_evidence"] = change.get(
                            "ctc_boundary_realign_evidence"
                        )
                        assignments[index]["ctc_clear_boundary"] = bool(change.get("ctc_clear_boundary"))
                        break
    report["backend"] = "hybrid"
    report["strategy"] = "auto-candidate-selection-ctc-local-fusion"
    report["ctc_local_fusion_count"] = len(changes)
    report["ctc_local_fusions"] = changes
    report["ctc_local_fusion_source_backend"] = "whisperx+ctc"
    if isinstance(raw_report, dict):
        report["raw_asr_diagnostic_backend"] = raw_report.get("backend")
        report["raw_asr_repeated_tail_after_0s"] = raw_report.get("asr_repeated_tail_after_0s")
    changes_by_entry = {int(change["entry"]): change for change in changes if isinstance(change.get("entry"), int)}
    suspicious = report.get("suspicious_alignments")
    suspicious_items = list(suspicious) if isinstance(suspicious, list) else []
    fused_entries = {int(change["entry"]) for change in changes if isinstance(change.get("entry"), int)}
    timing_consensus: list[dict[str, object]] = []
    if isinstance(assignments, list):
        for index, assignment in enumerate(assignments):
            if not isinstance(assignment, dict) or index >= max_items:
                continue
            whisperx_item = whisperx_assignments[index]
            ctc_item = ctc_assignments[index]
            raw_item = raw_assignments[index] if isinstance(raw_assignments, list) and index < len(raw_assignments) else None
            if not isinstance(whisperx_item, dict) or not isinstance(ctc_item, dict):
                continue
            try:
                selected_time = float(assignment.get("timestamp", fused[index]) or fused[index])
                whisperx_time = float(whisperx_item.get("timestamp", selected_time) or selected_time)
                whisperx_score = float(whisperx_item.get("score", 0.0) or 0.0)
                ctc_time = float(ctc_item.get("timestamp"))
                ctc_score = float(ctc_item.get("ctc_score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            raw_time = None
            raw_score = None
            if isinstance(raw_item, dict):
                try:
                    raw_time = float(raw_item.get("timestamp"))
                    raw_score = float(raw_item.get("score", 0.0) or 0.0)
                except (TypeError, ValueError):
                    raw_time = None
                    raw_score = None
            votes: list[tuple[str, float]] = []
            if whisperx_score >= 0.45 and abs(whisperx_time - selected_time) <= 0.75:
                votes.append(("whisperx", whisperx_time))
            if ctc_score >= 0.02 and abs(ctc_time - selected_time) <= 0.75:
                votes.append(("ctc", ctc_time))
            if raw_time is not None and raw_score is not None and raw_score >= 0.45 and abs(raw_time - selected_time) <= 0.75:
                votes.append(("raw", raw_time))
            vote_times = [time for _, time in votes]
            consensus = len(votes) >= 2 and (max(vote_times) - min(vote_times) <= 0.75 if vote_times else False)
            change = changes_by_entry.get(index + 1)
            raw_high_confidence_anchor = (
                change is not None
                and change.get("reason") == "raw-high-confidence-anchor-over-whisperx"
                and raw_score is not None
                and raw_score >= 0.95
                and raw_time is not None
                and abs(raw_time - selected_time) <= 0.05
            )
            if not consensus and not raw_high_confidence_anchor:
                continue
            reason = "multi-backend-time-consensus" if consensus else "high-confidence-raw-internal-anchor"
            assignment["timing_trusted"] = True
            assignment["timing_trusted_reason"] = reason
            assignment["timing_trusted_sources"] = [source for source, _ in votes] if consensus else ["raw"]
            assignment["timing_trusted_candidate_times"] = {
                "selected": round(selected_time, 3),
                "whisperx": round(whisperx_time, 3),
                "ctc": round(ctc_time, 3),
                "raw": round(raw_time, 3) if raw_time is not None else None,
            }
            timing_consensus.append(
                {
                    "entry": index + 1,
                    "reason": reason,
                    "sources": assignment["timing_trusted_sources"],
                    "candidate_times": assignment["timing_trusted_candidate_times"],
                }
            )
            if change is not None:
                change["fusion_trusted"] = True
                change["fusion_trust_reason"] = reason
    if timing_consensus:
        report["timing_consensus_count"] = len(timing_consensus)
        report["timing_consensus"] = timing_consensus
    for change in changes:
        delta = abs(float(change.get("delta", 0.0) or 0.0))
        fusion_trusted = bool(change.get("fusion_trusted"))
        severity = "resolved" if fusion_trusted else ("high" if delta >= 2.0 else "medium")
        flags = ["ctc_local_fusion", str(change["reason"])]
        if fusion_trusted:
            flags.append("fusion_trusted")
        suspicious_items.append(
            {
                "entry": change["entry"],
                "flags": flags,
                "severity": severity,
                "review_required": not fusion_trusted,
                "candidate_timestamps": {
                    "output": change["to"],
                    "whisperx": change["from"],
                    "ctc": change.get("ctc_timestamp"),
                    "raw": change.get("raw_timestamp"),
                },
                "candidate_scores": {
                    "whisperx": change.get("whisperx_score"),
                    "ctc": change.get("ctc_score"),
                    "raw": change.get("raw_score"),
                },
                "ctc_token_spans": change.get("ctc_token_spans"),
                "delta": change["delta"],
                "fusion_trusted": fusion_trusted,
                "fusion_trust_reason": change.get("fusion_trust_reason"),
            }
        )

    if isinstance(raw_assignments, list):
        for index in range(min(len(whisperx_assignments), len(ctc_assignments), len(raw_assignments))):
            entry_number = index + 1
            if entry_number in fused_entries:
                continue
            whisperx_item = whisperx_assignments[index]
            ctc_item = ctc_assignments[index]
            raw_item = raw_assignments[index]
            if not isinstance(whisperx_item, dict) or not isinstance(ctc_item, dict) or not isinstance(raw_item, dict):
                continue
            try:
                whisperx_time = float(whisperx_item.get("timestamp"))
                whisperx_score = float(whisperx_item.get("score", 0.0) or 0.0)
                raw_time = float(raw_item.get("timestamp"))
                raw_score = float(raw_item.get("score", 0.0) or 0.0)
                ctc_time = float(ctc_item.get("timestamp"))
                ctc_score = float(ctc_item.get("ctc_score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            raw_whisperx_delta = raw_time - whisperx_time
            if abs(raw_whisperx_delta) < 1.50:
                continue
            if raw_score < 0.82 or whisperx_score < 0.82:
                continue
            if abs(ctc_time - whisperx_time) <= 0.75:
                continue
            ctc_unusable = ctc_score < 0.08 or abs(ctc_time - raw_time) > 1.25
            if not ctc_unusable:
                continue
            suspicious_items.append(
                {
                    "entry": entry_number,
                    "flags": ["unresolved_backend_disagreement", "raw_whisperx_disagreement"],
                    "severity": "high",
                    "review_required": True,
                    "candidate_timestamps": {
                        "whisperx": round(whisperx_time, 3),
                        "raw": round(raw_time, 3),
                        "ctc": round(ctc_time, 3),
                    },
                    "candidate_scores": {
                        "whisperx": round(whisperx_score, 3),
                        "raw": round(raw_score, 3),
                        "ctc": round(ctc_score, 6),
                    },
                    "delta": round(raw_whisperx_delta, 3),
                }
            )
    suspicious_items = dedupe_suspicious_alignments(suspicious_items)
    severity_counts = {"high": 0, "medium": 0, "low": 0}
    review_required_count = 0
    for item in suspicious_items:
        severity = str(item.get("severity", "low"))
        severity_counts[severity if severity in severity_counts else "low"] += 1
        if item.get("review_required"):
            review_required_count += 1
    report["suspicious_alignment_count"] = len(suspicious_items)
    report["suspicious_alignment_severity_counts"] = severity_counts
    report["suspicious_alignments"] = suspicious_items
    report["review_required_count"] = review_required_count
    report["review_required"] = review_required_count > 0
    update_report_confidence_metrics(report)
    return fused, report, changes


def apply_ctc_micro_refinement_to_whisperx(
    whisperx_timestamps: list[float],
    whisperx_report: dict[str, object],
    ctc_report: dict[str, object],
    duration: float,
    raw_report: dict[str, object] | None = None,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    whisperx_assignments = whisperx_report.get("assignments")
    ctc_assignments = ctc_report.get("assignments")
    if not isinstance(whisperx_assignments, list) or not isinstance(ctc_assignments, list):
        return whisperx_timestamps, whisperx_report, []

    refined = list(whisperx_timestamps)
    changes: list[dict[str, object]] = []
    raw_assignments = raw_report.get("assignments") if isinstance(raw_report, dict) else None
    max_items = min(len(refined), len(whisperx_assignments), len(ctc_assignments))
    suspicious_entries = {
        int(item.get("entry"))
        for item in whisperx_report.get("suspicious_alignments", [])
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    }
    for index in range(max_items):
        entry_number = index + 1
        whisperx_item = whisperx_assignments[index]
        ctc_item = ctc_assignments[index]
        if not isinstance(whisperx_item, dict) or not isinstance(ctc_item, dict):
            continue
        if whisperx_item.get("ctc_local_fusion"):
            continue
        try:
            whisperx_time = float(whisperx_item.get("timestamp", refined[index]) or refined[index])
            ctc_time = float(ctc_item.get("timestamp"))
            ctc_score = float(ctc_item.get("ctc_score", 0.0) or 0.0)
            whisperx_score = float(whisperx_item.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        delta = ctc_time - whisperx_time
        if abs(delta) < 0.05 or abs(delta) > 0.65:
            continue
        if ctc_score < 0.02:
            continue
        if whisperx_score < 0.55:
            continue
        if delta > 0.30 and whisperx_score < 0.85 and ctc_score >= 0.22:
            continue
        raw_time: float | None = None
        raw_score: float | None = None
        if isinstance(raw_assignments, list) and index < len(raw_assignments):
            raw_item = raw_assignments[index]
            if isinstance(raw_item, dict):
                try:
                    raw_time = float(raw_item.get("timestamp"))
                    raw_score = float(raw_item.get("score", 0.0) or 0.0)
                except (TypeError, ValueError):
                    raw_time = None
                    raw_score = None

        suspicious_entry = entry_number in suspicious_entries
        # WhisperX and raw ASR often share the same decoded segment.  When both
        # land slightly late at the same timestamp but CTC has a strong earlier
        # first-token path, treat that as an onset correction rather than a
        # global backend preference change.
        asr_same_late_segment = (
            not suspicious_entry
            and raw_time is not None
            and raw_score is not None
            and raw_score >= 0.65
            and abs(raw_time - whisperx_time) <= 0.08
            and -0.55 <= delta <= -0.18
            and ctc_score >= 0.18
            and whisperx_score >= 0.65
        )
        if not suspicious_entry and not asr_same_late_segment:
            continue
        if asr_same_late_segment:
            spans = ctc_item.get("ctc_token_spans")
            first_token_score = 0.0
            if isinstance(spans, list) and spans:
                try:
                    first_token_score = float(spans[0].get("score", 0.0) or 0.0)
                except (AttributeError, TypeError, ValueError):
                    first_token_score = 0.0
            if first_token_score < 0.18:
                continue

        previous_time = refined[index - 1] if index > 0 else 0.0
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        if not (previous_time + 0.10 < ctc_time < next_time - 0.10):
            continue

        refined[index] = ctc_time
        changes.append(
            {
                "entry": entry_number,
                "from": round(whisperx_time, 3),
                "to": round(ctc_time, 3),
                "delta": round(delta, 3),
                "reason": "asr-late-ctc-onset-refinement" if asr_same_late_segment else "small-ctc-whisperx-refinement",
                "whisperx_score": round(whisperx_score, 3),
                "ctc_score": round(ctc_score, 6),
                "ctc_token_spans": ctc_item.get("ctc_token_spans"),
                "ctc_boundary_realign_trusted": bool(ctc_item.get("ctc_boundary_realign_trusted")),
                "ctc_boundary_realign_evidence": ctc_item.get("ctc_boundary_realign_evidence"),
                "raw_timestamp": round(raw_time, 3) if raw_time is not None else None,
                "raw_score": round(raw_score, 3) if raw_score is not None else None,
            }
        )

    if not changes:
        return whisperx_timestamps, whisperx_report, []

    for index in range(1, len(refined)):
        refined[index] = max(refined[index], refined[index - 1] + 0.10)
    for index in range(len(refined)):
        refined[index] = max(0.0, min(duration, refined[index]))

    report = copy.deepcopy(whisperx_report)
    assignments = report.get("assignments")
    changes_by_entry = {int(change["entry"]): change for change in changes if isinstance(change.get("entry"), int)}
    if isinstance(assignments, list):
        for index, timestamp in enumerate(refined):
            if index >= len(assignments) or not isinstance(assignments[index], dict):
                continue
            assignments[index]["timestamp"] = round(timestamp, 3)
            change = changes_by_entry.get(index + 1)
            if change is None:
                continue
            assignments[index]["ctc_micro_refinement"] = True
            assignments[index]["ctc_micro_refinement_reason"] = change["reason"]
            assignments[index]["ctc_score"] = change["ctc_score"]
            assignments[index]["ctc_token_spans"] = change.get("ctc_token_spans")
            assignments[index]["ctc_boundary_realign_trusted"] = bool(
                change.get("ctc_boundary_realign_trusted")
            )
            assignments[index]["ctc_zero_gap_boundary_realign"] = bool(
                change.get("ctc_boundary_realign_trusted")
            )
            assignments[index]["ctc_boundary_realign_evidence"] = change.get(
                "ctc_boundary_realign_evidence"
            )
            assignments[index]["timing_trusted"] = True
            assignments[index]["timing_trusted_reason"] = "small-ctc-whisperx-consensus"
            assignments[index]["timing_trusted_sources"] = ["whisperx", "ctc"]
            assignments[index]["timing_trusted_candidate_times"] = {
                "selected": round(timestamp, 3),
                "whisperx": change["from"],
                "ctc": change["to"],
                "raw": None,
            }

    suspicious = report.get("suspicious_alignments")
    suspicious_items = list(suspicious) if isinstance(suspicious, list) else []
    for item in suspicious_items:
        if not isinstance(item, dict):
            continue
        entry = item.get("entry")
        if not isinstance(entry, int) or entry not in changes_by_entry:
            continue
        change = changes_by_entry[entry]
        flags = item.get("flags")
        if not isinstance(flags, list):
            flags = []
        item["flags"] = list(dict.fromkeys([*flags, "ctc_micro_refinement", "timing_trusted"]))
        item["severity"] = "resolved"
        item["review_required"] = False
        candidates = item.get("candidate_timestamps")
        if not isinstance(candidates, dict):
            candidates = {}
        candidates["output"] = change["to"]
        candidates["whisperx"] = change["from"]
        candidates["ctc"] = change["to"]
        item["candidate_timestamps"] = candidates
        item["ctc_token_spans"] = change.get("ctc_token_spans")
    report["suspicious_alignments"] = suspicious_items
    report["ctc_micro_refinement_count"] = len(changes)
    report["ctc_micro_refinements"] = changes
    report["ctc_micro_refinement_source_backend"] = "whisperx+ctc"
    severity_counts = {"high": 0, "medium": 0, "low": 0, "resolved": 0}
    review_required_count = 0
    for item in suspicious_items:
        if not isinstance(item, dict):
            continue
        severity = str(item.get("severity", "low"))
        severity_counts[severity if severity in severity_counts else "low"] += 1
        if item.get("review_required"):
            review_required_count += 1
    report["suspicious_alignment_severity_counts"] = severity_counts
    report["review_required_count"] = review_required_count
    report["review_required"] = review_required_count > 0
    update_report_confidence_metrics(report)
    return refined, report, changes


def apply_whisperx_acoustic_boundary_refinement(
    audio_path: Path,
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return timestamps, report, []
    suspicious_items = [
        item for item in report.get("suspicious_alignments", []) if isinstance(item, dict)
    ]
    suspicious_by_entry = {
        int(item.get("entry")): item
        for item in suspicious_items
        if isinstance(item.get("entry"), int)
    }
    try:
        features = analyze_audio(audio_path, duration)
    except LrcError:
        return timestamps, report, []

    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        if (
            assignment.get("ctc_micro_refinement")
            or assignment.get("ctc_local_fusion")
            or assignment.get("ctc_boundary_realign_trusted")
        ):
            continue
        try:
            score = float(assignment.get("score", 0.0) or 0.0)
            current_time = float(assignment.get("timestamp", refined[index]) or refined[index])
        except (TypeError, ValueError):
            continue
        entry_number = index + 1
        risk = suspicious_by_entry.get(entry_number)
        flags = risk.get("flags") if isinstance(risk, dict) else []
        flags = flags if isinstance(flags, list) else []
        previous_time = refined[index - 1] if index > 0 else 0.0
        next_time = refined[index + 1] if index + 1 < len(refined) else duration

        candidate: float | None = None
        reason = ""
        if index == 0 and current_time <= 1.0:
            candidate = first_local_onset(features, 0.20, max(0.21, current_time - 0.10), threshold=0.65)
            if candidate is not None and not (0.12 <= current_time - candidate <= 0.35):
                candidate = None
            reason = "first-line-acoustic-onset"
        elif score >= 0.95 and flags == ["candidate_disagreement"]:
            candidate = first_local_onset(
                features,
                max(previous_time + 0.10, current_time - 0.85),
                current_time - 0.12,
                threshold=0.65,
            )
            if candidate is not None and not (0.45 <= current_time - candidate <= 0.65):
                candidate = None
            reason = "candidate-disagreement-acoustic-backtrack"
        elif (
            score >= 0.95
            and "close_neighbor_onset_uncertain" in flags
            and len(normalize_match_text(str(risk.get("text", "")) if isinstance(risk, dict) else "")) <= 4
        ):
            candidate = first_local_onset(
                features,
                max(previous_time + 0.10, current_time - 0.85),
                current_time - 0.12,
                threshold=0.65,
            )
            if candidate is not None and not (0.45 <= current_time - candidate <= 0.65):
                candidate = None
            reason = "short-line-acoustic-backtrack"
        elif (
            score >= 0.95
            and "close_neighbor_onset_uncertain" in flags
            and "candidate_disagreement" not in flags
            and current_time - previous_time >= 2.50
            and next_time - current_time >= 2.50
        ):
            candidate = first_local_onset(
                features,
                current_time + 0.20,
                min(next_time - 0.10, current_time + 0.70),
                threshold=0.65,
            )
            if candidate is not None and not (0.35 <= candidate - current_time <= 0.60):
                candidate = None
            reason = "lead-in-acoustic-forward-onset"
        elif (
            score >= 0.95
            and "follows_suspicious_long_line" in flags
            and "possible_bad_split_boundary" in flags
            and len(normalize_match_text(str(risk.get("text", "")) if isinstance(risk, dict) else "")) <= 12
            and current_time - previous_time >= 3.50
            and next_time - current_time <= 2.20
        ):
            candidate = first_local_onset(
                features,
                max(previous_time + 0.40, current_time - 6.80),
                current_time - 0.45,
                threshold=0.65,
            )
            if candidate is None:
                candidate = first_local_onset(
                    features,
                    max(previous_time + 0.40, current_time - 6.80),
                    current_time - 0.45,
                    threshold=0.55,
                )
            if candidate is not None and not (1.20 <= current_time - candidate <= 6.50):
                candidate = None
            reason = "short-duplicate-bad-split-acoustic-backtrack"
        elif (
            score >= 0.95
            and "follows_suspicious_long_line" in flags
            and "possible_bad_split_boundary" in flags
            and next_time - current_time <= 2.20
        ):
            candidate = first_local_onset(
                features,
                current_time + 0.10,
                min(next_time - 0.10, current_time + 0.85),
                threshold=0.65,
            )
            if candidate is not None and not (0.25 <= candidate - current_time <= 0.45):
                candidate = None
            reason = "bad-split-acoustic-forward-onset"
        if candidate is None:
            continue
        if not (previous_time + 0.05 < candidate < next_time - 0.05):
            continue

        refined[index] = candidate
        assignment["timestamp"] = round(candidate, 3)
        assignment["acoustic_boundary_refinement"] = True
        assignment["acoustic_boundary_refinement_reason"] = reason
        assignment["timing_trusted"] = True
        assignment["timing_trusted_reason"] = reason
        assignment["timing_trusted_sources"] = ["acoustic"]
        assignment["timing_trusted_candidate_times"] = {
            "selected": round(candidate, 3),
            "whisperx": round(current_time, 3),
            "ctc": assignment.get("ctc_timestamp"),
            "raw": None,
        }
        changes.append(
            {
                "entry": entry_number,
                "from": round(current_time, 3),
                "to": round(candidate, 3),
                "delta": round(candidate - current_time, 3),
                "reason": reason,
                "score": round(score, 3),
            }
        )
        if risk is not None:
            risk_flags = risk.get("flags")
            if not isinstance(risk_flags, list):
                risk_flags = []
            risk["flags"] = list(dict.fromkeys([*risk_flags, "acoustic_boundary_refinement", "timing_trusted"]))
            risk["severity"] = "resolved"
            risk["review_required"] = False
            candidates = risk.get("candidate_timestamps")
            if not isinstance(candidates, dict):
                candidates = {}
            candidates["output"] = round(candidate, 3)
            candidates["whisperx"] = round(current_time, 3)
            risk["candidate_timestamps"] = candidates

    if not changes:
        return timestamps, report, []
    report["suspicious_alignments"] = suspicious_items
    report["acoustic_boundary_refinement_count"] = len(changes)
    report["acoustic_boundary_refinements"] = changes
    severity_counts = {"high": 0, "medium": 0, "low": 0, "resolved": 0}
    review_required_count = 0
    for item in suspicious_items:
        severity = str(item.get("severity", "low"))
        severity_counts[severity if severity in severity_counts else "low"] += 1
        if item.get("review_required"):
            review_required_count += 1
    report["suspicious_alignment_severity_counts"] = severity_counts
    report["review_required_count"] = review_required_count
    report["review_required"] = review_required_count > 0
    update_report_confidence_metrics(report)
    return refined, report, changes


def apply_hybrid_ctc_opening_onset_backtrack(
    audio_path: Path,
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Backtrack a CTC-fused line when its opening tokens are visibly late.

    This is intentionally narrower than a general acoustic snap: it only runs
    after CTC has already beaten WhisperX by a large margin, and only when the
    first CTC tokens have weak posterior support while nearby later tokens are
    strong.  That pattern means CTC found the right lyric region but latched
    onto the first clear vowel/consonant cluster instead of the display onset.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return timestamps, report, []
    try:
        features = analyze_audio(audio_path, duration)
    except LrcError:
        return timestamps, report, []

    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict) or not assignment.get("ctc_local_fusion"):
            continue
        if assignment.get("ctc_boundary_realign_trusted"):
            continue
        if assignment.get("ctc_clear_boundary"):
            continue
        try:
            current_time = float(assignment.get("timestamp", refined[index]) or refined[index])
            ctc_score = float(assignment.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        if ctc_score < 0.12:
            continue
        spans = assignment.get("ctc_token_spans")
        if not isinstance(spans, list) or len(spans) < 5:
            continue
        first_scores: list[float] = []
        later_scores: list[float] = []
        for span in spans[:4]:
            if not isinstance(span, dict):
                continue
            try:
                first_scores.append(float(span.get("score", 0.0) or 0.0))
            except (TypeError, ValueError):
                pass
        for span in spans[4:10]:
            if not isinstance(span, dict):
                continue
            try:
                later_scores.append(float(span.get("score", 0.0) or 0.0))
            except (TypeError, ValueError):
                pass
        if not first_scores or max(first_scores) > 0.08:
            continue
        if not later_scores or max(later_scores) < 0.30:
            continue
        previous_time = refined[index - 1] if index else 0.0
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        search_start = max(previous_time + 0.20, current_time - 0.90)
        search_end = current_time - 0.08
        if search_end - search_start < 0.20:
            continue
        candidate = first_local_onset(features, search_start, search_end, threshold=0.65)
        if candidate is None:
            candidate = first_local_onset(features, search_start, search_end, threshold=0.55)
        if candidate is None:
            continue
        shift = current_time - candidate
        if not (0.25 <= shift <= 0.80):
            continue
        if not (previous_time + 0.05 < candidate < next_time - 0.05):
            continue

        refined[index] = candidate
        assignment["timestamp"] = round(candidate, 3)
        assignment["ctc_opening_onset_backtrack"] = True
        assignment["ctc_opening_onset_backtrack_from"] = round(current_time, 3)
        assignment["timing_repair_source"] = "ctc-local-fusion+acoustic-opening-onset"
        changes.append(
            {
                "entry": index + 1,
                "from": round(current_time, 3),
                "to": round(candidate, 3),
                "shift": round(shift, 3),
                "ctc_score": round(ctc_score, 6),
                "search_start": round(search_start, 3),
                "search_end": round(search_end, 3),
                "reason": "weak-opening-ctc-local-fusion-acoustic-onset",
            }
        )
    if not changes:
        return timestamps, report, []

    report["ctc_opening_onset_backtrack_count"] = len(changes)
    report["ctc_opening_onset_backtracks"] = changes
    changes_by_entry = {int(change["entry"]): change for change in changes if isinstance(change.get("entry"), int)}
    suspicious = report.get("suspicious_alignments")
    suspicious_items = list(suspicious) if isinstance(suspicious, list) else []
    for item in suspicious_items:
        if not isinstance(item, dict):
            continue
        entry = item.get("entry")
        if not isinstance(entry, int) or entry not in changes_by_entry:
            continue
        change = changes_by_entry[entry]
        candidates = item.get("candidate_timestamps")
        if not isinstance(candidates, dict):
            candidates = {}
        candidates["output"] = change["to"]
        candidates["acoustic_onset"] = change["to"]
        item["candidate_timestamps"] = candidates
        flags = item.get("flags")
        if not isinstance(flags, list):
            flags = []
        item["flags"] = list(dict.fromkeys([*flags, "ctc_opening_onset_backtrack"]))
        item["chosen_time"] = change["to"]
    return refined, report, changes



def _stage_demucs_input(audio_path: Path, staging_dir: Path, tag: str) -> Path:
    # Deliberately preserve the original bytes and vocal_cache_identity.
    suffix = audio_path.suffix.lower()
    if not re.fullmatch(r"\.[a-z0-9]{1,8}", suffix):
        raise OSError(f"Unsupported Demucs input extension: {suffix!r}")
    safe_tag = re.sub(r"[^A-Za-z0-9_-]", "_", tag)[:40] or "source"
    staged = staging_dir / f"audio_{safe_tag}{suffix}"
    shutil.copyfile(audio_path, staged)
    return staged


def vocal_onset_features(
    audio_path: Path, duration: float, args: argparse.Namespace
) -> tuple[AudioFeatures | None, str | None]:
    if not args.vocal_onset_refine:
        return None, "disabled"
    python_exe = default_ctc_python()
    if not python_exe.exists():
        return None, "missing-asr-python"
    with tempfile.TemporaryDirectory(prefix="lrc-vocals-") as temp_name:
        temp_dir = Path(temp_name)
        try:
            safe_audio = _stage_demucs_input(audio_path, temp_dir, "onset")
        except OSError as exc:
            return None, f"demucs-input-stage-failed: {exc}"
        command = [
            str(python_exe),
            "-m",
            "demucs",
            "--two-stems",
            "vocals",
            "--mp3",
            "-d",
            "cuda",
            "-o",
            str(temp_dir),
            str(safe_audio),
        ]
        proc = subprocess.run(command, check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if proc.returncode != 0:
            detail = (proc.stderr or proc.stdout).strip().replace("\n", " ")
            return None, f"demucs-failed: {detail[-1000:]}"
        stems = list(temp_dir.rglob("vocals.mp3"))
        if not stems:
            return None, "demucs-did-not-write-vocals"
        return analyze_vocal_onsets(stems[0], duration), None


@lru_cache(maxsize=4)
def _demucs_separator_identity(python_exe_text: str) -> tuple[str, str]:
    """Return the runtime Demucs version and deterministic separator revision."""
    demucs_version = "unknown"
    try:
        proc = run_command(
            [
                python_exe_text,
                "-X",
                "utf8",
                "-c",
                (
                    "import importlib.metadata as m; "
                    "print(m.version('demucs'))"
                ),
            ],
            timeout_seconds=15.0,
        )
        if proc.returncode == 0 and proc.stdout.strip():
            demucs_version = proc.stdout.strip().splitlines()[-1].strip()
    except (LrcError, OSError, subprocess.SubprocessError):
        pass
    payload = {
        "protocol_revision": VOCAL_SEPARATOR_PROTOCOL_REVISION,
        "module": "demucs",
        "demucs_version": demucs_version,
        "two_stems": "vocals",
        "format": "mp3",
        "device": "cuda",
    }
    return demucs_version, _timing_content_digest(payload)


def vocal_cache_identity(audio_path: Path, python_exe: Path) -> dict[str, object]:
    """Content-address the vocal stem; filesystem timestamps are diagnostic only."""
    stat = audio_path.stat()
    source_sha256 = _path_sha256(audio_path)
    demucs_version, separator_revision = _demucs_separator_identity(str(python_exe))
    key_payload = {
        "source_audio_sha256": source_sha256,
        "separator_revision": separator_revision,
    }
    return {
        "source_audio_sha256": source_sha256,
        "source_audio_size": int(stat.st_size),
        "source_audio_mtime_ns": int(stat.st_mtime_ns),
        "vocal_separator_protocol_revision": VOCAL_SEPARATOR_PROTOCOL_REVISION,
        "vocal_separator_demucs_version": demucs_version,
        "vocal_separator_revision": separator_revision,
        "vocal_cache_key": hashlib.sha256(
            json.dumps(
                key_payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()[:16],
    }


def _demucs_vocal_stem_valid(path: Path, source_audio: Path) -> bool:
    """Reject truncated/corrupt audio even when a cache file is non-empty."""
    try:
        if path.stat().st_size < 4096:
            return False
        proc = subprocess.run(
            [
                "ffprobe", "-v", "error", "-select_streams", "a:0",
                "-show_entries",
                "stream=codec_name,sample_rate,channels:format=duration",
                "-of", "json", str(path),
            ],
            check=False, capture_output=True, text=True,
            encoding="utf-8", errors="replace", timeout=12,
        )
        if proc.returncode != 0:
            return False
        probe = json.loads(proc.stdout)
        streams = probe.get("streams") or []
        if len(streams) != 1:
            return False
        stream = streams[0]
        if (
            str(stream.get("codec_name", "")).lower() != "mp3"
            or int(stream.get("sample_rate", 0)) < 8000
            or int(stream.get("channels", 0)) < 1
        ):
            return False
        duration = float(probe["format"]["duration"])
        if not math.isfinite(duration) or duration < 1:
            return False
        source_duration = probe_duration(source_audio)
        if abs(duration - source_duration) > max(2.5, source_duration * 0.03):
            return False
        return True
    except (OSError, ValueError, TypeError, KeyError, AttributeError,
            OverflowError, LrcError, subprocess.SubprocessError):
        return False


def _demucs_write_error(cache_dir: Path, detail: str) -> str:
    """Preserve full stderr under the song's own content-addressed cache."""
    log_file = cache_dir / "demucs_last_error.log"
    try:
        log_file.write_text(detail, encoding="utf-8")
        return str(log_file)
    except OSError:
        return "unavailable"


def prepare_vocal_ctc_audio(audio_path: Path, args: argparse.Namespace) -> tuple[Path, str, str | None]:
    """Build or reuse a validated content-addressed isolated vocal stem.

    The temporary output folder is unique per invocation and cannot select an
    earlier Demucs run's result from the shared cache tree.
    """
    if not getattr(args, "vocal_ctc", True):
        return audio_path, "mix", "disabled"
    python_exe = default_ctc_python()
    if not python_exe.exists():
        return audio_path, "mix", "missing-asr-python"
    try:
        identity = vocal_cache_identity(audio_path, python_exe)
    except OSError:
        return audio_path, "mix", "audio-stat-or-hash-failed"
    key = str(identity["vocal_cache_key"])
    cache_dir = DEFAULT_VOCAL_CACHE_DIR / key
    cached = cache_dir / "vocals.mp3"
    if cached.is_file() and _demucs_vocal_stem_valid(cached, audio_path):
        return cached, "vocal-stem", "cache-hit"
    cache_dir.mkdir(parents=True, exist_ok=True)
    demucs_env = os.environ.copy()
    demucs_env["PYTHONUTF8"] = "1"
    demucs_env["PYTHONIOENCODING"] = "utf-8"
    try:
        with tempfile.TemporaryDirectory(prefix="lrc-demucs-run-", dir=cache_dir) as temp_name:
            run_dir = Path(temp_name)
            staged_input = _stage_demucs_input(audio_path, run_dir, key)
            current_output = run_dir / "out"
            proc = subprocess.run(
                [
                    str(python_exe), "-X", "utf8", "-m", "demucs",
                    "--two-stems", "vocals", "--mp3", "--shifts", "0",
                    "-d", "cuda", "-o", str(current_output), str(staged_input),
                ],
                check=False, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                text=True, encoding="utf-8", errors="replace", env=demucs_env,
            )
            if proc.returncode:
                detail = (proc.stderr or proc.stdout or "").strip()
                logfile = _demucs_write_error(cache_dir, detail)
                tail = " ".join(detail[-1300:].splitlines())
                return audio_path, "mix", f"demucs-failed: {tail} [full-log: {logfile}]"
            new_stems = list(current_output.rglob("vocals.mp3"))
            if len(new_stems) != 1:
                return audio_path, "mix", f"demucs-invalid-output-count={len(new_stems)}"
            if not _demucs_vocal_stem_valid(new_stems[0], audio_path):
                return audio_path, "mix", "demucs-invalid-generated-vocal-stem"
            # The output file and the cache are on the same volume, so replace
            # makes a single atomic publication instead of a partial cache.
            os.replace(new_stems[0], cached)
            (cache_dir / "demucs_last_error.log").unlink(missing_ok=True)
    except OSError as exc:
        return audio_path, "mix", f"demucs-input-or-cache-io-failed: {type(exc).__name__}: {exc}"
    return cached, "vocal-stem", "generated"


def nearest_onset_evidence(features: AudioFeatures, timestamp: float) -> tuple[float, float] | None:
    mask = (features.frame_times >= timestamp - 0.35) & (features.frame_times <= timestamp + 0.35)
    indices = np.flatnonzero(mask)
    if not len(indices):
        return None
    peak = max(indices, key=lambda index: float(features.onset_strength[index]))
    return float(features.frame_times[peak]), float(features.onset_strength[peak])


def apply_vocal_onset_tiebreak(
    timestamps: list[float],
    report: dict[str, object],
    ctc_report: dict[str, object],
    audio_path: Path,
    duration: float,
    args: argparse.Namespace,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    features, unavailable = vocal_onset_features(audio_path, duration, args)
    if features is None:
        report["vocal_onset_refinement"] = {"status": "skipped", "reason": unavailable}
        return timestamps, report, []
    assignments = report.get("assignments")
    ctc_assignments = ctc_report.get("assignments")
    if not isinstance(assignments, list) or not isinstance(ctc_assignments, list):
        return timestamps, report, []
    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, current_time in enumerate(timestamps):
        if index >= len(assignments) or index >= len(ctc_assignments):
            continue
        assignment = assignments[index]
        ctc_assignment = ctc_assignments[index]
        if not isinstance(assignment, dict) or not isinstance(ctc_assignment, dict):
            continue
        if assignment.get("ctc_boundary_realign_trusted"):
            continue
        ctc_time = ctc_assignment.get("timestamp")
        if not isinstance(ctc_time, (int, float)):
            continue
        disagreement = abs(float(ctc_time) - current_time)
        if not 0.40 <= disagreement <= 2.0:
            continue
        current_evidence = nearest_onset_evidence(features, current_time)
        ctc_evidence = nearest_onset_evidence(features, float(ctc_time))
        if current_evidence is None or ctc_evidence is None:
            continue
        current_peak, current_strength = current_evidence
        ctc_peak, ctc_strength = ctc_evidence
        if abs(ctc_peak - float(ctc_time)) > 0.18 or abs(current_peak - current_time) < 0.16:
            continue
        if ctc_strength < 0.50 or ctc_strength < current_strength + 0.15:
            continue
        previous_time = refined[index - 1] if index else 0.0
        next_time = timestamps[index + 1] if index + 1 < len(timestamps) else duration
        if not previous_time + 0.10 < ctc_peak < next_time - 0.10:
            continue
        refined[index] = ctc_peak
        assignment["timestamp"] = round(ctc_peak, 3)
        assignment["vocal_onset_tiebreak"] = True
        assignment["timing_repair_source"] = "ctc+demucs-vocal-onset"
        changes.append(
            {
                "entry": index + 1,
                "from": round(current_time, 3),
                "to": round(ctc_peak, 3),
                "ctc_candidate": round(float(ctc_time), 3),
                "vocal_onset_strength": round(ctc_strength, 3),
                "competing_onset_strength": round(current_strength, 3),
                "reason": "demucs-vocal-onset-prefers-ctc",
            }
        )
    report["vocal_onset_refinement"] = {
        "status": "applied",
        "backend": "demucs-htdemucs",
        "change_count": len(changes),
        "changes": changes,
    }
    return refined, report, changes


def flag_unresolved_ctc_disagreements(
    timestamps: list[float], report: dict[str, object], ctc_report: dict[str, object]
) -> None:
    """Do not call a fused timestamp trusted while a CTC alternative remains far away."""
    assignments = report.get("assignments")
    ctc_assignments = ctc_report.get("assignments")
    if not isinstance(assignments, list) or not isinstance(ctc_assignments, list):
        return
    suspicious = report.get("suspicious_alignments")
    if not isinstance(suspicious, list):
        suspicious = []
        report["suspicious_alignments"] = suspicious
    by_entry = {
        item.get("entry"): item
        for item in suspicious
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    }
    for index, current_time in enumerate(timestamps):
        if index >= len(assignments) or index >= len(ctc_assignments):
            continue
        assignment = assignments[index]
        ctc_assignment = ctc_assignments[index]
        if not isinstance(assignment, dict) or not isinstance(ctc_assignment, dict):
            continue
        ctc_time = ctc_assignment.get("timestamp")
        if not isinstance(ctc_time, (int, float)):
            continue
        disagreement = abs(float(ctc_time) - current_time)
        if disagreement < 0.35 or assignment.get("vocal_onset_tiebreak"):
            continue
        entry_number = index + 1
        assignment["unresolved_ctc_disagreement"] = round(disagreement, 3)
        existing = by_entry.get(entry_number)
        if existing is not None:
            existing["review_required"] = True
            existing["severity"] = _ctc_disagreement_severity(disagreement)
            flags = existing.get("flags")
            if not isinstance(flags, list):
                flags = []
                existing["flags"] = flags
            if "unresolved_ctc_disagreement" not in flags:
                flags.append("unresolved_ctc_disagreement")
            candidates = existing.get("candidate_timestamps")
            if not isinstance(candidates, dict):
                candidates = {}
                existing["candidate_timestamps"] = candidates
            candidates["output"] = round(current_time, 3)
            candidates["ctc"] = round(float(ctc_time), 3)
            existing["candidate_disagreement_seconds"] = round(disagreement, 3)
            continue
        suspicious.append(
            {
                "entry": entry_number,
                "lyric": assignment.get("lyric", ""),
                "review_required": True,
                "severity": _ctc_disagreement_severity(disagreement),
                "flags": ["unresolved_ctc_disagreement"],
                "candidate_timestamps": {
                    "output": round(current_time, 3),
                    "ctc": round(float(ctc_time), 3),
                },
                "candidate_disagreement_seconds": round(disagreement, 3),
            }
        )
    review_count = sum(
        1 for item in suspicious if isinstance(item, dict) and bool(item.get("review_required"))
    )
    report["review_required_count"] = review_count
    report["review_required"] = review_count > 0
    update_report_confidence_metrics(report)


def flag_unresolved_raw_ctc_disagreements(
    timestamps: list[float],
    report: dict[str, object],
    raw_report: dict[str, object],
    entries: list[LyricEntry] | None = None,
) -> None:
    """Use raw ASR as a local diagnostic without letting a bad run poison CTC.

    Raw ASR has no guarantee that its matched segments retain a one-to-one
    relationship with the supplied lyric list.  In particular, it can drift by
    almost a constant amount for an entire verse, or continue emitting
    timestamps after matching has collapsed.  Those are useful *section*
    diagnostics, but are not independent per-line evidence against a
    known-lyric CTC path.
    """
    assignments = report.get("assignments")
    raw_assignments = raw_report.get("assignments")
    if not isinstance(assignments, list) or not isinstance(raw_assignments, list):
        return
    suspicious = report.get("suspicious_alignments")
    if not isinstance(suspicious, list):
        suspicious = []
        report["suspicious_alignments"] = suspicious

    observations: list[dict[str, object]] = []
    for index, current_time in enumerate(timestamps):
        if index >= len(assignments) or index >= len(raw_assignments):
            continue
        raw_assignment = raw_assignments[index]
        if not isinstance(raw_assignment, dict):
            continue
        try:
            raw_time = float(raw_assignment.get("timestamp"))
            raw_score = float(raw_assignment.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        observations.append(
            {
                "index": index,
                "raw_time": raw_time,
                "raw_score": raw_score,
                "borrowed": bool(raw_assignment.get("borrowed")),
                # Consensus evidence must come from a real raw-ASR segment, not
                # an interpolated/borrowed placeholder row.
                "segment_bound": raw_assignment.get("segment") is not None,
                "delta": raw_time - current_time,
            }
        )

    # A same-direction, near-constant offset across three or more neighboring
    # entries is raw-ASR clock/segment drift.  Preserve it as one diagnostic
    # rather than turning every lyric in the verse into a separate failure.
    drift_runs: list[dict[str, object]] = []
    current_run: list[dict[str, object]] = []
    for observation in observations:
        raw_score = float(observation["raw_score"])
        delta = float(observation["delta"])
        eligible = (
            not bool(observation["borrowed"])
            and raw_score >= 0.50
            and abs(delta) >= 0.75
        )
        same_direction = (
            not current_run
            or (float(current_run[-1]["delta"]) * delta > 0)
        )
        close_offset = (
            not current_run
            or abs(float(current_run[-1]["delta"]) - delta) <= 0.65
        )
        consecutive = not current_run or int(observation["index"]) == int(current_run[-1]["index"]) + 1
        if eligible and same_direction and close_offset and consecutive:
            current_run.append(observation)
            continue
        if len(current_run) >= 3:
            drift_runs.append(
                {
                    "entries": [int(item["index"]) + 1 for item in current_run],
                    "direction": "raw_earlier" if float(current_run[0]["delta"]) < 0 else "raw_later",
                    "median_delta_seconds": round(float(statistics.median(float(item["delta"]) for item in current_run)), 3),
                    "delta_range_seconds": round(
                        max(float(item["delta"]) for item in current_run)
                        - min(float(item["delta"]) for item in current_run),
                        3,
                    ),
                    "mean_raw_score": round(
                        sum(float(item["raw_score"]) for item in current_run) / len(current_run), 3
                    ),
                }
            )
        current_run = [observation] if eligible else []
    if len(current_run) >= 3:
        drift_runs.append(
            {
                "entries": [int(item["index"]) + 1 for item in current_run],
                "direction": "raw_earlier" if float(current_run[0]["delta"]) < 0 else "raw_later",
                "median_delta_seconds": round(float(statistics.median(float(item["delta"]) for item in current_run)), 3),
                "delta_range_seconds": round(
                    max(float(item["delta"]) for item in current_run)
                    - min(float(item["delta"]) for item in current_run),
                    3,
                ),
                "mean_raw_score": round(
                    sum(float(item["raw_score"]) for item in current_run) / len(current_run), 3
                ),
            }
        )
    systematic_drift_entries = {
        entry for drift_run in drift_runs for entry in drift_run["entries"]
    }

    # Raw ASR is already executed as an independent diagnostic backend.  When a
    # real, high-confidence, non-borrowed raw segment independently agrees with
    # the CTC line onset inside a tight tolerance, preserve that agreement as an
    # in-process authority.  It is intentionally runtime-only: serialized report
    # metadata cannot recreate independent evidence on a later run.
    raw_ctc_consensus: dict[int, dict[str, object]] = {}
    for observation in observations:
        index = int(observation["index"])
        entry_number = index + 1
        raw_score = float(observation["raw_score"])
        delta = float(observation["delta"])
        occurrence_binding = (
            _entry_occurrence_binding(entries, raw_assignments, index)
            if entries is not None and len(entries) == len(raw_assignments)
            else None
        )
        if (
            raw_score < RAW_CTC_CONSENSUS_MIN_SCORE
            or bool(observation["borrowed"])
            or not bool(observation["segment_bound"])
            or entry_number in systematic_drift_entries
            or abs(delta) > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
            or occurrence_binding is None
        ):
            continue
        raw_time = float(observation["raw_time"])
        ctc_time = float(timestamps[index])
        evidence_payload = {
            "entry_index": index,
            "raw_time": round(raw_time, 6),
            "ctc_time": round(ctc_time, 6),
            "raw_score": round(raw_score, 6),
            "max_delta_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
            "occurrence_binding": occurrence_binding,
            "producer": "raw-asr-consensus",
        }
        raw_ctc_consensus[index] = {
            **evidence_payload,
            "evidence_revision": _timing_content_digest(evidence_payload),
        }
    report[_RUNTIME_RAW_CTC_CONSENSUS_KEY] = raw_ctc_consensus
    report["raw_ctc_onset_consensus"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "min_raw_score": RAW_CTC_CONSENSUS_MIN_SCORE,
        "max_delta_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
        "candidate_count": len(raw_ctc_consensus),
        "entries": [index + 1 for index in sorted(raw_ctc_consensus)],
    }
    report["raw_asr_systematic_drift_runs"] = drift_runs
    report["raw_asr_zero_score_rejections"] = sum(
        1 for item in observations if float(item["raw_score"]) <= 0.0
    )
    by_entry = {
        item.get("entry"): item
        for item in suspicious
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    }
    for observation in observations:
        index = int(observation["index"])
        if index >= len(assignments):
            continue
        assignment = assignments[index]
        if not isinstance(assignment, dict):
            continue
        current_time = timestamps[index]
        raw_time = float(observation["raw_time"])
        raw_score = float(observation["raw_score"])
        borrowed = bool(observation["borrowed"])
        # score=0 was assigned only as a draft placeholder.  It is explicitly
        # not a competing alignment candidate and must not trigger review.
        if raw_score < 0.50:
            continue
        if index + 1 in systematic_drift_entries:
            continue
        disagreement = abs(raw_time - current_time)
        threshold = 0.45 if raw_score >= 0.90 and not borrowed else 0.75
        if disagreement < threshold:
            continue
        entry_number = index + 1
        assignment["unresolved_raw_ctc_disagreement"] = round(disagreement, 3)
        severity = _raw_disagreement_severity(raw_score, disagreement)
        existing = by_entry.get(entry_number)
        if existing is None:
            existing = {
                "entry": entry_number,
                "review_required": True,
                "severity": severity,
                "flags": [],
                "candidate_timestamps": {},
            }
            suspicious.append(existing)
            by_entry[entry_number] = existing
        existing["review_required"] = True
        existing["severity"] = severity
        flags = existing.get("flags")
        if not isinstance(flags, list):
            flags = []
            existing["flags"] = flags
        if "unresolved_raw_ctc_disagreement" not in flags:
            flags.append("unresolved_raw_ctc_disagreement")
        candidates = existing.get("candidate_timestamps")
        if not isinstance(candidates, dict):
            candidates = {}
            existing["candidate_timestamps"] = candidates
        candidates["output"] = round(current_time, 3)
        candidates["raw_asr"] = round(raw_time, 3)
        existing["raw_asr_score"] = round(raw_score, 3)
        existing["raw_asr_borrowed"] = borrowed
        existing["candidate_disagreement_seconds"] = round(disagreement, 3)

    for drift_run in drift_runs:
        entries_in_run = drift_run["entries"]
        if not isinstance(entries_in_run, list) or not entries_in_run:
            continue
        entry_number = int(entries_in_run[0])
        existing = by_entry.get(entry_number)
        if existing is None:
            existing = {
                "entry": entry_number,
                "review_required": False,
                "severity": "medium",
                "flags": [],
                "candidate_timestamps": {},
            }
            suspicious.append(existing)
            by_entry[entry_number] = existing
        existing["review_required"] = False
        existing["severity"] = "medium"
        flags = existing.get("flags")
        if not isinstance(flags, list):
            flags = []
            existing["flags"] = flags
        if "raw_asr_systematic_drift" not in flags:
            flags.append("raw_asr_systematic_drift")
        existing["raw_asr_systematic_drift"] = drift_run
    review_count = sum(
        1 for item in suspicious if isinstance(item, dict) and bool(item.get("review_required"))
    )
    report["review_required_count"] = review_count
    report["review_required"] = review_count > 0
    update_report_confidence_metrics(report)


def _central_preview_generation_candidates(
    candidates: list[dict[str, object]],
    selected_backend: str,
    selected_timestamps: list[float],
    selected_report: dict[str, object],
) -> list[dict[str, object]]:
    """Replace same-backend/same-timestamp diagnostic clones with the refined seed."""
    selected_payload = {
        "backend": selected_backend,
        "timestamps": list(selected_timestamps),
        "report": selected_report,
        "error": None,
    }
    result: list[dict[str, object]] = []
    inserted = False
    for candidate in candidates:
        if (
            not candidate.get("error")
            and candidate.get("backend") == selected_backend
            and candidate.get("timestamps") == selected_timestamps
        ):
            if not inserted:
                result.append(selected_payload)
                inserted = True
            continue
        result.append(candidate)
    if not inserted:
        result.append(selected_payload)
    return result


def run_auto_backend_competition(
    audio_path: Path,
    entries: list[LyricEntry],
    duration: float,
    args: argparse.Namespace,
    anchor_path: Path | None,
) -> tuple[list[float], dict[str, object], str, BackendSelection]:
    candidates: list[dict[str, object]] = []
    diagnostic_candidates: list[dict[str, object]] = []
    raw_diagnostic_report: dict[str, object] | None = None
    raw_diagnostic_timestamps: list[float] | None = None
    raw_diagnostic_segments: list[AsrSegment] | None = None
    shared_whisper_wav: Path | None = None
    whisperx_evidence_candidates: list[tuple[list[float], dict[str, object], str]] = []

    # R2L performance-only scheduling: Raw ASR does not consume CTC output,
    # while CTC local-window realignment *does* consume the Raw diagnostic.
    # Run Raw first so the base CTC pass and its local-window follow-up can share
    # one resident CTC helper lifecycle. Candidate/evidence logic is unchanged.
    if default_whisperx_ready():
        _close_persistent_helper_mode("ctc", reason="before-global-raw-asr")
        progress_log("running raw ASR diagnostic (pre-CTC schedule)")
        try:
            shared_whisper_wav = decode_temp_wav(audio_path)
        except (LrcError, OSError):
            shared_whisper_wav = None
        raw_timestamps, raw_report, raw_error, raw_diagnostic_segments = try_whispercpp_diagnostic_candidate(
            audio_path,
            entries,
            duration,
            args,
            predecoded_wav=shared_whisper_wav,
        )
        if not raw_error and isinstance(raw_report, dict):
            raw_diagnostic_report = raw_report
            raw_diagnostic_timestamps = raw_timestamps
            progress_log(
                "raw ASR diagnostic done: "
                f"trusted={raw_report.get('trusted_percent', raw_report.get('matched_percent'))}, "
                f"review={raw_report.get('review_required_count')}, "
                f"quality={candidate_selection_quality(raw_report):.1f}"
            )
        else:
            progress_log(f"raw ASR diagnostic failed: {raw_error}")
        diagnostic_candidates.append(
            {
                "backend": "whispercpp_raw",
                "timestamps": raw_timestamps,
                "report": raw_report,
                "error": raw_error,
            }
        )

    if default_ctc_ready():
        progress_log("running CTC candidate")
        ctc_timestamps, ctc_report, ctc_error = try_ctc_candidate(audio_path, entries, duration, args)
        if not ctc_error and isinstance(ctc_report, dict):
            progress_log(
                "CTC done: "
                f"device={ctc_report.get('ctc_device')}, "
                f"audio={ctc_report.get('ctc_audio_source')}, "
                f"low={ctc_report.get('ctc_low_score_count')}, "
                f"review={ctc_report.get('review_required_count')}, "
                f"quality={candidate_selection_quality(ctc_report):.1f}"
            )
            progress_report_changes("CTC acoustic backtrack candidate generated", ctc_report, "ctc_acoustic_backtracks")
            initial_boundary_stages = ctc_report.get("ctc_boundary_validation_stages")
            if isinstance(initial_boundary_stages, list) and initial_boundary_stages:
                initial_boundary = initial_boundary_stages[-1]
                if isinstance(initial_boundary, dict):
                    progress_change_log(
                        "CTC legacy forward weak-prefix evidence (inactive)",
                        initial_boundary.get("forward_supported_prefix_recoveries"),
                    )
                    progress_change_log(
                        "CTC legacy unresolved-boundary evidence (inactive)",
                        initial_boundary.get("unresolved_boundaries"),
                    )
        else:
            progress_log(f"CTC failed: {ctc_error}")
        candidates.append(
            {
                "backend": "ctc",
                "timestamps": ctc_timestamps,
                "report": ctc_report,
                "error": ctc_error,
            }
        )

    if default_whisperx_ready():
        ctc_candidate = next(
            (candidate for candidate in candidates if candidate.get("backend") == "ctc" and not candidate.get("error")),
            None,
        )
        if (
            ctc_candidate is not None
            and raw_diagnostic_report is not None
            and isinstance(ctc_candidate.get("report"), dict)
            and isinstance(ctc_candidate.get("timestamps"), list)
        ):
            window_timestamps, window_report, local_window_changes = apply_ctc_local_window_realign(
                ctc_alignment_audio_path(ctc_candidate["report"], audio_path),
                entries,
                list(ctc_candidate["timestamps"]),
                ctc_candidate["report"],
                raw_diagnostic_report,
                duration,
                args,
            )
            progress_change_log("CTC local window candidate generated", local_window_changes)
            window_report.update(inactive_legacy_timing_diagnostics())
            ctc_candidate["timestamps"] = window_timestamps
            ctc_candidate["report"] = window_report
            progress_log("checking raw/CTC disagreements")
            flag_unresolved_raw_ctc_disagreements(
                window_timestamps, window_report, raw_diagnostic_report, entries
            )
            bind_runtime_raw_content_identity(window_report, entries, raw_diagnostic_report)
            if (
                raw_asr_is_fallback_eligible(raw_diagnostic_report)
                and raw_diagnostic_timestamps is not None
            ):
                candidates.append(
                    {
                        "backend": "whispercpp",
                        "timestamps": raw_diagnostic_timestamps,
                        "report": raw_diagnostic_report,
                        "error": None,
                        "fallback_reason": "raw-asr-beats-conflicted-ctc",
                    }
                )

    if default_whisperx_ready():
        _park_persistent_helper_mode("ctc", reason="before-global-whisperx")
        try:
            progress_log(
                "running WhisperX candidate "
                f"(reuse_wav={'yes' if shared_whisper_wav is not None else 'no'}, "
                f"reuse_raw={'yes' if raw_diagnostic_segments is not None else 'no'})"
            )
            whisperx_timestamps, whisperx_report = run_whisperx_best_candidate(
                audio_path,
                entries,
                duration,
                args,
                predecoded_wav=shared_whisper_wav,
                normal_raw_segments=raw_diagnostic_segments,
            )
            whisperx_error = None
            progress_log(
                "WhisperX done: "
                f"trusted={whisperx_report.get('trusted_percent', whisperx_report.get('matched_percent'))}, "
                f"review={whisperx_report.get('review_required_count')}, "
                f"quality={candidate_selection_quality(whisperx_report):.1f}"
            )
        except WhisperXEvidenceBundleError as exc:
            whisperx_evidence_candidates = list(exc.evidence_candidates)
            whisperx_timestamps = []
            whisperx_report = {
                "backend": "whisperx",
                "error": str(exc),
                "evidence_candidate_count": len(whisperx_evidence_candidates),
            }
            whisperx_error = str(exc)
            progress_log(
                f"WhisperX failed globally; preserving line evidence from "
                f"{len(whisperx_evidence_candidates)} candidate(s): {whisperx_error}"
            )
        except LrcError as exc:
            whisperx_timestamps = []
            whisperx_report = {"backend": "whisperx", "error": str(exc)}
            whisperx_error = str(exc)
            progress_log(f"WhisperX failed: {whisperx_error}")
        candidates.append(
            {
                "backend": "whisperx",
                "timestamps": whisperx_timestamps,
                "report": whisperx_report,
                "error": whisperx_error,
            }
        )
        _park_persistent_helper_mode("whisperx", reason="global-whisperx-complete")

    # This is only a generation seed for optional hybrid producers.  The final
    # backend is selected later from immutable central evaluations.
    selected = next(
        (
            candidate for candidate in candidates
            if candidate.get("backend") == "whisperx" and not candidate.get("error")
        ),
        None,
    ) or choose_alignment_candidate(candidates)
    candidate_labels = [
        f"{candidate.get('backend')}:{float(candidate.get('quality', candidate_selection_quality(candidate.get('report', {}))) or -100.0):.1f}"
        for candidate in candidates
    ]
    progress_log(
        "hybrid generation seed: "
        f"{selected.get('backend', 'unknown')} "
        f"quality={float(selected.get('quality', candidate_selection_quality(selected.get('report', {}))) or -100.0):.1f}; "
        f"candidates={','.join(candidate_labels)}"
    )
    selected_report = copy.deepcopy(selected["report"])
    assert isinstance(selected_report, dict)
    selected_timestamps = list(selected["timestamps"])
    selected_backend = str(selected.get("backend", selected_report.get("backend", "auto")))
    if selected_backend == "ctc":
        if whisperx_evidence_candidates:
            bind_runtime_whisperx_row_evidence(
                selected_report, entries, whisperx_evidence_candidates
            )
            bind_runtime_whisperx_ctc_consensus(
                selected_report,
                entries,
                selected_timestamps,
                whisperx_evidence_candidates,
            )
            row_summary = selected_report.get("whisperx_row_evidence")
            consensus_summary = selected_report.get("whisperx_ctc_onset_consensus")
            progress_log(
                "WhisperX line evidence preserved: "
                f"rows={row_summary.get('candidate_count', 0) if isinstance(row_summary, dict) else 0}, "
                f"ctc_consensus={consensus_summary.get('candidate_count', 0) if isinstance(consensus_summary, dict) else 0}"
            )
        bind_runtime_ctc_assignment_tail_fallback(selected_report, entries)
    selected_quality = float(selected.get("quality", candidate_selection_quality(selected_report)) or -100.0)
    base_selected_report = copy.deepcopy(selected_report)
    base_selected_timestamps = list(selected_timestamps)
    base_selected_backend = selected_backend
    base_selected_quality = selected_quality
    ctc_candidate: dict[str, object] | None = None

    if selected_backend == "whisperx":
        base_ctc_candidate = next(
            (
                candidate
                for candidate in candidates
                if candidate.get("backend") == "ctc"
                and not candidate.get("error")
                and isinstance(candidate.get("report"), dict)
            ),
            None,
        )
        # Hybrid construction is allowed to mutate its own scratch candidate,
        # but never the preserved global CTC backend hypothesis in `candidates`.
        ctc_candidate = copy.deepcopy(base_ctc_candidate) if base_ctc_candidate is not None else None
        if ctc_candidate is not None:
            raw_candidate = next(
                (
                    candidate
                    for candidate in diagnostic_candidates
                    if candidate.get("backend") == "whispercpp_raw"
                    and not candidate.get("error")
                    and isinstance(candidate.get("report"), dict)
                ),
                None,
            )
            ctc_window_timestamps, ctc_window_report, hybrid_window_changes = apply_ctc_hybrid_window_realign(
                ctc_alignment_audio_path(ctc_candidate["report"], audio_path),
                entries,
                list(ctc_candidate["timestamps"]),
                ctc_candidate["report"],
                selected_report,
                duration,
                args,
            )
            progress_change_log("CTC hybrid window realign applied", hybrid_window_changes)
            ctc_window_report.update(inactive_legacy_timing_diagnostics())
            ctc_candidate["timestamps"] = ctc_window_timestamps
            ctc_candidate["report"] = ctc_window_report
            fused_timestamps, fused_report, fusion_changes = apply_ctc_local_fusion_to_whisperx(
                selected_timestamps,
                selected_report,
                ctc_candidate["report"],
                duration,
                raw_candidate["report"] if raw_candidate is not None else None,
            )
            if fusion_changes:
                selected_timestamps = fused_timestamps
                selected_report = fused_report
                selected_backend = "hybrid"
                selected_quality = candidate_selection_quality(selected_report)
            progress_change_log("local CTC/raw fusion applied", fusion_changes)
            micro_timestamps, micro_report, micro_changes = apply_ctc_micro_refinement_to_whisperx(
                selected_timestamps,
                selected_report,
                ctc_candidate["report"],
                duration,
                raw_candidate["report"] if raw_candidate is not None else None,
            )
            if micro_changes:
                selected_timestamps = micro_timestamps
                selected_report = micro_report
                selected_backend = "hybrid"
                selected_quality = candidate_selection_quality(selected_report)
            progress_change_log("micro CTC refinement applied", micro_changes)
            opening_timestamps, opening_report, opening_changes = apply_hybrid_ctc_opening_onset_backtrack(
                audio_path,
                selected_timestamps,
                selected_report,
                duration,
            )
            if opening_changes:
                selected_timestamps = opening_timestamps
                selected_report = opening_report
                selected_backend = "hybrid"
                selected_quality = candidate_selection_quality(selected_report)
            progress_change_log("opening onset backtrack applied", opening_changes)
            acoustic_timestamps, acoustic_report, acoustic_changes = apply_whisperx_acoustic_boundary_refinement(
                audio_path,
                selected_timestamps,
                selected_report,
                duration,
            )
            if acoustic_changes:
                selected_timestamps = acoustic_timestamps
                selected_report = acoustic_report
                selected_backend = "hybrid"
                selected_quality = candidate_selection_quality(selected_report)
            progress_change_log("acoustic boundary refinement applied", acoustic_changes)
    if ctc_candidate is not None and selected_backend in {"whisperx", "hybrid"}:
        ctc_report = ctc_candidate.get("report")
        if isinstance(ctc_report, dict):
            vocal_timestamps, vocal_report, vocal_changes = apply_vocal_onset_tiebreak(
                selected_timestamps,
                selected_report,
                ctc_report,
                audio_path,
                duration,
                args,
            )
            if vocal_changes:
                selected_timestamps = vocal_timestamps
                selected_report = vocal_report
                selected_backend = "hybrid"
                selected_quality = candidate_selection_quality(selected_report)
            progress_change_log("vocal onset tiebreak applied", vocal_changes)
            flag_unresolved_ctc_disagreements(selected_timestamps, selected_report, ctc_report)
    if selected_backend == "ctc" and raw_diagnostic_report is not None:
        flag_unresolved_raw_ctc_disagreements(selected_timestamps, selected_report, raw_diagnostic_report, entries)
    if selected_backend == "hybrid" and ctc_candidate is not None:
        carried_ctc_report = ctc_candidate.get("report")
        if isinstance(carried_ctc_report, dict):
            carry_bounded_retry_capability_seed(selected_report, carried_ctc_report)
    selected_report["generation_diagnostics"] = {
        "metric_stage": "generation-diagnostic",
        "seed_backend": base_selected_backend,
        "seed_legacy_quality": round(base_selected_quality, 3),
        "refined_legacy_quality": round(selected_quality, 3),
    }
    selected_report["backend"] = selected_backend
    generation_candidates = _central_preview_generation_candidates(
        candidates, selected_backend, selected_timestamps, selected_report
    )

    preview_records: list[dict[str, object]] = []
    shared_retry_helper_cache: dict[str, tuple[str, object]] = {}
    for candidate in generation_candidates:
        candidate_report = candidate.get("report")
        candidate_timestamps = candidate.get("timestamps")
        if (
            candidate.get("error")
            or not isinstance(candidate_report, dict)
            or not isinstance(candidate_timestamps, list)
            or len(candidate_timestamps) != len(entries)
        ):
            continue
        backend = str(candidate.get("backend") or candidate_report.get("backend") or "unknown")
        report_copy = copy.deepcopy(candidate_report)
        report_copy["backend"] = backend
        progress_log(f"central preview backend={backend}")
        preview_timestamps, preview_report, evaluated, _anchor_changes = prepare_backend_timing_preview(
            audio_path,
            entries,
            list(candidate_timestamps),
            report_copy,
            duration,
            args,
            anchor_path,
            retry_helper_cache=shared_retry_helper_cache,
        )
        bundle = _capture_evaluated_backend_bundle(
            evaluated,
            preview_report,
            audio_path=audio_path,
            args=args,
        )
        preview_records.append({
            "timestamps": preview_timestamps,
            "report": preview_report,
            "evaluated": evaluated,
            "bundle": bundle,
        })
    selection = select_evaluated_backend(tuple(
        record["evaluated"]
        for record in preview_records
        if isinstance(record.get("evaluated"), EvaluatedBackendTiming)
    ))
    selected_record = next(
        record for record in preview_records
        if record.get("evaluated") is selection.selected
    )
    selected_timestamps = list(selected_record["timestamps"])
    selected_report = selected_record["report"]
    assert isinstance(selected_report, dict)
    selected_backend = selection.selected.backend
    selected_report[_RUNTIME_BACKEND_PROVENANCE_PROJECTION_SEED_KEY] = (
        _build_backend_provenance_projection_seed(
            audio_path,
            args,
            generation_candidates,
            preview_records,
            selection,
            whisperx_evidence_candidates,
        )
    )
    # Capture extra tail evidence only after all Central previews have already
    # been evaluated.  This runtime-only bundle set is deliberately invisible
    # to peer simulation, backend selection and neutral arbitration.
    selected_report[_RUNTIME_POSTCENTRAL_EVIDENCE_BUNDLES_KEY] = tuple(
        _postcentral_tail_enriched_bundle(
            record["bundle"],
            record["report"],
            entries,
            whisperx_evidence_candidates,
        )
        for record in preview_records
        if isinstance(record.get("bundle"), EvaluatedBackendBundle)
        and isinstance(record.get("report"), dict)
    )
    postcentral_bundles = selected_report[_RUNTIME_POSTCENTRAL_EVIDENCE_BUNDLES_KEY]
    assert isinstance(postcentral_bundles, tuple)
    # Freeze the real in-process CTC execution authority for one later,
    # post-neutral tail-only producer.  No candidate set or Central input is
    # retained as mutable authority here; the bundle revision and frozen retry
    # epoch bind the helper execution to the already-evaluated CTC preview.
    for record in preview_records:
        evaluated = record.get("evaluated")
        bundle = record.get("bundle")
        ctc_report = record.get("report")
        if (
            not isinstance(evaluated, EvaluatedBackendTiming)
            or evaluated.backend != "ctc"
            or not isinstance(bundle, EvaluatedBackendBundle)
            or not isinstance(ctc_report, dict)
        ):
            continue
        capability = ctc_report.get(_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY)
        if not isinstance(capability, BoundedRetryCapability):
            continue
        tail_context = _tail_evidence_context_from_report(
            ctc_report, entries=entries, capability=capability
        )
        if tail_context is None or not _tail_context_is_valid(tail_context):
            continue
        enriched_bundle = next(
            (
                item for item in postcentral_bundles
                if isinstance(item, EvaluatedBackendBundle)
                and item.evaluated is evaluated
                and item.evaluated.backend == "ctc"
            ),
            None,
        )
        if enriched_bundle is None:
            continue
        retry_epoch = freeze_base_retry_epoch(
            "ctc",
            ctc_report,
            bundle.candidate_sets,
            thaw_generation_diagnostics(evaluated),
            capability,
        )
        selected_report[_RUNTIME_POSTCENTRAL_CTC_TAIL_PRODUCER_CONTEXT_KEY] = (
            PostcentralCtcTailProducerContext(
                capability=capability,
                epoch=retry_epoch,
                tail_context=tail_context,
                bundle_revision=enriched_bundle.bundle_revision,
                candidate_sets_revision=enriched_bundle.candidate_sets_revision,
                helper_cache=shared_retry_helper_cache,
            )
        )
        break

    selected_report["generation_diagnostics"] = {
        **(
            selected_report.get("generation_diagnostics")
            if isinstance(selected_report.get("generation_diagnostics"), dict)
            else {}
        ),
        "legacy_confidence_metrics": [
            candidate_summary(candidate["report"], str(candidate.get("error")) if candidate.get("error") else None)
            for candidate in generation_candidates
            if isinstance(candidate.get("report"), dict)
        ],
        "diagnostic_candidates": [
            candidate_summary(candidate["report"], str(candidate.get("error")) if candidate.get("error") else None)
            for candidate in diagnostic_candidates
            if isinstance(candidate.get("report"), dict)
        ],
    }
    progress_log(
        f"final central backend={selected_backend}: "
        f"timing_trusted={selection.selected.summary.timing_trusted_percent}, "
        f"authority_trusted={selection.selected.summary.overall_trusted_percent}, "
        f"review={selection.selected.summary.review_required_count}, "
        f"unverified={selection.selected.summary.unverified_count}, "
        f"quality={selection.selected.quality:.1f}"
    )
    return selected_timestamps, selected_report, selected_backend, selection


def low_confidence_run_start(report: dict[str, object], run_length: int = 4) -> int | None:
    assignments = report.get("assignments", [])
    if not isinstance(assignments, list):
        return None
    low_flags: list[bool] = []
    for item in assignments:
        if not isinstance(item, dict):
            low_flags.append(True)
            continue
        low_flags.append(item.get("segment") is None or float(item.get("score", 0.0) or 0.0) < 0.62)
    for index in range(0, max(0, len(low_flags) - run_length + 1)):
        if all(low_flags[index : index + run_length]):
            return index
    return None


def fused_candidate_report(
    normal_report: dict[str, object],
    sns_report: dict[str, object],
    timestamps: list[float],
    collapse_start: int,
    adopted_sns_entries: list[int],
) -> dict[str, object]:
    report = copy.deepcopy(sns_report)
    normal_assignments = normal_report.get("assignments", [])
    sns_assignments = sns_report.get("assignments", [])
    if isinstance(normal_assignments, list) and isinstance(sns_assignments, list):
        fused_assignments: list[object] = []
        for index in range(max(len(normal_assignments), len(sns_assignments), len(timestamps))):
            use_sns = index >= collapse_start or index in adopted_sns_entries
            source = sns_assignments if use_sns else normal_assignments
            item = copy.deepcopy(source[index]) if index < len(source) else {"entry": index + 1}
            if isinstance(item, dict) and index < len(timestamps):
                item["timestamp"] = round(timestamps[index], 3)
            fused_assignments.append(item)
        report["assignments"] = fused_assignments
    report["candidate_fusion"] = {
        "normal_until_entry": collapse_start,
        "sns_from_entry": collapse_start + 1,
        "adopted_sns_entries_before_tail": [entry + 1 for entry in adopted_sns_entries],
        "reason": "normal-candidate-low-confidence-run",
    }
    return report


def match_whisper_segments(entries: list[LyricEntry], segments: list[AsrSegment], duration: float) -> tuple[list[float], dict[str, object]]:
    entry_texts = [normalize_match_text(entry.lines[0] if entry.lines else entry.alignment_text) for entry in entries]
    segment_texts = [normalize_match_text(segment.text) for segment in segments]

    assignments: list[int | None] = [None] * len(entries)
    scores: list[float] = [0.0] * len(entries)
    borrowed: list[bool] = [False] * len(entries)
    last_segment = -1

    for entry_index, entry_text in enumerate(entry_texts):
        if not entry_text:
            continue
        best: tuple[float, int] | None = None
        search_start = max(0, last_segment)
        search_end = min(len(segment_texts), last_segment + 12)
        for segment_index in range(search_start, search_end):
            variant_best: tuple[float, int] | None = None
            for span in (1, 2, 3):
                if segment_index + span > len(segment_texts):
                    continue
                parts = segment_texts[segment_index : segment_index + span]
                combined = "".join(parts)
                score = lyric_segment_score(entry_text, combined)
                target_segment = segment_index
                exact_index = combined.find(entry_text)
                if exact_index >= 0:
                    cursor = 0
                    for offset, part in enumerate(parts):
                        if exact_index < cursor + len(part):
                            target_segment = segment_index + offset
                            break
                        cursor += len(part)
                candidate = (score, target_segment)
                if variant_best is None or candidate[0] > variant_best[0]:
                    variant_best = candidate
            if variant_best and (best is None or variant_best[0] > best[0]):
                best = variant_best
            if variant_best and variant_best[0] >= 0.88:
                break
        if best and best[0] >= 0.42:
            scores[entry_index] = best[0]
            assignments[entry_index] = best[1]
            last_segment = max(last_segment, best[1])

    for entry_index, segment_index in enumerate(assignments):
        if segment_index is None or segment_index <= 0:
            continue
        entry_text = entry_texts[entry_index]
        current_text = segment_texts[segment_index]
        for previous_index in range(segment_index - 1, max(-1, segment_index - 3), -1):
            previous_text = segment_texts[previous_index]
            if not previous_text:
                continue
            if segments[segment_index].start - segments[previous_index].start > 2.5:
                continue
            if sequence_ratio(previous_text, current_text) < 0.70:
                continue
            previous_score = lyric_segment_score(entry_text, previous_text)
            if previous_score >= scores[entry_index] - 0.05:
                assignments[entry_index] = previous_index
                scores[entry_index] = max(scores[entry_index], previous_score)
                segment_index = previous_index
                current_text = previous_text
                break
        if segment_index is None or segment_index <= 0:
            continue
        for previous_index in range(segment_index - 1, max(-1, segment_index - 4), -1):
            previous_text = segment_texts[previous_index]
            if not previous_text:
                continue
            if segments[segment_index].start - segments[previous_index].start > 5.0:
                continue
            if sequence_ratio(previous_text, current_text) < 0.86:
                continue
            if not entry_text.startswith(previous_text):
                continue
            assignments[entry_index] = previous_index
            scores[entry_index] = max(scores[entry_index], 0.80)
            break

    timestamps: list[float | None] = [None] * len(entries)
    for index, segment_index in enumerate(assignments):
        if segment_index is not None:
            timestamp = segments[segment_index].start
            char_time = segment_char_time(entry_texts[index], segments[segment_index])
            if char_time is not None:
                timestamp = char_time
            elif not segments[segment_index].chars:
                raw_entry_text = entries[index].lines[0] if entries[index].lines else entries[index].alignment_text
                estimated_time = estimated_segment_text_time(entry_texts[index], raw_entry_text, segments[segment_index])
                if estimated_time is not None:
                    timestamp = estimated_time
            timestamps[index] = timestamp

    # Fill missing lines by interpolation. If a missing line immediately precedes
    # a close matched segment, treat it as the first lyric in that combined ASR
    # segment instead of placing it halfway through the previous gap.
    for index, timestamp in enumerate(timestamps):
        if timestamp is not None:
            continue
        left = next((idx for idx in range(index - 1, -1, -1) if timestamps[idx] is not None), None)
        right = next((idx for idx in range(index + 1, len(timestamps)) if timestamps[idx] is not None), None)
        if (
            left is not None
            and right is not None
            and assignments[left] is not None
            and assignments[left] == assignments[right]
        ):
            assignments[index] = assignments[left]
            timestamps[index] = segments[assignments[index]].start
            continue
        if right is not None and assignments[right] is not None:
            segment_start = segments[assignments[right]].start
            if (
                (left is None or segment_start - float(timestamps[left] or 0.0) <= 4.2)
                and (left is None or segment_start > float(timestamps[left] or 0.0) + 0.4)
            ):
                timestamps[index] = segment_start
                assignments[index] = assignments[right]
                borrowed[index] = True
                continue
        if (
            left is not None
            and right is not None
            and assignments[left] is not None
            and not is_instrumental_marker(entries[index])
        ):
            previous_end = segments[assignments[left]].end
            if float(timestamps[right] or 0.0) - previous_end >= 6.0:
                entry_text = normalize_match_text(entries[index].lines[0] if entries[index].lines else entries[index].alignment_text)
                tail_offset = min(3.2, max(2.8, len(entry_text) * 0.45))
                timestamps[index] = min(
                    float(timestamps[right] or 0.0) - 0.50,
                    previous_end + tail_offset,
                )
                continue
        if left is not None and right is not None:
            span = right - left
            timestamps[index] = float(timestamps[left] or 0.0) + (float(timestamps[right] or 0.0) - float(timestamps[left] or 0.0)) * ((index - left) / span)
        elif left is not None:
            timestamps[index] = min(duration, float(timestamps[left] or 0.0) + 2.0 * (index - left))
        elif right is not None:
            timestamps[index] = max(0.0, float(timestamps[right] or 0.0) - 2.0 * (right - index))
        else:
            timestamps[index] = 0.0

    # When a borrowed line and the following matched line share one ASR segment,
    # split the segment instead of stamping both at the same start time.
    for index in range(len(timestamps) - 1):
        if borrowed[index] and assignments[index] is not None and assignments[index + 1] == assignments[index]:
            segment = segments[assignments[index]]
            segment_duration = max(0.0, segment.end - segment.start)
            timestamps[index] = segment.start
            timestamps[index + 1] = max(
                float(timestamps[index + 1] or 0.0),
                segment.start + segment_duration * 0.55,
            )

    final = [float(timestamp or 0.0) for timestamp in timestamps]
    for index in range(1, len(final) - 1):
        segment_index = assignments[index]
        next_segment_index = assignments[index + 1]
        if (
            segment_index is None
            or next_segment_index is None
            or segment_index == next_segment_index
            or scores[index] < 0.60
        ):
            continue
        current_segment = segments[segment_index]
        next_time = final[index + 1]
        gap_after_segment = next_time - current_segment.end
        gap_after_previous = final[index] - final[index - 1]
        current_duration = current_segment.end - current_segment.start
        current_text = segment_texts[segment_index]
        entry_text = normalize_match_text(entries[index].lines[0] if entries[index].lines else entries[index].alignment_text)
        direct_segment_match = (
            bool(entry_text)
            and (
                entry_text in current_text
                or current_text in entry_text
                or lyric_segment_score(entry_text, current_text) >= 0.82
            )
        )
        if (
            gap_after_segment < 6.0
            or next_time - final[index] < 8.0
            or gap_after_previous < 4.5
            or current_duration < 2.5
            or direct_segment_match
        ):
            continue
        lead_time = min(2.8, max(1.4, 1.0 + len(entry_text) * 0.10))
        shifted = max(final[index - 1] + 0.10, next_time - lead_time)
        if final[index] < shifted < next_time - 0.30:
            final[index] = shifted

    group_start = 0
    while group_start < len(final):
        segment_index = assignments[group_start]
        group_end = group_start + 1
        while group_end < len(final) and assignments[group_end] == segment_index:
            group_end += 1
        group_size = group_end - group_start
        if segment_index is not None and group_size > 1:
            segment = segments[segment_index]
            next_segment_start: float | None = None
            for later_index in range(group_end, len(final)):
                later_segment = assignments[later_index]
                if later_segment is not None and later_segment != segment_index:
                    next_segment_start = segments[later_segment].start
                    break
            segment_span = max(0.5, segment.end - segment.start)
            if next_segment_start is not None and 0.5 < next_segment_start - segment.start <= 18.0:
                interval_end = next_segment_start - 0.10
            else:
                interval_end = segment.start + max(segment_span, group_size * 3.5)
                if next_segment_start is not None:
                    interval_end = min(interval_end, next_segment_start - 0.10)
            interval_end = max(interval_end, segment.start + 0.20 * group_size)
            interval = interval_end - segment.start
            for offset, entry_index in enumerate(range(group_start, group_end)):
                if group_size == 2:
                    fraction = offset / group_size
                else:
                    fraction = offset / max(1.0, group_size - 0.55)
                distributed = segment.start + interval * fraction
                final[entry_index] = max(final[entry_index], distributed)
        group_start = group_end

    for index in range(1, len(final)):
        final[index] = max(final[index], final[index - 1] + 0.10)
    for index in range(len(final)):
        final[index] = max(0.0, min(duration, final[index]))

    assigned = sum(1 for assignment in assignments if assignment is not None)
    trusted = sum(
        1
        for assignment, score in zip(assignments, scores)
        if assignment is not None and score >= TRUSTED_ALIGNMENT_SCORE
    )
    low_confidence = [
        {
            "entry": index + 1,
            "score": round(scores[index], 3),
            "lyric": entries[index].lines[0] if entries[index].lines else "",
            "asr_segment": assignments[index] + 1 if assignments[index] is not None else None,
        }
        for index in range(len(entries))
        if assignments[index] is None or scores[index] < 0.62
    ]
    raw_review_entries = [
        {
            "entry": index + 1,
            "text": entry_sung_text(entries[index]),
            "flags": [
                "raw_asr_missing_alignment" if assignments[index] is None else "raw_asr_low_match_score",
                *( ["raw_asr_borrowed_segment"] if borrowed[index] else [] ),
            ],
            "severity": "high" if assignments[index] is None or scores[index] <= 0.0 else "medium",
            "review_required": True,
        }
        for index in range(len(entries))
        if assignments[index] is None or scores[index] < TRUSTED_ALIGNMENT_SCORE or borrowed[index]
    ]
    report: dict[str, object] = {
        "backend": "whispercpp",
        "asr_segments": len(segments),
        "timing_entries": len(entries),
        "assigned_entries": assigned,
        "assigned_percent": ratio_percent(assigned, len(entries)),
        "trusted_entries": trusted,
        "trusted_percent": ratio_percent(trusted, len(entries)),
        "matched_entries": trusted,
        "matched_percent": ratio_percent(trusted, len(entries)),
        "low_confidence_entries": low_confidence,
        "low_confidence_count": len(low_confidence),
        "low_confidence_percent": ratio_percent(len(low_confidence), len(entries)),
        "review_required_count": len(raw_review_entries),
        "review_required_percent": ratio_percent(len(raw_review_entries), len(entries)),
        "review_required": bool(raw_review_entries),
        "suspicious_alignment_count": len(raw_review_entries),
        "suspicious_alignment_severity_counts": {
            "high": sum(1 for item in raw_review_entries if item["severity"] == "high"),
            "medium": sum(1 for item in raw_review_entries if item["severity"] == "medium"),
            "low": 0,
        },
        "suspicious_alignments": raw_review_entries,
        "assignments": [
            {
                "entry": index + 1,
                "segment": assignments[index] + 1 if assignments[index] is not None else None,
                "score": round(scores[index], 3),
                "borrowed": borrowed[index],
                "timestamp": round(final[index], 3),
            }
            for index in range(len(entries))
        ],
        "note": "Experimental ASR-to-lyric matching. Review low-confidence entries before trusting output.",
    }
    return final, report


def lyric_alignment_windows(entries: list[LyricEntry], timestamps: list[float], duration: float) -> list[dict[str, object]]:
    transcript: list[dict[str, object]] = []
    for index, (entry, timestamp) in enumerate(zip(entries, timestamps)):
        previous_time = timestamps[index - 1] if index > 0 else 0.0
        next_time = timestamps[index + 1] if index + 1 < len(timestamps) else min(duration, timestamp + 4.0)
        entry_text = normalize_match_text(entry_sung_text(entry))
        gap_from_previous = timestamp - previous_time if index > 0 else timestamp
        lookback = 4.2 if len(entry_text) <= 3 and gap_from_previous >= 4.0 else 1.2
        start = max(0.0, min(timestamp - lookback, (previous_time + timestamp) / 2 if index > 0 else timestamp - lookback))
        end = min(duration, max(next_time + 0.5, timestamp + 1.2))
        transcript.append({"start": start, "end": end, "text": entry_sung_text(entry)})
    return transcript


def first_forced_char_time(segment: AsrSegment) -> float:
    if segment.chars:
        return segment.chars[0][1]
    return segment.start


def first_local_onset(
    features: AudioFeatures,
    start: float,
    end: float,
    threshold: float = 0.55,
    *,
    edge_guard_seconds: float = 0.20,
) -> float | None:
    if end <= start:
        return None
    effective_start = start + max(0.0, edge_guard_seconds)
    indices = np.flatnonzero((features.frame_times >= effective_start) & (features.frame_times <= end))
    for index in indices:
        strength = float(features.onset_strength[index])
        if strength < threshold:
            continue
        left = float(features.onset_strength[index - 1]) if index > 0 else 0.0
        right = float(features.onset_strength[index + 1]) if index + 1 < len(features.onset_strength) else 0.0
        if strength >= left and strength >= right:
            plateau_end = index
            while (
                plateau_end + 1 < len(features.onset_strength)
                and float(features.frame_times[plateau_end + 1]) <= end
                and abs(float(features.onset_strength[plateau_end + 1]) - strength) <= 1e-6
            ):
                plateau_end += 1
            if plateau_end > index:
                return float((features.frame_times[index] + features.frame_times[plateau_end]) / 2.0)
            return float(features.frame_times[index])
    return None


def should_accept_zero_gap_boundary_realign(
    boundary_gap: float,
    current_score: float,
    current_time: float,
    local_time: float,
    local_score: float,
) -> bool:
    """Accept a bounded re-align only when it repairs a collapsed line boundary."""
    return (
        boundary_gap <= 0.04
        and local_time - current_time >= 0.30
        and local_score >= max(0.05, current_score * 1.05)
    )


def should_accept_ctc_boundary_realign(
    current_evidence: dict[str, object],
    local_evidence: dict[str, object],
    current_score: float,
    local_score: float,
    current_time: float,
    local_time: float,
    acoustic_onset_time: float | None,
) -> tuple[bool, list[str]]:
    """Require independent improvements before replacing a collapsed boundary."""
    reasons: list[str] = []
    if not current_evidence.get("realign_required"):
        return False, ["current-boundary-not-pathological"]
    if local_time - current_time < 0.30:
        return False, ["local-shift-too-small"]
    if local_score < max(0.05, current_score * 1.05):
        return False, ["local-ctc-score-not-improved"]

    current_gap = float(current_evidence.get("boundary_gap_seconds", 0.0) or 0.0)
    local_gap = float(local_evidence.get("boundary_gap_seconds", 0.0) or 0.0)
    if local_gap < 0.08 or local_gap - current_gap < 0.08:
        return False, ["local-boundary-gap-not-improved"]
    reasons.append("boundary-gap-improved")
    current_previous_score = float(current_evidence.get("previous_token_score", 0.0) or 0.0)
    local_previous_score = float(local_evidence.get("previous_token_score", 0.0) or 0.0)
    if local_previous_score >= max(0.08, current_previous_score + 0.08):
        reasons.append("previous-line-tail-evidence-improved")

    current_mean = float(current_evidence.get("prefix_mean_score", 0.0) or 0.0)
    local_mean = float(local_evidence.get("prefix_mean_score", 0.0) or 0.0)
    current_weak = float(current_evidence.get("prefix_weak_ratio", 1.0) or 1.0)
    local_weak = float(local_evidence.get("prefix_weak_ratio", 1.0) or 1.0)
    prefix_improved = (
        local_mean >= current_mean + 0.02
        or local_weak <= current_weak - 0.25
        or (
            bool(current_evidence.get("abnormal_prefix_compression"))
            and not bool(local_evidence.get("abnormal_prefix_compression"))
        )
    )
    if not prefix_improved:
        return False, [*reasons, "local-prefix-not-improved"]
    reasons.append("prefix-evidence-improved")

    acoustic_supported = acoustic_onset_time is not None and abs(acoustic_onset_time - local_time) <= 0.30
    local_first = float(local_evidence.get("first_token_score", 0.0) or 0.0)
    reliable_index = local_evidence.get("next_reliable_token_index")
    reliable_score = float(local_evidence.get("next_reliable_token_score", 0.0) or 0.0)
    reliable_delay = local_evidence.get("reliable_token_delay_seconds")
    next_reliable_supported = (
        isinstance(reliable_index, int)
        and isinstance(reliable_delay, (int, float))
        and float(reliable_delay) <= 0.75
        and reliable_score >= 0.08
    )
    phonetic_supported = next_reliable_supported and (local_first >= 0.03 or local_mean >= 0.04)
    if not next_reliable_supported:
        return False, [*reasons, "no-nearby-reliable-token-evidence"]
    reasons.append("next-reliable-token-support")
    if not acoustic_supported and not phonetic_supported:
        return False, [*reasons, "no-acoustic-or-prefix-phonetic-onset-support"]
    reasons.append("acoustic-onset-support" if acoustic_supported else "multi-token-phonetic-support")
    return True, reasons


def apply_ctc_zero_gap_boundary_realign(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
) -> list[dict[str, object]]:
    """Re-align a collapsed CTC line boundary inside a compact lyric window."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return []
    python_exe = default_ctc_python()
    helper = Path(__file__).resolve().parent / "ctc_align.py"
    changes: list[dict[str, object]] = []
    attempts: list[dict[str, object]] = []
    acoustic_features: AudioFeatures | None = None
    acoustic_checked = False
    annotate_ctc_boundary_evidence(assignments)
    with tempfile.TemporaryDirectory(prefix="lrc-ctc-boundary-") as temp_name:
        temp_dir = Path(temp_name)
        for index in range(1, len(entries)):
            previous = assignments[index - 1]
            current = assignments[index]
            if not isinstance(previous, dict) or not isinstance(current, dict):
                continue
            previous_spans = previous.get("ctc_token_spans")
            current_spans = current.get("ctc_token_spans")
            if not isinstance(previous_spans, list) or not previous_spans or not isinstance(current_spans, list) or not current_spans:
                continue
            try:
                previous_end = max(float(span.get("end")) for span in previous_spans if isinstance(span, dict))
                current_time = float(timestamps[index])
                current_score = float(current.get("ctc_score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            boundary_gap = current_time - previous_end
            current_evidence = ctc_prefix_boundary_evidence(current, boundary_gap)
            if not current_evidence.get("realign_required"):
                continue
            start_index = index - 1
            end_index = min(len(entries), index + 2)
            start_time = max(0.0, timestamps[start_index] - 0.50)
            end_time = min(duration, (timestamps[index + 1] + 0.75) if index + 1 < len(timestamps) else current_time + 5.0)
            if not 1.0 <= end_time - start_time <= 16.0:
                continue
            transcript_path = temp_dir / f"boundary-{index + 1}.json"
            output_path = temp_dir / f"boundary-{index + 1}.result.json"
            transcript_path.write_text(
                json.dumps([entry_sung_text(entry) for entry in entries[start_index:end_index]], ensure_ascii=False),
                encoding="utf-8",
            )
            command = [
                str(python_exe), str(helper), "--audio", str(audio_path), "--transcript", str(transcript_path),
                "--output", str(output_path), "--device", args.whisperx_device,
                "--start", f"{start_time:.3f}", "--end", f"{end_time:.3f}",
            ]
            proc = _run_model_helper_command(command, mode="ctc")
            if proc.returncode != 0 or not output_path.exists():
                continue
            rows = json.loads(output_path.read_text(encoding="utf-8")).get("entries")
            if not isinstance(rows, list) or len(rows) < 2 or not isinstance(rows[1], dict):
                continue
            row = rows[1]
            try:
                local_time = float(row.get("start"))
                local_score = float(row.get("ctc_score", 0.0) or 0.0)
            except (TypeError, ValueError):
                continue
            previous_row = rows[0] if isinstance(rows[0], dict) else {}
            previous_local_spans = previous_row.get("token_spans")
            try:
                previous_local_end, previous_local_score = max(
                    (
                        (
                            float(span.get("end")),
                            float(span.get("score", 0.0) or 0.0),
                        )
                        for span in previous_local_spans
                        if isinstance(span, dict)
                    ),
                    key=lambda item: item[0],
                )
            except (TypeError, ValueError):
                previous_local_end = previous_end
                previous_local_score = None
            local_evidence = ctc_prefix_boundary_evidence(
                {
                    "ctc_score": local_score,
                    "ctc_token_spans": row.get("token_spans"),
                    "ctc_previous_token_score": previous_local_score,
                },
                local_time - previous_local_end,
            )
            if not acoustic_checked:
                acoustic_checked = True
                try:
                    acoustic_features = analyze_vocal_onsets(audio_path, duration)
                except LrcError:
                    acoustic_features = None
            acoustic_onset: float | None = None
            acoustic_strength: float | None = None
            if acoustic_features is not None:
                search_start = max(previous_local_end + 0.02, local_time - 0.45)
                search_end = min(end_time - 0.05, local_time + 0.35)
                acoustic_onset = first_local_onset(acoustic_features, search_start, search_end, threshold=0.45)
                if acoustic_onset is None:
                    acoustic_onset = first_local_onset(acoustic_features, search_start, search_end, threshold=0.35)
                if acoustic_onset is not None and len(acoustic_features.frame_times):
                    nearest = int(np.argmin(np.abs(acoustic_features.frame_times - acoustic_onset)))
                    acoustic_strength = float(acoustic_features.onset_strength[nearest])
            accepted, acceptance_reasons = should_accept_ctc_boundary_realign(
                current_evidence,
                local_evidence,
                current_score,
                local_score,
                current_time,
                local_time,
                acoustic_onset,
            )
            previous_bound = timestamps[index - 1] + 0.05
            next_bound = timestamps[index + 1] - 0.05 if index + 1 < len(timestamps) else duration - 0.05
            if accepted and not (previous_bound < local_time < next_bound):
                accepted = False
                acceptance_reasons = [*acceptance_reasons, "candidate-outside-neighbor-bounds"]
            repaired_time = local_time
            if (
                accepted
                and acoustic_onset is not None
                and previous_local_end + 0.05 < acoustic_onset <= local_time + 0.08
                and 0.0 <= local_time - acoustic_onset <= 0.25
                and acoustic_onset - current_time >= 0.30
            ):
                repaired_time = acoustic_onset
                acceptance_reasons = [*acceptance_reasons, "bounded-acoustic-consonant-onset"]
            attempt = {
                "entry": index + 1,
                "from": round(current_time, 3),
                "candidate": round(repaired_time, 3),
                "local_ctc_candidate": round(local_time, 3),
                "accepted": accepted,
                "current_ctc_score": round(current_score, 6),
                "local_ctc_score": round(local_score, 6),
                "current_evidence": current_evidence,
                "local_evidence": local_evidence,
                "acoustic_onset": round(acoustic_onset, 3) if acoustic_onset is not None else None,
                "acoustic_onset_strength": round(acoustic_strength, 3) if acoustic_strength is not None else None,
                "decision_reasons": acceptance_reasons,
            }
            attempts.append(attempt)
            current["ctc_boundary_realign_attempt"] = attempt
            if not accepted:
                continue
            timestamps[index] = repaired_time
            current["timestamp"] = round(repaired_time, 3)
            current["ctc_score"] = row.get("ctc_score")
            current["ctc_token_spans"] = row.get("token_spans")
            current["ctc_first_token_candidates"] = row.get("first_token_candidates")
            current["ctc_zero_gap_boundary_realign"] = True
            current["ctc_boundary_realign_trusted"] = True
            current["ctc_boundary_realign_evidence"] = attempt
            current.pop("ctc_unresolved_boundary", None)
            current["timing_repair_source"] = "torchaudio-mms-fa+zero-gap-boundary-realign"
            changes.append({**attempt, "to": round(repaired_time, 3)})
    if changes:
        annotate_ctc_boundary_evidence(assignments)
        existing_changes = report.get("ctc_zero_gap_boundary_realign")
        report["ctc_zero_gap_boundary_realign"] = [
            *(existing_changes if isinstance(existing_changes, list) else []),
            *changes,
        ]
    if attempts:
        report["ctc_boundary_realign_attempts"] = attempts
    return changes


def apply_ctc_acoustic_backtrack(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> list[dict[str, object]]:
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return []
    if len(timestamps) < 3:
        return []

    try:
        features = analyze_audio(audio_path, duration)
    except LrcError:
        return []

    changes: list[dict[str, object]] = []
    rejections: list[dict[str, object]] = []
    for index in range(1, len(timestamps)):
        assignment = assignments[index] if isinstance(assignments[index], dict) else {}
        if assignment.get("timing_repair") != "ctc-forced-align":
            continue
        try:
            ctc_score = float(assignment.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            ctc_score = 0.0
        current_time = timestamps[index]
        previous_time = timestamps[index - 1]
        next_time = timestamps[index + 1] if index + 1 < len(timestamps) else duration
        if current_time - previous_time < 2.4:
            continue
        if next_time - current_time < 1.2:
            continue

        search_start = 0.0
        search_end = current_time
        mode = ""
        candidate: float | None = None
        candidate_score: float | None = None
        candidate_ratio: float | None = None
        first_candidates = assignment.get("ctc_first_token_candidates")
        parsed_candidates: list[tuple[float, float]] = []
        if isinstance(first_candidates, list):
            for item in first_candidates:
                if not isinstance(item, dict):
                    continue
                try:
                    parsed_candidates.append(
                        (float(item.get("time")), float(item.get("score", 0.0) or 0.0))
                    )
                except (TypeError, ValueError):
                    continue
        try:
            previous_token_end = float(assignment.get("ctc_previous_token_end"))
        except (TypeError, ValueError):
            previous_token_end = None
        tail_conflicts = [
            (time_value, score)
            for time_value, score in parsed_candidates
            if previous_token_end is not None
            and time_value > previous_time + 0.20
            and time_value <= previous_token_end + 0.20
        ]
        for time_value, score in tail_conflicts:
            rejection = {
                "entry": index + 1,
                "from": round(current_time, 3),
                "candidate": round(time_value, 3),
                "reason": "candidate-borrows-previous-line-tail",
                "previous_token_end": round(previous_token_end, 3),
                "candidate_gap_seconds": round(time_value - previous_token_end, 3),
                "candidate_score": round(score, 6),
                "lyric": entries[index].lines[0] if entries[index].lines else "",
            }
            rejections.append(rejection)
            assignment["ctc_acoustic_backtrack_rejected"] = True
            assignment["ctc_acoustic_backtrack_rejection_reason"] = rejection["reason"]
        top_score = max((score for _time, score in parsed_candidates), default=0.0)
        eligible = [
            (time_value, score, score / top_score if top_score > 0.0 else 0.0)
            for time_value, score in parsed_candidates
            if previous_time + 0.20 < time_value < current_time - 0.20
            and (previous_token_end is None or time_value - previous_token_end > 0.20)
            and current_time - time_value <= 2.50
            and score >= 0.01
            and (top_score <= 0.0 or score >= top_score * 0.20)
        ]
        if ctc_score <= 0.28 and eligible:
            candidate, candidate_score, candidate_ratio = max(
                eligible, key=lambda value: (value[1], -value[0])
            )
            mode = "ctc-first-token-posterior"
            search_start = max(previous_time + 0.20, current_time - 2.50)
            search_end = current_time - 0.05
            min_shift = 0.20
            max_shift = 2.50
        elif ctc_score <= 0.05:
            prefix_evidence = ctc_prefix_boundary_evidence(
                assignment, assignment.get("ctc_boundary_gap_seconds")
            )
            if prefix_evidence.get("unsupported_weak_prefix") or prefix_evidence.get(
                "detached_weak_prefix"
            ):
                rejections.append(
                    {
                        "entry": index + 1,
                        "from": round(current_time, 3),
                        "mode": "ctc-short-acoustic-onset",
                        "reason": "weak-prefix-has-no-phonetic-support-for-backtrack",
                        "ctc_boundary_evidence": prefix_evidence,
                        "lyric": entries[index].lines[0] if entries[index].lines else "",
                    }
                )
                assignment["ctc_acoustic_backtrack_rejected"] = True
                assignment["ctc_acoustic_backtrack_rejection_reason"] = (
                    "weak-prefix-has-no-phonetic-support-for-backtrack"
                )
                continue
            mode = "ctc-short-acoustic-onset"
            search_start = max(previous_time + 0.35, current_time - 0.72)
            search_end = current_time - 0.10
            if search_end - search_start < 0.18:
                continue
            candidate = first_local_onset(features, search_start, search_end, threshold=0.50)
            if candidate is None:
                candidate = first_local_onset(features, search_start, search_end, threshold=0.45)
            min_shift = 0.20
            max_shift = 0.55
        else:
            continue
        if candidate is None:
            continue

        shift = current_time - candidate
        if shift < min_shift or shift > max_shift:
            continue
        if candidate <= previous_time + 0.20:
            continue
        if candidate >= next_time - 0.20:
            continue
        previous_units = max(1, len(normalize_match_text(entry_sung_text(entries[index - 1]))))
        current_units = max(1, len(normalize_match_text(entry_sung_text(entries[index]))))
        before_tempo_error = abs(
            ((current_time - previous_time) / previous_units)
            - ((next_time - current_time) / current_units)
        )
        after_tempo_error = abs(
            ((candidate - previous_time) / previous_units)
            - ((next_time - candidate) / current_units)
        )
        # The mixed-track onset can fire on a preceding sustain or instrument.
        # Do not backtrack a short CTC line when its initial consonant is already
        # credible and the proposed move makes adjacent lyric pacing less
        # coherent.  Local CTC can still revise genuinely weak starts later.
        first_token_score = 0.0
        token_spans = assignment.get("ctc_token_spans")
        if isinstance(token_spans, list) and token_spans:
            try:
                first_token_score = float(token_spans[0].get("score", 0.0) or 0.0)
            except (AttributeError, TypeError, ValueError):
                first_token_score = 0.0
        harms_pacing = (
            before_tempo_error <= 0.025
            or after_tempo_error > max(0.01, before_tempo_error * 1.30)
        )
        if mode == "ctc-short-acoustic-onset" and first_token_score >= 0.04 and harms_pacing:
            continue
        if mode == "ctc-short-acoustic-onset" and first_token_score >= 0.05:
            continue
        hypothesis_spans: list[dict[str, object]] = []
        acoustic_strength: float | None = None
        acoustic_onset_time: float | None = None
        direct_onset_time: float | None = None
        identity_support: EvidenceState = "unavailable"
        acoustic_support: EvidenceState = "unavailable"
        direct_onset_support: EvidenceState = "unavailable"
        if mode == "ctc-first-token-posterior":
            token = ""
            romaji = assignment.get("romaji")
            if isinstance(romaji, str) and romaji:
                token = romaji[0]
            hypothesis_spans = [{
                "char": token,
                "start": round(float(candidate), 6),
                "end": round(float(candidate) + HOP_SECONDS, 6),
                "score": round(float(candidate_score), 8),
            }]
            identity_support = "supported"
        else:
            if len(features.frame_times):
                nearest_index = int(np.argmin(np.abs(features.frame_times - float(candidate))))
                acoustic_strength = float(features.onset_strength[nearest_index])
            acoustic_onset_time = float(candidate)
            direct_onset_time = float(candidate)
            acoustic_support = "supported"
            direct_onset_support = "supported"
        hypothesis = record_alignment_hypothesis(
            assignment,
            source="ctc-acoustic-backtrack",
            stage="ctc-acoustic-backtrack",
            raw_time=float(candidate),
            confidence=(float(candidate_score) if mode == "ctc-first-token-posterior" else float(acoustic_strength or 0.0)),
            spans=hypothesis_spans,
            identity_support=identity_support,
            sequence_support="supported",
            acoustic_support=acoustic_support,
            direct_onset_support=direct_onset_support,
            acoustic_strength=acoustic_strength,
            acoustic_onset_time=acoustic_onset_time,
            direct_onset_time=direct_onset_time,
            parent_source="ctc-global-mms",
            parent_time=current_time,
            window={"start": round(search_start, 3), "end": round(search_end, 3)},
            mode=mode,
        )
        assignment["ctc_acoustic_backtrack_candidate_generated"] = True
        assignment["ctc_acoustic_backtrack_mode"] = mode
        changes.append(
            {
                "entry": index + 1,
                "from": round(current_time, 3),
                "to": round(candidate, 3),
                "shift": round(shift, 3),
                "ctc_score": round(ctc_score, 6),
                "search_start": round(search_start, 3),
                "search_end": round(search_end, 3),
                "mode": mode,
                "before_tempo_error": round(before_tempo_error, 6),
                "after_tempo_error": round(after_tempo_error, 6),
                "lyric": entries[index].lines[0] if entries[index].lines else "",
            }
        )

    if changes:
        report["ctc_acoustic_backtrack_count"] = len(changes)
        report["ctc_acoustic_backtracks"] = changes
    else:
        report["ctc_acoustic_backtrack_count"] = 0
        report["ctc_acoustic_backtracks"] = []
    report["ctc_acoustic_backtrack_authoritative"] = False
    report["ctc_acoustic_backtrack_mutates_baseline"] = False
    report["ctc_acoustic_backtrack_rejections"] = rejections
    report["ctc_acoustic_backtrack_rejection_count"] = len(rejections)
    return changes


def repair_intro_hallucination(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
) -> tuple[list[float], list[dict[str, object]]]:
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(timestamps) < 3:
        return timestamps, []
    first_assignment = assignments[0] if isinstance(assignments[0], dict) else {}
    if assignment_score(first_assignment) >= COLLAPSE_SEGMENT_SCORE:
        return timestamps, []
    if not first_assignment.get("borrowed") and first_assignment.get("segment") is None:
        return timestamps, []
    if timestamps[0] >= 10.0:
        return timestamps, []

    anchor_index: int | None = None
    for index in range(1, min(len(timestamps), len(assignments))):
        assignment = assignments[index] if isinstance(assignments[index], dict) else {}
        if assignment_score(assignment) >= TRUSTED_ALIGNMENT_SCORE and timestamps[index] >= 20.0:
            anchor_index = index
            break
    if anchor_index is None or anchor_index < 2:
        return timestamps, []

    anchor_time = timestamps[anchor_index]
    prefix_count = anchor_index
    search_start = max(0.0, anchor_time - min(12.0, 4.0 + prefix_count * 4.0))
    search_end = max(search_start + 0.2, anchor_time - 6.0)
    features = analyze_audio(audio_path, duration)
    repaired_start = first_local_onset(features, search_start, search_end)
    if repaired_start is None:
        return timestamps, []
    if repaired_start <= timestamps[0] + 1.0:
        return timestamps, []

    repaired = list(timestamps)
    changes: list[dict[str, object]] = []
    interval = max(0.2, anchor_time - repaired_start)
    for index in range(prefix_count):
        fraction = index / max(1, prefix_count)
        new_time = repaired_start + interval * fraction
        if index > 0:
            new_time = max(new_time, repaired[index - 1] + 0.10)
        new_time = min(new_time, anchor_time - 0.10 * (prefix_count - index))
        changes.append(
            {
                "entry": index + 1,
                "from": round(repaired[index], 3),
                "to": round(new_time, 3),
                "reason": "intro-hallucination-prefix-redistribution",
                "anchor_entry": anchor_index + 1,
                "anchor_time": round(anchor_time, 3),
                "search_window": [round(search_start, 3), round(search_end, 3)],
                "lyric": entries[index].lines[0] if index < len(entries) and entries[index].lines else "",
            }
        )
        repaired[index] = new_time

    report["intro_hallucination_repair_count"] = len(changes)
    report["intro_hallucination_repairs"] = changes
    return repaired, changes


def repair_long_segment_hallucinations(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    raw_segments: list[AsrSegment],
    duration: float,
) -> tuple[list[float], list[dict[str, object]]]:
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(timestamps) < 3:
        return timestamps, []
    features: AudioFeatures | None = None
    repaired = list(timestamps)
    changes: list[dict[str, object]] = []

    for index in range(1, min(len(repaired) - 1, len(assignments))):
        assignment = assignments[index] if isinstance(assignments[index], dict) else {}
        segment_number = assignment.get("segment")
        if not isinstance(segment_number, int):
            continue
        segment_index = segment_number - 1
        if not (0 <= segment_index < len(raw_segments)):
            continue
        segment = raw_segments[segment_index]
        segment_duration = segment.end - segment.start
        next_time = repaired[index + 1]
        score = assignment_score(assignment)
        if not (
            segment_duration >= 18.0
            and score >= 0.80
            and next_time - repaired[index] >= 12.0
            and abs(next_time - segment.end) <= 0.30
        ):
            continue
        text_length = len(normalize_match_text(entry_sung_text(entries[index])))
        lead = min(2.2, max(1.4, text_length * 0.055))
        new_time = max(repaired[index - 1] + 0.10, next_time - lead)
        if not (repaired[index] + 5.0 < new_time < next_time - 0.20):
            continue
        changes.append(
            {
                "entry": index + 1,
                "from": round(repaired[index], 3),
                "to": round(new_time, 3),
                "reason": "long-segment-pre-vocal-hallucination",
                "segment": segment_number,
                "segment_duration": round(segment_duration, 3),
                "next_anchor_time": round(next_time, 3),
                "lyric": entries[index].lines[0] if entries[index].lines else "",
            }
        )
        repaired[index] = new_time

        next_index = index + 1
        if next_index + 1 >= len(repaired):
            continue
        next_assignment = assignments[next_index] if isinstance(assignments[next_index], dict) else {}
        if assignment_score(next_assignment) < TRUSTED_ALIGNMENT_SCORE:
            continue
        if features is None:
            features = analyze_audio(audio_path, duration)
        search_start = repaired[next_index] + 1.20
        search_end = min(repaired[next_index] + 2.60, repaired[next_index + 1] - 0.10)
        onset = first_local_onset(features, search_start, search_end, threshold=0.55)
        if onset is None or not (repaired[next_index] + 0.40 < onset < repaired[next_index + 1] - 0.10):
            continue
        changes.append(
            {
                "entry": next_index + 1,
                "from": round(repaired[next_index], 3),
                "to": round(onset, 3),
                "reason": "post-long-segment-local-onset",
                "previous_repaired_entry": index + 1,
                "search_window": [round(search_start, 3), round(search_end, 3)],
                "lyric": entries[next_index].lines[0] if entries[next_index].lines else "",
            }
        )
        repaired[next_index] = onset

    if changes:
        report["long_segment_repair_count"] = len(changes)
        report["long_segment_repairs"] = changes
    return repaired, changes


def sync_scratch_assignment_timestamps(report: dict[str, object], timestamps: list[float]) -> None:
    """Synchronize mutable pre-finalization generation scratch only."""
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return
    for index, timestamp in enumerate(timestamps):
        if index < len(assignments) and isinstance(assignments[index], dict):
            assignments[index]["timestamp"] = round(timestamp, 3)


def assert_report_timestamp_equality(report: dict[str, object], state: FinalTimingState) -> None:
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(state.written_times):
        raise LrcError("Final report assignment count does not match immutable timing state")
    for index, (assignment, written_time, decision, audit) in enumerate(zip(
        assignments,
        state.written_times,
        state.decisions,
        state.audits,
    )):
        if not isinstance(assignment, dict):
            raise LrcError(f"Final report assignment {index + 1} is invalid")
        if assignment.get("canonical_written_centiseconds") != written_time.centiseconds:
            raise LrcError(f"Final report timestamp mismatch at entry {index + 1}")
        if assignment.get("lrc_tag") != written_time.lrc_tag:
            raise LrcError(f"Final report LRC tag mismatch at entry {index + 1}")
        if assignment.get("timestamp_status") != audit.status:
            raise LrcError(f"Final report timing status mismatch at entry {index + 1}")
        if assignment.get("timing_trusted") is not audit.timing_trusted:
            raise LrcError(f"Final report timing trust mismatch at entry {index + 1}")
        expected_selected = decision.selected_candidate_id if audit.timing_trusted else None
        if assignment.get("selected_candidate_id") != expected_selected:
            raise LrcError(f"Final report selection mismatch at entry {index + 1}")


def low_confidence_tail_start(report: dict[str, object], min_remaining: int = 4) -> int | None:
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return None
    for index in range(max(1, len(assignments) - 12), len(assignments) - min_remaining + 1):
        remaining = assignments[index:]
        low_count = sum(1 for item in remaining if assignment_score(item) < TRUSTED_ALIGNMENT_SCORE)
        if low_count < max(3, math.ceil(len(remaining) * 0.55)):
            continue
        consecutive_low = 0
        for item in remaining:
            if assignment_score(item) < TRUSTED_ALIGNMENT_SCORE:
                consecutive_low += 1
            else:
                break
        if consecutive_low >= 2:
            return index
    return None


def first_sustained_onset(
    features: AudioFeatures,
    start: float,
    end: float,
    onset_threshold: float = 0.70,
    median_rms_floor: float = -18.0,
    sustain_seconds: float = 3.0,
) -> float | None:
    if end <= start:
        return None
    frame_times = features.frame_times
    mask = (frame_times >= start) & (frame_times <= end)
    for index in np.flatnonzero(mask):
        strength = float(features.onset_strength[index])
        if strength < onset_threshold:
            continue
        time = float(frame_times[index])
        sustain_mask = (frame_times >= time) & (frame_times <= min(time + sustain_seconds, features.duration))
        if not np.any(sustain_mask):
            continue
        if float(np.median(features.rms_db[sustain_mask])) >= median_rms_floor:
            return time
    return None


def has_repeated_asr_tail(segments: list[AsrSegment], after_time: float, min_run: int = 6) -> bool:
    run_text = ""
    run_count = 0
    for segment in segments:
        if segment.start < after_time:
            continue
        normalized = normalize_match_text(segment.text)
        if len(normalized) < 8:
            run_text = ""
            run_count = 0
            continue
        if run_text and sequence_ratio(run_text, normalized) >= 0.86:
            run_count += 1
        else:
            run_text = normalized
            run_count = 1
        if run_count >= min_run:
            return True
    return False


def repair_tail_hallucination(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    segments: list[AsrSegment],
    duration: float,
) -> tuple[list[float], list[dict[str, object]]]:
    tail_start = low_confidence_tail_start(report)
    if tail_start is None or tail_start <= 0:
        return timestamps, []

    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return timestamps, []
    anchor_time = timestamps[tail_start - 1]
    if anchor_time <= 0.0:
        return timestamps, []
    if not has_repeated_asr_tail(segments, anchor_time + 4.0):
        report["tail_hallucination_repair"] = {
            "status": "skipped",
            "reason": "no-repeated-asr-tail",
            "candidate_start_entry": tail_start + 1,
            "anchor_entry": tail_start,
            "anchor_time": round(anchor_time, 3),
        }
        return timestamps, []

    features = analyze_audio(audio_path, duration)
    search_start = min(duration, anchor_time + 8.0)
    search_end = min(duration, anchor_time + 58.0)
    tail_time = first_sustained_onset(features, search_start, search_end)
    if tail_time is None:
        tail_time = min(duration, anchor_time + 12.0)
    if tail_time - anchor_time < 12.0:
        report["tail_hallucination_repair"] = {
            "status": "skipped",
            "reason": "tail-onset-too-close-to-anchor",
            "candidate_start_entry": tail_start + 1,
            "anchor_entry": tail_start,
            "anchor_time": round(anchor_time, 3),
            "tail_start_time": round(tail_time, 3),
        }
        return timestamps, []

    tail_end = duration
    if features.segments:
        tail_end = max(tail_time + 1.0, min(duration, features.segments[-1][1]))
    if tail_end - tail_time < max(8.0, (len(entries) - tail_start) * 1.4):
        return timestamps, []

    tail_times = weighted_rough_times(entries[tail_start:], tail_time, tail_end)
    tail_times = snap_to_onsets(tail_times, features, window_seconds=0.90, min_gap=0.35)
    repaired = list(timestamps)
    changes: list[dict[str, object]] = []
    for offset, entry_index in enumerate(range(tail_start, len(entries))):
        new_time = max(repaired[entry_index - 1] + 0.35 if entry_index > 0 else 0.0, tail_times[offset])
        old_time = repaired[entry_index]
        repaired[entry_index] = min(duration, new_time)
        if entry_index < len(assignments) and isinstance(assignments[entry_index], dict):
            assignment = assignments[entry_index]
            assignment["timestamp"] = round(repaired[entry_index], 3)
            assignment["timing_repair"] = "tail-hallucination-acoustic"
            assignment["timing_repair_source"] = "sustained-onset-weighted-tail"
            assignment["score"] = max(assignment_score(assignment), 0.70)
        changes.append(
            {
                "entry": entry_index + 1,
                "from": round(old_time, 3),
                "to": round(repaired[entry_index], 3),
                "reason": "tail-hallucination-acoustic",
                "lyric": entries[entry_index].lines[0] if entries[entry_index].lines else "",
            }
        )

    report["tail_hallucination_repair"] = {
        "status": "applied",
        "start_entry": tail_start + 1,
        "anchor_entry": tail_start,
        "anchor_time": round(anchor_time, 3),
        "tail_start_time": round(tail_time, 3),
        "tail_end_time": round(tail_end, 3),
        "entries": len(changes),
        "method": "sustained-onset-weighted-tail",
    }
    report["tail_hallucination_repairs"] = changes
    update_report_confidence_metrics(report)
    return repaired, changes


def blend_tail_repair_with_forced(
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    forced_segments: list[AsrSegment],
    duration: float,
) -> tuple[list[float], list[dict[str, object]]]:
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        return timestamps, []
    refined = list(timestamps)
    changes: list[dict[str, object]] = []
    for index, assignment in enumerate(assignments):
        if not isinstance(assignment, dict):
            continue
        if assignment.get("timing_repair") != "tail-hallucination-acoustic":
            continue
        if index >= len(forced_segments):
            continue
        forced_time = first_forced_char_time(forced_segments[index])
        current_time = refined[index]
        previous_time = refined[index - 1] if index > 0 else 0.0
        next_time = refined[index + 1] if index + 1 < len(refined) else duration
        if not (previous_time + 0.35 < forced_time < next_time - 0.35):
            continue
        lead = current_time - forced_time
        if abs(lead) <= 0.35:
            candidate = forced_time
        elif 0.35 < lead <= 6.0:
            candidate = current_time - min(1.60, lead * 0.34)
        else:
            continue
        if not (previous_time + 0.35 < candidate < next_time - 0.35):
            continue
        # Candidate producer only: never mutate the backend baseline before
        # central evaluation.  The forced-first estimate is advisory until an
        # independently proven opening/ownership relation validates it.
        changes.append(
            {
                "entry": index + 1,
                "from": round(current_time, 3),
                "to": round(candidate, 3),
                "forced_first": round(forced_time, 3),
                "reason": "tail-forced-blend",
                "lyric": entries[index].lines[0] if entries[index].lines else "",
            }
        )

    if changes:
        existing = report.get("tail_hallucination_repair")
        if isinstance(existing, dict):
            existing["method"] = "sustained-onset-weighted-tail+forced-blend"
            existing["forced_blend_count"] = len(changes)
        report["tail_forced_blend_count"] = len(changes)
        report["tail_forced_blends"] = changes
        report["tail_forced_blend_candidate_only"] = True
        report["tail_forced_blend_mutates_baseline"] = False
        update_report_confidence_metrics(report)
    return list(timestamps), changes




def lyric_prefix_probe_text(entry: LyricEntry, minimum_chars: int = 8) -> str:
    """Return a compact leading lyric phrase suitable for an independent CTC probe.

    The probe deliberately uses only the opening phrase, so a fractured whole-line
    path cannot drag the candidate to a later repeated word or the right edge.
    """
    text = entry_sung_text(entry).strip()
    if not text:
        return ""
    # Preserve natural phrase boundaries; Japanese full-width spaces are common.
    parts = [
        part.strip(" ,，、。.!！?？…:：;；()（）[]【】{}「」『』\"")
        for part in re.split(r"[\s\u3000]+", text)
        if part.strip()
    ]
    if not parts:
        return text
    selected: list[str] = []
    compact_len = 0
    for part in parts:
        if not part:
            continue
        selected.append(part)
        compact_len += len(normalize_match_text(part))
        if compact_len >= minimum_chars:
            break
        # Two lexical chunks are enough for an onset probe even when the first
        # chunk is very short.
        if len(selected) >= 2:
            break
    return " ".join(selected).strip()


def ctc_path_fracture_evidence(assignment: dict[str, object]) -> dict[str, object]:
    """Detect a forced path that splits one lyric into disconnected time islands."""
    spans = assignment.get("ctc_token_spans")
    if not isinstance(spans, list) or len(spans) < 4:
        return {"fractured": False, "max_gap_seconds": 0.0, "gap_after_token_index": None}
    parsed: list[tuple[float, float, float]] = []
    for span in spans:
        if not isinstance(span, dict):
            continue
        try:
            parsed.append((
                float(span.get("start")),
                float(span.get("end")),
                float(span.get("score", 0.0) or 0.0),
            ))
        except (TypeError, ValueError):
            continue
    if len(parsed) < 4:
        return {"fractured": False, "max_gap_seconds": 0.0, "gap_after_token_index": None}
    gaps = [max(0.0, parsed[i + 1][0] - parsed[i][1]) for i in range(len(parsed) - 1)]
    if not gaps:
        return {"fractured": False, "max_gap_seconds": 0.0, "gap_after_token_index": None}
    max_gap = max(gaps)
    gap_index = gaps.index(max_gap)
    positive = sorted(g for g in gaps if g > 0.0)
    median_gap = float(statistics.median(positive)) if positive else 0.0
    # A multi-second hole inside one lyric is categorically different from
    # ordinary mora spacing.  Scale against the line's normal token gap too,
    # so slower songs are not penalised.
    fractured = bool(
        max_gap >= 3.0
        and (
            median_gap <= 0.0
            or max_gap >= max(3.0, median_gap * 8.0)
        )
    )
    return {
        "fractured": fractured,
        "max_gap_seconds": round(max_gap, 3),
        "gap_after_token_index": gap_index if fractured else None,
        "median_positive_gap_seconds": round(median_gap, 3),
    }


def run_ctc_prefix_probe(
    audio_path: Path,
    entry: LyricEntry,
    start_time: float,
    end_time: float,
    args: argparse.Namespace,
) -> dict[str, object] | None:
    """Run an independent MMS/CTC alignment of only the lyric opening phrase."""
    if end_time - start_time < 0.55:
        return None
    prefix_text = lyric_prefix_probe_text(entry)
    if not prefix_text:
        return None
    python_exe = default_ctc_python()
    helper = Path(__file__).resolve().parent / "ctc_align.py"
    if not python_exe.exists() or not helper.exists():
        return None
    with tempfile.TemporaryDirectory(prefix="lrc-ctc-prefix-") as temp_name:
        temp_dir = Path(temp_name)
        transcript_path = temp_dir / "prefix.json"
        output_path = temp_dir / "prefix-result.json"
        transcript_path.write_text(
            json.dumps([prefix_text], ensure_ascii=False),
            encoding="utf-8",
        )
        command = [
            str(python_exe),
            str(helper),
            "--audio",
            str(audio_path),
            "--transcript",
            str(transcript_path),
            "--output",
            str(output_path),
            "--device",
            str(getattr(args, "whisperx_device", "auto") or "auto"),
            "--start",
            f"{start_time:.3f}",
            "--end",
            f"{end_time:.3f}",
        ]
        proc = _run_model_helper_command(command, mode="ctc")
        if proc.returncode != 0 or not output_path.exists():
            return {
                "accepted": False,
                "prefix_text": prefix_text,
                "window": [round(start_time, 3), round(end_time, 3)],
                "error": (proc.stderr or proc.stdout).strip()[:240],
            }
        try:
            payload = json.loads(output_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None
        rows = payload.get("entries")
        if not isinstance(rows, list) or not rows or not isinstance(rows[0], dict):
            return None
        row = rows[0]
        try:
            candidate = float(row.get("start"))
            score = float(row.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            return None
        token_spans = row.get("token_spans")
        token_scores: list[float] = []
        token_times: list[float] = []
        if isinstance(token_spans, list):
            for span in token_spans[:10]:
                if not isinstance(span, dict):
                    continue
                try:
                    token_scores.append(float(span.get("score", 0.0) or 0.0))
                    token_times.append(float(span.get("start")))
                except (TypeError, ValueError):
                    continue
        prefix_mean = float(statistics.mean(token_scores)) if token_scores else 0.0
        weak_ratio = (
            sum(value < 0.05 for value in token_scores) / len(token_scores)
            if token_scores else 1.0
        )
        span_seconds = (
            token_times[-1] - token_times[0]
            if len(token_times) >= 2
            else 0.0
        )
        accepted = bool(
            start_time <= candidate <= end_time
            and score >= 0.045
            and len(token_scores) >= 4
            and prefix_mean >= 0.045
            and weak_ratio <= 0.70
            and span_seconds >= 0.18
        )
        return {
            "accepted": accepted,
            "prefix_text": prefix_text,
            "window": [round(start_time, 3), round(end_time, 3)],
            "candidate": round(candidate, 3),
            "ctc_score": round(score, 6),
            "prefix_mean_score": round(prefix_mean, 6),
            "prefix_weak_ratio": round(weak_ratio, 3),
            "prefix_span_seconds": round(span_seconds, 3),
            "token_spans": token_spans,
            "first_token_candidates": row.get("first_token_candidates"),
        }


def duplicate_block_offset_evidence(
    entries: list[LyricEntry],
    assignments: list[dict[str, object] | object],
    target_index: int,
) -> dict[str, object] | None:
    """Estimate a repeated-block offset from an adjacent duplicate lyric pair.

    This does not choose a timestamp.  It only provides a projection window for
    a later independent vocal/CTC onset probe.
    """
    groups: dict[str, list[int]] = {}
    for index, entry in enumerate(entries):
        normalized = normalize_match_text(entry_sung_text(entry))
        if normalized:
            groups.setdefault(normalized, []).append(index)
    normalized = normalize_match_text(entry_sung_text(entries[target_index]))
    pair = groups.get(normalized, [])
    if len(pair) != 2 or target_index not in pair:
        return None
    first_target, second_target = pair
    # Find an adjacent duplicated lyric whose two occurrences are shifted by
    # the same section offset.  Prefer the immediately preceding line.
    neighbors = [target_index - 1, target_index + 1]
    for neighbor in neighbors:
        if not 0 <= neighbor < len(entries):
            continue
        neighbor_norm = normalize_match_text(entry_sung_text(entries[neighbor]))
        neighbor_pair = groups.get(neighbor_norm, [])
        if len(neighbor_pair) != 2:
            continue
        a, b = neighbor_pair
        if (neighbor == first_target - 1 and a == first_target - 1 and b == second_target - 1) or (
            neighbor == second_target - 1 and a == first_target - 1 and b == second_target - 1
        ) or (
            neighbor == first_target + 1 and a == first_target + 1 and b == second_target + 1
        ) or (
            neighbor == second_target + 1 and a == first_target + 1 and b == second_target + 1
        ):
            if not (0 <= a < len(assignments) and 0 <= b < len(assignments)):
                continue
            left = assignments[a]
            right = assignments[b]
            if not isinstance(left, dict) or not isinstance(right, dict):
                continue
            left_spans = left.get("ctc_token_spans")
            right_spans = right.get("ctc_token_spans")
            if not isinstance(left_spans, list) or not isinstance(right_spans, list):
                continue
            deltas: list[float] = []
            for ls, rs in zip(left_spans, right_spans):
                if not isinstance(ls, dict) or not isinstance(rs, dict):
                    continue
                try:
                    if str(ls.get("char")) != str(rs.get("char")):
                        continue
                    lscore = float(ls.get("score", 0.0) or 0.0)
                    rscore = float(rs.get("score", 0.0) or 0.0)
                    if lscore < 0.05 or rscore < 0.05:
                        continue
                    deltas.append(float(rs.get("start")) - float(ls.get("start")))
                except (TypeError, ValueError):
                    continue
            if len(deltas) < 3:
                continue
            offset = float(statistics.median(deltas))
            spread = float(statistics.median(abs(value - offset) for value in deltas))
            if spread > 0.10:
                continue
            projected = None
            if target_index == first_target:
                other = assignments[second_target]
                if isinstance(other, dict):
                    try:
                        projected = float(other.get("timestamp")) - offset
                    except (TypeError, ValueError):
                        projected = None
            else:
                other = assignments[first_target]
                if isinstance(other, dict):
                    try:
                        projected = float(other.get("timestamp")) + offset
                    except (TypeError, ValueError):
                        projected = None
            return {
                "offset_seconds": round(offset, 3),
                "mad_seconds": round(spread, 3),
                "supporting_entries": [a + 1, b + 1],
                "projected_time": round(projected, 3) if projected is not None else None,
            }
    return None


def apply_final_ctc_timing_guard(
    audio_path: Path,
    entries: list[LyricEntry],
    timestamps: list[float],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace | None = None,
) -> tuple[list[float], dict[str, object], list[dict[str, object]]]:
    """Final fail-closed audit/repair for CTC onset boundaries.

    Earlier stages are allowed to alter token spans and candidate timestamps.
    This final pass therefore re-evaluates the *actual timestamp that will be
    written to LRC*.  When a zero-gap/weak-prefix boundary has a later reliable
    CTC token, an isolated-vocal acoustic onset may move the timestamp forward.
    If no such evidence exists, the line remains review-required instead of
    inheriting a high whole-line confidence.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(timestamps):
        return timestamps, report, []
    if not any(
        isinstance(item, dict) and isinstance(item.get("ctc_token_spans"), list)
        for item in assignments
    ):
        return timestamps, report, []

    refined = list(timestamps)
    for item in assignments:
        if isinstance(item, dict):
            item.pop("ctc_final_timing_guard_unresolved", None)
            if (
                item.get("ctc_crossline_initial_recovery")
                and not item.get("ctc_crossline_initial_recovery_trusted")
            ):
                # Do not let an earlier provisional cross-line move keep a
                # stale effective-token index.  The final audit must evaluate
                # the token spans that actually begin at the selected time.
                item.pop("ctc_effective_token_start_index", None)
    annotate_ctc_boundary_evidence(assignments)
    try:
        features = analyze_audio(audio_path, duration)
    except LrcError:
        features = None
    try:
        vocal_onset_features = analyze_vocal_onsets(audio_path, duration)
    except LrcError:
        vocal_onset_features = None

    prefix_probe_records: list[dict[str, object]] = []
    rejected_onset_candidates: dict[int, dict[str, object]] = {}
    local_window_report = report.get("ctc_local_window_realign")
    if isinstance(local_window_report, dict):
        rejected_rows = local_window_report.get("rejected_rows")
        if isinstance(rejected_rows, list):
            for row in rejected_rows:
                if not isinstance(row, dict) or row.get("reason") != "local-window-right-edge-pileup":
                    continue
                try:
                    entry_number = int(row.get("entry"))
                    candidate_time = float(row.get("candidate"))
                except (TypeError, ValueError):
                    continue
                rejected_onset_candidates[entry_number] = {
                    **row,
                    "candidate": candidate_time,
                }

    def later_prefix_support(
        assignment: dict[str, object], current_time: float
    ) -> tuple[float, float, int] | None:
        """Find a later token that survives an otherwise weak opening prefix.

        An isolated first-token posterior is not enough when 75% of the first
        eight tokens are weak.  Scan forward for a materially later supported
        token after the weak cluster; the acoustic onset is then searched just
        before that token instead of treating the isolated first character as
        proof of the LRC boundary.
        """
        spans = assignment.get("ctc_token_spans")
        if not isinstance(spans, list):
            return None
        parsed: list[tuple[float, float]] = []
        for span in spans[:16]:
            if not isinstance(span, dict):
                continue
            try:
                parsed.append((float(span.get("start")), float(span.get("score", 0.0) or 0.0)))
            except (TypeError, ValueError):
                continue
        if len(parsed) < 4:
            return None
        for index in range(2, len(parsed)):
            start, score = parsed[index]
            delay = start - current_time
            if not 0.35 <= delay <= 3.00 or score < 0.12:
                continue
            preceding = [value for _time, value in parsed[1:index]]
            if preceding:
                weak_ratio = sum(value < 0.05 for value in preceding) / len(preceding)
                if weak_ratio < 0.60:
                    continue
            return start, score, index
        return None

    changes: list[dict[str, object]] = []
    for index in range(1, len(assignments)):
        previous = assignments[index - 1]
        current = assignments[index]
        if not isinstance(previous, dict) or not isinstance(current, dict):
            continue
        evidence = current.get("ctc_boundary_evidence")
        if not isinstance(evidence, dict) or not evidence.get("available"):
            continue

        try:
            current_time = float(current.get("timestamp", refined[index]) or refined[index])
        except (TypeError, ValueError):
            continue
        previous_end = refined[index - 1]
        previous_spans = previous.get("ctc_token_spans")
        if isinstance(previous_spans, list):
            for span in previous_spans:
                if not isinstance(span, dict):
                    continue
                try:
                    previous_end = max(previous_end, float(span.get("end")))
                except (TypeError, ValueError):
                    continue
        next_time = refined[index + 1] if index + 1 < len(refined) else duration

        try:
            first_score = float(evidence.get("first_token_score", 0.0) or 0.0)
            weak_ratio = float(evidence.get("prefix_weak_ratio", 0.0) or 0.0)
            reliable_delay_raw = evidence.get("reliable_token_delay_seconds")
            reliable_delay = (
                float(reliable_delay_raw)
                if isinstance(reliable_delay_raw, (int, float))
                else None
            )
            reliable_time_raw = evidence.get("next_reliable_token_time")
            reliable_time = (
                float(reliable_time_raw)
                if isinstance(reliable_time_raw, (int, float))
                else None
            )
            reliable_score_raw = evidence.get("next_reliable_token_score")
            reliable_score = (
                float(reliable_score_raw)
                if isinstance(reliable_score_raw, (int, float))
                else 0.0
            )
        except (TypeError, ValueError):
            continue

        zero_gap_weak = bool(
            evidence.get("zero_boundary_gap")
            and evidence.get("unclear_boundary")
            and (
                first_score < 0.08
                or weak_ratio >= 0.50
                or (reliable_delay is not None and reliable_delay >= 0.45)
            )
        )
        near_gap_weak = bool(evidence.get("near_gap_weak_prefix"))
        fracture = ctc_path_fracture_evidence(current)
        current["ctc_path_fracture_evidence"] = fracture
        hard_boundary = bool(
            zero_gap_weak
            or near_gap_weak
            or fracture.get("fractured")
            or evidence.get("borrowed_tail_prefix")
            or evidence.get("ghost_weak_prefix")
            or evidence.get("prior_line_truncation_contamination")
            or evidence.get("timestamp_precedes_ctc_support")
            or evidence.get("realign_required")
        )
        if not hard_boundary:
            continue

        recovery_time: float | None = None
        acoustic_threshold: float | None = None
        recovery_reason = ""

        # v4: never salvage a timestamp from a full-line row whose tail already
        # proved that the path is broken.  Instead, independently re-run CTC on
        # only the lyric opening phrase.  This gives the onset its own semantic
        # evidence and prevents a later "again"/repeated word or a right-edge
        # pileup from donating a timestamp to token 0.
        duplicate_projection = duplicate_block_offset_evidence(
            entries, assignments, index
        )
        prefix_probe: dict[str, object] | None = None
        if args is not None:
            probe_floor = max(previous_end + 0.10, current_time + 0.05)
            probe_ceiling = next_time - 0.12
            projected_time = None
            if isinstance(duplicate_projection, dict):
                value = duplicate_projection.get("projected_time")
                if isinstance(value, (int, float)):
                    projected_time = float(value)
            if projected_time is not None:
                probe_start = max(probe_floor, projected_time - 0.85)
                probe_end = min(probe_ceiling, projected_time + 1.25)
            elif fracture.get("fractured"):
                # A fractured line needs a broad semantic search.  The prefix
                # probe, not the old full-line path, decides where token 0 is.
                probe_start = probe_floor
                probe_end = probe_ceiling
            else:
                probe_start = probe_floor
                probe_end = min(probe_ceiling, current_time + 4.0)

            if probe_end - probe_start >= 0.55:
                prefix_probe = run_ctc_prefix_probe(
                    audio_path,
                    entries[index],
                    probe_start,
                    probe_end,
                    args,
                )
                if isinstance(prefix_probe, dict):
                    prefix_probe["entry"] = index + 1
                    prefix_probe["duplicate_projection"] = duplicate_projection
                    prefix_probe_records.append(prefix_probe)
                    current["ctc_prefix_probe_evidence"] = prefix_probe

        if isinstance(prefix_probe, dict) and prefix_probe.get("accepted"):
            try:
                probe_candidate = float(prefix_probe.get("candidate"))
                probe_score = float(prefix_probe.get("ctc_score", 0.0) or 0.0)
                probe_mean = float(prefix_probe.get("prefix_mean_score", 0.0) or 0.0)
            except (TypeError, ValueError):
                probe_candidate = -1.0
                probe_score = 0.0
                probe_mean = 0.0

            acoustic_peak: dict[str, float] | None = None
            for onset_features, minimum in (
                (vocal_onset_features, 0.28),
                (features, 0.38),
            ):
                if onset_features is None:
                    continue
                candidate_peak = nearest_local_peak(
                    onset_features,
                    probe_candidate,
                    radius=0.24,
                    minimum_strength=minimum,
                )
                if isinstance(candidate_peak, dict):
                    try:
                        if (
                            abs(float(candidate_peak.get("delta_seconds", 9.0)))
                            <= PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
                        ):
                            acoustic_peak = candidate_peak
                            break
                    except (TypeError, ValueError):
                        pass

            # Strong prefix CTC may stand on its own; otherwise require the
            # isolated-vocal onset to agree.  The timestamp remains the CTC
            # prefix start (semantic evidence), not whichever spectral peak is
            # strongest.
            semantic_acoustic_support = bool(
                acoustic_peak is not None
                or (probe_score >= 0.12 and probe_mean >= 0.09)
            )
            if (
                semantic_acoustic_support
                and probe_candidate >= previous_end + 0.10
                and probe_candidate < next_time - 0.10
                and probe_candidate >= current_time + 0.10
            ):
                recovery_time = probe_candidate
                reliable_time = probe_candidate
                reliable_score = probe_score
                reliable_delay = probe_candidate - current_time
                recovery_reason = "independent-lyric-prefix-ctc-probe"
                current["ctc_prefix_probe_recovery"] = True
                current["ctc_prefix_probe_evidence"] = prefix_probe
                current["ctc_prefix_probe_acoustic_peak"] = acoustic_peak

        # For a 40-150 ms weak boundary, the first CTC character can be an
        # isolated accidental hit.  Use a later supported prefix token as a
        # *forward bound*, then search the vocal track for the new line onset
        # shortly before that token.  This is the 03:45 ``again`` failure that
        # v2 missed because token 0 happened to score 0.20.
        forward_support = later_prefix_support(current, current_time) if near_gap_weak or zero_gap_weak else None
        if recovery_time is None and prefix_probe is None and features is not None and forward_support is not None:
            support_time, support_score, support_index = forward_support
            search_start = max(
                previous_end + 0.10,
                current_time + 0.10,
                support_time - 1.10,
            )
            search_end = min(next_time - 0.10, support_time + 0.12)
            if search_end - search_start >= 0.20:
                for threshold in (0.70, 0.60, 0.50, 0.42):
                    onset = first_local_onset(features, search_start, search_end, threshold=threshold)
                    if onset is None:
                        continue
                    if (
                        onset >= previous_end + 0.10
                        and onset >= current_time + 0.10
                        and -0.12 <= support_time - onset <= 1.10
                    ):
                        recovery_time = onset
                        acoustic_threshold = threshold
                        reliable_time = support_time
                        reliable_score = support_score
                        reliable_delay = support_time - current_time
                        current["ctc_final_timing_recovery_support_token_index"] = support_index
                        recovery_reason = "near-gap-weak-prefix-recovered-by-acoustic-onset-and-forward-ctc"
                        break

        # Do not "repair" a compact 40 ms leak by simply picking the next CTC
        # character.  Require a materially later supported token and an acoustic
        # onset after ownership of the previous line has ended.
        if recovery_time is None and prefix_probe is None and (
            features is not None
            and reliable_time is not None
            and reliable_delay is not None
            and reliable_delay >= 0.55
            and reliable_score >= 0.08
        ):
            search_start = max(previous_end + 0.05, current_time + 0.05)
            search_end = min(next_time - 0.10, reliable_time + 0.15)
            if search_end - search_start >= 0.25:
                for threshold in (0.70, 0.60, 0.50, 0.42):
                    onset = first_local_onset(features, search_start, search_end, threshold=threshold)
                    if onset is None:
                        continue
                    # A new lyric needs its own acoustic event.  Keep at least
                    # 120 ms clear of the prior token tail and require it to be
                    # reasonably close to the later CTC support.
                    if (
                        onset >= previous_end + 0.12
                        and onset >= current_time + 0.12
                        and onset <= reliable_time + 0.15
                        and reliable_time - onset <= 1.10
                    ):
                        recovery_time = onset
                        acoustic_threshold = threshold
                        recovery_reason = "zero-gap-weak-prefix-recovered-by-acoustic-onset-and-forward-ctc"
                        break

        if recovery_time is not None:
            old_time = current_time
            refined[index] = recovery_time
            current["timestamp"] = round(recovery_time, 3)
            current["chosen_time"] = round(recovery_time, 3)
            current["ctc_final_timing_recovery"] = True
            current["ctc_final_timing_recovery_trusted"] = True
            current.pop("ctc_final_timing_guard_unresolved", None)
            current["ctc_final_timing_recovery_from"] = round(old_time, 3)
            current["ctc_final_timing_recovery_reliable_token_time"] = round(reliable_time, 3)
            current["ctc_final_timing_recovery_reliable_token_score"] = round(reliable_score, 6)
            current["ctc_final_timing_recovery_acoustic_threshold"] = acoustic_threshold
            current["timing_trusted"] = True
            if recovery_reason == "independent-lyric-prefix-ctc-probe":
                current["timing_trusted_reason"] = "independent-lyric-prefix-ctc-probe"
                current["timing_trusted_sources"] = ["ctc-prefix-probe", "vocal-onset"]
            else:
                current["timing_trusted_reason"] = "final-acoustic-onset-with-forward-ctc-support"
                current["timing_trusted_sources"] = ["acoustic", "ctc-forward-support"]
            current["timing_trusted_candidate_times"] = {
                "selected": round(recovery_time, 3),
                "previous_selected": round(old_time, 3),
                "next_reliable_ctc": round(reliable_time, 3),
            }
            current["timing_repair_source"] = (
                str(current.get("timing_repair_source") or "torchaudio-mms-fa")
                + "+final-timing-guard"
            )
            changes.append(
                {
                    "entry": index + 1,
                    "from": round(old_time, 3),
                    "to": round(recovery_time, 3),
                    "previous_token_end": round(previous_end, 3),
                    "next_reliable_ctc": round(reliable_time, 3),
                    "next_reliable_ctc_score": round(reliable_score, 6),
                    "acoustic_threshold": acoustic_threshold,
                    "reason": recovery_reason or "final-timing-guard-multi-evidence-recovery",
                }
            )
        else:
            current["ctc_final_timing_guard_unresolved"] = True
            current.pop("timing_trusted", None)
            current.pop("timing_trusted_reason", None)
            current.pop("timing_trusted_sources", None)
            current.pop("timing_trusted_candidate_times", None)

    annotate_ctc_boundary_evidence(assignments)
    # Final validation is authoritative: scoring is no longer allowed to clear
    # a boundary defect merely because the whole lyric path had a high score.
    unresolved = flag_unresolved_ctc_boundary_issues(entries, report, persist=True)
    report["ctc_final_timing_guard_count"] = len(changes)
    report["ctc_final_timing_guard_recoveries"] = changes
    report["ctc_final_timing_guard_unresolved"] = unresolved
    report["ctc_prefix_probe_count"] = len(prefix_probe_records)
    report["ctc_prefix_probes"] = prefix_probe_records
    update_report_confidence_metrics(report)
    return refined, report, changes


def _timing_spans_from_value(value: object) -> tuple[TimingTokenSpan, ...]:
    if not isinstance(value, list):
        return ()
    spans: list[TimingTokenSpan] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        try:
            start = float(item.get("start"))
            end = float(item.get("end"))
            score = float(item.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        spans.append(TimingTokenSpan(start, end, score, str(item.get("char") or "")))
    return tuple(sorted(spans, key=lambda span: (span.start, span.end)))


def _candidate_confidence(item: dict[str, object]) -> float:
    for key in ("confidence", "score", "ctc_score"):
        value = item.get(key)
        if isinstance(value, (int, float)):
            return _finite_unit_confidence(value)
    return 0.0


def _path_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


@lru_cache(maxsize=32)
def _cached_file_sha256(path_text: str, size: int, mtime_ns: int) -> str:
    # size/mtime are part of the cache key only; content is still actually hashed.
    del size, mtime_ns
    return _path_sha256(Path(path_text))


def _stable_file_sha256(path: Path) -> str:
    resolved = path.resolve()
    stat = resolved.stat()
    return _cached_file_sha256(str(resolved), stat.st_size, stat.st_mtime_ns)


def build_local_whisper_capability(
    audio_path: Path,
    args: argparse.Namespace,
) -> LocalWhisperCapability | None:
    """Build live provenance for unresolved-only Whisper-family observations.

    This authority is reconstructed from the actual current executable/model/helper
    files and source audio.  It is never inferred from serialized report metadata.
    """
    whisper_cli_arg = getattr(args, "whisper_cli", None)
    whisper_model_arg = getattr(args, "whisper_model", None)
    whisperx_python_arg = getattr(args, "whisperx_python", None)
    cli = Path(whisper_cli_arg).expanduser().resolve() if whisper_cli_arg else default_whisper_cli()
    model = Path(whisper_model_arg).expanduser().resolve() if whisper_model_arg else default_whisper_model()
    python_exe = Path(whisperx_python_arg).expanduser().resolve() if whisperx_python_arg else default_whisperx_python()
    helper = Path(__file__).resolve().parent / "whisperx_refine.py"
    try:
        source = audio_path.resolve()
    except OSError:
        return None
    if not all(path.is_file() for path in (source, cli, model, python_exe, helper)):
        return None
    try:
        payload = {
            "kind": "whispercpp-whisperx-local",
            "backend_lineage": "whisper-family",
            "audio_path": str(source),
            "audio_sha256": _stable_file_sha256(source),
            "whisper_cli_path": str(cli),
            "whisper_cli_sha256": _stable_file_sha256(cli),
            "whisper_model_path": str(model),
            "whisper_model_sha256": _stable_file_sha256(model),
            "whisperx_python_path": str(python_exe),
            "whisperx_helper_path": str(helper),
            "whisperx_helper_sha256": _stable_file_sha256(helper),
            "language": str(getattr(args, "whisper_language", "auto") or "auto"),
            "device": str(getattr(args, "whisperx_device", "auto") or "auto"),
            "protocol_revision": _LOCAL_WHISPER_PROTOCOL_REVISION,
        }
    except (OSError, LrcError):
        return None
    return LocalWhisperCapability(
        **payload,
        capability_revision=_canonical_json_digest(
            _local_whisper_capability_semantic_payload(payload)
        ),
    )


def _canonical_json_digest(value: object) -> str:
    try:
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        )
    except (TypeError, ValueError) as exc:
        raise LrcError(f"Value is not finite canonical JSON: {exc}") from exc
    return hashlib.sha256(encoded.encode("utf-8")).hexdigest()


def _bounded_retry_protocol_revision(helper_sha256: str) -> str:
    return _canonical_json_digest({
        "helper_sha256": helper_sha256,
        "protocol": _BOUNDED_RETRY_HELPER_PROTOCOL,
        "required_fields": ["entries", "entry", "text", "romaji", "tokens", "token_spans"],
    })


def _bounded_retry_capability_semantic_payload(
    payload: dict[str, object],
) -> dict[str, object]:
    """Return the path-free semantic identity for one CTC capability."""
    return {
        key: value
        for key, value in payload.items()
        if key not in {"helper_path", "alignment_audio_path", "capability_revision"}
    }


def _local_whisper_capability_semantic_payload(
    payload: dict[str, object],
) -> dict[str, object]:
    """Return the path-free semantic identity for local Whisper execution."""
    return {
        key: value
        for key, value in payload.items()
        if key not in {
            "audio_path",
            "whisper_cli_path",
            "whisper_model_path",
            "whisperx_python_path",
            "whisperx_helper_path",
            "capability_revision",
        }
    }


def create_bounded_retry_capability_seed(
    alignment_audio: Path,
    audio_source: str,
    helper: Path,
    *,
    sample_rate: int,
    device: str,
) -> dict[str, object]:
    """Create provenance only after the MMS known-lyric generation succeeded."""
    helper = helper.resolve()
    alignment_audio = alignment_audio.resolve()
    helper_sha = _path_sha256(helper)
    protocol_revision = _bounded_retry_protocol_revision(helper_sha)
    payload: dict[str, object] = {
        "kind": "mms-known-lyric-ctc",
        "backend_lineage": "ctc",
        "helper_path": str(helper),
        "helper_sha256": helper_sha,
        "helper_protocol_revision": protocol_revision,
        "alignment_audio_path": str(alignment_audio),
        "alignment_audio_sha256": _path_sha256(alignment_audio),
        "alignment_audio_source": audio_source,
        "sample_rate": sample_rate,
        "model_identity": _BOUNDED_RETRY_MODEL_IDENTITY,
        "device": device,
    }
    return {
        **payload,
        "capability_revision": _canonical_json_digest(
            _bounded_retry_capability_semantic_payload(payload)
        ),
    }


def _attach_bounded_retry_runtime_capability(
    report: dict[str, object],
    seed: dict[str, object],
) -> None:
    """Attach non-serializable in-process authority after a real CTC generation.

    The serialized seed is diagnostic provenance only.  Retry permission must not
    be reconstructible from report metadata loaded or fabricated later.
    """
    try:
        capability = BoundedRetryCapability(**seed)  # type: ignore[arg-type]
    except TypeError as exc:
        raise LrcError(f"Invalid bounded-retry capability seed: {exc}") from exc
    report[_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY] = capability


def carry_bounded_retry_capability_seed(
    target_report: dict[str, object],
    ctc_report: dict[str, object],
) -> None:
    seed = ctc_report.get("ctc_bounded_retry_capability_seed")
    if not isinstance(seed, dict):
        return
    target_report["ctc_bounded_retry_capability_seed"] = copy.deepcopy(seed)
    authority = ctc_report.get(_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY)
    if isinstance(authority, BoundedRetryCapability):
        target_report[_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY] = authority
    for key in (
        "ctc_backend", "ctc_device", "ctc_sample_rate", "ctc_audio_source", "ctc_audio_path"
    ):
        target_report[key] = ctc_report.get(key)


def build_bounded_retry_capability(
    report: dict[str, object],
    audio_path: Path,
    args: argparse.Namespace,
) -> BoundedRetryCapability | None:
    """Verify a generation-carried capability; metadata alone is never enough."""
    if str(report.get("backend") or "") not in {"ctc", "hybrid"}:
        return None
    seed = report.get("ctc_bounded_retry_capability_seed")
    authority = report.get(_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY)
    if not isinstance(seed, dict) or not isinstance(authority, BoundedRetryCapability):
        return None
    seed_payload = _bounded_retry_capability_semantic_payload(seed)
    try:
        if seed.get("capability_revision") != _canonical_json_digest(seed_payload):
            return None
    except LrcError:
        return None
    helper = Path(__file__).resolve().parent / "ctc_align.py"
    if seed.get("kind") != "mms-known-lyric-ctc" or seed.get("backend_lineage") != "ctc":
        return None
    try:
        effective_audio = audio_path.resolve()
        configured_path = Path(str(seed.get("alignment_audio_path"))).resolve()
        seeded_helper = Path(str(seed.get("helper_path"))).resolve()
    except (OSError, TypeError, ValueError):
        return None
    if (
        configured_path != effective_audio
        or seeded_helper != helper.resolve()
        or not helper.is_file()
        or not effective_audio.is_file()
    ):
        return None
    try:
        sample_rate = int(seed.get("sample_rate") or 0)
    except (TypeError, ValueError):
        return None
    helper_sha = _path_sha256(helper)
    if (
        sample_rate != SAMPLE_RATE
        or seed.get("helper_sha256") != helper_sha
        or seed.get("helper_protocol_revision") != _bounded_retry_protocol_revision(helper_sha)
        or seed.get("alignment_audio_sha256") != _path_sha256(effective_audio)
        or seed.get("model_identity") != _BOUNDED_RETRY_MODEL_IDENTITY
        or not str(seed.get("device") or "").strip()
    ):
        return None
    source = str(seed.get("alignment_audio_source") or "")
    if not source:
        return None
    try:
        seeded_capability = BoundedRetryCapability(**seed)  # type: ignore[arg-type]
    except TypeError:
        return None
    if authority != seeded_capability:
        return None
    return authority


def freeze_base_retry_epoch(
    backend: str,
    report: dict[str, object],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    diagnostics: dict[str, object],
    capability: BoundedRetryCapability | None,
) -> BaseRetryEpoch:
    candidate_revision = _candidate_set_semantic_revision(candidate_sets)
    _diagnostics_json, diagnostics_integrity_revision = freeze_generation_diagnostics(
        diagnostics
    )
    diagnostics_revision = generation_diagnostics_semantic_revision(diagnostics)
    epoch_payload = {
        "backend": backend,
        "report_projection_revision": timing_report_evaluation_revision(report),
        "ordinary_candidate_sets_revision": candidate_revision,
        "ordinary_diagnostics_revision": diagnostics_revision,
        "capability_revision": capability.capability_revision if capability else None,
        "schema_version": 1,
    }
    return BaseRetryEpoch(
        **epoch_payload,
        ordinary_diagnostics_integrity_revision=diagnostics_integrity_revision,
        retry_epoch_revision=_timing_content_digest(epoch_payload),
    )


def _retry_candidate_reference(candidate: TimingCandidate) -> RetryCandidateReference:
    regions = analyze_candidate_regions(candidate)
    return RetryCandidateReference(
        candidate.candidate_id,
        candidate.generation_revision,
        regions.region_revision,
        candidate.written_time.centiseconds,
    )


def plan_crossline_retry_requests(
    epoch: BaseRetryEpoch,
    capability: BoundedRetryCapability | None,
    entries: list[LyricEntry],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    duration: float,
    independent_tail_evidence: RuntimeTailEvidence | None = None,
    tail_evidence_context: TailEvidenceContext | None = None,
) -> tuple[CrossLineRetryRequest, ...]:
    """Plan bounded *current-line opening* recovery.

    The retry target is the current lyric alone.  Previous/next line starts
    bound the search window, while previous-line tail evidence is diagnostic
    only.  This prevents a long backing-vocal/ad-lib tail from forcing the
    current lyric to start after the previous transcript has been serially
    consumed.
    """
    if capability is None or capability.capability_revision != epoch.capability_revision:
        return ()
    if len(entries) != len(candidate_sets) or not math.isfinite(duration) or duration <= 0.0:
        return ()
    state = build_final_timing_state(
        candidate_sets,
        independent_tail_evidence=independent_tail_evidence,
        tail_evidence_context=tail_evidence_context,
    )
    requests: list[CrossLineRetryRequest] = []
    duration_revision = _timing_content_digest({"duration": round(duration, 6)})

    for index in range(1, len(entries)):
        decision = state.decisions[index]
        if decision.status != "provisional_unresolved":
            continue

        previous_decision = state.decisions[index - 1]
        previous_tail = resolve_reliable_tail(
            previous_decision.candidate,
            independent_tail_evidence[index - 1] if independent_tail_evidence else None,
            tail_evidence_context=tail_evidence_context,
        )
        relation = decision.evidence.ownership
        if (
            relation.previous_tail_evidence_revision is not None
            and relation.previous_tail_evidence_revision != previous_tail.tail_evidence_revision
        ):
            continue

        # A current-line-only retry cannot manufacture missing predecessor-tail
        # ownership evidence.  If the current lyric already has coherent intrinsic
        # opening/path proof and the *only* structural blocker is unavailable
        # previous-tail ownership, re-aligning the same current lyric is impossible
        # to change the authority graph.  Preserve retry for ambiguous/incoherent
        # current paths and for valid-tail uncertainty/violation where a changed
        # current boundary can legitimately change the relation.
        structural_failures = set(decision.evidence.structural_failures)
        current_tail = derive_reliable_tail(decision.candidate)
        if (
            relation.status == "unknown"
            and previous_tail.validity != "valid"
            and current_tail.validity == "valid"
            and decision.evidence.temporal_coherence == "coherent"
            and decision.evidence.onset_proof_end is not None
            and decision.evidence.reliable_support_count >= 3
            and structural_failures
            and structural_failures <= {"previous-tail-ownership-unknown"}
        ):
            continue

        current_ref = _retry_candidate_reference(decision.candidate)
        previous_ref = _retry_candidate_reference(previous_decision.candidate)
        next_ref = (
            _retry_candidate_reference(state.decisions[index + 1].candidate)
            if index + 1 < len(entries)
            else None
        )

        # Opening-first recovery aligns only the current lyric.  Do not serially
        # prepend the previous lyric, because that makes overlap impossible.
        context_indexes = (index,)
        context_candidates = (decision.candidate,)
        transcripts = (entry_sung_text(entries[index]),)
        transcript_digests = (_timing_content_digest(transcripts[0]),)
        row_mapping = ((index, 0),)

        current_start = decision.written_time.seconds
        previous_start = previous_decision.written_time.seconds
        previous_spacing = max(HOP_SECONDS, current_start - previous_start)

        # Search several seconds before the provisional start, but never before
        # the previous lyric's own start.  The previous *tail* is not a lower
        # bound: overlapping vocals are legal.
        backtrack = min(4.0, max(1.25, previous_spacing * 0.60))
        window_start = max(
            0.0,
            previous_start + HOP_SECONDS,
            current_start - backtrack,
        )

        if index + 1 < len(entries):
            next_start = state.decisions[index + 1].written_time.seconds
            # A helper row that reaches the right edge is incomplete evidence,
            # not a reason to accept the truncated path.  On the next bounded
            # fixed-point pass, widen by one *existing* 0.75 s overlap unit per
            # observed truncated retry, with a hard finite expansion count.
            truncated_retry_count = sum(
                1
                for candidate in candidate_sets[index]
                if candidate.source == "ctc-opening-local-retry"
                and candidate.window_truncated
            )
            expansion_count = min(
                CROSSLINE_RETRY_MAX_WINDOW_EXPANSIONS, truncated_retry_count
            )
            forward_overlap = CROSSLINE_RETRY_FORWARD_OVERLAP_SECONDS * (1 + expansion_count)
            # Give the current line a bounded overlap allowance beyond the next
            # provisional start so ad-libs/backing vocals do not compress its
            # terminal tokens.  Cap the forward horizon because opening
            # recovery must remain local even when the next lyric is far away.
            window_end = min(duration, next_start + forward_overlap, current_start + 14.0)
        else:
            # Terminal line: infer a bounded phrase horizon from the previous
            # inter-line spacing instead of aligning against the entire song.
            forward = min(14.0, max(7.0, previous_spacing * 1.60))
            window_end = min(duration, current_start + forward)

        if not 1.0 <= window_end - window_start <= 20.0:
            continue

        mapping_revision = _timing_content_digest(row_mapping)
        window_revision = _timing_content_digest({
            "mode": "opening-first-single-line",
            "start": round(window_start, 6),
            "end": round(window_end, 6),
            "previous_start": previous_ref.canonical_centiseconds,
            "current": current_ref.candidate_id,
            "next": next_ref.candidate_id if next_ref else None,
            "retry_window_truncation_count": (
                min(CROSSLINE_RETRY_MAX_WINDOW_EXPANSIONS, truncated_retry_count)
                if index + 1 < len(entries) else 0
            ),
            "duration_revision": duration_revision,
        })
        payload = {
            "retry_epoch_revision": epoch.retry_epoch_revision,
            "entry_index": index,
            "ordinal": 1,
            "capability_revision": capability.capability_revision,
            "alignment_audio_revision": capability.alignment_audio_sha256,
            "current": current_ref,
            "previous": previous_ref,
            "next_bound": next_ref,
            "audio_end_seconds": round(duration, 6),
            "audio_duration_revision": duration_revision,
            "previous_tail_evidence_revision": previous_tail.tail_evidence_revision,
            "previous_tail_start": previous_tail.reliable_tail_start,
            "previous_tail_end": previous_tail.reliable_tail_end,
            "previous_tail_uncertainty": previous_tail.uncertainty_seconds,
            "previous_tail_validity": previous_tail.validity,
            "ownership_relation_revision": relation.relation_revision,
            "context_entry_indexes": context_indexes,
            "context_candidate_ids": tuple(item.candidate_id for item in context_candidates),
            "transcript_digests": transcript_digests,
            "transcript_digest": _timing_content_digest(transcripts),
            "row_mapping": row_mapping,
            "row_mapping_revision": mapping_revision,
            "window_start": round(window_start, 6),
            "window_end": round(window_end, 6),
            "window_definition_revision": window_revision,
        }
        revision_payload = {
            **payload,
            "current": current_ref.__dict__,
            "previous": previous_ref.__dict__,
            "next_bound": next_ref.__dict__ if next_ref else None,
        }
        requests.append(CrossLineRetryRequest(
            **payload,
            request_revision=_timing_content_digest(revision_payload),
        ))
    return tuple(sorted(requests, key=lambda item: (item.entry_index, item.request_revision)))


def plan_joint_boundary_retry_requests(
    epoch: BaseRetryEpoch,
    capability: BoundedRetryCapability | None,
    entries: list[LyricEntry],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    duration: float,
    independent_tail_evidence: RuntimeTailEvidence | None = None,
    tail_evidence_context: TailEvidenceContext | None = None,
) -> tuple[CrossLineRetryRequest, ...]:
    """Plan bounded *previous+current lyric* joint boundary observations.

    Current-line-only retry can recover opening geometry, but it cannot directly
    answer which side of an ambiguous acoustic boundary belongs to the previous
    lyric.  This producer therefore aligns the immutable previous and current
    lyric rows *together* inside one bounded window.

    The helper result is observation-only.  It is never eligible for direct
    central selection; a later consensus step must bind it to a separately
    generated current-line candidate within the existing 0.18 s consensus
    tolerance before it may become boundary-grade evidence.
    """
    if capability is None or capability.capability_revision != epoch.capability_revision:
        return ()
    if len(entries) != len(candidate_sets) or not math.isfinite(duration) or duration <= 0.0:
        return ()

    state = build_final_timing_state(
        candidate_sets,
        independent_tail_evidence=independent_tail_evidence,
        tail_evidence_context=tail_evidence_context,
    )
    requests: list[CrossLineRetryRequest] = []
    duration_revision = _timing_content_digest({"duration": round(duration, 6)})

    for index in range(1, len(entries)):
        decision = state.decisions[index]
        if decision.status != "provisional_unresolved":
            continue

        audit_flags = set(decision.evidence.structural_failures)
        lacks_opening = not (
            decision.evidence.onset_proof_end is not None
            or candidate_has_bound_direct_onset_evidence(decision.candidate)
        )
        needs_boundary = bool(
            decision.evidence.ownership.status in {"unknown", "violation"}
            or lacks_opening
            or {
                "previous-tail-ownership-unknown",
                "previous-tail-overlap",
            }.intersection(audit_flags)
        )
        if not needs_boundary:
            continue

        previous_decision = state.decisions[index - 1]
        previous_tail = resolve_reliable_tail(
            previous_decision.candidate,
            independent_tail_evidence[index - 1] if independent_tail_evidence else None,
            tail_evidence_context=tail_evidence_context,
        )
        relation = decision.evidence.ownership
        if (
            relation.previous_tail_evidence_revision is not None
            and relation.previous_tail_evidence_revision != previous_tail.tail_evidence_revision
        ):
            continue

        current_ref = _retry_candidate_reference(decision.candidate)
        previous_ref = _retry_candidate_reference(previous_decision.candidate)
        next_ref = (
            _retry_candidate_reference(state.decisions[index + 1].candidate)
            if index + 1 < len(entries)
            else None
        )

        context_indexes = (index - 1, index)
        context_candidates = (previous_decision.candidate, decision.candidate)
        transcripts = tuple(entry_sung_text(entries[item]) for item in context_indexes)
        transcript_digests = tuple(_timing_content_digest(text) for text in transcripts)
        row_mapping = ((index - 1, 0), (index, 1))

        previous_start = previous_decision.written_time.seconds
        current_start = decision.written_time.seconds
        previous_previous_start = (
            state.decisions[index - 2].written_time.seconds if index >= 2 else 0.0
        )

        # Include enough pre-roll to let the helper observe the previous row's
        # real opening without swallowing the row before it.
        spacing = max(HOP_SECONDS, current_start - previous_start)
        pre_roll = min(3.0, max(1.0, spacing * 0.45))
        lower_neighbor = previous_previous_start + HOP_SECONDS if index >= 2 else 0.0
        window_start = max(lower_neighbor, previous_start - pre_roll)

        if index + 1 < len(entries):
            next_start = state.decisions[index + 1].written_time.seconds
            window_end = min(
                duration,
                next_start + 2.0 * CROSSLINE_RETRY_FORWARD_OVERLAP_SECONDS,
                current_start + 14.0,
            )
        else:
            window_end = min(duration, current_start + min(14.0, max(7.0, spacing * 1.8)))

        if not 2.0 <= window_end - window_start <= 24.0:
            continue

        mapping_revision = _timing_content_digest(row_mapping)
        window_revision = _timing_content_digest({
            "mode": "joint-previous-current-boundary",
            "start": round(window_start, 6),
            "end": round(window_end, 6),
            "previous_previous_start": round(previous_previous_start, 6),
            "previous": previous_ref.candidate_id,
            "current": current_ref.candidate_id,
            "next": next_ref.candidate_id if next_ref else None,
            "duration_revision": duration_revision,
        })
        payload = {
            "retry_epoch_revision": epoch.retry_epoch_revision,
            "entry_index": index,
            "ordinal": 2,
            "capability_revision": capability.capability_revision,
            "alignment_audio_revision": capability.alignment_audio_sha256,
            "current": current_ref,
            "previous": previous_ref,
            "next_bound": next_ref,
            "audio_end_seconds": round(duration, 6),
            "audio_duration_revision": duration_revision,
            "previous_tail_evidence_revision": previous_tail.tail_evidence_revision,
            "previous_tail_start": previous_tail.reliable_tail_start,
            "previous_tail_end": previous_tail.reliable_tail_end,
            "previous_tail_uncertainty": previous_tail.uncertainty_seconds,
            "previous_tail_validity": previous_tail.validity,
            "ownership_relation_revision": relation.relation_revision,
            "context_entry_indexes": context_indexes,
            "context_candidate_ids": tuple(item.candidate_id for item in context_candidates),
            "transcript_digests": transcript_digests,
            "transcript_digest": _timing_content_digest(transcripts),
            "row_mapping": row_mapping,
            "row_mapping_revision": mapping_revision,
            "window_start": round(window_start, 6),
            "window_end": round(window_end, 6),
            "window_definition_revision": window_revision,
        }
        revision_payload = {
            **payload,
            "current": current_ref.__dict__,
            "previous": previous_ref.__dict__,
            "next_bound": next_ref.__dict__ if next_ref else None,
        }
        requests.append(CrossLineRetryRequest(
            **payload,
            request_revision=_timing_content_digest(revision_payload),
        ))
    return tuple(sorted(requests, key=lambda item: (item.entry_index, item.request_revision)))


def crossline_retry_request_is_current(
    request: CrossLineRetryRequest,
    epoch: BaseRetryEpoch,
    capability: BoundedRetryCapability | None,
    entries: list[LyricEntry],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    duration: float,
    independent_tail_evidence: RuntimeTailEvidence | None = None,
    tail_evidence_context: TailEvidenceContext | None = None,
) -> bool:
    planner = (
        plan_joint_boundary_retry_requests
        if len(request.context_entry_indexes) == 2
        else plan_crossline_retry_requests
    )
    return request in planner(
        epoch,
        capability,
        entries,
        candidate_sets,
        duration,
        independent_tail_evidence,
        tail_evidence_context,
    )



def plan_local_whisper_requests(
    report: dict[str, object],
    capability: LocalWhisperCapability | None,
    entries: list[LyricEntry],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    duration: float,
    independent_tail_evidence: RuntimeTailEvidence | None = None,
    tail_evidence_context: TailEvidenceContext | None = None,
) -> tuple[LocalWhisperRequest, ...]:
    """Plan independent Whisper-family observations only where central evidence is incomplete."""
    if capability is None or len(entries) != len(candidate_sets):
        return ()
    if not math.isfinite(duration) or duration <= 0.0:
        return ()
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return ()
    state = build_final_timing_state(
        candidate_sets,
        independent_tail_evidence=independent_tail_evidence,
        tail_evidence_context=tail_evidence_context,
    )
    requests: list[LocalWhisperRequest] = []
    audio_revision = capability.audio_sha256

    for index, (decision, assignment) in enumerate(zip(state.decisions, assignments)):
        if not isinstance(assignment, dict):
            continue
        timing_need = decision.status == "provisional_unresolved"
        content_need = bool(
            not assignment_content_is_trusted(assignment)
            and not runtime_independent_content_identity_sources_for_entry(report, index)
        )
        review_need = _suspicious_entry_requires_review(report, index + 1)
        if not (timing_need or content_need or review_need):
            continue

        # Build a bounded identity context with one row of redundancy on each
        # available side.  The extra rows are not presumed trusted; they merely
        # give sparse occurrence binding a second anchor when an immediate
        # neighbor is weak.  If the expanded window would exceed the existing
        # 30 s local cap, fall back to the original minimal context.
        if _entry_identity_is_unique(entries, index):
            base_left = max(0, index - 1)
            base_right = min(len(entries) - 1, index + 1)
        else:
            fingerprint = _minimal_unique_sequence_context(entries, index, max_items=9)
            if fingerprint is None:
                continue
            base_left, base_right = fingerprint

        # Preserve the original minimal probe *and* optionally add one broader
        # sparse-context probe.  Broader context is evidence-additive only: it
        # must never replace a narrower request that may expose a cleaner direct
        # onset.  Runtime merging already ranks direct-onset evidence above
        # occurrence-only evidence for the same entry.
        context_options: list[tuple[int, int]] = [(base_left, base_right)]
        # Evaluate a small monotonic context ladder rather than betting the whole
        # observation on one segmentation-sensitive window.  Each broader probe
        # is optional evidence only; the minimal probe is always preserved.
        # Bound the ladder to at most three contexts and nine lyric rows so the
        # helper cost stays finite even on long songs.
        for expansion in (1, 2):
            expanded_left = max(0, base_left - expansion)
            expanded_right = min(len(entries) - 1, base_right + expansion)
            option = (expanded_left, expanded_right)
            if (
                expanded_left < index < expanded_right
                and expanded_right - expanded_left + 1 <= 9
                and option not in context_options
            ):
                context_options.append(option)

        seen_contexts: set[tuple[int, int, int, int]] = set()
        for option_left, option_right in context_options:
            option_left_start = state.decisions[option_left].written_time.seconds
            if option_left > 0:
                option_predecessor = state.decisions[option_left - 1].written_time.seconds
                option_window_start = max(
                    0.0,
                    option_predecessor + HOP_SECONDS,
                    option_left_start - LOCAL_WHISPER_CONTEXT_MARGIN_SECONDS,
                )
            else:
                option_window_start = 0.0

            option_right_start = state.decisions[option_right].written_time.seconds
            if option_right + 1 < len(entries):
                option_successor = state.decisions[option_right + 1].written_time.seconds
                option_window_end = min(
                    duration,
                    option_successor + LOCAL_WHISPER_CONTEXT_MARGIN_SECONDS,
                )
            else:
                option_window_end = min(duration, option_right_start + 8.0)
            if option_window_end <= option_right_start + 0.5:
                option_window_end = min(duration, option_right_start + 4.0)
            option_length = option_window_end - option_window_start
            if not 2.0 <= option_length <= LOCAL_WHISPER_MAX_WINDOW_SECONDS:
                continue

            context_indexes = tuple(range(option_left, option_right + 1))
            if not context_indexes or index not in context_indexes or len(context_indexes) > 9:
                continue
            semantic_key = (
                option_left,
                option_right,
                int(round(option_window_start * 1000)),
                int(round(option_window_end * 1000)),
            )
            if semantic_key in seen_contexts:
                continue
            seen_contexts.add(semantic_key)

            context_candidates = tuple(state.decisions[item].candidate for item in context_indexes)
            transcripts = tuple(entry_sung_text(entries[item]) for item in context_indexes)
            transcript_digests = tuple(_timing_content_digest(text) for text in transcripts)

            window_definition = {
                "mode": "unresolved-only-local-whisper",
                "start": round(option_window_start, 6),
                "end": round(option_window_end, 6),
                "context_indexes": list(context_indexes),
                "context_candidate_ids": [item.candidate_id for item in context_candidates],
                "timing_need": timing_need,
                "content_need": content_need,
                "review_need": review_need,
                "capability_revision": capability.capability_revision,
            }
            payload = {
                "entry_index": index,
                "capability_revision": capability.capability_revision,
                "audio_revision": audio_revision,
                "context_entry_indexes": context_indexes,
                "context_candidate_ids": tuple(item.candidate_id for item in context_candidates),
                "transcript_digests": transcript_digests,
                "transcript_digest": _timing_content_digest(transcripts),
                "window_start": round(option_window_start, 6),
                "window_end": round(option_window_end, 6),
                "window_definition_revision": _timing_content_digest(window_definition),
            }
            requests.append(LocalWhisperRequest(
                **payload,
                request_revision=_timing_content_digest({
                    **payload,
                    "context_entry_indexes": list(context_indexes),
                    "context_candidate_ids": list(payload["context_candidate_ids"]),
                    "transcript_digests": list(transcript_digests),
                }),
            ))
    return tuple(sorted(
        requests,
        key=lambda item: (item.entry_index, len(item.context_entry_indexes), item.request_revision),
    ))



_R2T_NEUTRAL_CONFLICT_PROBE_KEY = "r2t_unified_neutral_conflict_probe"
_R2T_NEUTRAL_CONFLICT_PROBE_MODE = "r2t-final-material-conflict-source-audio-neutral-local-whisper-v1"


def _r2t_validated_peer_conflict_rows(
    report: dict[str, object],
) -> tuple[dict[str, object] | None, tuple[dict[str, object], ...]]:
    projection = report.get(_BACKEND_PROVENANCE_PROJECTION_KEY)
    if not isinstance(projection, dict):
        return None, ()
    conflicts = projection.get("cross_backend_material_conflicts")
    if not isinstance(conflicts, dict):
        return None, ()
    if conflicts.get("authority") != "review-only" or conflicts.get("status") != "RETRIEVED":
        return conflicts, ()
    revision = conflicts.get("revision")
    if not isinstance(revision, str) or not revision:
        return conflicts, ()
    canonical = dict(conflicts)
    canonical.pop("revision", None)
    if _timing_content_digest(canonical) != revision:
        return conflicts, ()
    rows = conflicts.get("entries")
    if not isinstance(rows, list):
        return conflicts, ()
    return conflicts, tuple(
        item for item in rows
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    )


def _r2t_unresolved_projection_rows(
    report: dict[str, object],
) -> tuple[dict[str, object] | None, tuple[dict[str, object], ...]]:
    projection = report.get(_UNRESOLVED_EVIDENCE_REQUIREMENTS_KEY)
    if not isinstance(projection, dict) or projection.get("status") != "RETRIEVED":
        return projection if isinstance(projection, dict) else None, ()
    revision = projection.get("projection_revision")
    if not isinstance(revision, str) or not revision:
        return projection, ()
    canonical = dict(projection)
    canonical.pop("projection_revision", None)
    if _timing_content_digest(canonical) != revision:
        return projection, ()
    rows = projection.get("rows")
    if not isinstance(rows, list):
        return projection, ()
    return projection, tuple(
        item for item in rows
        if isinstance(item, dict) and isinstance(item.get("entry"), int)
    )


def _r2t_material_cluster_rows(value: object) -> tuple[dict[str, object], ...]:
    if not isinstance(value, list):
        return ()
    rows: list[dict[str, object]] = []
    for item in value:
        if (
            isinstance(item, dict)
            and item.get("relation") == "distant"
            and item.get("review_required") is True
            and item.get("explicit_falsification") is not True
        ):
            try:
                anchor = float(item.get("anchor_time"))
            except (TypeError, ValueError):
                continue
            if not math.isfinite(anchor):
                continue
            rows.append(item)
    return tuple(rows)


def _r2t_collect_final_material_targets(
    report: dict[str, object],
    final_state: FinalTimingState,
) -> tuple[dict[int, dict[str, object]], dict[str, object]]:
    """Collect final unresolved material clusters from both Central and peer consumers.

    This is reporting/probe planning only.  It consumes already-finalized state,
    never reconstructs candidate semantics, and never changes review or trust.
    """
    targets: dict[int, dict[str, object]] = {}
    unresolved_projection, unresolved_rows = _r2t_unresolved_projection_rows(report)
    peer_projection, peer_rows = _r2t_validated_peer_conflict_rows(report)

    def ensure_target(entry_number: int) -> dict[str, object] | None:
        index = entry_number - 1
        if not 0 <= index < len(final_state.decisions):
            return None
        selected = final_state.decisions[index]
        target = targets.setdefault(index, {
            "entry": entry_number,
            "selected_time": round(selected.written_time.seconds, 6),
            "selected_centiseconds": selected.written_time.centiseconds,
            "selected_candidate_id": selected.candidate.candidate_id,
            "selected_source": selected.candidate.source,
            "owners": [],
            "clusters": [],
        })
        return target

    for row in unresolved_rows:
        if row.get("review_required") is not True:
            continue
        clusters = _r2t_material_cluster_rows(row.get("material_clusters"))
        if not clusters:
            continue
        target = ensure_target(int(row["entry"]))
        if target is None:
            continue
        if "central" not in target["owners"]:
            target["owners"].append("central")
        for cluster in clusters:
            target["clusters"].append({
                "owner": "central",
                "anchor_time": round(float(cluster["anchor_time"]), 6),
                "anchor_centiseconds": canonicalize_lrc_time(float(cluster["anchor_time"])).centiseconds,
                "cluster_revision": cluster.get("cluster_revision"),
                "support_families": copy.deepcopy(cluster.get("support_families", [])),
                "member_candidate_ids": copy.deepcopy(cluster.get("member_candidate_ids", [])),
                "representative_candidate_id": cluster.get("representative_candidate_id"),
                "projection_revision": unresolved_projection.get("projection_revision")
                if isinstance(unresolved_projection, dict) else None,
            })

    for row in peer_rows:
        clusters = _r2t_material_cluster_rows(row.get("clusters"))
        if not clusters:
            continue
        target = ensure_target(int(row["entry"]))
        if target is None:
            continue
        if "peer" not in target["owners"]:
            target["owners"].append("peer")
        for cluster in clusters:
            target["clusters"].append({
                "owner": "peer",
                "anchor_time": round(float(cluster["anchor_time"]), 6),
                "anchor_centiseconds": canonicalize_lrc_time(float(cluster["anchor_time"])).centiseconds,
                "cluster_revision": cluster.get("cluster_revision"),
                "support_families": copy.deepcopy(cluster.get("support_families", [])),
                "member_candidate_ids": copy.deepcopy(cluster.get("member_candidate_ids", [])),
                "representative_candidate_id": cluster.get("representative_candidate_id"),
                "projection_revision": peer_projection.get("revision")
                if isinstance(peer_projection, dict) else None,
            })

    tolerance_centiseconds = int(round(RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS * 100.0))
    for index in list(targets):
        target = targets[index]
        selected_centiseconds = int(target["selected_centiseconds"])
        dedup: dict[int, dict[str, object]] = {}
        for cluster in target["clusters"]:
            anchor_centiseconds = int(cluster["anchor_centiseconds"])
            if abs(anchor_centiseconds - selected_centiseconds) <= tolerance_centiseconds:
                continue
            existing = dedup.get(anchor_centiseconds)
            if existing is None:
                existing = {
                    "anchor_time": round(anchor_centiseconds / 100.0, 6),
                    "anchor_centiseconds": anchor_centiseconds,
                    "owners": [],
                    "cluster_revisions": [],
                    "projection_revisions": [],
                    "support_families": [],
                    "member_candidate_ids": [],
                    "representative_candidate_ids": [],
                }
                dedup[anchor_centiseconds] = existing
            owner = cluster.get("owner")
            if isinstance(owner, str) and owner:
                existing["owners"].append(owner)
            revision = cluster.get("cluster_revision")
            if isinstance(revision, str) and revision:
                existing["cluster_revisions"].append(revision)
            projection_revision = cluster.get("projection_revision")
            if isinstance(projection_revision, str) and projection_revision:
                existing["projection_revisions"].append(projection_revision)
            families = cluster.get("support_families")
            if isinstance(families, list):
                existing["support_families"].extend(
                    str(item) for item in families if isinstance(item, str) and item
                )
            member_ids = cluster.get("member_candidate_ids")
            if isinstance(member_ids, list):
                existing["member_candidate_ids"].extend(
                    str(item) for item in member_ids if isinstance(item, str) and item
                )
            representative = cluster.get("representative_candidate_id")
            if isinstance(representative, str) and representative:
                existing["representative_candidate_ids"].append(representative)
        for cluster in dedup.values():
            for key in (
                "owners",
                "cluster_revisions",
                "projection_revisions",
                "support_families",
                "member_candidate_ids",
                "representative_candidate_ids",
            ):
                cluster[key] = sorted(set(cluster[key]))
        target["clusters"] = sorted(
            dedup.values(),
            key=lambda item: int(item["anchor_centiseconds"]),
        )
        target["owners"] = sorted(set(str(item) for item in target["owners"]))
        if not target["clusters"]:
            del targets[index]

    metadata = {
        "central_projection_revision": (
            unresolved_projection.get("projection_revision")
            if isinstance(unresolved_projection, dict) else None
        ),
        "peer_projection_revision": (
            peer_projection.get("revision")
            if isinstance(peer_projection, dict) else None
        ),
        "central_target_count": sum("central" in item["owners"] for item in targets.values()),
        "peer_target_count": sum("peer" in item["owners"] for item in targets.values()),
        "union_target_count": len(targets),
        "materiality_tolerance_centiseconds": tolerance_centiseconds,
    }
    return targets, metadata


def _r2t_plan_neutral_conflict_probe_requests(
    report: dict[str, object],
    capability: LocalWhisperCapability | None,
    entries: list[LyricEntry],
    final_state: FinalTimingState,
    duration: float,
) -> tuple[tuple[LocalWhisperRequest, ...], dict[int, dict[str, object]], dict[str, object]]:
    targets, source_metadata = _r2t_collect_final_material_targets(report, final_state)
    if len(final_state.decisions) != len(entries):
        return (), {}, source_metadata
    if not math.isfinite(duration) or duration <= 0.0:
        return (), {}, source_metadata

    metadata: dict[int, dict[str, object]] = {}
    requests: list[LocalWhisperRequest] = []
    for index, target in sorted(targets.items()):
        entry_number = index + 1
        selected_time = final_state.decisions[index].written_time.seconds
        anchor_times = [float(item["anchor_time"]) for item in target["clusters"]]
        if not anchor_times:
            continue

        if _entry_identity_is_unique(entries, index):
            # Global uniqueness is already sufficient occurrence context.  Keep
            # the neutral window centered on the disputed row so long inter-line
            # gaps do not inflate or suppress the probe.
            left = index
            right = index
        else:
            context = _minimal_unique_sequence_context(entries, index, max_items=9)
            if context is None:
                metadata[index] = {
                    **copy.deepcopy(target),
                    "status": "skipped",
                    "skip_reason": "unique-lyric-context-unavailable",
                }
                continue
            left, right = context

        context_times = [
            final_state.decisions[item].written_time.seconds
            for item in range(left, right + 1)
        ]
        low = min([selected_time, *anchor_times, *context_times])
        high = max([selected_time, *anchor_times, *context_times])
        window_start = max(0.0, low - LOCAL_WHISPER_CONTEXT_MARGIN_SECONDS)
        if right + 1 < len(entries):
            successor = final_state.decisions[right + 1].written_time.seconds
            high = max(high, min(successor, high + LOCAL_WHISPER_CONTEXT_MARGIN_SECONDS))
        window_end = min(duration, high + LOCAL_WHISPER_CONTEXT_MARGIN_SECONDS)
        window_length = window_end - window_start
        if not 2.0 <= window_length <= LOCAL_WHISPER_MAX_WINDOW_SECONDS:
            metadata[index] = {
                **copy.deepcopy(target),
                "status": "skipped",
                "skip_reason": "neutral-window-outside-bounds",
                "window_start": round(window_start, 6),
                "window_end": round(window_end, 6),
                "window_length": round(window_length, 6),
            }
            continue

        context_indexes = tuple(range(left, right + 1))
        context_candidates = tuple(final_state.decisions[item].candidate for item in context_indexes)
        transcripts = tuple(entry_sung_text(entries[item]) for item in context_indexes)
        transcript_digests = tuple(_timing_content_digest(item) for item in transcripts)
        window_definition = {
            "mode": _R2T_NEUTRAL_CONFLICT_PROBE_MODE,
            "entry": entry_number,
            "start": round(window_start, 6),
            "end": round(window_end, 6),
            "selected_time": round(selected_time, 6),
            "clusters": copy.deepcopy(target["clusters"]),
            "owners": list(target["owners"]),
            "context_indexes": list(context_indexes),
            "context_candidate_ids": [item.candidate_id for item in context_candidates],
            "source_metadata": source_metadata,
            "capability_revision": capability.capability_revision if capability is not None else None,
        }
        metadata[index] = {
            **copy.deepcopy(target),
            "status": "planned" if capability is not None else "capability-unavailable",
            "window_start": round(window_start, 6),
            "window_end": round(window_end, 6),
            "context_entries": [item + 1 for item in context_indexes],
            "window_definition_revision": _timing_content_digest(window_definition),
        }
        if capability is None:
            continue

        payload = {
            "entry_index": index,
            "capability_revision": capability.capability_revision,
            "audio_revision": capability.audio_sha256,
            "context_entry_indexes": context_indexes,
            "context_candidate_ids": tuple(item.candidate_id for item in context_candidates),
            "transcript_digests": transcript_digests,
            "transcript_digest": _timing_content_digest(transcripts),
            "window_start": round(window_start, 6),
            "window_end": round(window_end, 6),
            "window_definition_revision": _timing_content_digest(window_definition),
        }
        requests.append(LocalWhisperRequest(
            **payload,
            request_revision=_timing_content_digest({
                **payload,
                "context_entry_indexes": list(context_indexes),
                "context_candidate_ids": list(payload["context_candidate_ids"]),
                "transcript_digests": list(transcript_digests),
            }),
        ))
    return (
        tuple(sorted(requests, key=lambda item: (item.entry_index, item.request_revision))),
        metadata,
        source_metadata,
    )


def _r2t_authority_snapshot(report: dict[str, object]) -> str:
    assignments = report.get("assignments")
    assignment_projection: list[object] = []
    if isinstance(assignments, list):
        for item in assignments:
            if not isinstance(item, dict):
                assignment_projection.append(None)
                continue
            assignment_projection.append({
                "timestamp": item.get("timestamp"),
                "candidate_source": item.get("candidate_source"),
                "candidate_id": item.get("selected_candidate_id") or item.get("provisional_candidate_id"),
                "timing_trusted": item.get("timing_trusted"),
                "review_required": item.get("review_required"),
                "overall_trusted": item.get("overall_trusted"),
                "verification_status": item.get("verification_status"),
            })
    return _timing_content_digest({
        "assignments": assignment_projection,
        "central_timing_state": report.get("central_timing_state"),
        "candidate_selection": report.get("candidate_selection"),
        "review_reason_breakdown": report.get("review_reason_breakdown"),
        "authority_trusted_percent": report.get("authority_trusted_percent"),
        "review_required_percent": report.get("review_required_percent"),
    })


def _r2t_probe_relation(
    observation_time: float | None,
    selected_centiseconds: int,
    clusters: list[dict[str, object]],
) -> dict[str, object]:
    tolerance_centiseconds = int(round(RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS * 100.0))
    if observation_time is None or not math.isfinite(observation_time):
        return {
            "status": "no-boundary-observation",
            "selected_distance_centiseconds": None,
            "matched_clusters": [],
        }
    observed_centiseconds = canonicalize_lrc_time(observation_time).centiseconds
    selected_distance = abs(observed_centiseconds - selected_centiseconds)
    matched_clusters: list[dict[str, object]] = []
    for cluster in clusters:
        try:
            anchor_centiseconds = int(cluster.get("anchor_centiseconds"))
        except (TypeError, ValueError):
            continue
        distance = abs(observed_centiseconds - anchor_centiseconds)
        if distance <= tolerance_centiseconds:
            matched_clusters.append({
                "owners": copy.deepcopy(cluster.get("owners", [])),
                "anchor_time": cluster.get("anchor_time"),
                "anchor_centiseconds": anchor_centiseconds,
                "distance_centiseconds": distance,
                "cluster_revisions": copy.deepcopy(cluster.get("cluster_revisions", [])),
            })
    selected_match = selected_distance <= tolerance_centiseconds
    if selected_match and not matched_clusters:
        status = "selected-only"
    elif not selected_match and len(matched_clusters) == 1:
        status = "one-material-cluster-only"
    elif selected_match or matched_clusters:
        status = "ambiguous-multi-cluster"
    else:
        status = "no-cluster-match"
    return {
        "status": status,
        "observation_centiseconds": observed_centiseconds,
        "selected_distance_centiseconds": selected_distance,
        "matched_clusters": matched_clusters,
    }


def run_r2t_unified_neutral_conflict_probe(
    audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
    final_state: FinalTimingState,
) -> tuple[dict[str, object], dict[int, LocalWhisperOutcome]]:
    """Probe every final material conflict from neutral source audio.

    The probe itself remains non-authoritative.  The returned runtime outcomes may
    be consumed only by the bounded Central arbitration stage below.
    """
    _validate_unresolved_evidence_requirements_projection(report)
    _validate_backend_provenance_projection(report)
    authority_before = _r2t_authority_snapshot(report)
    capability = build_local_whisper_capability(audio_path, args)
    requests, metadata, source_metadata = _r2t_plan_neutral_conflict_probe_requests(
        report, capability, entries, final_state, duration
    )
    outcomes: tuple[LocalWhisperOutcome, ...] = ()
    preparation_errors: dict[str, str] = {}
    if capability is not None and requests:
        progress_log(
            f"R2T neutral material probe: targets={len(requests)} workers={DEFAULT_EVIDENCE_WORKERS}"
        )
        work = [
            (_local_whisper_cache_key(request, capability), ordinal, request)
            for ordinal, request in enumerate(requests, start=1)
        ]
        prepared, preparation_errors = _prepare_local_whisper_batch(work, capability, args)

        def execute_one(
            item: tuple[str, int, LocalWhisperRequest],
        ) -> tuple[int, LocalWhisperOutcome]:
            key, ordinal, request = item
            outcome = execute_local_whisper_request(
                request,
                capability,
                entries,
                args,
                cache={},
                runtime_stats={},
                prepared=prepared.get(key),
                preparation_error=preparation_errors.get(key),
            )
            return ordinal, outcome

        by_ordinal: dict[int, LocalWhisperOutcome] = {}
        with concurrent.futures.ThreadPoolExecutor(
            max_workers=min(DEFAULT_EVIDENCE_WORKERS, len(work) or 1),
            thread_name_prefix="lrc-r2t-neutral",
        ) as pool:
            for ordinal, outcome in pool.map(execute_one, work):
                by_ordinal[ordinal] = outcome
        outcomes = tuple(by_ordinal[index] for index in range(1, len(work) + 1))

    result_rows: list[dict[str, object]] = []
    request_by_revision = {item.request_revision: item for item in requests}
    for outcome in outcomes:
        request = request_by_revision.get(outcome.request_revision)
        detail = metadata.get(outcome.entry_index)
        if request is None or not isinstance(detail, dict):
            continue
        occurrence_time = None
        if isinstance(outcome.occurrence_binding, dict):
            try:
                value = float(outcome.occurrence_binding.get("timestamp"))
            except (TypeError, ValueError):
                value = math.nan
            if math.isfinite(value):
                occurrence_time = value
        clusters = detail.get("clusters")
        cluster_rows = clusters if isinstance(clusters, list) else []
        selected_centiseconds = int(detail["selected_centiseconds"])
        onset_relation = _r2t_probe_relation(
            outcome.onset_time,
            selected_centiseconds,
            cluster_rows,
        )
        occurrence_relation = _r2t_probe_relation(
            occurrence_time,
            selected_centiseconds,
            cluster_rows,
        )
        result_rows.append({
            **copy.deepcopy(detail),
            "status": outcome.status,
            "reason": outcome.reason,
            "request_revision": outcome.request_revision,
            "onset_time": round(outcome.onset_time, 6) if outcome.onset_time is not None else None,
            "onset_relation": onset_relation,
            "score": round(outcome.score, 6) if outcome.score is not None else None,
            "occurrence_binding_mode": (
                outcome.occurrence_binding.get("mode")
                if isinstance(outcome.occurrence_binding, dict) else None
            ),
            "occurrence_binding_revision": (
                outcome.occurrence_binding.get("binding_revision")
                if isinstance(outcome.occurrence_binding, dict) else None
            ),
            "occurrence_time": round(occurrence_time, 6) if occurrence_time is not None else None,
            "occurrence_relation": occurrence_relation,
            "evidence_revision": outcome.evidence_revision,
            "outcome_revision": outcome.outcome_revision,
        })

    authority_after = _r2t_authority_snapshot(report)
    if authority_after != authority_before:
        raise LrcError("R2T neutral material probe mutated Central authority state")
    onset_relation_counts = dict(sorted(collections.Counter(
        str(item.get("onset_relation", {}).get("status"))
        for item in result_rows
        if isinstance(item.get("onset_relation"), dict)
    ).items()))
    occurrence_relation_counts = dict(sorted(collections.Counter(
        str(item.get("occurrence_relation", {}).get("status"))
        for item in result_rows
        if isinstance(item.get("occurrence_relation"), dict)
    ).items()))
    skipped = [
        copy.deepcopy(item)
        for item in metadata.values()
        if isinstance(item, dict) and item.get("status") == "skipped"
    ]
    payload: dict[str, object] = {
        "schema_version": 1,
        "authority": "diagnostic-only",
        "mode": _R2T_NEUTRAL_CONFLICT_PROBE_MODE,
        "status": "complete" if capability is not None else "capability-unavailable",
        **source_metadata,
        "planned_entries": [item.entry_index + 1 for item in requests],
        "target_count": len(requests),
        "evidence_count": sum(item.status == "evidence" for item in outcomes),
        "invalid_count": sum(item.status == "invalid" for item in outcomes),
        "error_count": sum(item.status == "error" for item in outcomes),
        "skipped_count": len(skipped),
        "preparation_error_count": len(preparation_errors),
        "onset_relation_counts": onset_relation_counts,
        "occurrence_relation_counts": occurrence_relation_counts,
        "source_audio_neutral": True,
        "occurrence_time_semantics": "identity-binding-only-not-boundary-authority",
        "onset_relation_semantics": "diagnostic-only-existing-18cs-materiality-contract",
        "candidate_graph_mutated": False,
        "timestamp_mutated": False,
        "trust_mutated": False,
        "central_re_evaluated": False,
        "authority_snapshot_unchanged": authority_after == authority_before,
        "entries": result_rows,
        "skipped_entries": sorted(skipped, key=lambda item: int(item.get("entry", 0))),
    }
    payload["probe_revision"] = _timing_content_digest(payload)
    report[_R2T_NEUTRAL_CONFLICT_PROBE_KEY] = payload
    return payload, {item.entry_index: item for item in outcomes}


_NEUTRAL_BOUNDARY_ARBITRATION_KEY = "neutral_boundary_cross_backend_arbitration"
_NEUTRAL_BOUNDARY_ARBITRATION_MODE = "unique-neutral-onset-material-cluster-central-replay-v1"


def _neutral_arbitration_support_families(candidate: TimingCandidate) -> frozenset[str]:
    """Conservative lineage view used only by neutral-conflict arbitration.

    Keep the production mapper unchanged here, but close its known diagnostic gap
    for ``whispercpp-current`` so this arbitration can never manufacture a false
    independent vote from the same Whisper family.
    """
    families = set(_candidate_support_families(candidate))
    labels = " ".join(filter(None, [
        candidate.source,
        candidate.direct_onset_evidence.producer if candidate.direct_onset_evidence else "",
        candidate.acoustic_evidence.producer if candidate.acoustic_evidence else "",
    ])).lower()
    if "whispercpp" in labels:
        families.add("whisper-family")
    return frozenset(families)


def _neutral_probe_trigger_rows(payload: dict[str, object]) -> tuple[dict[str, object], ...]:
    """Freeze the blind discriminator before any reference evaluation."""
    if payload.get("source_audio_neutral") is not True:
        return ()
    tolerance_cs = int(round(RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS * 100.0))
    rows = payload.get("entries")
    if not isinstance(rows, list):
        return ()
    triggered: list[dict[str, object]] = []
    for row in rows:
        if not isinstance(row, dict) or row.get("status") != "evidence":
            continue
        relation = row.get("onset_relation")
        if not isinstance(relation, dict) or relation.get("status") != "one-material-cluster-only":
            continue
        matched = relation.get("matched_clusters")
        if not isinstance(matched, list) or len(matched) != 1 or not isinstance(matched[0], dict):
            continue
        try:
            selected_distance = int(relation.get("selected_distance_centiseconds"))
            onset_cs = int(relation.get("observation_centiseconds"))
            anchor_cs = int(matched[0].get("anchor_centiseconds"))
            score = float(row.get("score"))
        except (TypeError, ValueError):
            continue
        if (
            selected_distance <= tolerance_cs
            or abs(onset_cs - anchor_cs) > tolerance_cs
            or not math.isfinite(score)
        ):
            continue
        mode = row.get("occurrence_binding_mode")
        if mode not in _CANDIDATE_OCCURRENCE_MODES:
            continue
        triggered.append(row)
    return tuple(triggered)


def _neutral_arbitration_candidate_map(
    selection: BackendSelection,
) -> dict[str, TimingCandidate]:
    found: dict[str, TimingCandidate] = {}
    for evaluated in selection.candidates:
        for candidates in evaluated.candidate_sets:
            for candidate in candidates:
                found.setdefault(candidate.candidate_id, candidate)
    return found


def _neutral_arbitration_valid_candidate_ids(
    selection: BackendSelection,
    entry_index: int,
) -> frozenset[str]:
    """Return only candidates Central already considered structurally valid.

    A raw candidate being present in a backend bundle is not evidence that it
    supports a boundary.  This deliberately excludes candidates already
    rejected for ownership/minimum-proof/structural failures, preventing the
    neutral arbitration from resurrecting them as support or vetoes.
    """
    valid: set[str] = set()
    for evaluated in selection.candidates:
        if not 0 <= entry_index < len(evaluated.state.decisions):
            continue
        decision = evaluated.state.decisions[entry_index]
        if decision.status == "selected_valid" and decision.selected_candidate_id:
            valid.add(decision.selected_candidate_id)
        for rejected in decision.rejected_candidates:
            if rejected.valid:
                valid.add(rejected.candidate.candidate_id)
    return frozenset(valid)


def _neutral_arbitration_matching_cluster(
    row: dict[str, object],
) -> dict[str, object] | None:
    relation = row.get("onset_relation")
    clusters = row.get("clusters")
    if not isinstance(relation, dict) or not isinstance(clusters, list):
        return None
    matched = relation.get("matched_clusters")
    if not isinstance(matched, list) or len(matched) != 1 or not isinstance(matched[0], dict):
        return None
    try:
        anchor_cs = int(matched[0].get("anchor_centiseconds"))
    except (TypeError, ValueError):
        return None
    exact: list[dict[str, object]] = []
    for item in clusters:
        if not isinstance(item, dict):
            continue
        try:
            item_anchor_cs = int(item.get("anchor_centiseconds"))
        except (TypeError, ValueError):
            continue
        if item_anchor_cs == anchor_cs:
            exact.append(item)
    return exact[0] if len(exact) == 1 else None


def _neutral_arbitration_consensus_candidate(
    *,
    entries: list[LyricEntry],
    entry_index: int,
    parent: TimingCandidate,
    outcome: LocalWhisperOutcome,
    cluster: dict[str, object],
    probe_revision: str,
) -> TimingCandidate | None:
    if outcome.status != "evidence" or outcome.onset_time is None or outcome.score is None:
        return None
    occurrence = candidate_occurrence_evidence_from_binding(
        entries,
        entry_index,
        producer="local-whisper-aligner",
        occurrence_binding=outcome.occurrence_binding,
        upstream_evidence_revision=outcome.evidence_revision,
    )
    if occurrence is None:
        return None
    families = _neutral_arbitration_support_families(parent)
    if "whisper-family" in families:
        return None
    if "ctc" in families:
        source = "ctc-local-whisper-neutral-conflict-consensus"
    elif "recurrence" in families:
        source = "recurrence-local-whisper-neutral-conflict-consensus"
    else:
        return None
    artifact = {
        "mode": _NEUTRAL_BOUNDARY_ARBITRATION_MODE,
        "probe_revision": probe_revision,
        "neutral_outcome_revision": outcome.outcome_revision,
        "neutral_evidence_revision": outcome.evidence_revision,
        "parent_candidate_id": parent.candidate_id,
        "parent_generation_revision": parent.generation_revision,
        "cluster_revisions": copy.deepcopy(cluster.get("cluster_revisions", [])),
        "cluster_anchor_centiseconds": cluster.get("anchor_centiseconds"),
        "onset_time": round(float(outcome.onset_time), 6),
    }
    return make_timing_candidate(
        entry_index=entry_index,
        entry_text=entry_sung_text(entries[entry_index]),
        source=source,
        raw_time=parent.raw_time,
        spans=parent.spans,
        confidence=min(parent.confidence, float(outcome.score)),
        identity_support="supported",
        sequence_support="supported",
        acoustic_support="unavailable",
        direct_onset_support="supported",
        direct_onset_time=float(outcome.onset_time),
        direct_onset_source_artifact=artifact,
        direct_onset_evidence_producer="local-whisper-aligner",
        direct_onset_evidence_kind="cross-backend-onset",
        direct_onset_evidence_independent=True,
        occurrence_evidence=occurrence,
        independent_content_identity=True,
        current=False,
        prefix_scope=parent.prefix_scope,
        right_edge_pileup=False,
        window_truncated=False,
        source_artifact=artifact,
    )


def _update_projection_seed_for_arbitrated_selection(
    seed: dict[str, object],
    selection: BackendSelection,
    arbitration_payload: dict[str, object],
) -> dict[str, object]:
    rebound = copy.deepcopy(seed)
    rebound["selection"] = central_candidate_selection_payload(selection)
    rows = rebound.get("candidates")
    by_backend = {item.backend: item for item in selection.candidates}
    if isinstance(rows, list):
        for row in rows:
            if not isinstance(row, dict):
                continue
            backend = str(row.get("backend") or "")
            evaluated = by_backend.get(backend)
            if evaluated is None:
                continue
            row["selection_status"] = (
                "selected" if evaluated is selection.selected else "nonselected"
            )
            row["evaluation"] = central_backend_summary_payload(evaluated)
            row["selection_reason"] = central_selection_reason(selection)
    rebound["neutral_boundary_arbitration"] = copy.deepcopy(arbitration_payload)
    return rebound



_NEUTRAL_ARBITRATION_FINAL_SEMANTIC_FIELDS = (
    "timestamp",
    "canonical_written_centiseconds",
    "selected_candidate_id",
    "provisional_candidate_id",
    "candidate_source",
    "timestamp_status",
    "timing_trusted",
    "content_trusted",
    "content_trust_source",
    "review_required",
    "review_reason_classes",
    "overall_trusted",
    "verification_status",
    "confidence",
)

# ``review_reason_classes`` explains *why* an already-review-required row is
# reviewable.  It is not itself an authority verdict.  A predecessor correction
# may legitimately rebind that taxonomy on a successor while leaving timestamp,
# candidate, trust and verification verdict unchanged (an accepted predecessor-correction
# behavior already demonstrates this dependency class).  Keep the field in diagnostics, but do not let a
# reason-class-only dependent rebind veto an otherwise safe target.
_NEUTRAL_ARBITRATION_HARD_COLLATERAL_FIELDS = frozenset(
    field
    for field in _NEUTRAL_ARBITRATION_FINAL_SEMANTIC_FIELDS
    if field != "review_reason_classes"
)


def _neutral_arbitration_final_semantic_rows(
    report: dict[str, object],
) -> tuple[dict[str, object], ...]:
    """Return the post-consumer semantic surface used by the replay safety gate.

    R2R FINAL established that producer/Central correctness is insufficient when
    downstream suspicious/material-review consumers can resurrect a conflict.
    Neutral arbitration therefore compares the fully projected assignment
    semantics, not only the selected candidate/time/timing-audit tuple.
    Evidence/provenance metadata may legitimately rebind on successor rows and
    is intentionally excluded unless it changes a final semantic field below.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list):
        raise LrcError("Neutral arbitration projection has no assignments")
    rows: list[dict[str, object]] = []
    for index, item in enumerate(assignments):
        if not isinstance(item, dict) or item.get("entry") != index + 1:
            raise LrcError("Neutral arbitration projection assignment is malformed")
        rows.append({
            "entry": index + 1,
            **{key: copy.deepcopy(item.get(key)) for key in _NEUTRAL_ARBITRATION_FINAL_SEMANTIC_FIELDS},
        })
    return tuple(rows)


def _neutral_arbitration_project_selection(
    report: dict[str, object],
    selection: BackendSelection,
) -> tuple[dict[str, object], FinalTimingState]:
    """Privately run the ordinary final projection for one candidate selection.

    This uses the same Central commit and downstream review consumers as
    production, but only on a deep copy.  It cannot write production state.
    """
    projected = copy.deepcopy(report)
    state = _apply_evaluated_backend_projection(selection, projected)
    assert_report_timestamp_equality(projected, state)
    update_report_confidence_metrics(projected)
    assert_report_review_contract(projected)
    return projected, state


def _neutral_arbitration_selection_with_revised_eval(
    selection: BackendSelection,
    original_selected: EvaluatedBackendTiming,
    revised_eval: EvaluatedBackendTiming,
) -> BackendSelection:
    replaced = tuple(
        revised_eval if item is original_selected else item
        for item in selection.candidates
    )
    return select_evaluated_backend(replaced)


def _neutral_arbitration_replay_gate(
    before_report: dict[str, object],
    after_report: dict[str, object],
    target_indexes: frozenset[int] | set[int],
    outcome_map: Mapping[int, LocalWhisperOutcome],
    tolerance_centiseconds: int,
) -> tuple[list[int], list[int], dict[int, tuple[str, ...]]]:
    """Validate one private replay through the complete final consumer path.

    ``target_indexes`` is the exact set of candidate graphs intentionally
    changed.  Any non-target mutation of the hard final verdict surface is
    collateral.  Review/overall/verification state remains blocking so the
    replay cannot repeat the R2R producer-success/consumer-mismatch failure
    mode; a review-reason taxonomy-only rebind is diagnostic and non-blocking.
    """
    targets = set(target_indexes)
    before_rows = _neutral_arbitration_final_semantic_rows(before_report)
    after_rows = _neutral_arbitration_final_semantic_rows(after_report)
    if len(before_rows) != len(after_rows):
        raise LrcError("Neutral arbitration projection changed assignment count")
    collateral: list[int] = []
    failed_targets: list[int] = []
    changed_fields: dict[int, tuple[str, ...]] = {}
    for index, (before, after) in enumerate(zip(before_rows, after_rows)):
        fields = tuple(
            key
            for key in _NEUTRAL_ARBITRATION_FINAL_SEMANTIC_FIELDS
            if before.get(key) != after.get(key)
        )
        if fields:
            changed_fields[index + 1] = fields
        blocking_fields = tuple(
            key for key in fields
            if key in _NEUTRAL_ARBITRATION_HARD_COLLATERAL_FIELDS
        )
        if blocking_fields and index not in targets:
            collateral.append(index + 1)
        if index not in targets:
            continue
        outcome = outcome_map.get(index)
        after_cs = after.get("canonical_written_centiseconds")
        if (
            outcome is None
            or outcome.onset_time is None
            or after.get("timestamp_status") != "selected_valid"
            or after.get("timing_trusted") is not True
            or not isinstance(after_cs, int)
            or abs(
                after_cs
                - canonicalize_lrc_time(float(outcome.onset_time)).centiseconds
            ) > tolerance_centiseconds
        ):
            failed_targets.append(index + 1)
    return collateral, failed_targets, changed_fields


def _precommit_neutral_boundary_arbitration(
    audio_path: Path,
    entries: list[LyricEntry],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
    selection: BackendSelection,
) -> tuple[BackendSelection, dict[str, object], dict[str, object]]:
    """Acquire neutral boundary evidence once, then replay only the selected Central graph.

    The discovery commit occurs on a private report copy.  Production state is
    unchanged until a revised ``EvaluatedBackendTiming`` passes all fail-closed
    invariants and is committed through the ordinary Central owner.
    """
    shadow = copy.deepcopy(report)
    shadow_state = _apply_evaluated_backend_projection(selection, shadow)
    assert_report_timestamp_equality(shadow, shadow_state)
    update_report_confidence_metrics(shadow)
    shadow[_UNRESOLVED_EVIDENCE_REQUIREMENTS_KEY] = (
        _build_unresolved_evidence_requirements_projection(shadow, shadow_state)
    )
    probe_payload, outcome_map = run_r2t_unified_neutral_conflict_probe(
        audio_path, entries, shadow, duration, args, shadow_state
    )
    triggers = _neutral_probe_trigger_rows(probe_payload)
    base_payload: dict[str, object] = {
        "schema_version": 1,
        "mode": _NEUTRAL_BOUNDARY_ARBITRATION_MODE,
        "probe_revision": probe_payload.get("probe_revision"),
        "trigger_count": len(triggers),
        "trigger_entries": sorted(
            int(item.get("entry")) for item in triggers if isinstance(item.get("entry"), int)
        ),
        "status": "NO_TRIGGER" if not triggers else "EVALUATING",
        "central_replayed": False,
        "candidate_admission_count": 0,
        "falsified_candidate_count": 0,
        "replay_safety_scope": "full-final-assignment-semantics-v1",
        "consumer_parity_guard": True,
        "entries": [],
    }
    if not triggers:
        base_payload["revision"] = _timing_content_digest(base_payload)
        return selection, probe_payload, base_payload

    candidate_map = _neutral_arbitration_candidate_map(selection)
    selected_eval = selection.selected
    revised_sets = [list(items) for items in selected_eval.candidate_sets]
    tolerance_cs = int(round(RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS * 100.0))
    diagnostics: list[dict[str, object]] = []
    targeted_indexes: set[int] = set()

    for row in triggers:
        entry_number = row.get("entry")
        if not isinstance(entry_number, int):
            continue
        index = entry_number - 1
        if not 0 <= index < len(revised_sets):
            continue
        outcome = outcome_map.get(index)
        cluster = _neutral_arbitration_matching_cluster(row)
        if outcome is None or cluster is None or outcome.onset_time is None or outcome.score is None:
            continue
        original_decision = selected_eval.state.decisions[index]
        selected_candidate = original_decision.candidate
        selected_families = _neutral_arbitration_support_families(selected_candidate)
        if (
            "whisper-family" not in selected_families
            or "ctc" in selected_families
            or "recurrence" in selected_families
            or float(outcome.score) < selected_candidate.confidence
        ):
            continue
        onset_cs = canonicalize_lrc_time(float(outcome.onset_time)).centiseconds
        selected_cs = original_decision.written_time.centiseconds
        if abs(onset_cs - selected_cs) <= tolerance_cs:
            continue

        member_ids = cluster.get("member_candidate_ids")
        if not isinstance(member_ids, list):
            continue
        valid_candidate_ids = _neutral_arbitration_valid_candidate_ids(selection, index)
        parents: list[TimingCandidate] = []
        for candidate_id in member_ids:
            if not isinstance(candidate_id, str):
                continue
            parent = candidate_map.get(candidate_id)
            if parent is None or parent.entry_index != index:
                continue
            families = _neutral_arbitration_support_families(parent)
            if "whisper-family" in families or not ({"ctc", "recurrence"} & set(families)):
                continue
            if abs(parent.written_time.centiseconds - onset_cs) > tolerance_cs:
                continue
            if parent.identity_support != "supported" or parent.sequence_support != "supported":
                continue
            parents.append(parent)
        if not parents:
            continue

        # Fail closed if the selected boundary already has an independent
        # non-Whisper witness anywhere in the frozen backend corpus.
        independent_selected_support = [
            candidate for candidate in candidate_map.values()
            if candidate.entry_index == index
            and candidate.candidate_id in valid_candidate_ids
            and abs(candidate.written_time.centiseconds - selected_cs) <= tolerance_cs
            and "whisper-family" not in _neutral_arbitration_support_families(candidate)
            and bool({"ctc", "recurrence"} & set(_neutral_arbitration_support_families(candidate)))
            and candidate.identity_support == "supported"
            and candidate.sequence_support == "supported"
        ]
        if independent_selected_support:
            continue

        consensus: list[TimingCandidate] = []
        for parent in sorted(parents, key=lambda item: item.candidate_id):
            candidate = _neutral_arbitration_consensus_candidate(
                entries=entries,
                entry_index=index,
                parent=parent,
                outcome=outcome,
                cluster=cluster,
                probe_revision=str(probe_payload.get("probe_revision") or ""),
            )
            if candidate is not None:
                consensus.append(candidate)
        if not consensus:
            continue

        falsified = [
            candidate for candidate in revised_sets[index]
            if abs(candidate.written_time.centiseconds - selected_cs) <= tolerance_cs
            and "whisper-family" in _neutral_arbitration_support_families(candidate)
            and "ctc" not in _neutral_arbitration_support_families(candidate)
            and "recurrence" not in _neutral_arbitration_support_families(candidate)
        ]
        falsified_ids = {item.candidate_id for item in falsified}
        if selected_candidate.candidate_id not in falsified_ids:
            continue
        survivors = [
            item for item in revised_sets[index] if item.candidate_id not in falsified_ids
        ]
        merged = {item.candidate_id: item for item in [*survivors, *consensus]}
        revised_sets[index] = [merged[key] for key in sorted(merged)]
        targeted_indexes.add(index)
        diagnostics.append({
            "entry": entry_number,
            "old_selected_candidate_id": selected_candidate.candidate_id,
            "old_selected_centiseconds": selected_cs,
            "neutral_onset_centiseconds": onset_cs,
            "cluster_anchor_centiseconds": cluster.get("anchor_centiseconds"),
            "parent_candidate_ids": sorted(item.candidate_id for item in parents),
            "admitted_candidate_ids": sorted(item.candidate_id for item in consensus),
            "falsified_candidate_ids": sorted(falsified_ids),
            "neutral_evidence_revision": outcome.evidence_revision,
            "neutral_outcome_revision": outcome.outcome_revision,
        })

    if not targeted_indexes:
        base_payload["status"] = "NO_SAFE_ARBITRATION"
        base_payload["entries"] = diagnostics
        base_payload["revision"] = _timing_content_digest(base_payload)
        return selection, probe_payload, base_payload

    generation_diagnostics = thaw_generation_diagnostics(selected_eval)
    generation_diagnostics[_NEUTRAL_BOUNDARY_ARBITRATION_KEY] = {
        "mode": _NEUTRAL_BOUNDARY_ARBITRATION_MODE,
        "probe_revision": probe_payload.get("probe_revision"),
        "entries": copy.deepcopy(diagnostics),
    }
    revised_eval = evaluate_backend_timing(
        selected_eval.backend,
        tuple(tuple(items) for items in revised_sets),
        report,
        generation_diagnostics,
        arbiter_mode=selected_eval.arbiter_mode,
    )

    # First try the full blind trigger set exactly as before.  When several
    # independent neutral positives exist in one song, one unsafe trigger must
    # not mask another demonstrably safe trigger.  If the combined private
    # replay fails, isolate every trigger against the same immutable pre-replay
    # Central state, retain only individually safe triggers, then perform one
    # final consolidated Central replay over that safe subset.  Production is
    # still committed only once by the ordinary owner.
    revised_selection = _neutral_arbitration_selection_with_revised_eval(
        selection, selected_eval, revised_eval
    )
    initial_backend_flip = revised_selection.selected.backend != selected_eval.backend
    if initial_backend_flip:
        collateral = []
        failed_targets = sorted(index + 1 for index in targeted_indexes)
        initial_changed_fields: dict[int, tuple[str, ...]] = {}
    else:
        revised_shadow, _revised_shadow_state = _neutral_arbitration_project_selection(
            report, revised_selection
        )
        collateral, failed_targets, initial_changed_fields = (
            _neutral_arbitration_replay_gate(
                shadow,
                revised_shadow,
                targeted_indexes,
                outcome_map,
                tolerance_cs,
            )
        )
    initial_combined_failure = {
        "collateral_entries": list(collateral),
        "failed_target_entries": list(failed_targets),
        "backend_flip": initial_backend_flip,
        "candidate_backend": revised_selection.selected.backend,
        "changed_final_semantic_fields": {
            str(entry): list(fields)
            for entry, fields in sorted(initial_changed_fields.items())
        },
    }
    isolation_rows: list[dict[str, object]] = []
    rejected_target_indexes: set[int] = set()

    if collateral or failed_targets:
        independently_safe: set[int] = set()
        diagnostics_by_index = {
            int(item["entry"]) - 1: item
            for item in diagnostics
            if isinstance(item.get("entry"), int)
        }
        for index in sorted(targeted_indexes):
            isolated_sets = [list(items) for items in selected_eval.candidate_sets]
            isolated_sets[index] = list(revised_sets[index])
            isolated_generation_diagnostics = thaw_generation_diagnostics(selected_eval)
            isolated_generation_diagnostics[_NEUTRAL_BOUNDARY_ARBITRATION_KEY] = {
                "mode": _NEUTRAL_BOUNDARY_ARBITRATION_MODE,
                "probe_revision": probe_payload.get("probe_revision"),
                "entries": copy.deepcopy(
                    [diagnostics_by_index[index]] if index in diagnostics_by_index else []
                ),
                "private_replay_scope": "single-trigger-isolation",
            }
            isolated_eval = evaluate_backend_timing(
                selected_eval.backend,
                tuple(tuple(items) for items in isolated_sets),
                report,
                isolated_generation_diagnostics,
                arbiter_mode=selected_eval.arbiter_mode,
            )
            isolated_selection = _neutral_arbitration_selection_with_revised_eval(
                selection, selected_eval, isolated_eval
            )
            isolated_backend_flip = (
                isolated_selection.selected.backend != selected_eval.backend
            )
            if isolated_backend_flip:
                isolated_collateral = []
                isolated_failed = [index + 1]
                isolated_changed_fields: dict[int, tuple[str, ...]] = {}
            else:
                isolated_shadow, _isolated_shadow_state = (
                    _neutral_arbitration_project_selection(report, isolated_selection)
                )
                isolated_collateral, isolated_failed, isolated_changed_fields = (
                    _neutral_arbitration_replay_gate(
                        shadow,
                        isolated_shadow,
                        {index},
                        outcome_map,
                        tolerance_cs,
                    )
                )
            safe = not isolated_collateral and not isolated_failed
            isolation_rows.append({
                "entry": index + 1,
                "status": "SAFE" if safe else "REJECTED",
                "collateral_entries": isolated_collateral,
                "failed_target_entries": isolated_failed,
                "backend_flip": isolated_backend_flip,
                "candidate_backend": isolated_selection.selected.backend,
                "changed_final_semantic_fields": {
                    str(entry): list(fields)
                    for entry, fields in sorted(isolated_changed_fields.items())
                },
                "evaluation_revision": isolated_eval.evaluation_revision,
                "selection_revision": isolated_selection.selection_revision,
            })
            if safe:
                independently_safe.add(index)
            else:
                rejected_target_indexes.add(index)

        if not independently_safe:
            for item in diagnostics:
                if isinstance(item.get("entry"), int):
                    item["arbitration_disposition"] = "rejected-private-replay"
            base_payload.update({
                "status": "FAIL_CLOSED",
                "collateral_entries": collateral,
                "failed_target_entries": failed_targets,
                "entries": diagnostics,
                "initial_combined_replay": initial_combined_failure,
                "trigger_isolation": isolation_rows,
                "applied_trigger_entries": [],
                "rejected_trigger_entries": sorted(index + 1 for index in targeted_indexes),
            })
            base_payload["revision"] = _timing_content_digest(base_payload)
            return selection, probe_payload, base_payload

        consolidated_sets = [list(items) for items in selected_eval.candidate_sets]
        for index in independently_safe:
            consolidated_sets[index] = list(revised_sets[index])
        consolidated_generation_diagnostics = thaw_generation_diagnostics(selected_eval)
        consolidated_generation_diagnostics[_NEUTRAL_BOUNDARY_ARBITRATION_KEY] = {
            "mode": _NEUTRAL_BOUNDARY_ARBITRATION_MODE,
            "probe_revision": probe_payload.get("probe_revision"),
            "entries": copy.deepcopy([
                item for item in diagnostics
                if isinstance(item.get("entry"), int)
                and int(item["entry"]) - 1 in independently_safe
            ]),
            "private_replay_scope": "safe-subset-consolidation",
        }
        consolidated_eval = evaluate_backend_timing(
            selected_eval.backend,
            tuple(tuple(items) for items in consolidated_sets),
            report,
            consolidated_generation_diagnostics,
            arbiter_mode=selected_eval.arbiter_mode,
        )
        consolidated_selection = _neutral_arbitration_selection_with_revised_eval(
            selection, selected_eval, consolidated_eval
        )
        consolidated_backend_flip = (
            consolidated_selection.selected.backend != selected_eval.backend
        )
        if consolidated_backend_flip:
            consolidated_collateral = []
            consolidated_failed = sorted(index + 1 for index in independently_safe)
            consolidated_changed_fields: dict[int, tuple[str, ...]] = {}
        else:
            consolidated_shadow, _consolidated_shadow_state = (
                _neutral_arbitration_project_selection(report, consolidated_selection)
            )
            (
                consolidated_collateral,
                consolidated_failed,
                consolidated_changed_fields,
            ) = _neutral_arbitration_replay_gate(
                shadow,
                consolidated_shadow,
                independently_safe,
                outcome_map,
                tolerance_cs,
            )
        if consolidated_collateral or consolidated_failed:
            for item in diagnostics:
                if isinstance(item.get("entry"), int):
                    item["arbitration_disposition"] = "rejected-consolidated-replay"
            base_payload.update({
                "status": "FAIL_CLOSED_SAFE_SUBSET",
                "collateral_entries": consolidated_collateral,
                "failed_target_entries": consolidated_failed,
                "backend_flip": consolidated_backend_flip,
                "candidate_backend": consolidated_selection.selected.backend,
                "changed_final_semantic_fields": {
                    str(entry): list(fields)
                    for entry, fields in sorted(consolidated_changed_fields.items())
                },
                "entries": diagnostics,
                "initial_combined_replay": initial_combined_failure,
                "trigger_isolation": isolation_rows,
                "applied_trigger_entries": [],
                "rejected_trigger_entries": sorted(index + 1 for index in targeted_indexes),
            })
            base_payload["revision"] = _timing_content_digest(base_payload)
            return selection, probe_payload, base_payload

        targeted_indexes = independently_safe
        revised_eval = consolidated_eval
        revised_selection = consolidated_selection
        collateral = []
        failed_targets = []
    else:
        rejected_target_indexes = set()

    if revised_selection.selected.backend != selected_eval.backend:
        base_payload.update({
            "status": "FAIL_CLOSED_BACKEND_FLIP",
            "entries": diagnostics,
            "candidate_backend": revised_selection.selected.backend,
        })
        base_payload["revision"] = _timing_content_digest(base_payload)
        return selection, probe_payload, base_payload

    for item in diagnostics:
        index = int(item["entry"]) - 1
        if index not in targeted_indexes:
            item["arbitration_disposition"] = "rejected-private-replay"
            continue
        decision = revised_eval.state.decisions[index]
        audit = revised_eval.state.audits[index]
        item["arbitration_disposition"] = "applied"
        item["new_selected_candidate_id"] = decision.candidate.candidate_id
        item["new_selected_source"] = decision.candidate.source
        item["new_selected_centiseconds"] = decision.written_time.centiseconds
        item["new_timing_trusted"] = audit.timing_trusted

    applied_diagnostics = [
        item for item in diagnostics
        if isinstance(item.get("entry"), int)
        and int(item["entry"]) - 1 in targeted_indexes
    ]
    payload = {
        **base_payload,
        "status": "APPLIED",
        "central_replayed": True,
        "candidate_admission_count": sum(
            len(item["admitted_candidate_ids"]) for item in applied_diagnostics
        ),
        "falsified_candidate_count": sum(
            len(item["falsified_candidate_ids"]) for item in applied_diagnostics
        ),
        "entries": diagnostics,
        "old_evaluation_revision": selected_eval.evaluation_revision,
        "new_evaluation_revision": revised_eval.evaluation_revision,
        "old_selection_revision": selection.selection_revision,
        "new_selection_revision": revised_selection.selection_revision,
        "collateral_entries": [],
        "applied_trigger_entries": sorted(index + 1 for index in targeted_indexes),
        "rejected_trigger_entries": sorted(
            int(item["entry"])
            for item in diagnostics
            if isinstance(item.get("entry"), int)
            and int(item["entry"]) - 1 not in targeted_indexes
        ),
        "initial_combined_replay": initial_combined_failure,
        "trigger_isolation": isolation_rows,
    }
    payload["revision"] = _timing_content_digest(payload)
    seed = report.get(_RUNTIME_BACKEND_PROVENANCE_PROJECTION_SEED_KEY)
    if isinstance(seed, dict):
        report[_RUNTIME_BACKEND_PROVENANCE_PROJECTION_SEED_KEY] = (
            _update_projection_seed_for_arbitrated_selection(seed, revised_selection, payload)
        )
    return revised_selection, probe_payload, payload


def _local_whisper_cache_key(
    request: LocalWhisperRequest,
    capability: LocalWhisperCapability,
) -> str:
    return "local-whisper:" + _timing_content_digest({
        "request_revision": request.request_revision,
        "capability_revision": capability.capability_revision,
        "protocol_revision": capability.protocol_revision,
    })


def _shift_local_assignment_to_global(
    assignment: object,
    offset: float,
) -> dict[str, object] | None:
    if not isinstance(assignment, dict):
        return None
    shifted = copy.deepcopy(assignment)
    try:
        shifted["timestamp"] = round(float(assignment.get("timestamp")) + offset, 6)
    except (TypeError, ValueError):
        return None
    return shifted


def execute_local_whisper_request(
    request: LocalWhisperRequest,
    capability: LocalWhisperCapability,
    entries: list[LyricEntry],
    args: argparse.Namespace,
    *,
    cache: dict[str, tuple[str, object]] | None = None,
    runtime_stats: dict[str, int] | None = None,
    prepared: tuple[list[AsrSegment], dict[str, object]] | None = None,
    preparation_error: str | None = None,
) -> LocalWhisperOutcome:
    """Run one bounded Whisper.cpp -> WhisperX observation; never select a timestamp directly."""
    def finish(
        status: Literal["evidence", "invalid", "error"],
        reason: str,
        *,
        onset_time: float | None = None,
        score: float | None = None,
        evidence_revision: str | None = None,
        occurrence_binding: dict[str, object] | None = None,
        raw_transcript_revision: str | None = None,
        aligned_transcript_revision: str | None = None,
    ) -> LocalWhisperOutcome:
        base = {
            "entry_index": request.entry_index,
            "request_revision": request.request_revision,
            "status": status,
            "reason": reason,
            "onset_time": onset_time,
            "score": score,
            "evidence_revision": evidence_revision,
            "occurrence_binding": occurrence_binding,
            "raw_transcript_revision": raw_transcript_revision,
            "aligned_transcript_revision": aligned_transcript_revision,
        }
        return LocalWhisperOutcome(
            **base,
            outcome_revision=_timing_content_digest(base),
        )

    if capability.capability_revision != request.capability_revision:
        return finish("invalid", "capability-revision-mismatch")
    if request.audio_revision != capability.audio_sha256:
        return finish("invalid", "audio-revision-mismatch")
    if not 0 <= request.entry_index < len(entries):
        return finish("invalid", "entry-out-of-range")
    source_audio = Path(capability.audio_path)
    try:
        if _stable_file_sha256(source_audio) != capability.audio_sha256:
            return finish("invalid", "source-audio-changed")
    except (OSError, LrcError):
        return finish("invalid", "source-audio-unavailable")

    if cache is None:
        cache = {}
    if runtime_stats is None:
        runtime_stats = {}
    cache_key = _local_whisper_cache_key(request, capability)
    cached = cache.get(cache_key)
    if isinstance(cached, tuple) and len(cached) == 2 and isinstance(cached[1], LocalWhisperOutcome):
        runtime_stats["cache_hits"] = runtime_stats.get("cache_hits", 0) + 1
        return cached[1]
    runtime_stats["cache_misses"] = runtime_stats.get("cache_misses", 0) + 1

    try:
        if preparation_error is not None:
            raise LrcError(preparation_error)
        if prepared is None:
            wav_path = decode_temp_wav_window(
                source_audio, request.window_start, request.window_end
            )
            raw_segments = _run_whispercpp_wav(wav_path, args, suppress_nst=False)
            aligned_payload = run_whisperx_alignment(
                wav_path, asr_transcript(raw_segments), args, predecoded_wav=True
            )
        else:
            raw_segments, aligned_payload = prepared
        aligned_segments = whisperx_segments(aligned_payload)
        runtime_stats["helper_invocations"] = runtime_stats.get("helper_invocations", 0) + 1
    except (LrcError, OSError, ValueError, json.JSONDecodeError) as exc:
        outcome = finish("error", f"local-whisper-failed:{type(exc).__name__}")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome

    context_entries = [entries[index] for index in request.context_entry_indexes]
    local_duration = request.window_end - request.window_start
    try:
        local_times, local_report = match_whisper_segments(
            context_entries, aligned_segments, local_duration
        )
    except (LrcError, ValueError, IndexError) as exc:
        outcome = finish("error", f"local-match-failed:{type(exc).__name__}")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome
    assignments = local_report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(context_entries):
        outcome = finish("invalid", "local-assignment-shape-mismatch")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome

    full_assignments: list[object] = [None] * len(entries)
    target_local_index: int | None = None
    for local_index, global_index in enumerate(request.context_entry_indexes):
        shifted = _shift_local_assignment_to_global(assignments[local_index], request.window_start)
        if shifted is not None:
            full_assignments[global_index] = shifted
        if global_index == request.entry_index:
            target_local_index = local_index
    if target_local_index is None:
        outcome = finish("invalid", "target-context-mapping-missing")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome
    target_text = normalize_match_text(entry_sung_text(entries[request.entry_index]))
    target_assignment = full_assignments[request.entry_index]
    score = 0.0
    segment_number: int | None = None
    target_assignment_trusted = False
    if isinstance(target_assignment, dict):
        try:
            score = float(target_assignment.get("score", 0.0) or 0.0)
            segment_number = int(target_assignment.get("segment"))
        except (TypeError, ValueError):
            score = 0.0
            segment_number = None
        target_assignment_trusted = bool(
            score >= TRUSTED_ALIGNMENT_SCORE
            and not bool(target_assignment.get("borrowed"))
            and segment_number is not None
            and 1 <= segment_number <= len(aligned_segments)
        )

    occurrence_binding: dict[str, object] | None = None
    recovered_exact_match: dict[str, object] | None = None
    recovered_prefix_match: dict[str, object] | None = None
    recovered_phonetic_match: dict[str, object] | None = None
    if not target_assignment_trusted:
        # Do not promote a weak matcher score.  Recover only from real forced
        # WhisperX characters.  A full exact target is strongest; when the full
        # line is absent from WhisperX segmentation, a forced opening prefix may
        # recover the target only if that synthetic onset makes a full/sparse
        # immutable lyric context uniquely bind the occurrence.  No nearest-time
        # choice is allowed, and partial-prefix recovery never falls back to a
        # global-unique-only identity claim.
        direct_text_score = lyric_segment_score(target_text, target_text)

        def recovered_trials(
            matches: tuple[dict[str, object], ...],
            *,
            prefix_only: bool,
        ) -> list[tuple[dict[str, object], dict[str, object], list[object]]]:
            recovered: list[tuple[dict[str, object], dict[str, object], list[object]]] = []
            for match in matches:
                global_onset = float(match["onset_time"]) + request.window_start
                synthetic = {
                    "timestamp": round(global_onset, 6),
                    "score": direct_text_score,
                    "segment": int(match["start_segment_index"]) + 1,
                    "borrowed": False,
                    "direct_exact_char_stream": not prefix_only,
                    "direct_prefix_char_stream": prefix_only,
                    "char_match_revision": match["match_revision"],
                }
                trial_assignments = list(full_assignments)
                trial_assignments[request.entry_index] = synthetic
                binding = _entry_occurrence_binding(
                    entries, trial_assignments, request.entry_index, require_context=True
                )
                if binding is None and not prefix_only:
                    binding = _entry_occurrence_binding(
                        entries, trial_assignments, request.entry_index
                    )
                if binding is None:
                    continue
                if prefix_only and not _occurrence_binding_has_strong_context(binding):
                    continue
                recovered.append((match, binding, trial_assignments))
            return recovered

        exact_matches = _aligned_exact_target_matches(target_text, aligned_segments)
        recovered = recovered_trials(exact_matches, prefix_only=False)
        unique_recovered = {
            (str(item[0].get("match_revision")), str(item[1].get("binding_revision"))): item
            for item in recovered
        }
        if len(unique_recovered) == 1:
            recovered_exact_match, occurrence_binding, full_assignments = next(iter(unique_recovered.values()))
        elif len(unique_recovered) > 1:
            outcome = finish("invalid", "target-exact-char-occurrence-ambiguous")
            cache[cache_key] = (outcome.outcome_revision, outcome)
            return outcome
        else:
            prefix_matches = _aligned_target_prefix_matches(target_text, aligned_segments)
            recovered_prefix = recovered_trials(prefix_matches, prefix_only=True)
            unique_prefix = {
                (str(item[0].get("match_revision")), str(item[1].get("binding_revision"))): item
                for item in recovered_prefix
            }
            if len(unique_prefix) == 1:
                recovered_prefix_match, occurrence_binding, full_assignments = next(iter(unique_prefix.values()))
            elif len(unique_prefix) > 1:
                outcome = finish("invalid", "target-prefix-char-occurrence-ambiguous")
                cache[cache_key] = (outcome.outcome_revision, outcome)
                return outcome
            else:
                # Exact phonetic identity is a separate content proof.  It can
                # recover a weak text assignment caused by kana/kanji spelling
                # variation, but it does not itself claim a line onset.
                phonetic_matches = _aligned_exact_phonetic_target_matches(
                    entry_sung_text(entries[request.entry_index]), aligned_segments
                )
                phonetic_recovered: list[tuple[dict[str, object], dict[str, object], list[object]]] = []
                for match in phonetic_matches:
                    try:
                        start_segment_index = int(match["start_segment_index"])
                        local_reference_time = float(aligned_segments[start_segment_index].start)
                        phonetic_score = float(match["phonetic_score"])
                    except (KeyError, TypeError, ValueError, IndexError):
                        continue
                    if not math.isfinite(local_reference_time) or phonetic_score < TRUSTED_ALIGNMENT_SCORE:
                        continue
                    synthetic = {
                        "timestamp": round(local_reference_time + request.window_start, 6),
                        "score": round(phonetic_score, 6),
                        "segment": start_segment_index + 1,
                        "borrowed": False,
                        "direct_exact_phonetic_identity": True,
                        "phonetic_match_revision": match["match_revision"],
                    }
                    trial_assignments = list(full_assignments)
                    trial_assignments[request.entry_index] = synthetic
                    binding = _entry_occurrence_binding(
                        entries, trial_assignments, request.entry_index, require_context=True
                    )
                    if binding is None:
                        binding = _entry_occurrence_binding(
                            entries, trial_assignments, request.entry_index
                        )
                    if binding is None:
                        continue
                    phonetic_recovered.append((match, binding, trial_assignments))
                unique_phonetic = {
                    (str(item[0].get("match_revision")), str(item[1].get("binding_revision"))): item
                    for item in phonetic_recovered
                }
                if len(unique_phonetic) == 1:
                    recovered_phonetic_match, occurrence_binding, full_assignments = next(
                        iter(unique_phonetic.values())
                    )
                elif len(unique_phonetic) > 1:
                    outcome = finish("invalid", "target-phonetic-occurrence-ambiguous")
                    cache[cache_key] = (outcome.outcome_revision, outcome)
                    return outcome
                else:
                    outcome = finish(
                        "invalid",
                        "target-local-assignment-untrusted"
                        if not exact_matches and not prefix_matches and not phonetic_matches
                        else "target-independent-identity-occurrence-unproven",
                    )
                    cache[cache_key] = (outcome.outcome_revision, outcome)
                    return outcome

        target_assignment = full_assignments[request.entry_index]
        assert isinstance(target_assignment, dict)
        score = float(target_assignment["score"])
        segment_number = int(target_assignment["segment"])
        target_assignment_trusted = True

    if not target_assignment_trusted or segment_number is None:
        outcome = finish("invalid", "target-local-assignment-untrusted")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome

    # Prefer a full/sparse trusted sequence bracket.  Unique lyrics retain the
    # weaker global-unique fallback for content identity, but only context-bound
    # observations may participate in hypothesis falsification.
    if occurrence_binding is None:
        occurrence_binding = _entry_occurrence_binding(
            entries, full_assignments, request.entry_index, require_context=True
        )
        if occurrence_binding is None:
            occurrence_binding = _entry_occurrence_binding(
                entries, full_assignments, request.entry_index
            )
    if occurrence_binding is None:
        outcome = finish("invalid", "occurrence-binding-unproven")
        cache[cache_key] = (outcome.outcome_revision, outcome)
        return outcome

    # Timing evidence must be an actual forced-character onset.  Search the full
    # aligned char stream first so a lyric split across WhisperX segments remains
    # directly observable.  No interpolation or nearest-candidate choice is used.
    direct_match = recovered_exact_match or recovered_prefix_match or _select_unique_aligned_target_match(
        target_text, aligned_segments,
        occurrence_binding=occurrence_binding,
        entry_index=request.entry_index,
        preferred_segment_number=segment_number,
    )
    used_prefix_match = recovered_prefix_match is not None
    if direct_match is None:
        direct_match = _select_unique_aligned_target_prefix_match(
            target_text,
            aligned_segments,
            occurrence_binding=occurrence_binding,
            entry_index=request.entry_index,
            preferred_segment_number=segment_number,
        )
        used_prefix_match = direct_match is not None
    direct_local_onset = (
        float(direct_match["onset_time"]) if isinstance(direct_match, dict) else None
    )
    if direct_local_onset is None:
        aligned_segment = aligned_segments[segment_number - 1]
        direct_local_onset = segment_char_time(target_text, aligned_segment)
        if direct_local_onset is None:
            aligned_text = normalize_match_text(aligned_segment.text)
            if aligned_text.startswith(target_text) and target_text:
                direct_local_onset = aligned_segment.start
    onset_time = (
        float(direct_local_onset) + request.window_start
        if direct_local_onset is not None else None
    )
    if onset_time is not None and (
        not math.isfinite(onset_time)
        or onset_time < request.window_start - HOP_SECONDS
        or onset_time > request.window_end + HOP_SECONDS
    ):
        onset_time = None

    lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entries[request.entry_index])).encode("utf-8")
    ).hexdigest()
    raw_projection = [
        {
            "start": round(segment.start, 6),
            "end": round(segment.end, 6),
            "text_digest": _timing_content_digest(normalize_match_text(segment.text)),
        }
        for segment in raw_segments
    ]
    aligned_projection = [
        {
            "start": round(segment.start, 6),
            "end": round(segment.end, 6),
            "text_digest": _timing_content_digest(normalize_match_text(segment.text)),
            "first_char": round(first_forced_char_time(segment), 6),
        }
        for segment in aligned_segments
    ]
    raw_transcript_revision = _timing_content_digest(raw_projection)
    aligned_transcript_revision = _timing_content_digest(aligned_projection)
    evidence_payload = {
        "entry_index": request.entry_index,
        "lyric_sha256": lyric_sha,
        "onset_time": (round(onset_time, 6) if onset_time is not None else None),
        "score": round(score, 6),
        "occurrence_binding": occurrence_binding,
        "request_revision": request.request_revision,
        "capability_revision": capability.capability_revision,
        "audio_revision": capability.audio_sha256,
        "window_start": round(request.window_start, 6),
        "window_end": round(request.window_end, 6),
        "raw_transcript_revision": raw_transcript_revision,
        "aligned_transcript_revision": aligned_transcript_revision,
        "producer": "local-whisper-aligner",
    }
    evidence_revision = _timing_content_digest(evidence_payload)
    if recovered_exact_match is not None:
        outcome_reason = (
            "trusted-local-whisper-exact-char-recovery-and-onset"
            if onset_time is not None
            else "trusted-local-whisper-exact-char-recovery-occurrence-only"
        )
    elif recovered_phonetic_match is not None:
        outcome_reason = (
            "trusted-local-whisper-exact-phonetic-and-onset"
            if onset_time is not None
            else "trusted-local-whisper-exact-phonetic-occurrence-only"
        )
    elif recovered_prefix_match is not None and onset_time is not None:
        outcome_reason = "trusted-local-whisper-context-prefix-recovery-and-onset"
    elif used_prefix_match and onset_time is not None:
        outcome_reason = "trusted-local-whisper-context-prefix-onset"
    elif isinstance(occurrence_binding, dict) and occurrence_binding.get("mode") == "sparse-sequence-bracket":
        outcome_reason = (
            "trusted-local-whisper-sparse-occurrence-and-onset"
            if onset_time is not None
            else "trusted-local-whisper-sparse-occurrence-only"
        )
    else:
        outcome_reason = (
            "trusted-local-whisper-occurrence-and-onset"
            if onset_time is not None
            else "trusted-local-whisper-occurrence-only"
        )
    outcome = finish(
        "evidence",
        outcome_reason,
        onset_time=onset_time,
        score=score,
        evidence_revision=evidence_revision,
        occurrence_binding=occurrence_binding,
        raw_transcript_revision=raw_transcript_revision,
        aligned_transcript_revision=aligned_transcript_revision,
    )
    cache[cache_key] = (outcome.outcome_revision, outcome)
    return outcome



def _prepare_local_whisper_batch(
    work: list[tuple[str, int, LocalWhisperRequest]],
    capability: LocalWhisperCapability,
    args: argparse.Namespace,
) -> tuple[
    dict[str, tuple[list[AsrSegment], dict[str, object]]],
    dict[str, str],
]:
    """Prepare a frozen local-Whisper epoch with batched raw ASR and resident WhisperX.

    This function performs no Central mutation.  It only materializes the same
    per-request raw/aligned observations that execute_local_whisper_request would
    otherwise acquire one process at a time.
    """
    prepared: dict[str, tuple[list[AsrSegment], dict[str, object]]] = {}
    errors: dict[str, str] = {}
    if not work:
        return prepared, errors
    source_audio = Path(capability.audio_path)
    decoded: dict[str, Path] = {}

    def decode_one(item: tuple[str, int, LocalWhisperRequest]) -> tuple[str, Path | None, str | None]:
        key, _ordinal, request = item
        try:
            wav_path = decode_temp_wav_window(source_audio, request.window_start, request.window_end)
            return key, wav_path, None
        except (LrcError, OSError, ValueError) as exc:
            return key, None, f"decode:{type(exc).__name__}:{exc}"

    progress_log(f"local Whisper prepare: decode_windows={len(work)} workers={DEFAULT_EVIDENCE_WORKERS}")
    with concurrent.futures.ThreadPoolExecutor(
        max_workers=min(DEFAULT_EVIDENCE_WORKERS, len(work) or 1),
        thread_name_prefix="lrc-local-decode",
    ) as pool:
        for key, wav_path, error in pool.map(decode_one, work):
            if error is not None or wav_path is None:
                errors[key] = error or "decode:unknown"
            else:
                decoded[key] = wav_path

    raw_inputs = [(key, decoded[key]) for key, _ordinal, _request in work if key in decoded]
    # Raw whisper.cpp gets exclusive ownership of the heavy GPU phase; park the
    # resident WhisperX align model on CPU before entering that phase.
    _park_persistent_helper_mode("whisperx", reason="before-local-whispercpp-batch")
    raw_results, raw_errors = _run_whispercpp_wav_batch(raw_inputs, args, suppress_nst=False)
    errors.update(raw_errors)

    align_items = [
        (key, raw_results[key], decoded[key])
        for key, _ordinal, _request in work
        if key in raw_results and key in decoded and key not in errors
    ]
    progress_log(
        f"local Whisper align batch: requests={len(align_items)} "
        f"resident_workers={DEFAULT_EVIDENCE_WORKERS}"
    )

    def align_one(item: tuple[str, list[AsrSegment], Path]) -> tuple[str, dict[str, object] | None, str | None]:
        key, raw_segments, wav_path = item
        try:
            payload = run_whisperx_alignment(
                wav_path,
                asr_transcript(raw_segments),
                args,
                predecoded_wav=True,
            )
            return key, payload, None
        except (LrcError, OSError, ValueError, json.JSONDecodeError) as exc:
            return key, None, f"align:{type(exc).__name__}:{exc}"

    with concurrent.futures.ThreadPoolExecutor(
        max_workers=min(DEFAULT_EVIDENCE_WORKERS, len(align_items) or 1),
        thread_name_prefix="lrc-local-whisperx",
    ) as pool:
        for key, payload, error in pool.map(align_one, align_items):
            if error is not None or payload is None:
                errors[key] = error or "align:unknown"
            else:
                prepared[key] = (raw_results[key], payload)
    _park_persistent_helper_mode("whisperx", reason="local-whisperx-align-complete")
    progress_log(
        f"local Whisper prepare complete: prepared={len(prepared)} errors={len(errors)}"
    )
    return prepared, errors


def bind_runtime_local_whisper_evidence(
    report: dict[str, object],
    entries: list[LyricEntry],
    capability: LocalWhisperCapability | None,
    requests: tuple[LocalWhisperRequest, ...],
    outcomes: tuple[LocalWhisperOutcome, ...],
) -> None:
    if capability is None:
        return
    request_by_revision = {item.request_revision: item for item in requests}

    # Fixed-point recollection may legitimately stop requesting an entry after a
    # first-round local observation changes the candidate graph.  The observation
    # itself is immutable audio/lyric evidence and must not disappear merely
    # because the next planner round no longer needs to execute that request.
    # Seed from canonical-valid prior runtime evidence, then monotonically merge
    # any new observations.  Tampered/stale evidence fails the canonical accessor
    # and is therefore not retained.
    prior_runtime: dict[int, dict[str, object]] = {}
    previous_runtime = report.get(_RUNTIME_LOCAL_WHISPER_EVIDENCE_KEY)
    if isinstance(previous_runtime, dict):
        for entry_index in sorted(previous_runtime):
            if not isinstance(entry_index, int) or not 0 <= entry_index < len(entries):
                continue
            retained = runtime_local_whisper_evidence_for_entry(report, entries, entry_index)
            if retained is not None:
                prior_runtime[entry_index] = retained
    retained_before_merge = len(prior_runtime)

    observations: dict[int, list[dict[str, object]]] = {
        index: [dict(value)] for index, value in prior_runtime.items()
    }
    for outcome in outcomes:
        if outcome.status != "evidence" or outcome.evidence_revision is None:
            continue
        request = request_by_revision.get(outcome.request_revision)
        if request is None or outcome.score is None:
            continue
        lyric_sha = hashlib.sha256(
            normalize_match_text(entry_sung_text(entries[outcome.entry_index])).encode("utf-8")
        ).hexdigest()
        payload = {
            "entry_index": outcome.entry_index,
            "lyric_sha256": lyric_sha,
            "onset_time": (
                round(float(outcome.onset_time), 6)
                if outcome.onset_time is not None else None
            ),
            "score": round(float(outcome.score), 6),
            "occurrence_binding": outcome.occurrence_binding,
            "request_revision": request.request_revision,
            "capability_revision": capability.capability_revision,
            "audio_revision": capability.audio_sha256,
            "window_start": round(request.window_start, 6),
            "window_end": round(request.window_end, 6),
            "raw_transcript_revision": outcome.raw_transcript_revision,
            "aligned_transcript_revision": outcome.aligned_transcript_revision,
            "producer": "local-whisper-aligner",
        }
        evidence = {
            **payload,
            "evidence_revision": _timing_content_digest(payload),
        }
        observations.setdefault(outcome.entry_index, []).append(evidence)

    composite_count = 0
    # A narrow probe may contain the clean forced-character onset while a wider
    # probe contains the sequence context needed to bind a repeated lyric.  They
    # are complementary observations from the same immutable audio/lyric source,
    # not independent votes.  Merge only when both observations are revision-
    # bound, their target times agree inside the existing association tolerance,
    # and the onset lies inside the context bracket.  The timestamp is never
    # averaged or moved: it remains the original direct onset observation.
    for entry_index, items in list(observations.items()):
        onset_items = [item for item in items if item.get("onset_time") is not None]
        context_items = [
            item for item in items
            if _occurrence_binding_has_strong_context(item.get("occurrence_binding"))
        ]
        composites: list[dict[str, object]] = []
        for onset_item in onset_items:
            try:
                onset_time = float(onset_item.get("onset_time"))
                onset_score = float(onset_item.get("score"))
            except (TypeError, ValueError):
                continue
            for context_item in context_items:
                context_binding = context_item.get("occurrence_binding")
                if context_binding == onset_item.get("occurrence_binding"):
                    continue
                if (
                    onset_item.get("lyric_sha256") != context_item.get("lyric_sha256")
                    or onset_item.get("capability_revision") != context_item.get("capability_revision")
                    or onset_item.get("audio_revision") != context_item.get("audio_revision")
                ):
                    continue
                try:
                    context_time = float(context_binding.get("timestamp"))  # type: ignore[union-attr]
                    context_score = float(context_item.get("score"))
                except (TypeError, ValueError, AttributeError):
                    continue
                if (
                    not math.isfinite(onset_time)
                    or not math.isfinite(context_time)
                    or abs(onset_time - context_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
                ):
                    continue
                left_bound, right_bound = _occurrence_binding_time_bounds(
                    context_binding, entry_index
                )
                if left_bound is not None and onset_time <= left_bound - HOP_SECONDS:
                    continue
                if right_bound is not None and onset_time >= right_bound + HOP_SECONDS:
                    continue
                composite_payload = {
                    "entry_index": entry_index,
                    "lyric_sha256": onset_item.get("lyric_sha256"),
                    "onset_time": round(onset_time, 6),
                    "score": round(min(onset_score, context_score), 6),
                    "occurrence_binding": context_binding,
                    "request_revision": onset_item.get("request_revision"),
                    "capability_revision": onset_item.get("capability_revision"),
                    "audio_revision": onset_item.get("audio_revision"),
                    "window_start": round(float(onset_item.get("window_start")), 6),
                    "window_end": round(float(onset_item.get("window_end")), 6),
                    "raw_transcript_revision": onset_item.get("raw_transcript_revision"),
                    "aligned_transcript_revision": onset_item.get("aligned_transcript_revision"),
                    "producer": "local-whisper-aligner",
                    "composite_onset_evidence_revision": onset_item.get("evidence_revision"),
                    "composite_context_evidence_revision": context_item.get("evidence_revision"),
                }
                composite = {
                    **composite_payload,
                    "evidence_revision": _timing_content_digest(composite_payload),
                }
                composites.append(composite)
        if composites:
            unique = {item["evidence_revision"]: item for item in composites}
            observations[entry_index].extend(unique.values())
            composite_count += len(unique)

    def evidence_rank(item: dict[str, object]) -> tuple[int, int, float, str]:
        try:
            score = float(item.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            score = 0.0
        return (
            int(item.get("onset_time") is not None),
            int(_occurrence_binding_has_strong_context(item.get("occurrence_binding"))),
            score,
            str(item.get("evidence_revision") or ""),
        )

    runtime: dict[int, dict[str, object]] = {}
    for entry_index, items in observations.items():
        if not items:
            continue
        runtime[entry_index] = max(items, key=evidence_rank)

    report[_RUNTIME_LOCAL_WHISPER_EVIDENCE_KEY] = runtime
    report["local_whisper_evidence"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "protocol_revision": capability.protocol_revision,
        "candidate_count": len(runtime),
        "retained_from_prior_collect_count": retained_before_merge,
        "composite_evidence_count": composite_count,
        "entries": [index + 1 for index in sorted(runtime)],
    }


def runtime_local_whisper_evidence_for_entry(
    report: dict[str, object],
    entries: list[LyricEntry],
    entry_index: int,
) -> dict[str, object] | None:
    runtime = report.get(_RUNTIME_LOCAL_WHISPER_EVIDENCE_KEY)
    if not isinstance(runtime, dict) or not 0 <= entry_index < len(entries):
        return None
    evidence = runtime.get(entry_index)
    if not isinstance(evidence, dict):
        return None
    try:
        raw_onset_time = evidence.get("onset_time")
        onset_time = float(raw_onset_time) if raw_onset_time is not None else None
        score = float(evidence.get("score"))
        window_start = float(evidence.get("window_start"))
        window_end = float(evidence.get("window_end"))
    except (TypeError, ValueError):
        return None
    lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entries[entry_index])).encode("utf-8")
    ).hexdigest()
    payload = {
        "entry_index": entry_index,
        "lyric_sha256": lyric_sha,
        "onset_time": (round(onset_time, 6) if onset_time is not None else None),
        "score": round(score, 6),
        "occurrence_binding": evidence.get("occurrence_binding"),
        "request_revision": evidence.get("request_revision"),
        "capability_revision": evidence.get("capability_revision"),
        "audio_revision": evidence.get("audio_revision"),
        "window_start": round(window_start, 6),
        "window_end": round(window_end, 6),
        "raw_transcript_revision": evidence.get("raw_transcript_revision"),
        "aligned_transcript_revision": evidence.get("aligned_transcript_revision"),
        "producer": "local-whisper-aligner",
    }
    if (
        evidence.get("composite_onset_evidence_revision") is not None
        or evidence.get("composite_context_evidence_revision") is not None
    ):
        payload["composite_onset_evidence_revision"] = evidence.get(
            "composite_onset_evidence_revision"
        )
        payload["composite_context_evidence_revision"] = evidence.get(
            "composite_context_evidence_revision"
        )
    if (
        evidence.get("producer") != "local-whisper-aligner"
        or evidence.get("lyric_sha256") != lyric_sha
        or not isinstance(evidence.get("raw_transcript_revision"), str)
        or not evidence.get("raw_transcript_revision")
        or not isinstance(evidence.get("aligned_transcript_revision"), str)
        or not evidence.get("aligned_transcript_revision")
        or score < TRUSTED_ALIGNMENT_SCORE
        or (
            onset_time is not None
            and (
                not math.isfinite(onset_time)
                or not window_start - HOP_SECONDS <= onset_time <= window_end + HOP_SECONDS
            )
        )
        or not _runtime_occurrence_binding_is_valid(
            entries, entry_index, evidence.get("occurrence_binding")
        )
        or evidence.get("evidence_revision") != _timing_content_digest(payload)
    ):
        return None
    return dict(evidence)



def _local_whisper_vocal_fusion_candidate(
    *,
    entry_index: int,
    entry: LyricEntry,
    local_evidence: dict[str, object] | None,
    vocal_onset_features: AudioFeatures | None,
    audio_revision: str | None,
    occurrence_evidence: CandidateOccurrenceEvidence | None = None,
) -> TimingCandidate | None:
    """Fuse context-bound Local Whisper identity with an independent vocal onset.

    Local Whisper occurrence-only evidence already proves *which lyric row* is
    present, but intentionally does not manufacture an onset when exact forced
    characters are absent.  The existing isolated-vocal detector is a distinct
    acoustic producer.  When a production-grade vocal onset lies near the
    context-bound Local Whisper semantic time, their fusion may create a real
    boundary-grade candidate.  Global-unique-only identity is excluded here so a
    repeated lyric cannot acquire timing authority without contextual binding.
    """
    if (
        not isinstance(local_evidence, dict)
        or local_evidence.get("onset_time") is not None
        or vocal_onset_features is None
        or not audio_revision
    ):
        return None
    binding = local_evidence.get("occurrence_binding")
    if not _occurrence_binding_has_strong_context(binding):
        return None
    try:
        identity_time = float(binding.get("timestamp"))  # type: ignore[union-attr]
        identity_score = float(local_evidence.get("score"))
    except (TypeError, ValueError, AttributeError):
        return None
    if not math.isfinite(identity_time) or identity_score < TRUSTED_ALIGNMENT_SCORE:
        return None
    peak = _strong_vocal_onset_near(vocal_onset_features, identity_time)
    if peak is None:
        return None
    peak_time, peak_strength, peak_prominence = peak
    artifact = {
        "producer": "local-whisper-vocal-fusion",
        "local_whisper_evidence_revision": local_evidence.get("evidence_revision"),
        "occurrence_binding_revision": (
            binding.get("binding_revision") if isinstance(binding, dict) else None
        ),
        "local_identity_time": round(identity_time, 6),
        "local_identity_score": round(identity_score, 6),
        "vocal_onset_time": round(peak_time, 6),
        "vocal_onset_strength": round(peak_strength, 8),
        "vocal_onset_prominence": round(peak_prominence, 8),
        "audio_sha256": audio_revision,
        "feature_revision": "vocal-consonant-onset-v1",
        "runtime_only": True,
    }
    return make_timing_candidate(
        entry_index=entry_index,
        entry_text=entry_sung_text(entry),
        source="local-whisper-vocal-independent-fusion",
        raw_time=peak_time,
        spans=(),
        confidence=min(identity_score, peak_strength),
        identity_support="supported",
        sequence_support="supported",
        acoustic_support="supported",
        direct_onset_support="supported",
        acoustic_strength=peak_strength,
        acoustic_onset_time=peak_time,
        acoustic_source_artifact=artifact,
        acoustic_evidence_producer="local-whisper-vocal-fusion",
        acoustic_evidence_kind="vocal-onset",
        acoustic_evidence_independent=True,
        direct_onset_time=peak_time,
        direct_onset_source_artifact=artifact,
        direct_onset_evidence_producer="local-whisper-vocal-fusion",
        direct_onset_evidence_kind="cross-backend-onset",
        direct_onset_evidence_independent=True,
        occurrence_evidence=occurrence_evidence,
        independent_content_identity=True,
        current=False,
        source_artifact=artifact,
    )


def _augment_candidates_with_local_whisper_vocal_consensus(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    report: dict[str, object],
    entries: list[LyricEntry],
    vocal_onset_features: AudioFeatures | None,
    audio_revision: str | None,
) -> tuple[tuple[TimingCandidate, ...], ...]:
    """Add context-bound Local Whisper/vocal observations and CTC composites.

    This is an evidence-additive producer.  Local Whisper proves occurrence
    identity; the isolated-vocal detector proves a real acoustic onset; a CTC
    parent may contribute token geometry.  No timestamp is averaged: the
    standalone candidate uses the observed vocal onset, while the composite
    keeps the CTC parent's raw time and binds the same observed onset as direct
    onset evidence.  Whisper-derived parents are excluded so one model lineage
    can never count twice.
    """
    if vocal_onset_features is None or not audio_revision:
        return candidate_sets
    augmented = [list(items) for items in candidate_sets]
    for index, parents in enumerate(candidate_sets):
        evidence = runtime_local_whisper_evidence_for_entry(report, entries, index)
        local_vocal = _local_whisper_vocal_fusion_candidate(
            entry_index=index,
            entry=entries[index],
            local_evidence=evidence,
            vocal_onset_features=vocal_onset_features,
            audio_revision=audio_revision,
            occurrence_evidence=(
                candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="local-whisper-vocal-fusion",
                    occurrence_binding=(
                        evidence.get("occurrence_binding")
                        if isinstance(evidence, dict) else None
                    ),
                    upstream_evidence_revision=(
                        evidence.get("evidence_revision")
                        if isinstance(evidence, dict) else None
                    ),
                )
                if isinstance(evidence, dict) else None
            ),
        )
        if local_vocal is None:
            continue
        augmented[index].append(local_vocal)
        onset_evidence = local_vocal.direct_onset_evidence
        if onset_evidence is None:
            continue
        for parent in parents:
            families = _candidate_support_families(parent)
            if "ctc" not in families or "whisper-family" in families:
                continue
            if (
                parent.identity_support != "supported"
                or parent.sequence_support != "supported"
                or parent.right_edge_pileup
                or parent.window_truncated
                or abs(parent.written_time.seconds - local_vocal.written_time.seconds)
                > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
            ):
                continue
            artifact = {
                "producer": "local-whisper-vocal-fusion",
                "local_vocal_candidate_id": local_vocal.candidate_id,
                "local_vocal_generation_revision": local_vocal.generation_revision,
                "local_whisper_evidence_revision": (
                    evidence.get("evidence_revision") if isinstance(evidence, dict) else None
                ),
                "parent_candidate_id": parent.candidate_id,
                "parent_generation_revision": parent.generation_revision,
                "parent_source": parent.source,
                "parent_time": round(parent.raw_time, 6),
                "vocal_onset_time": round(onset_evidence.onset_time, 6),
                "audio_sha256": audio_revision,
                "runtime_only": True,
            }
            augmented[index].append(make_timing_candidate(
                entry_index=index,
                entry_text=entry_sung_text(entries[index]),
                source="ctc-local-whisper-vocal-independent-consensus",
                raw_time=parent.raw_time,
                spans=parent.spans,
                confidence=min(parent.confidence, local_vocal.confidence),
                identity_support="supported",
                sequence_support="supported",
                acoustic_support="supported",
                direct_onset_support="supported",
                acoustic_strength=(
                    local_vocal.acoustic_evidence.strength
                    if local_vocal.acoustic_evidence is not None else None
                ),
                acoustic_onset_time=onset_evidence.onset_time,
                acoustic_source_artifact=artifact,
                acoustic_evidence_producer="local-whisper-vocal-fusion",
                acoustic_evidence_kind="vocal-onset",
                acoustic_evidence_independent=True,
                direct_onset_time=onset_evidence.onset_time,
                direct_onset_source_artifact=artifact,
                direct_onset_evidence_producer="local-whisper-vocal-fusion",
                direct_onset_evidence_kind="cross-backend-onset",
                direct_onset_evidence_independent=True,
                occurrence_evidence=candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="local-whisper-vocal-fusion",
                    occurrence_binding=evidence.get("occurrence_binding"),
                    upstream_evidence_revision=evidence.get("evidence_revision"),
                ),
                independent_content_identity=True,
                current=False,
                prefix_scope=parent.prefix_scope,
                right_edge_pileup=False,
                window_truncated=False,
                source_artifact=artifact,
            ))
    return tuple(
        tuple({item.candidate_id: item for item in items}[key] for key in sorted(
            {item.candidate_id: item for item in items}
        ))
        for items in augmented
    )


def _augment_candidates_with_local_whisper_consensus(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    report: dict[str, object],
    entries: list[LyricEntry],
) -> tuple[tuple[TimingCandidate, ...], ...]:
    """Fuse local Whisper onset/identity into existing candidates without moving time."""
    augmented = [list(items) for items in candidate_sets]
    for index, parents in enumerate(candidate_sets):
        evidence = runtime_local_whisper_evidence_for_entry(report, entries, index)
        if evidence is None:
            continue
        raw_onset_time = evidence.get("onset_time")
        if raw_onset_time is None:
            continue
        onset_time = float(raw_onset_time)
        evidence_score = float(evidence["score"])
        for parent in parents:
            families = _candidate_support_families(parent)
            # Local Whisper is one Whisper-family observation. Never use a
            # Whisper-derived parent to manufacture a second independent vote.
            if "whisper-family" in families:
                continue
            if (
                parent.identity_support != "supported"
                or parent.sequence_support != "supported"
                or parent.right_edge_pileup
                or parent.window_truncated
                or abs(parent.written_time.seconds - onset_time) > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
            ):
                continue
            if "ctc" in families:
                source = "ctc-local-whisper-independent-consensus"
            elif "recurrence" in families:
                source = "recurrence-local-whisper-independent-consensus"
            else:
                source = "local-whisper-independent-consensus"
            artifact = {
                "producer": "local-whisper-aligner",
                "local_whisper_evidence_revision": evidence["evidence_revision"],
                "parent_candidate_id": parent.candidate_id,
                "parent_generation_revision": parent.generation_revision,
                "parent_source": parent.source,
                "parent_time": round(parent.raw_time, 6),
                "onset_time": round(onset_time, 6),
                "runtime_only": True,
            }
            augmented[index].append(make_timing_candidate(
                entry_index=index,
                entry_text=entry_sung_text(entries[index]),
                source=source,
                raw_time=parent.raw_time,
                spans=parent.spans,
                confidence=min(parent.confidence, evidence_score),
                identity_support="supported",
                sequence_support="supported",
                acoustic_support="unavailable",
                direct_onset_support="supported",
                direct_onset_time=onset_time,
                direct_onset_source_artifact=artifact,
                direct_onset_evidence_producer="local-whisper-aligner",
                direct_onset_evidence_kind="cross-backend-onset",
                direct_onset_evidence_independent=True,
                occurrence_evidence=candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="local-whisper-aligner",
                    occurrence_binding=evidence.get("occurrence_binding"),
                    upstream_evidence_revision=evidence.get("evidence_revision"),
                ),
                independent_content_identity=True,
                current=False,
                prefix_scope=parent.prefix_scope,
                right_edge_pileup=False,
                window_truncated=False,
                source_artifact=artifact,
            ))
    return tuple(
        tuple({item.candidate_id: item for item in items}[key] for key in sorted(
            {item.candidate_id: item for item in items}
        ))
        for items in augmented
    )




def _apply_context_conditioned_whisper_hypothesis_arbitration(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    report: dict[str, object],
    entries: list[LyricEntry],
) -> tuple[tuple[tuple[TimingCandidate, ...], ...], tuple[dict[str, object], ...]]:
    """Invalidate weaker whole-song Whisper hypotheses with stronger bound context.

    This is *not* majority voting.  A global raw-ASR occurrence may be removed only
    when all of the following are provenance-bound facts:

    1. bounded local Whisper re-identifies the lyric inside a trusted full or
       sparse left/target/right sequence bracket and exposes either a direct aligned
       onset or an exact revision-bound independent vocal onset;
    2. an independent CTC+local-Whisper composite converges at that onset inside the
       existing 0.18 s tolerance;
    3. the global raw occurrence is only ``global-unique`` (no sequence bracket), is
       distant from the bounded onset, and is not independently corroborated by CTC
       or recurrence near its own time;
    4. the bounded observation is at least as confident as the raw identity row.

    The losing timestamp is not overwritten.  Its candidate is excluded from the
    central valid graph with an explicit diagnostic that binds both evidence
    revisions.  If any premise is absent, nothing is invalidated and fail-closed
    review behavior is preserved.
    """
    revised: list[tuple[TimingCandidate, ...]] = []
    diagnostics: list[dict[str, object]] = []
    tolerance = RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS

    for index, candidates in enumerate(candidate_sets):
        local = runtime_local_whisper_evidence_for_entry(report, entries, index)
        raw_identity = runtime_raw_content_identity_for_entry(report, entries, index)
        if not isinstance(local, dict) or not isinstance(raw_identity, dict):
            revised.append(candidates)
            continue
        local_binding = local.get("occurrence_binding")
        raw_binding = raw_identity.get("occurrence_binding")
        if not (
            _occurrence_binding_has_strong_context(local_binding)
            and isinstance(raw_binding, dict)
            and raw_binding.get("mode") == "global-unique"
        ):
            revised.append(candidates)
            continue
        try:
            local_score = float(local.get("score"))
            raw_time = float(raw_identity.get("raw_time"))
            raw_score = float(raw_identity.get("raw_score"))
        except (TypeError, ValueError):
            revised.append(candidates)
            continue

        # Independent corroboration must already exist as an actual composite;
        # raw CTC proximity or generic acoustic activity is not inferred here.
        raw_local_onset = local.get("onset_time")
        if raw_local_onset is not None:
            try:
                local_onset = float(raw_local_onset)
            except (TypeError, ValueError):
                revised.append(candidates)
                continue
            local_cluster = [
                candidate for candidate in candidates
                if candidate.source == "ctc-local-whisper-independent-consensus"
                and abs(candidate.written_time.seconds - local_onset) <= tolerance
                and candidate.identity_support == "supported"
                and candidate.sequence_support == "supported"
                and candidate_has_bound_direct_onset_evidence(candidate)
            ]
        else:
            # Occurrence-only Local Whisper can already have a boundary-grade
            # onset in the candidate graph via the independent vocal-fusion
            # producer.  Consume only an exact revision/binding match; never
            # synthesize an onset from the occurrence timestamp itself.
            local_revision = local.get("evidence_revision")
            binding_revision = (
                local_binding.get("binding_revision")
                if isinstance(local_binding, dict) else None
            )
            bound_vocal: list[tuple[TimingCandidate, float]] = []
            for candidate in candidates:
                if (
                    candidate.source != "ctc-local-whisper-vocal-independent-consensus"
                    or candidate.identity_support != "supported"
                    or candidate.sequence_support != "supported"
                    or not candidate_has_boundary_grade_direct_onset_evidence(candidate, entries)
                ):
                    continue
                occurrence = candidate.occurrence_evidence
                onset_evidence = candidate.direct_onset_evidence
                if (
                    occurrence is None
                    or onset_evidence is None
                    or occurrence.producer != "local-whisper-vocal-fusion"
                    or occurrence.upstream_evidence_revision != local_revision
                    or occurrence.binding_revision != binding_revision
                    or onset_evidence.producer != "local-whisper-vocal-fusion"
                ):
                    continue
                onset = float(onset_evidence.onset_time)
                if (
                    math.isfinite(onset)
                    and abs(candidate.written_time.seconds - onset) <= tolerance
                ):
                    bound_vocal.append((candidate, onset))
            canonical_onsets = {round(onset, 6) for _, onset in bound_vocal}
            if len(canonical_onsets) != 1:
                revised.append(candidates)
                continue
            local_onset = next(iter(canonical_onsets))
            local_cluster = [candidate for candidate, _ in bound_vocal]

        if (
            not all(math.isfinite(value) for value in (local_onset, local_score, raw_time, raw_score))
            or abs(local_onset - raw_time) <= tolerance
            or local_score < raw_score
            or not local_cluster
        ):
            revised.append(candidates)
            continue

        # If CTC or recurrence independently supports the raw cluster, it is a
        # genuine competing hypothesis and must remain review-required.
        raw_independent_support = any(
            abs(candidate.written_time.seconds - raw_time) <= tolerance
            and (
                "ctc" in _candidate_support_families(candidate)
                or "recurrence" in _candidate_support_families(candidate)
            )
            and "whisper-family" not in _candidate_support_families(candidate)
            for candidate in candidates
        )
        if raw_independent_support:
            revised.append(candidates)
            continue

        falsified = [
            candidate for candidate in candidates
            if "whisper-family" in _candidate_support_families(candidate)
            and "ctc" not in _candidate_support_families(candidate)
            and "recurrence" not in _candidate_support_families(candidate)
            and abs(candidate.written_time.seconds - raw_time) <= tolerance
            and abs(candidate.written_time.seconds - local_onset) > tolerance
        ]
        if not falsified:
            revised.append(candidates)
            continue
        falsified_ids = {candidate.candidate_id for candidate in falsified}
        survivors = tuple(candidate for candidate in candidates if candidate.candidate_id not in falsified_ids)
        if not survivors:
            revised.append(candidates)
            continue
        revised.append(survivors)
        diagnostics.append({
            "entry": index + 1,
            "reason": "bounded-sequence-context-falsifies-weaker-global-whisper-occurrence",
            "local_whisper_evidence_revision": local.get("evidence_revision"),
            "raw_content_identity_revision": raw_identity.get("evidence_revision"),
            "local_onset": round(local_onset, 6),
            "raw_identity_time": round(raw_time, 6),
            "local_score": round(local_score, 6),
            "raw_score": round(raw_score, 6),
            "context_binding_revision": local_binding.get("binding_revision"),
            "raw_binding_revision": raw_binding.get("binding_revision"),
            "corroborating_candidate_ids": sorted(candidate.candidate_id for candidate in local_cluster),
            "falsified_candidate_ids": sorted(falsified_ids),
            "max_delta_seconds": tolerance,
            "authority": "candidate-exclusion-only-central-still-commits",
        })

    return tuple(revised), tuple(diagnostics)


def _joint_previous_tail_evidence(
    request: CrossLineRetryRequest,
    capability: BoundedRetryCapability,
    rows: list[object],
    parsed_rows: list[tuple[TimingTokenSpan, ...]],
    previous_probe: TimingCandidate | None,
    previous_pair_tail: TailRegionEvidence | None,
    target_probe: TimingCandidate,
    target_regions: CandidateRegionEvidence,
    output_revision: str,
    pair_gap_seconds: float | None,
    edge: dict[str, object],
    touches_edge: bool,
    touches_left_edge: bool,
    strong_joint_boundary: bool,
) -> IndependentTailEvidence | None:
    """Retain strong joint previous-row tail evidence in the existing sidecar.

    The helper's previous probe is an immutable known-lyric observation.  It is
    independent of the selected predecessor timestamp; request planning may use
    selected timestamps to choose a bounded window, but this evidence revision is
    built only from helper output, immutable lyric/transcript binding, audio and
    the probe's terminal geometry.  Weak/edge/truncated pairs fail closed.
    """
    if (
        not strong_joint_boundary
        or previous_probe is None
        or previous_pair_tail is None
        or previous_pair_tail.validity != "valid"
        or previous_pair_tail.reliable_tail_start is None
        or previous_pair_tail.reliable_tail_end is None
        or not math.isfinite(float(previous_pair_tail.reliable_tail_start))
        or not math.isfinite(float(previous_pair_tail.reliable_tail_end))
        or not math.isfinite(float(pair_gap_seconds or 0.0))
        or touches_edge
        or touches_left_edge
        or bool(edge.get("right_edge_pileup"))
        or previous_probe.right_edge_pileup
        or previous_probe.window_truncated
    ):
        return None
    previous_local_index = dict(request.row_mapping).get(request.entry_index - 1)
    if (
        previous_local_index is None
        or not 0 <= previous_local_index < len(parsed_rows)
        or previous_local_index >= len(rows)
        or not isinstance(rows[previous_local_index], dict)
    ):
        return None
    previous_spans = parsed_rows[previous_local_index]
    previous_span_payload = [
        [round(span.start, 6), round(span.end, 6), round(span.score, 8), span.token]
        for span in previous_spans
    ]
    target_span_payload = [
        [round(span.start, 6), round(span.end, 6), round(span.score, 8), span.token]
        for span in target_probe.spans
    ]
    evidence_payload = {
        "schema": "joint-previous-tail-v1",
        "producer": "joint-ctc-boundary-previous-tail",
        "entry_index": request.entry_index - 1,
        "context_entry_indexes": list(request.context_entry_indexes),
        "row_mapping": [list(pair) for pair in request.row_mapping],
        "row_mapping_revision": request.row_mapping_revision,
        "previous_lyric_digest": (
            request.transcript_digests[previous_local_index]
            if previous_local_index < len(request.transcript_digests)
            else None
        ),
        "transcript_digests": list(request.transcript_digests),
        "transcript_digest": request.transcript_digest,
        "capability_revision": capability.capability_revision,
        "helper_sha256": capability.helper_sha256,
        "helper_protocol_revision": capability.helper_protocol_revision,
        "alignment_audio_revision": request.alignment_audio_revision,
        "retry_epoch_revision": request.retry_epoch_revision,
        "request_revision": request.request_revision,
        "output_revision": output_revision,
        "previous_probe_candidate_id": previous_probe.candidate_id,
        "previous_probe_generation_revision": previous_probe.generation_revision,
        "previous_probe_region_revision": analyze_candidate_regions(previous_probe).region_revision,
        "previous_spans_revision": _timing_content_digest(previous_span_payload),
        "previous_spans": previous_span_payload,
        "target_spans_revision": _timing_content_digest(target_span_payload),
        "target_region_revision": target_regions.region_revision,
        "target_onset_proof_end": target_regions.onset_proof_end,
        "target_temporal_coherence": target_regions.temporal_coherence,
        "pair_gap_seconds": round(float(pair_gap_seconds), 6),
        "previous_pair_tail_revision": previous_pair_tail.tail_evidence_revision,
        "tail": {
            "validity": previous_pair_tail.validity,
            "start": round(float(previous_pair_tail.reliable_tail_start), 6),
            "end": round(float(previous_pair_tail.reliable_tail_end), 6),
            "uncertainty": round(float(previous_pair_tail.uncertainty_seconds or 0.0), 6),
            "confidence": round(float(previous_pair_tail.confidence or 0.0), 6),
            "terminal_span_indexes": list(previous_pair_tail.terminal_span_indexes),
            "local_gap_references": [
                round(float(value), 6)
                for value in previous_pair_tail.local_gap_references
            ],
        },
        "previous_touches_left_edge": bool(touches_left_edge),
        "previous_right_edge_pileup": bool(previous_probe.right_edge_pileup),
        "previous_window_truncated": bool(previous_probe.window_truncated),
        "target_right_edge_pileup": bool(edge.get("right_edge_pileup")),
        "target_touches_edge": bool(touches_edge),
    }
    entry_index = request.entry_index - 1
    tail_start = float(previous_pair_tail.reliable_tail_start)
    tail_end = float(previous_pair_tail.reliable_tail_end)
    uncertainty_seconds = max(0.0, float(previous_pair_tail.uncertainty_seconds or 0.0))
    confidence = _finite_unit_confidence(previous_pair_tail.confidence or 0.0)
    producer = "joint-ctc-boundary-previous-tail"
    provenance = _make_tail_provenance(
        entry_index=entry_index,
        tail_start=tail_start,
        tail_end=tail_end,
        uncertainty_seconds=uncertainty_seconds,
        confidence=confidence,
        producer=producer,
        backend_lineage=capability.backend_lineage,
        model_identity=capability.model_identity,
        helper_revision=_tail_helper_revision(
            capability.helper_sha256,
            capability.helper_protocol_revision,
        ),
        capability_revision=capability.capability_revision,
        audio_revision=request.alignment_audio_revision,
        transcript_revision=request.transcript_digest,
        row_revision=request.row_mapping_revision,
    )
    source_revision = provenance.observation_revision if provenance is not None else _timing_content_digest(evidence_payload)
    return IndependentTailEvidence(
        entry_index=entry_index,
        tail_start=tail_start,
        tail_end=tail_end,
        uncertainty_seconds=uncertainty_seconds,
        confidence=confidence,
        producer=producer,
        source_revision=source_revision,
        provenance=provenance,
    )


def parse_crossline_retry_output(
    request: CrossLineRetryRequest,
    capability: BoundedRetryCapability,
    entries: list[LyricEntry],
    payload: object,
) -> CrossLineRetryOutcome:
    def invalid(reason: str) -> CrossLineRetryOutcome:
        base = {
            "retry_epoch_revision": request.retry_epoch_revision,
            "request_revision": request.request_revision,
            "entry_index": request.entry_index,
            "status": "invalid",
            "reason": reason,
            "candidate": None,
            "output_revision": None,
        }
        return CrossLineRetryOutcome(**base, outcome_revision=_timing_content_digest(base))

    if not isinstance(payload, dict):
        return invalid("helper-output-not-object")
    try:
        output_revision = _canonical_json_digest(payload)
    except LrcError:
        return invalid("helper-output-nonfinite-or-noncanonical")
    rows = payload.get("entries")
    if not isinstance(rows, list) or len(rows) != len(request.context_entry_indexes):
        return invalid("helper-row-count-mismatch")
    try:
        payload_window_start = float(payload.get("window_start", -1.0))
        payload_window_end = float(payload.get("window_end", -1.0))
    except (TypeError, ValueError):
        return invalid("helper-window-malformed")
    if round(payload_window_start, 3) != round(request.window_start, 3):
        return invalid("helper-window-start-mismatch")
    if round(payload_window_end, 3) != round(request.window_end, 3):
        return invalid("helper-window-end-mismatch")
    parsed_rows: list[tuple[TimingTokenSpan, ...]] = []
    previous_end = request.window_start
    for local_index, (global_index, row) in enumerate(zip(request.context_entry_indexes, rows)):
        if not isinstance(row, dict) or row.get("entry") != local_index + 1:
            return invalid("helper-row-mapping-mismatch")
        if row.get("text") != entry_sung_text(entries[global_index]):
            return invalid("helper-transcript-mismatch")
        raw_spans = row.get("token_spans")
        romaji = row.get("romaji")
        tokens = row.get("tokens")
        if (
            not isinstance(raw_spans, list)
            or not raw_spans
            or not isinstance(romaji, str)
            or not isinstance(tokens, int)
            or tokens != len(raw_spans)
            or len(romaji) != len(raw_spans)
        ):
            return invalid("helper-row-incomplete")
        spans: list[TimingTokenSpan] = []
        for token_index, raw_span in enumerate(raw_spans):
            if not isinstance(raw_span, dict):
                return invalid("helper-span-malformed")
            try:
                start = float(raw_span.get("start"))
                end = float(raw_span.get("end"))
                score = float(raw_span.get("score"))
            except (TypeError, ValueError):
                return invalid("helper-span-malformed")
            if (
                not all(math.isfinite(value) for value in (start, end, score))
                or start > end
                or start < request.window_start - HOP_SECONDS
                or end > request.window_end + HOP_SECONDS
                or start < previous_end
            ):
                return invalid("helper-span-nonmonotonic-or-outside-window")
            token = str(raw_span.get("char") or "")
            if token != romaji[token_index]:
                return invalid("helper-token-sequence-mismatch")
            spans.append(TimingTokenSpan(start, end, score, token))
            previous_end = end
        try:
            row_start = float(row.get("start"))
            row_end = float(row.get("end"))
        except (TypeError, ValueError):
            return invalid("helper-row-boundary-missing")
        if (
            not math.isfinite(row_start)
            or not math.isfinite(row_end)
            or row_start != spans[0].start
            or row_end != spans[-1].end
        ):
            return invalid("helper-row-boundary-mismatch")
        parsed_rows.append(tuple(spans))
    mapping = dict(request.row_mapping)
    target_local_index = mapping.get(request.entry_index)
    if target_local_index is None or not 0 <= target_local_index < len(parsed_rows):
        return invalid("target-row-mapping-missing")
    target_row = rows[target_local_index]
    assert isinstance(target_row, dict)
    target_spans = parsed_rows[target_local_index]
    joint_pair = bool(
        len(request.context_entry_indexes) == 2
        and request.context_entry_indexes == (request.entry_index - 1, request.entry_index)
        and target_local_index == 1
    )
    local_window = {"end": request.window_end}
    edge = ctc_right_edge_pileup_evidence({
        "ctc_local_window": local_window,
        "ctc_token_spans": [
            {"start": span.start, "end": span.end, "score": span.score}
            for span in target_spans
        ],
    })
    edge_margin = request.window_end - target_spans[-1].end
    touches_edge = -0.03 <= edge_margin <= 0.10
    touches_left_edge = False
    previous_probe: TimingCandidate | None = None
    previous_pair_tail: TailRegionEvidence | None = None
    pair_gap_seconds: float | None = None
    if joint_pair:
        previous_local_index = dict(request.row_mapping).get(request.entry_index - 1)
        if previous_local_index is None or not 0 <= previous_local_index < len(parsed_rows):
            return invalid("joint-previous-row-mapping-missing")
        previous_row = rows[previous_local_index]
        assert isinstance(previous_row, dict)
        previous_spans = parsed_rows[previous_local_index]
        touches_left_edge = (
            -0.03 <= previous_spans[0].start - request.window_start <= 0.10
        )
        try:
            previous_confidence = float(previous_row.get("ctc_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            return invalid("helper-previous-score-malformed")
        if not math.isfinite(previous_confidence):
            return invalid("helper-previous-score-nonfinite")
        previous_probe = make_timing_candidate(
            entry_index=request.entry_index - 1,
            entry_text=entry_sung_text(entries[request.entry_index - 1]),
            source="ctc-joint-boundary-previous-probe",
            raw_time=previous_spans[0].start,
            spans=previous_spans,
            confidence=previous_confidence,
            identity_support="supported",
            sequence_support="supported",
            current=False,
            source_artifact={
                "output_revision": output_revision,
                "row_mapping_revision": request.row_mapping_revision,
                "joint_boundary_probe": True,
            },
        )
        previous_pair_tail = derive_reliable_tail(previous_probe)
        pair_gap_seconds = target_spans[0].start - previous_spans[-1].end
    try:
        confidence = float(target_row.get("ctc_score", 0.0) or 0.0)
    except (TypeError, ValueError):
        return invalid("helper-target-score-malformed")
    if not math.isfinite(confidence):
        return invalid("helper-target-score-nonfinite")

    probe = make_timing_candidate(
        entry_index=request.entry_index,
        entry_text=entry_sung_text(entries[request.entry_index]),
        source="ctc-joint-boundary-current-probe" if joint_pair else "ctc-opening-local-retry-probe",
        raw_time=target_spans[0].start,
        spans=target_spans,
        confidence=confidence,
        identity_support="supported",
        sequence_support="supported",
        current=False,
        prefix_scope=False,
        right_edge_pileup=bool(edge.get("right_edge_pileup")),
        window_truncated=bool(touches_edge or touches_left_edge),
        source_artifact={"probe": True, "output_revision": output_revision},
    )
    target_regions = analyze_candidate_regions(probe)
    strong_joint_boundary = bool(
        joint_pair
        and previous_pair_tail is not None
        and previous_pair_tail.validity == "valid"
        and previous_pair_tail.reliable_tail_end is not None
        and previous_pair_tail.reliable_tail_end <= target_spans[0].start
        and pair_gap_seconds is not None
        and pair_gap_seconds >= -HOP_SECONDS * 0.51
        and target_regions.temporal_coherence == "coherent"
        and target_regions.onset_proof_end is not None
        and not bool(edge.get("right_edge_pileup"))
        and not touches_edge
        and not touches_left_edge
    )
    source = (
        "ctc-joint-boundary-observation"
        if strong_joint_boundary
        else "ctc-joint-boundary-observation-weak"
        if joint_pair
        else "ctc-opening-local-retry"
    )
    candidate = make_timing_candidate(
        entry_index=request.entry_index,
        entry_text=entry_sung_text(entries[request.entry_index]),
        source=source,
        raw_time=target_spans[0].start,
        spans=target_spans,
        confidence=confidence,
        identity_support="supported",
        sequence_support="supported",
        current=False,
        prefix_scope=False,
        right_edge_pileup=bool(edge.get("right_edge_pileup")),
        window_truncated=bool(touches_edge or touches_left_edge),
        source_artifact={
            "capability_revision": capability.capability_revision,
            "retry_semantic_revision": _crossline_retry_semantic_key(request, capability),
            "helper_input_revision": _crossline_retry_helper_cache_key(request, capability),
            "output_revision": output_revision,
            "transcript_digest": request.transcript_digest,
            "row_mapping_revision": request.row_mapping_revision,
            "joint_boundary": joint_pair,
            "strong_joint_boundary": strong_joint_boundary,
            "pair_gap_seconds": round(pair_gap_seconds, 6) if pair_gap_seconds is not None else None,
            "pair_previous_tail_revision": (
                previous_pair_tail.tail_evidence_revision
                if previous_pair_tail is not None else None
            ),
        },
    )
    previous_tail_evidence = _joint_previous_tail_evidence(
        request,
        capability,
        rows,
        parsed_rows,
        previous_probe,
        previous_pair_tail,
        probe,
        target_regions,
        output_revision,
        pair_gap_seconds,
        edge,
        touches_edge,
        touches_left_edge,
        strong_joint_boundary,
    )
    base = {
        "retry_epoch_revision": request.retry_epoch_revision,
        "request_revision": request.request_revision,
        "entry_index": request.entry_index,
        "status": "candidate",
        "reason": ("complete-joint-boundary-rows" if joint_pair else "complete-known-lyric-target-row"),
        "candidate": candidate,
        "output_revision": output_revision,
        "previous_tail_evidence": previous_tail_evidence,
    }
    return CrossLineRetryOutcome(**base, outcome_revision=_timing_content_digest({
        **base, "candidate": candidate.candidate_id,
        "previous_tail_evidence": (
            {
                "entry_index": previous_tail_evidence.entry_index,
                "tail_start": previous_tail_evidence.tail_start,
                "tail_end": previous_tail_evidence.tail_end,
                "uncertainty_seconds": previous_tail_evidence.uncertainty_seconds,
                "confidence": previous_tail_evidence.confidence,
                "producer": previous_tail_evidence.producer,
                "source_revision": previous_tail_evidence.source_revision,
            }
            if previous_tail_evidence is not None
            else None
        ),
    }))


def _crossline_retry_helper_cache_key(
    request: CrossLineRetryRequest,
    capability: BoundedRetryCapability,
) -> str:
    """Digest only the actual helper inputs, excluding retry-epoch bookkeeping."""
    return _timing_content_digest({
        "schema": 1,
        "helper_sha256": capability.helper_sha256,
        "helper_protocol_revision": capability.helper_protocol_revision,
        "alignment_audio_sha256": request.alignment_audio_revision,
        "model_identity": capability.model_identity,
        "device": capability.device,
        "transcript_digest": request.transcript_digest,
        "window_start": request.window_start,
        "window_end": request.window_end,
    })


def _crossline_retry_semantic_key(
    request: CrossLineRetryRequest,
    capability: BoundedRetryCapability,
) -> str:
    """Stable retry meaning, excluding epoch/request bookkeeping.

    The helper inference key captures the actual model inputs.  Entry identity and
    row mapping are added here because the same acoustic/helper payload can be
    interpreted for different immutable lyric entries, which must remain distinct
    central candidates.
    """
    return _timing_content_digest({
        "schema": 1,
        "entry_index": request.entry_index,
        "row_mapping_revision": request.row_mapping_revision,
        "helper_input_revision": _crossline_retry_helper_cache_key(request, capability),
    })


def _novel_crossline_retry_requests(
    requests: tuple[CrossLineRetryRequest, ...],
    capability: BoundedRetryCapability,
    processed_semantics: set[str],
) -> tuple[tuple[CrossLineRetryRequest, ...], tuple[str, ...]]:
    """Return only requests that can produce genuinely new retry evidence."""
    novel: list[CrossLineRetryRequest] = []
    semantic_keys: list[str] = []
    for request in sorted(requests, key=lambda item: (item.entry_index, item.request_revision)):
        semantic_key = _crossline_retry_semantic_key(request, capability)
        if semantic_key in processed_semantics:
            continue
        novel.append(request)
        semantic_keys.append(semantic_key)
    return tuple(novel), tuple(semantic_keys)


def invoke_crossline_retry(
    request: CrossLineRetryRequest,
    capability: BoundedRetryCapability,
    entries: list[LyricEntry],

    *,
    helper_cache: dict[str, tuple[str, object]] | None = None,
    timeout_seconds: float = 180.0,
) -> CrossLineRetryOutcome:
    def error_outcome(reason: str) -> CrossLineRetryOutcome:
        base = {
            "retry_epoch_revision": request.retry_epoch_revision,
            "request_revision": request.request_revision,
            "entry_index": request.entry_index,
            "status": "error",
            "reason": reason,
            "candidate": None,
            "output_revision": None,
        }
        return CrossLineRetryOutcome(**base, outcome_revision=_timing_content_digest(base))

    # R2L performance-only cache fast path: helper payload cache hits are
    # immutable model outputs.  Do not create a temp directory/transcript/command
    # merely to discover that the helper input was already evaluated.  Parsing
    # still runs against the *current* immutable request, preserving all epoch,
    # ownership, and candidate semantics.
    cache_key = _crossline_retry_helper_cache_key(request, capability)
    cached = helper_cache.get(cache_key) if helper_cache is not None else None
    if cached is not None:
        result_kind, result_value = cached
        if result_kind == "error":
            return error_outcome(str(result_value))
        return parse_crossline_retry_output(request, capability, entries, result_value)

    with tempfile.TemporaryDirectory(prefix="lrc-crossline-retry-") as temp_name:
        temp_dir = Path(temp_name)
        transcript_path = temp_dir / "transcript.json"
        output_path = temp_dir / "result.json"
        transcript_path.write_text(
            json.dumps(
                [entry_sung_text(entries[index]) for index in request.context_entry_indexes],
                ensure_ascii=False,
            ),
            encoding="utf-8",
        )
        command = [
            str(default_ctc_python()), capability.helper_path,
            "--audio", capability.alignment_audio_path,
            "--transcript", str(transcript_path),
            "--output", str(output_path),
            "--device", capability.device,
            "--start", f"{request.window_start:.3f}",
            "--end", f"{request.window_end:.3f}",
        ]
        try:
            proc = _run_model_helper_command(command, mode="ctc", timeout_seconds=timeout_seconds)
        except subprocess.TimeoutExpired:
            result: tuple[str, object] = ("error", "helper-timeout")
        except (LrcError, OSError, subprocess.SubprocessError):
            result = ("error", "helper-invocation-error")
        else:
            if proc.returncode != 0 or not output_path.is_file():
                result = ("error", "helper-invocation-failed")
            else:
                try:
                    payload = json.loads(output_path.read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    payload = None
                result = ("payload", payload)
        if helper_cache is not None:
            helper_cache[cache_key] = result
        result_kind, result_value = result
        if result_kind == "error":
            return error_outcome(str(result_value))
        payload = result_value
    return parse_crossline_retry_output(request, capability, entries, payload)


def record_crossline_retry_identity_hypothesis(
    report: dict[str, object],
    outcome: CrossLineRetryOutcome,
) -> dict[str, object] | None:
    """Publish a completed bounded retry as identity-only evidence.

    The retry helper aligned the current immutable lyric row inside a bounded
    audio window.  A complete, non-truncated row can therefore establish local
    occurrence identity for later reciprocal-recurrence reasoning.  It does
    *not* establish an onset by itself and is deliberately excluded from the
    ordinary central timing-candidate collector.
    """
    candidate = outcome.candidate
    if (
        outcome.status != "candidate"
        or candidate is None
        or candidate.source != "ctc-opening-local-retry"
        or candidate.identity_support != "supported"
        or candidate.sequence_support != "supported"
        or len(candidate.spans) < 4
        or candidate.window_truncated
        or candidate.right_edge_pileup
    ):
        return None
    assignments = report.get("assignments")
    if (
        not isinstance(assignments, list)
        or not (0 <= outcome.entry_index < len(assignments))
        or not isinstance(assignments[outcome.entry_index], dict)
    ):
        return None
    assignment = assignments[outcome.entry_index]
    assert isinstance(assignment, dict)
    spans = [
        {
            "char": span.token,
            "start": round(float(span.start), 6),
            "end": round(float(span.end), 6),
            "score": round(float(span.score), 8),
        }
        for span in candidate.spans
    ]
    window = {
        "candidate_id": candidate.candidate_id,
        "generation_revision": candidate.generation_revision,
        "request_revision": outcome.request_revision,
        "retry_epoch_revision": outcome.retry_epoch_revision,
        "output_revision": outcome.output_revision,
        "outcome_revision": outcome.outcome_revision,
        "status": outcome.status,
        "reason": outcome.reason,
        "identity_only": True,
    }
    before = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else 0
    hypothesis = record_alignment_hypothesis(
        assignment,
        source="ctc-opening-local-retry-identity",
        stage="bounded-crossline-retry-identity",
        raw_time=candidate.raw_time,
        confidence=candidate.confidence,
        spans=spans,
        identity_support="supported",
        sequence_support="supported",
        acoustic_support="unavailable",
        direct_onset_support="unavailable",
        parent_source="ctc-opening-local-retry",
        parent_time=candidate.raw_time,
        window=window,
        mode="identity-only-complete-known-lyric-row",
        right_edge_pileup=False,
        window_truncated=False,
    )
    after = len(assignment.get("alignment_hypotheses", [])) if isinstance(assignment.get("alignment_hypotheses"), list) else before
    return hypothesis if after > before else None


def execute_crossline_retry_epoch(
    epoch: BaseRetryEpoch,
    capability: BoundedRetryCapability | None,
    entries: list[LyricEntry],
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    duration: float,
    requests: tuple[CrossLineRetryRequest, ...],
    *,
    helper_cache: dict[str, tuple[str, object]] | None = None,
    timeout_seconds: float = 180.0,
    pass_index: int | str | None = None,
    runtime_stats: dict[str, int] | None = None,
    independent_tail_evidence: RuntimeTailEvidence | None = None,
    tail_evidence_context: TailEvidenceContext | None = None,
    worker_count: int = 1,
) -> tuple[CrossLineRetryOutcome, ...]:
    """Execute one frozen retry epoch.

    Performance mode may run independent helper inputs concurrently.  Planning,
    request-currentness checks, cache semantics, result ordering, and all Central
    mutations remain outside the concurrent section and therefore deterministic.
    """
    if capability is None:
        return ()

    seen: set[tuple[str, int]] = set()
    ordered_requests = sorted(requests, key=lambda item: (item.entry_index, item.request_revision))
    pass_label = str(pass_index) if pass_index is not None else "?"
    total = len(ordered_requests)

    # R2L performance-only planning dedup: request currentness is evaluated
    # against a frozen epoch/candidate/tail state.  The legacy per-request
    # helper recomputed the complete planner output for every row even though
    # those inputs cannot change inside this epoch.  Compute each applicable
    # planner exactly once, then preserve the same membership test.
    needs_joint = any(len(item.context_entry_indexes) == 2 for item in ordered_requests)
    needs_regular = any(len(item.context_entry_indexes) != 2 for item in ordered_requests)
    current_joint = set(
        plan_joint_boundary_retry_requests(
            epoch, capability, entries, candidate_sets, duration,
            independent_tail_evidence, tail_evidence_context,
        )
    ) if needs_joint else set()
    current_regular = set(
        plan_crossline_retry_requests(
            epoch, capability, entries, candidate_sets, duration,
            independent_tail_evidence, tail_evidence_context,
        )
    ) if needs_regular else set()

    prepared: list[tuple[int, CrossLineRetryRequest, str]] = []
    for ordinal, request in enumerate(ordered_requests, start=1):
        ledger_key = (request.retry_epoch_revision, request.entry_index)
        if ledger_key in seen:
            continue
        seen.add(ledger_key)
        current_requests = current_joint if len(request.context_entry_indexes) == 2 else current_regular
        if request not in current_requests:
            continue
        prepared.append((ordinal, request, _crossline_retry_helper_cache_key(request, capability)))

    if not prepared:
        return ()

    worker_count = max(1, min(int(worker_count or 1), 4))
    if worker_count == 1 or len(prepared) <= 1:
        outcomes: list[CrossLineRetryOutcome] = []
        for ordinal, request, cache_key in prepared:
            cache_hit = helper_cache is not None and cache_key in helper_cache
            if runtime_stats is not None:
                runtime_stats["cache_hits" if cache_hit else "cache_misses"] = (
                    runtime_stats.get("cache_hits" if cache_hit else "cache_misses", 0) + 1
                )
                if not cache_hit:
                    runtime_stats["helper_invocations"] = runtime_stats.get("helper_invocations", 0) + 1
            progress_log(
                f"crossline retry pass {pass_label}: {ordinal}/{total} "
                f"entry={request.entry_index + 1} "
                f"window={request.window_start:.2f}-{request.window_end:.2f}s "
                f"cache={'hit' if cache_hit else 'miss'}"
            )
            if helper_cache is None and timeout_seconds == 180.0:
                outcome = invoke_crossline_retry(request, capability, entries)
            else:
                outcome = invoke_crossline_retry(
                    request, capability, entries,
                    helper_cache=helper_cache, timeout_seconds=timeout_seconds,
                )
            if runtime_stats is not None and outcome.reason == "helper-timeout":
                runtime_stats["timeouts"] = runtime_stats.get("timeouts", 0) + 1
            progress_log(
                f"crossline retry pass {pass_label}: entry={request.entry_index + 1} "
                f"status={outcome.status} reason={outcome.reason}"
            )
            outcomes.append(outcome)
        return tuple(outcomes)

    # Recreate the exact serial cache semantics before dispatch: for every helper
    # input already cached, all requests are hits; otherwise the first request is
    # the one real invocation and later requests sharing that helper input are hits.
    grouped: dict[str, list[tuple[int, CrossLineRetryRequest]]] = {}
    for ordinal, request, cache_key in prepared:
        grouped.setdefault(cache_key, []).append((ordinal, request))

    outcomes_by_ordinal: dict[int, CrossLineRetryOutcome] = {}
    work: list[tuple[str, int, CrossLineRetryRequest]] = []
    for cache_key, group in grouped.items():
        pre_cached = helper_cache is not None and cache_key in helper_cache
        if runtime_stats is not None:
            if pre_cached:
                runtime_stats["cache_hits"] = runtime_stats.get("cache_hits", 0) + len(group)
            else:
                runtime_stats["cache_misses"] = runtime_stats.get("cache_misses", 0) + 1
                runtime_stats["cache_hits"] = runtime_stats.get("cache_hits", 0) + max(0, len(group) - 1)
                runtime_stats["helper_invocations"] = runtime_stats.get("helper_invocations", 0) + 1
        if pre_cached:
            for ordinal, request in group:
                progress_log(
                    f"crossline retry pass {pass_label}: cached {ordinal}/{total} "
                    f"entry={request.entry_index + 1}"
                )
                outcomes_by_ordinal[ordinal] = invoke_crossline_retry(
                    request, capability, entries,
                    helper_cache=helper_cache, timeout_seconds=timeout_seconds,
                )
        else:
            first_ordinal, first_request = group[0]
            work.append((cache_key, first_ordinal, first_request))

    progress_log(
        f"crossline retry pass {pass_label}: parallel_workers={worker_count} "
        f"unique_exec={len(work)}"
    )

    def _run_retry_parallel(
        item: tuple[str, int, CrossLineRetryRequest],
    ) -> tuple[str, int, CrossLineRetryOutcome, dict[str, tuple[str, object]]]:
        cache_key, ordinal, request = item
        private_cache: dict[str, tuple[str, object]] = {}
        progress_log(
            f"crossline retry pass {pass_label}: start {ordinal}/{total} "
            f"entry={request.entry_index + 1} "
            f"window={request.window_start:.2f}-{request.window_end:.2f}s"
        )
        outcome = invoke_crossline_retry(
            request, capability, entries,
            helper_cache=private_cache, timeout_seconds=timeout_seconds,
        )
        return cache_key, ordinal, outcome, private_cache

    if work:
        with concurrent.futures.ThreadPoolExecutor(
            max_workers=min(worker_count, len(work)),
            thread_name_prefix="lrc-ctc-retry",
        ) as pool:
            future_map = {pool.submit(_run_retry_parallel, item): item for item in work}
            for future in concurrent.futures.as_completed(future_map):
                cache_key, ordinal, outcome, private_cache = future.result()
                if helper_cache is not None:
                    helper_cache.update(private_cache)
                outcomes_by_ordinal[ordinal] = outcome
                progress_log(
                    f"crossline retry pass {pass_label}: done {ordinal}/{total} "
                    f"entry={outcome.entry_index + 1} "
                    f"status={outcome.status} reason={outcome.reason}"
                )
                # Same helper payload may map to more than one immutable request.
                # Parse those additional requests only after the representative
                # payload is in the shared cache; no second model invocation occurs.
                for grouped_ordinal, grouped_request in grouped[cache_key][1:]:
                    outcomes_by_ordinal[grouped_ordinal] = invoke_crossline_retry(
                        grouped_request, capability, entries,
                        helper_cache=helper_cache, timeout_seconds=timeout_seconds,
                    )

    ordered_outcomes = tuple(
        outcomes_by_ordinal[ordinal]
        for ordinal, _request, _cache_key in prepared
        if ordinal in outcomes_by_ordinal
    )
    if runtime_stats is not None:
        runtime_stats["timeouts"] = runtime_stats.get("timeouts", 0) + sum(
            item.reason == "helper-timeout" for item in ordered_outcomes
        )
    return ordered_outcomes

def _retry_diagnostic_payload(item: object) -> dict[str, object]:
    if isinstance(item, CrossLineRetryRequest):
        return {
            "entry": item.entry_index + 1,
            "ordinal": item.ordinal,
            "retry_epoch_revision": item.retry_epoch_revision,
            "request_revision": item.request_revision,
            "capability_revision": item.capability_revision,
            "alignment_audio_revision": item.alignment_audio_revision,
            "current": item.current.__dict__,
            "previous": item.previous.__dict__,
            "next_bound": item.next_bound.__dict__ if item.next_bound else None,
            "ownership_relation_revision": item.ownership_relation_revision,
            "previous_tail_evidence_revision": item.previous_tail_evidence_revision,
            "previous_tail": {
                "start": item.previous_tail_start,
                "end": item.previous_tail_end,
                "uncertainty": item.previous_tail_uncertainty,
                "validity": item.previous_tail_validity,
            },
            "audio_end_seconds": item.audio_end_seconds,
            "audio_duration_revision": item.audio_duration_revision,
            "context_entry_indexes": list(item.context_entry_indexes),
            "context_candidate_ids": list(item.context_candidate_ids),
            "transcript_digests": list(item.transcript_digests),
            "window": [item.window_start, item.window_end],
            "window_definition_revision": item.window_definition_revision,
            "transcript_digest": item.transcript_digest,
            "row_mapping": [list(pair) for pair in item.row_mapping],
            "row_mapping_revision": item.row_mapping_revision,
        }
    if isinstance(item, CrossLineRetryOutcome):
        return {
            "entry": item.entry_index + 1,
            "retry_epoch_revision": item.retry_epoch_revision,
            "request_revision": item.request_revision,
            "status": item.status,
            "reason": item.reason,
            "candidate_id": item.candidate.candidate_id if item.candidate else None,
            "output_revision": item.output_revision,
            "outcome_revision": item.outcome_revision,
            "previous_tail_evidence": _independent_tail_evidence_payload(
                item.previous_tail_evidence
            ),
        }
    raise TypeError("Unsupported retry diagnostic item")


def _retry_capability_diagnostic_payload(
    capability: BoundedRetryCapability | None,
) -> dict[str, object] | None:
    if capability is None:
        return None
    return {
        "kind": capability.kind,
        "backend_lineage": capability.backend_lineage,
        "helper_path": capability.helper_path,
        "helper_sha256": capability.helper_sha256,
        "helper_protocol_revision": capability.helper_protocol_revision,
        "alignment_audio_path": capability.alignment_audio_path,
        "alignment_audio_sha256": capability.alignment_audio_sha256,
        "alignment_audio_source": capability.alignment_audio_source,
        "sample_rate": capability.sample_rate,
        "model_identity": capability.model_identity,
        "device": capability.device,
        "capability_revision": capability.capability_revision,
    }


def inactive_legacy_timing_diagnostics() -> dict[str, object]:
    return {
        "legacy_boundary_mutation_pipeline": {
            "status": "inactive",
            "executed": False,
            "authoritative": False,
            "inactive_stages": ["zero-gap", "crossline-initial", "forward-prefix", "weak-prefix"],
            "raw_existing_evidence_preserved": True,
            "evidence_scope": "historical-nonauthoritative",
        },
        "legacy_prefix_probe_candidate_generation": {
            "status": "inactive",
            "executed": False,
            "authoritative": False,
            "active_candidate_count": 0,
            "raw_existing_evidence_preserved": True,
            "evidence_scope": "historical-nonauthoritative",
        },
    }



def _entry_identity_is_unique(entries: list[LyricEntry], index: int) -> bool:
    normalized = normalize_match_text(entry_sung_text(entries[index]))
    if not normalized:
        return False
    occurrences = sum(
        1
        for entry in entries
        if normalize_match_text(entry_sung_text(entry)) == normalized
    )
    return occurrences == 1 and not has_ambiguous_lyric_prefix(entries, index)


def _minimal_unique_sequence_context(
    entries: list[LyricEntry],
    index: int,
    *,
    max_items: int = 9,
) -> tuple[int, int] | None:
    """Return the shortest immutable lyric window uniquely identifying one occurrence.

    Individual chorus lines often repeat. Requiring globally-unique single-line
    anchors can therefore force an unnecessarily large window or make a valid
    occurrence impossible to probe. A contiguous lyric sequence is sufficient
    identity evidence when that exact normalized sequence occurs once in the
    immutable lyric list. The target must be strictly inside the bracket.
    """
    if not 0 <= index < len(entries) or max_items < 3:
        return None
    lyrics = [
        normalize_match_text(entry_sung_text(entry))
        for entry in entries
    ]
    if not lyrics[index]:
        return None
    upper = min(max_items, len(entries))
    candidates: list[tuple[int, int, int, int, int]] = []
    for length in range(3, upper + 1):
        min_left = max(0, index - length + 1)
        max_left = min(index - 1, len(entries) - length)
        for left in range(min_left, max_left + 1):
            right = left + length - 1
            if not (left < index < right):
                continue
            sequence = tuple(lyrics[left : right + 1])
            if any(not item for item in sequence):
                continue
            occurrences = [
                start
                for start in range(0, len(lyrics) - length + 1)
                if tuple(lyrics[start : start + length]) == sequence
            ]
            if occurrences != [left]:
                continue
            left_distance = index - left
            right_distance = right - index
            candidates.append((length, max(left_distance, right_distance), abs(left_distance - right_distance), left, right))
        if candidates:
            break
    if not candidates:
        return None
    _, _, _, left, right = min(candidates)
    return left, right


def _sparse_unique_sequence_anchor_set(
    entries: list[LyricEntry],
    assignments: list[object],
    index: int,
    *,
    max_items: int = 9,
) -> tuple[int, int, tuple[int, ...]] | None:
    """Return the smallest trusted sparse fingerprint that uniquely binds a target.

    Only real trusted backend rows participate. Missing/weak context rows are
    ignored rather than interpolated. The selected target+anchor lyric offsets
    must identify exactly one target occurrence in the immutable lyric list and
    fit inside the existing bounded context size.
    """
    if not 0 <= index < len(entries) or len(assignments) != len(entries) or max_items < 3:
        return None
    if _identity_assignment_observation(assignments[index]) is None:
        return None
    search_left = max(0, index - max_items + 1)
    search_right = min(len(entries) - 1, index + max_items - 1)
    observed = [
        item
        for item in range(search_left, search_right + 1)
        if _identity_assignment_observation(assignments[item]) is not None
    ]
    left_observed = [item for item in observed if item < index]
    right_observed = [item for item in observed if item > index]
    # A sparse immutable lyric fingerprint does not intrinsically require one
    # anchor on each side.  Two trusted non-target anchors on the same side can
    # still prove exactly one target occurrence in the song.  Keep two-sided
    # fingerprints preferred when available, but do not discard a globally
    # unique one-sided proof merely because unrelated rows on the other side
    # were weak.
    if len([item for item in observed if item != index]) < 2:
        return None

    lyrics = [normalize_match_text(entry_sung_text(entry)) for entry in entries]
    target = lyrics[index]
    if not target:
        return None
    target_occurrences = [item for item, text in enumerate(lyrics) if text == target]
    anchors = [item for item in observed if item != index]
    ranked: list[tuple[int, int, int, int, tuple[int, ...]]] = []
    for count in range(2, len(anchors) + 1):
        for subset in itertools.combinations(anchors, count):
            selected = tuple(sorted((index, *subset)))
            if selected[-1] - selected[0] + 1 > max_items:
                continue
            observations = [_identity_assignment_observation(assignments[item]) for item in selected]
            if any(item is None for item in observations):
                continue
            typed = [item for item in observations if item is not None]
            timestamps = [item[0] for item in typed]
            segments = [item[1] for item in typed]
            if (
                any(left >= right for left, right in zip(timestamps, timestamps[1:]))
                or any(left > right for left, right in zip(segments, segments[1:]))
            ):
                continue
            offsets = tuple(item - index for item in selected)
            expected = tuple(lyrics[item] for item in selected)
            matches: list[int] = []
            for occurrence in target_occurrences:
                candidate_indexes = [occurrence + offset for offset in offsets]
                if any(item < 0 or item >= len(lyrics) for item in candidate_indexes):
                    continue
                if tuple(lyrics[item] for item in candidate_indexes) == expected:
                    matches.append(occurrence)
            if matches != [index]:
                continue
            span = selected[-1] - selected[0]
            distance = sum(abs(item - index) for item in selected if item != index)
            two_sided = any(item < index for item in selected) and any(item > index for item in selected)
            # Same evidence count: prefer a two-sided bracket, then the tightest
            # immutable fingerprint.  One-sided proof is only a fallback.
            ranked.append((count, int(not two_sided), span, distance, selected))
        if ranked:
            break
    if not ranked:
        return None
    _, _, _, _, selected = min(ranked)
    return selected[0], selected[-1], selected


def _sparse_sequence_fingerprint_is_unique(
    entries: list[LyricEntry],
    index: int,
    anchor_indexes: list[int],
) -> bool:
    if index not in anchor_indexes or len(set(anchor_indexes) - {index}) < 2:
        return False
    lyrics = [normalize_match_text(entry_sung_text(entry)) for entry in entries]
    if not 0 <= index < len(lyrics) or not lyrics[index]:
        return False
    ordered = sorted(anchor_indexes)
    offsets = tuple(item - index for item in ordered)
    expected = tuple(lyrics[item] for item in ordered)
    matches: list[int] = []
    for occurrence, text in enumerate(lyrics):
        if text != lyrics[index]:
            continue
        candidate_indexes = [occurrence + offset for offset in offsets]
        if any(item < 0 or item >= len(lyrics) for item in candidate_indexes):
            continue
        if tuple(lyrics[item] for item in candidate_indexes) == expected:
            matches.append(occurrence)
    return matches == [index]


def _occurrence_binding_has_strong_context(binding: object) -> bool:
    return bool(
        isinstance(binding, dict)
        and binding.get("mode") in {"sequence-bracket", "sparse-sequence-bracket"}
    )


def _identity_assignment_observation(
    assignment: object,
) -> tuple[float, int, float] | None:
    """Return a real backend row suitable for occurrence binding."""
    if not isinstance(assignment, dict):
        return None
    try:
        timestamp = float(assignment.get("timestamp"))
        score = float(assignment.get("score", 0.0) or 0.0)
    except (TypeError, ValueError):
        return None
    segment = assignment.get("segment")
    if (
        not math.isfinite(timestamp)
        or score < TRUSTED_ALIGNMENT_SCORE
        or bool(assignment.get("borrowed"))
        or not isinstance(segment, int)
    ):
        return None
    return timestamp, segment, score


def _entry_occurrence_binding(
    entries: list[LyricEntry],
    assignments: list[object],
    index: int,
    *,
    require_context: bool = False,
) -> dict[str, object] | None:
    """Prove which immutable lyric occurrence an independent backend identified.

    Prefer a fully trusted contiguous sequence bracket.  If one or more unrelated
    context rows are weak, fall back to the smallest trusted sparse fingerprint
    that still uniquely identifies the target occurrence.  No timestamp or lyric
    is inferred for missing rows.
    """
    if not (0 <= index < len(entries)) or len(assignments) != len(entries):
        return None
    current = _identity_assignment_observation(assignments[index])
    if current is None:
        return None
    current_time, current_segment, current_score = current
    target = normalize_match_text(entry_sung_text(entries[index]))
    if not target:
        return None

    if _entry_identity_is_unique(entries, index) and not require_context:
        payload = {
            "mode": "global-unique",
            "entry_index": index,
            "lyric_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
            "segment": current_segment,
            "timestamp": round(current_time, 6),
            "score": round(current_score, 6),
        }
        return {**payload, "binding_revision": _timing_content_digest(payload)}

    context = _minimal_unique_sequence_context(entries, index, max_items=9)
    if context is None:
        return None
    left_index, right_index = context
    context_indexes = list(range(left_index, right_index + 1))
    observations = [
        _identity_assignment_observation(assignments[context_index])
        for context_index in context_indexes
    ]
    if all(item is not None for item in observations):
        typed = [item for item in observations if item is not None]
        timestamps = [item[0] for item in typed]
        segments = [item[1] for item in typed]
        scores = [item[2] for item in typed]
        if (
            not any(left >= right for left, right in zip(timestamps, timestamps[1:]))
            and not any(left > right for left, right in zip(segments, segments[1:]))
        ):
            relative_index = index - left_index
            current_time, current_segment, current_score = typed[relative_index]
            context_payload = {
                "left_index": left_index,
                "target_index": index,
                "right_index": right_index,
                "lyrics": [
                    normalize_match_text(entry_sung_text(entry))
                    for entry in entries[left_index : right_index + 1]
                ],
            }
            payload = {
                "mode": "sequence-bracket",
                "entry_index": index,
                "lyric_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
                "segment": current_segment,
                "timestamp": round(current_time, 6),
                "score": round(current_score, 6),
                "left_entry_index": left_index,
                "left_segment": segments[0],
                "left_timestamp": round(timestamps[0], 6),
                "left_score": round(scores[0], 6),
                "right_entry_index": right_index,
                "right_segment": segments[-1],
                "right_timestamp": round(timestamps[-1], 6),
                "right_score": round(scores[-1], 6),
                "context_entry_indexes": context_indexes,
                "context_segments": segments,
                "context_timestamps": [round(value, 6) for value in timestamps],
                "context_scores": [round(value, 6) for value in scores],
                "context_revision": _timing_content_digest(context_payload),
            }
            return {**payload, "binding_revision": _timing_content_digest(payload)}

    sparse = _sparse_unique_sequence_anchor_set(entries, assignments, index, max_items=9)
    if sparse is None:
        return None
    sparse_left, sparse_right, anchor_indexes = sparse
    sparse_observations = [
        _identity_assignment_observation(assignments[item])
        for item in anchor_indexes
    ]
    if any(item is None for item in sparse_observations):
        return None
    typed_sparse = [item for item in sparse_observations if item is not None]
    anchor_timestamps = [item[0] for item in typed_sparse]
    anchor_segments = [item[1] for item in typed_sparse]
    anchor_scores = [item[2] for item in typed_sparse]
    target_position = anchor_indexes.index(index)
    current_time, current_segment, current_score = typed_sparse[target_position]
    fingerprint_payload = {
        "target_index": index,
        "context_left_index": sparse_left,
        "context_right_index": sparse_right,
        "anchor_entry_indexes": list(anchor_indexes),
        "anchor_lyrics": [
            normalize_match_text(entry_sung_text(entries[item]))
            for item in anchor_indexes
        ],
    }
    payload = {
        "mode": "sparse-sequence-bracket",
        "entry_index": index,
        "lyric_sha256": hashlib.sha256(target.encode("utf-8")).hexdigest(),
        "segment": current_segment,
        "timestamp": round(current_time, 6),
        "score": round(current_score, 6),
        "context_left_index": sparse_left,
        "context_right_index": sparse_right,
        "anchor_entry_indexes": list(anchor_indexes),
        "anchor_segments": anchor_segments,
        "anchor_timestamps": [round(value, 6) for value in anchor_timestamps],
        "anchor_scores": [round(value, 6) for value in anchor_scores],
        "fingerprint_revision": _timing_content_digest(fingerprint_payload),
    }
    return {**payload, "binding_revision": _timing_content_digest(payload)}


def _runtime_occurrence_binding_is_valid(
    entries: list[LyricEntry],
    index: int,
    binding: object,
) -> bool:
    """Revalidate immutable lyric context and monotonic runtime binding data."""
    if not isinstance(binding, dict) or not (0 <= index < len(entries)):
        return False
    if not _candidate_occurrence_binding_keys_are_canonical(binding):
        return False
    target = normalize_match_text(entry_sung_text(entries[index]))
    if not target or binding.get("entry_index") != index:
        return False
    if binding.get("lyric_sha256") != hashlib.sha256(target.encode("utf-8")).hexdigest():
        return False
    payload = {key: value for key, value in binding.items() if key != "binding_revision"}
    if binding.get("binding_revision") != _timing_content_digest(payload):
        return False
    mode = binding.get("mode")
    if mode == "global-unique":
        return _entry_identity_is_unique(entries, index)

    if mode == "sequence-bracket":
        try:
            left_index = int(binding.get("left_entry_index"))
            right_index = int(binding.get("right_entry_index"))
            current_segment = int(binding.get("segment"))
            current_time = float(binding.get("timestamp"))
        except (TypeError, ValueError):
            return False
        expected_context = _minimal_unique_sequence_context(entries, index, max_items=9)
        if expected_context != (left_index, right_index):
            return False
        context_indexes = binding.get("context_entry_indexes")
        context_segments = binding.get("context_segments")
        context_timestamps = binding.get("context_timestamps")
        context_scores = binding.get("context_scores")
        expected_indexes = list(range(left_index, right_index + 1))
        if (
            context_indexes != expected_indexes
            or not isinstance(context_segments, list)
            or not isinstance(context_timestamps, list)
            or not isinstance(context_scores, list)
            or not (len(context_segments) == len(context_timestamps) == len(context_scores) == len(expected_indexes))
        ):
            return False
        try:
            segments = [int(value) for value in context_segments]
            timestamps = [float(value) for value in context_timestamps]
            scores = [float(value) for value in context_scores]
        except (TypeError, ValueError):
            return False
        if (
            any(not math.isfinite(value) for value in timestamps + scores)
            or any(score < TRUSTED_ALIGNMENT_SCORE for score in scores)
            or any(left > right for left, right in zip(segments, segments[1:]))
            or any(left >= right for left, right in zip(timestamps, timestamps[1:]))
        ):
            return False
        relative_index = index - left_index
        if (
            segments[relative_index] != current_segment
            or abs(timestamps[relative_index] - current_time) > 1e-6
            or int(binding.get("left_segment")) != segments[0]
            or int(binding.get("right_segment")) != segments[-1]
            or abs(float(binding.get("left_timestamp")) - timestamps[0]) > 1e-6
            or abs(float(binding.get("right_timestamp")) - timestamps[-1]) > 1e-6
        ):
            return False
        context_payload = {
            "left_index": left_index,
            "target_index": index,
            "right_index": right_index,
            "lyrics": [
                normalize_match_text(entry_sung_text(entry))
                for entry in entries[left_index : right_index + 1]
            ],
        }
        return binding.get("context_revision") == _timing_content_digest(context_payload)

    if mode != "sparse-sequence-bracket":
        return False
    try:
        context_left = int(binding.get("context_left_index"))
        context_right = int(binding.get("context_right_index"))
        current_segment = int(binding.get("segment"))
        current_time = float(binding.get("timestamp"))
    except (TypeError, ValueError):
        return False
    anchor_indexes = binding.get("anchor_entry_indexes")
    anchor_segments = binding.get("anchor_segments")
    anchor_timestamps = binding.get("anchor_timestamps")
    anchor_scores = binding.get("anchor_scores")
    if (
        not isinstance(anchor_indexes, list)
        or not isinstance(anchor_segments, list)
        or not isinstance(anchor_timestamps, list)
        or not isinstance(anchor_scores, list)
        or not (len(anchor_indexes) == len(anchor_segments) == len(anchor_timestamps) == len(anchor_scores))
        or len(anchor_indexes) < 3
    ):
        return False
    try:
        indexes = [int(value) for value in anchor_indexes]
        segments = [int(value) for value in anchor_segments]
        timestamps = [float(value) for value in anchor_timestamps]
        scores = [float(value) for value in anchor_scores]
    except (TypeError, ValueError):
        return False
    if (
        indexes != sorted(indexes)
        or len(set(indexes)) != len(indexes)
        or index not in indexes
        or context_left != indexes[0]
        or context_right != indexes[-1]
        or context_right - context_left + 1 > 9
        or any(item < context_left or item > context_right for item in indexes)
        or len(set(indexes) - {index}) < 2
        or any(not math.isfinite(value) for value in timestamps + scores)
        or any(score < TRUSTED_ALIGNMENT_SCORE for score in scores)
        or any(left > right for left, right in zip(segments, segments[1:]))
        or any(left >= right for left, right in zip(timestamps, timestamps[1:]))
        or not _sparse_sequence_fingerprint_is_unique(entries, index, indexes)
    ):
        return False
    target_position = indexes.index(index)
    if segments[target_position] != current_segment or abs(timestamps[target_position] - current_time) > 1e-6:
        return False
    fingerprint_payload = {
        "target_index": index,
        "context_left_index": context_left,
        "context_right_index": context_right,
        "anchor_entry_indexes": indexes,
        "anchor_lyrics": [
            normalize_match_text(entry_sung_text(entries[item]))
            for item in indexes
        ],
    }
    return binding.get("fingerprint_revision") == _timing_content_digest(fingerprint_payload)


def bind_runtime_raw_content_identity(
    report: dict[str, object],
    entries: list[LyricEntry],
    raw_report: dict[str, object],
) -> None:
    """Bind independent raw-ASR lyric identity without granting timing authority."""
    raw_assignments = raw_report.get("assignments")
    if not isinstance(raw_assignments, list) or len(raw_assignments) != len(entries):
        return
    drift_entries = {
        int(entry)
        for run in report.get("raw_asr_systematic_drift_runs", [])
        if isinstance(run, dict)
        for entry in run.get("entries", [])
        if isinstance(entry, int)
    }
    runtime: dict[int, dict[str, object]] = {}
    for index, raw_assignment in enumerate(raw_assignments):
        if not isinstance(raw_assignment, dict):
            continue
        occurrence_binding = _entry_occurrence_binding(entries, raw_assignments, index)
        if occurrence_binding is None:
            continue
        try:
            raw_time = float(raw_assignment.get("timestamp"))
            raw_score = float(raw_assignment.get("score", 0.0) or 0.0)
        except (TypeError, ValueError):
            continue
        segment = raw_assignment.get("segment")
        if (
            raw_score < TRUSTED_ALIGNMENT_SCORE
            or bool(raw_assignment.get("borrowed"))
            or segment is None
            or index + 1 in drift_entries
        ):
            continue
        lyric_sha = hashlib.sha256(
            normalize_match_text(entry_sung_text(entries[index])).encode("utf-8")
        ).hexdigest()
        payload = {
            "entry_index": index,
            "lyric_sha256": lyric_sha,
            "raw_time": round(raw_time, 6),
            "raw_score": round(raw_score, 6),
            "segment": int(segment) if isinstance(segment, int) else str(segment),
            "occurrence_binding": occurrence_binding,
            "producer": "raw-asr-content-identity",
        }
        runtime[index] = {
            **payload,
            "evidence_revision": _timing_content_digest(payload),
        }
    report[_RUNTIME_RAW_CONTENT_IDENTITY_KEY] = runtime
    report["raw_asr_content_identity"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "minimum_score": TRUSTED_ALIGNMENT_SCORE,
        "candidate_count": len(runtime),
        "entries": [index + 1 for index in sorted(runtime)],
    }


def runtime_raw_content_identity_for_entry(
    report: dict[str, object],
    entries: list[LyricEntry],
    entry_index: int,
) -> dict[str, object] | None:
    runtime = report.get(_RUNTIME_RAW_CONTENT_IDENTITY_KEY)
    if not isinstance(runtime, dict):
        return None
    evidence = runtime.get(entry_index)
    if not isinstance(evidence, dict):
        return None
    lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entries[entry_index])).encode("utf-8")
    ).hexdigest()
    try:
        raw_time = float(evidence.get("raw_time"))
        raw_score = float(evidence.get("raw_score"))
    except (TypeError, ValueError):
        return None
    payload = {
        "entry_index": entry_index,
        "lyric_sha256": lyric_sha,
        "raw_time": round(raw_time, 6),
        "raw_score": round(raw_score, 6),
        "segment": evidence.get("segment"),
        "occurrence_binding": evidence.get("occurrence_binding"),
        "producer": "raw-asr-content-identity",
    }
    if (
        evidence.get("producer") != "raw-asr-content-identity"
        or raw_score < TRUSTED_ALIGNMENT_SCORE
        or evidence.get("lyric_sha256") != lyric_sha
        or not _runtime_occurrence_binding_is_valid(
            entries, entry_index, evidence.get("occurrence_binding")
        )
        or evidence.get("evidence_revision") != _timing_content_digest(payload)
    ):
        return None
    return dict(evidence)


def bind_runtime_whisperx_row_evidence(
    report: dict[str, object],
    entries: list[LyricEntry],
    evidence_candidates: list[tuple[list[float], dict[str, object], str]],
) -> None:
    """Preserve trusted per-line WhisperX identity/boundary geometry at runtime.

    Whole-backend rejection is an aggregate decision.  A row with a real,
    non-borrowed ASR match can still contribute independent identity and forced
    alignment geometry.  Authority remains runtime-only and row review defects
    are excluded before binding.
    """
    best: dict[int, dict[str, object]] = {}
    tail_candidates: dict[int, list[IndependentTailEvidence]] = {}
    scope_records: dict[tuple[int, str], list[TailEvidenceScope]] = {}
    for _candidate_times, candidate_report, _error in evidence_candidates:
        assignments = candidate_report.get("assignments")
        forced_rows = candidate_report.get("whisperx_forced_rows")
        runtime_provenance = candidate_report.get(
            _RUNTIME_WHISPERX_EXECUTION_PROVENANCE_KEY
        )
        if not isinstance(assignments, list) or not isinstance(forced_rows, list):
            continue
        if len(assignments) != len(entries) or len(forced_rows) != len(entries):
            continue
        actionable_entries = {
            int(row.get("entry"))
            for row in candidate_report.get("suspicious_alignments", [])
            if isinstance(row, dict)
            and isinstance(row.get("entry"), int)
            and _suspicious_row_requires_review(row)
        }
        suppress_nst = bool(candidate_report.get("whisper_suppress_nst"))
        for index, (assignment, forced) in enumerate(zip(assignments, forced_rows)):
            if (
                not isinstance(assignment, dict)
                or not isinstance(forced, dict)
                or index + 1 in actionable_entries
            ):
                continue
            occurrence_binding = _entry_occurrence_binding(entries, assignments, index)
            if occurrence_binding is None:
                continue
            try:
                score = float(assignment.get("score", 0.0) or 0.0)
                segment_start = float(forced.get("segment_start"))
                segment_end = float(forced.get("segment_end"))
                first_time = float(forced.get("first_char_time"))
                last_time = float(forced.get("last_char_time"))
                char_count = int(forced.get("char_count", 0) or 0)
            except (TypeError, ValueError):
                continue
            numeric = (score, segment_start, segment_end, first_time, last_time)
            if (
                not all(math.isfinite(value) for value in numeric)
                or score < TRUSTED_ALIGNMENT_SCORE
                or bool(assignment.get("borrowed"))
                or assignment.get("segment") is None
                or char_count <= 0
                or segment_end < segment_start
                or not (segment_start - HOP_SECONDS <= first_time <= segment_end + HOP_SECONDS)
                or not (first_time - HOP_SECONDS <= last_time <= segment_end + HOP_SECONDS)
            ):
                continue
            lyric_sha = hashlib.sha256(
                normalize_match_text(entry_sung_text(entries[index])).encode("utf-8")
            ).hexdigest()
            payload = {
                "entry_index": index,
                "lyric_sha256": lyric_sha,
                "score": round(score, 6),
                "segment": assignment.get("segment"),
                "segment_start": round(segment_start, 6),
                "segment_end": round(segment_end, 6),
                "first_char_time": round(first_time, 6),
                "last_char_time": round(last_time, 6),
                "char_count": char_count,
                "suppress_nst": suppress_nst,
                "occurrence_binding": occurrence_binding,
                "producer": "whisperx-row-evidence",
            }
            revision = _timing_content_digest(payload)
            row = {**payload, "evidence_revision": revision}
            current = best.get(index)
            if current is None or (score, char_count, -segment_end) > (
                float(current.get("score", 0.0) or 0.0),
                int(current.get("char_count", 0) or 0),
                -float(current.get("segment_end", 0.0) or 0.0),
            ):
                best[index] = row
            uncertainty_seconds = max(0.0, segment_end - last_time)
            provenance: TailEvidenceProvenance | None = None
            scope: TailEvidenceScope | None = None
            if _whisperx_runtime_provenance_is_valid(runtime_provenance):
                assert isinstance(runtime_provenance, WhisperXRuntimeProvenance)
                model_identity = (
                    f"{runtime_provenance.align_model_id}@"
                    f"{runtime_provenance.align_model_revision}#"
                    f"{runtime_provenance.align_model_blob_sha256}"
                )
                helper_revision = _timing_content_digest({
                    "helper_sha256": runtime_provenance.helper_sha256,
                    "helper_protocol_revision": runtime_provenance.helper_protocol_revision,
                })
                transcript_revision = _timing_content_digest({
                    "raw_transcript_revision": runtime_provenance.raw_transcript_revision,
                    "entry_index": index,
                    "lyric_sha256": lyric_sha,
                    "occurrence_binding": occurrence_binding,
                })
                provenance = _make_tail_provenance(
                    entry_index=index,
                    tail_start=first_time,
                    tail_end=last_time,
                    uncertainty_seconds=uncertainty_seconds,
                    confidence=score,
                    producer="whisperx-forced-row",
                    backend_lineage=runtime_provenance.backend_lineage,
                    model_identity=model_identity,
                    helper_revision=helper_revision,
                    capability_revision=runtime_provenance.capability_revision,
                    audio_revision=runtime_provenance.alignment_wav_sha256,
                    transcript_revision=transcript_revision,
                    row_revision=revision,
                )
                if provenance is not None:
                    scope = TailEvidenceScope(
                        entry_index=index,
                        producer="whisperx-forced-row",
                        backend_lineage=runtime_provenance.backend_lineage,
                        model_identity=model_identity,
                        helper_revision=helper_revision,
                        capability_revision=runtime_provenance.capability_revision,
                        audio_revision=runtime_provenance.alignment_wav_sha256,
                        transcript_revisions=(transcript_revision,),
                        row_revisions=(revision,),
                    )
            source_revision = provenance.observation_revision if provenance is not None else revision
            if scope is not None:
                scope_records.setdefault((index, scope.producer), []).append(scope)
            tail_candidates.setdefault(index, []).append(
                IndependentTailEvidence(
                    entry_index=index,
                    tail_start=first_time,
                    tail_end=last_time,
                    uncertainty_seconds=uncertainty_seconds,
                    confidence=score,
                    producer="whisperx-forced-row",
                    source_revision=source_revision,
                    provenance=provenance,
                )
            )

    tails = _runtime_tail_observation_map(report)
    for index, candidates in tail_candidates.items():
        tails.setdefault(index, []).extend(candidates)

    report[_RUNTIME_WHISPERX_ROW_EVIDENCE_KEY] = best
    report[_RUNTIME_INDEPENDENT_TAIL_EVIDENCE_KEY] = _freeze_runtime_tail_observation_map(tails)
    scopes: dict[tuple[int, str], TailEvidenceScope] = {}
    for key, values in scope_records.items():
        first = values[0]
        if any(
            (
                item.backend_lineage != first.backend_lineage
                or item.model_identity != first.model_identity
                or item.helper_revision != first.helper_revision
                or item.audio_revision != first.audio_revision
            )
            for item in values[1:]
        ):
            continue
        scopes[key] = replace(first, **{
            "transcript_revisions": tuple(sorted({
                revision
                for item in values
                for revision in item.transcript_revisions
            })),
            "row_revisions": tuple(sorted({
                revision
                for item in values
                for revision in item.row_revisions
            })),
            "capability_revisions": tuple(sorted({
                item.capability_revision
                for item in values[1:]
            })),
        })
    report[_RUNTIME_WHISPERX_TAIL_SCOPES_KEY] = tuple(
        scopes[key]
        for key in sorted(scopes)
    )
    report["whisperx_row_evidence"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "minimum_score": TRUSTED_ALIGNMENT_SCORE,
        "candidate_count": len(best),
        "entries": [index + 1 for index in sorted(best)],
        "tail_evidence_count": len(tails),
    }



def bind_runtime_ctc_assignment_tail_fallback(
    report: dict[str, object],
    entries: list[LyricEntry],
) -> None:
    """Restore predecessor-tail geometry that would otherwise be lost after fusion.

    A selected Raw/WhisperX/onset-fusion candidate can legitimately carry no CTC
    spans even though the authoritative CTC assignment for the same immutable lyric
    row still contains usable terminal geometry.  Losing that geometry turns the
    next boundary into UNKNOWN for an implementation reason rather than an evidence
    reason.

    This is intentionally a *fallback*, not another independent backend vote:
    existing WhisperX row-tail evidence always wins.  The CTC row is admitted only
    when no distinct-backend runtime tail exists for that predecessor, and only when
    the normal ``derive_reliable_tail`` rules already classify its terminal run as
    valid.  No timestamp or tail limit is fabricated.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        return
    assert_lyric_identity_contract(entries, report, initialize=True)
    tails = _runtime_tail_observation_map(report)
    generated: list[int] = []
    for index, (entry, assignment) in enumerate(zip(entries, assignments)):
        if index in tails or not isinstance(assignment, dict):
            continue
        spans = _timing_spans_from_value(assignment.get("ctc_token_spans"))
        if len(spans) < 2:
            continue
        raw_time = assignment.get("timestamp")
        if not isinstance(raw_time, (int, float)) or not math.isfinite(float(raw_time)):
            continue
        lyric_sha = hashlib.sha256(
            normalize_match_text(entry_sung_text(entry)).encode("utf-8")
        ).hexdigest()
        span_payload = [
            [round(span.start, 6), round(span.end, 6), round(span.score, 8), span.token]
            for span in spans
        ]
        artifact = {
            "producer": "ctc-assignment-terminal-row",
            "entry_index": index,
            "lyric_sha256": lyric_sha,
            "timing_repair_source": assignment.get("timing_repair_source"),
            "ctc_audio_source": report.get("ctc_audio_source"),
            "ctc_audio_sha256": report.get("ctc_audio_sha256") or report.get("vocal_stem_sha256"),
            "spans_revision": _timing_content_digest(span_payload),
        }
        probe = make_timing_candidate(
            entry_index=index,
            entry_text=entry_sung_text(entry),
            source="ctc-assignment-tail-fallback",
            raw_time=float(raw_time),
            spans=spans,
            confidence=_candidate_confidence(assignment),
            identity_support="supported",
            sequence_support="supported",
            current=False,
            right_edge_pileup=bool(assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(
                assignment.get("ctc_right_edge_truncation")
                or assignment.get("ctc_boundary_realign_required")
            ),
            source_artifact=artifact,
        )
        tail = derive_reliable_tail(probe)
        if (
            tail.validity != "valid"
            or tail.reliable_tail_start is None
            or tail.reliable_tail_end is None
        ):
            continue
        payload = {
            **artifact,
            "tail_start": round(tail.reliable_tail_start, 6),
            "tail_end": round(tail.reliable_tail_end, 6),
            "uncertainty_seconds": round(float(tail.uncertainty_seconds or 0.0), 6),
            "confidence": round(float(tail.confidence or 0.0), 6),
            "tail_evidence_revision": tail.tail_evidence_revision,
        }
        entry_index = index
        tail_start = float(tail.reliable_tail_start)
        tail_end = float(tail.reliable_tail_end)
        uncertainty_seconds = max(0.0, float(tail.uncertainty_seconds or 0.0))
        confidence = _finite_unit_confidence(tail.confidence or 0.0)
        capability = report.get(_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY)
        if isinstance(capability, BoundedRetryCapability):
            backend_lineage = capability.backend_lineage
            model_identity = capability.model_identity
            helper_revision = _tail_helper_revision(
                capability.helper_sha256,
                capability.helper_protocol_revision,
            )
            capability_revision = capability.capability_revision
            audio_revision = capability.alignment_audio_sha256
        else:
            backend_lineage = str(report.get("backend_lineage") or "")
            model_identity = str(report.get("model_identity") or "")
            helper_revision = str(report.get("helper_revision") or "")
            capability_revision = str(report.get("capability_revision") or "")
            audio_revision = str(
                report.get("ctc_audio_sha256") or report.get("vocal_stem_sha256") or ""
            )
        provenance = _make_tail_provenance(
            entry_index=entry_index,
            tail_start=tail_start,
            tail_end=tail_end,
            uncertainty_seconds=uncertainty_seconds,
            confidence=confidence,
            producer="ctc-assignment-terminal-row",
            backend_lineage=backend_lineage,
            model_identity=model_identity,
            helper_revision=helper_revision,
            capability_revision=capability_revision,
            audio_revision=audio_revision,
            transcript_revision=lyric_sha,
            row_revision=_timing_content_digest(span_payload),
        )
        source_revision = (
            provenance.observation_revision
            if provenance is not None else _timing_content_digest(payload)
        )
        observation = IndependentTailEvidence(
            entry_index=entry_index,
            tail_start=tail_start,
            tail_end=tail_end,
            uncertainty_seconds=uncertainty_seconds,
            confidence=confidence,
            producer="ctc-assignment-terminal-row",
            source_revision=source_revision,
            provenance=provenance,
        )
        tails.setdefault(index, []).append(observation)
        generated.append(index + 1)
    report[_RUNTIME_INDEPENDENT_TAIL_EVIDENCE_KEY] = _freeze_runtime_tail_observation_map(tails)
    report["ctc_assignment_tail_fallback"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "role": "fallback-only-when-distinct-backend-tail-missing",
        "candidate_count": len(generated),
        "entries": generated,
    }


def _augment_local_ctc_candidates_with_runtime_backend_consensus(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    report: dict[str, object],
    entries: list[LyricEntry],
) -> tuple[tuple[TimingCandidate, ...], ...]:
    """Extend existing cross-backend onset proof to local/retry CTC candidates.

    v14.2 could bind Raw/WhisperX identity only to the baseline ``ctc-current``
    time.  A bounded local CTC retry may produce a better lyric-specific opening,
    yet remain unable to use the same independent backend observation.  This
    helper closes only that provenance gap.  It reuses the existing 0.18 s
    consensus tolerance and keeps the CTC candidate's existing timestamp; no
    averaging or synthetic boundary is introduced.
    """
    local_sources = {"ctc-local-window", "ctc-opening-local-retry"}
    augmented: list[tuple[TimingCandidate, ...]] = []
    for index, items in enumerate(candidate_sets):
        rows = list(items)
        raw_identity = runtime_raw_content_identity_for_entry(report, entries, index)
        whisperx_row = runtime_whisperx_row_evidence_for_entry(report, entries, index)
        for parent in items:
            if (
                parent.source not in local_sources
                or not parent.spans
                or parent.right_edge_pileup
                or parent.window_truncated
            ):
                continue
            backend_rows: list[tuple[str, float, float, str, str]] = []
            if isinstance(raw_identity, dict):
                try:
                    raw_time = float(raw_identity.get("raw_time"))
                    raw_score = float(raw_identity.get("raw_score"))
                except (TypeError, ValueError):
                    raw_time = math.nan
                    raw_score = 0.0
                if (
                    math.isfinite(raw_time)
                    and raw_score >= RAW_CTC_CONSENSUS_MIN_SCORE
                    and abs(raw_time - parent.written_time.seconds)
                    <= RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
                ):
                    backend_rows.append((
                        "raw", raw_time, raw_score,
                        str(raw_identity.get("evidence_revision") or ""),
                        "raw-asr-consensus",
                    ))
            if isinstance(whisperx_row, dict):
                try:
                    forced_time = float(whisperx_row.get("first_char_time"))
                    whisperx_score = float(whisperx_row.get("score"))
                except (TypeError, ValueError):
                    forced_time = math.nan
                    whisperx_score = 0.0
                if (
                    math.isfinite(forced_time)
                    and whisperx_score >= TRUSTED_ALIGNMENT_SCORE
                    and abs(forced_time - parent.written_time.seconds)
                    <= RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
                ):
                    backend_rows.append((
                        "whisperx", forced_time, whisperx_score,
                        str(whisperx_row.get("evidence_revision") or ""),
                        "whisperx-consensus",
                    ))
            for label, independent_time, independent_score, evidence_revision, producer in backend_rows:
                identity_evidence = (
                    raw_identity if label == "raw" else whisperx_row
                )
                occurrence_evidence = candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer=producer,
                    occurrence_binding=(
                        identity_evidence.get("occurrence_binding")
                        if isinstance(identity_evidence, dict) else None
                    ),
                    upstream_evidence_revision=(
                        identity_evidence.get("evidence_revision")
                        if isinstance(identity_evidence, dict) else None
                    ),
                )
                artifact = {
                    "producer": f"ctc-local-{label}-consensus",
                    "parent_candidate_id": parent.candidate_id,
                    "parent_generation_revision": parent.generation_revision,
                    "parent_time": round(parent.written_time.seconds, 6),
                    "independent_time": round(independent_time, 6),
                    "independent_score": round(independent_score, 6),
                    "independent_evidence_revision": evidence_revision,
                    "consensus_tolerance_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
                    "runtime_only": True,
                }
                rows.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entries[index]),
                        source=f"ctc-local-{label}-independent-consensus",
                        raw_time=parent.written_time.seconds,
                        spans=parent.spans,
                        confidence=min(parent.confidence, independent_score),
                        identity_support="supported",
                        sequence_support="supported",
                        acoustic_support="unavailable",
                        direct_onset_support="supported",
                        direct_onset_time=independent_time,
                        direct_onset_source_artifact=artifact,
                        direct_onset_evidence_producer=producer,
                        direct_onset_evidence_kind="cross-backend-onset",
                        direct_onset_evidence_independent=True,
                        occurrence_evidence=occurrence_evidence,
                        independent_content_identity=occurrence_evidence is not None,
                        current=False,
                        source_artifact=artifact,
                    )
                )
        unique = {candidate.candidate_id: candidate for candidate in rows}
        augmented.append(tuple(unique[key] for key in sorted(unique)))
    return tuple(augmented)


def _augment_candidates_with_joint_boundary_consensus(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    pair_outcomes: tuple[CrossLineRetryOutcome, ...],
    entries: list[LyricEntry],
) -> tuple[tuple[TimingCandidate, ...], ...]:
    """Bind joint previous+current CTC boundary observations to separate candidates.

    The pair observation is deliberately not selectable by itself.  It may only
    certify a separately generated current-line candidate when both boundaries
    converge within the already-established 0.18 s consensus tolerance.

    This is stronger than generic acoustic activity: the observation explicitly
    aligns the immutable previous lyric and current lyric in one CTC sequence,
    and the selected timestamp still comes from an independent candidate
    generation path rather than from the pair observation.
    """
    by_entry: dict[int, list[TimingCandidate]] = collections.defaultdict(list)
    for outcome in pair_outcomes:
        candidate = outcome.candidate
        if (
            outcome.status != "candidate"
            or candidate is None
            or candidate.source != "ctc-joint-boundary-observation"
            or candidate.window_truncated
            or candidate.right_edge_pileup
            or not candidate.spans
        ):
            continue
        by_entry[outcome.entry_index].append(candidate)

    augmented: list[tuple[TimingCandidate, ...]] = []
    for index, items in enumerate(candidate_sets):
        rows = list(items)
        observations = by_entry.get(index, [])
        if observations:
            for parent in items:
                if (
                    parent.source.startswith("ctc-joint-boundary")
                    or parent.window_truncated
                    or parent.right_edge_pileup
                    or parent.identity_support != "supported"
                    or parent.sequence_support != "supported"
                ):
                    continue
                for observation in observations:
                    if (
                        abs(
                            observation.written_time.seconds
                            - parent.written_time.seconds
                        )
                        > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
                    ):
                        continue
                    artifact = {
                        "producer": "joint-ctc-boundary-consensus",
                        "parent_candidate_id": parent.candidate_id,
                        "parent_generation_revision": parent.generation_revision,
                        "parent_time": round(parent.written_time.seconds, 6),
                        "pair_candidate_id": observation.candidate_id,
                        "pair_generation_revision": observation.generation_revision,
                        "pair_time": round(observation.written_time.seconds, 6),
                        "pair_span_digest": _timing_content_digest([
                            [
                                round(span.start, 6),
                                round(span.end, 6),
                                round(span.score, 8),
                                span.token,
                            ]
                            for span in observation.spans
                        ]),
                        "consensus_tolerance_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
                        "runtime_only": True,
                    }
                    rows.append(
                        make_timing_candidate(
                            entry_index=index,
                            entry_text=entry_sung_text(entries[index]),
                            source="ctc-joint-boundary-consensus",
                            raw_time=parent.written_time.seconds,
                            spans=parent.spans,
                            confidence=min(parent.confidence, observation.confidence),
                            identity_support="supported",
                            sequence_support="supported",
                            acoustic_support=parent.acoustic_support,
                            direct_onset_support="supported",
                            acoustic_strength=parent.acoustic_strength,
                            acoustic_onset_time=(
                                parent.acoustic_evidence.onset_time
                                if parent.acoustic_evidence is not None else None
                            ),
                            acoustic_source_artifact=(
                                {
                                    "parent_acoustic_revision":
                                        parent.acoustic_evidence.source_revision
                                }
                                if parent.acoustic_evidence is not None else None
                            ),
                            acoustic_evidence_producer=(
                                parent.acoustic_evidence.producer
                                if parent.acoustic_evidence is not None else None
                            ),
                            acoustic_evidence_kind=(
                                parent.acoustic_evidence.kind
                                if parent.acoustic_evidence is not None
                                else "generic-acoustic"
                            ),
                            acoustic_evidence_independent=(
                                parent.acoustic_evidence.independent
                                if parent.acoustic_evidence is not None else False
                            ),
                            direct_onset_time=observation.written_time.seconds,
                            direct_onset_source_artifact=artifact,
                            direct_onset_evidence_producer="joint-ctc-boundary-consensus",
                            direct_onset_evidence_kind="joint-lyric-boundary",
                            direct_onset_evidence_independent=True,
                            occurrence_evidence=parent.occurrence_evidence,
                            independent_content_identity=(
                                parent.independent_content_identity
                                and parent.occurrence_evidence is not None
                            ),
                            current=False,
                            prefix_scope=parent.prefix_scope,
                            source_artifact=artifact,
                        )
                    )
        unique = {candidate.candidate_id: candidate for candidate in rows}
        augmented.append(tuple(unique[key] for key in sorted(unique)))
    return tuple(augmented)


def runtime_whisperx_row_evidence_for_entry(
    report: dict[str, object],
    entries: list[LyricEntry],
    entry_index: int,
) -> dict[str, object] | None:
    runtime = report.get(_RUNTIME_WHISPERX_ROW_EVIDENCE_KEY)
    if not isinstance(runtime, dict):
        return None
    evidence = runtime.get(entry_index)
    if not isinstance(evidence, dict):
        return None
    lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entries[entry_index])).encode("utf-8")
    ).hexdigest()
    try:
        score = float(evidence.get("score"))
        segment_start = float(evidence.get("segment_start"))
        segment_end = float(evidence.get("segment_end"))
        first_time = float(evidence.get("first_char_time"))
        last_time = float(evidence.get("last_char_time"))
        char_count = int(evidence.get("char_count", 0) or 0)
    except (TypeError, ValueError):
        return None
    payload = {
        "entry_index": entry_index,
        "lyric_sha256": lyric_sha,
        "score": round(score, 6),
        "segment": evidence.get("segment"),
        "segment_start": round(segment_start, 6),
        "segment_end": round(segment_end, 6),
        "first_char_time": round(first_time, 6),
        "last_char_time": round(last_time, 6),
        "char_count": char_count,
        "suppress_nst": bool(evidence.get("suppress_nst")),
        "occurrence_binding": evidence.get("occurrence_binding"),
        "producer": "whisperx-row-evidence",
    }
    if (
        evidence.get("producer") != "whisperx-row-evidence"
        or evidence.get("lyric_sha256") != lyric_sha
        or score < TRUSTED_ALIGNMENT_SCORE
        or not _runtime_occurrence_binding_is_valid(
            entries, entry_index, evidence.get("occurrence_binding")
        )
        or char_count <= 0
        or segment_end < segment_start
        or not (segment_start - HOP_SECONDS <= first_time <= segment_end + HOP_SECONDS)
        or not (first_time - HOP_SECONDS <= last_time <= segment_end + HOP_SECONDS)
        or evidence.get("evidence_revision") != _timing_content_digest(payload)
    ):
        return None
    return dict(evidence)


def runtime_independent_content_identity_sources_for_entry(
    report: dict[str, object],
    entry_index: int,
) -> tuple[str, ...]:
    """Return validated runtime-only content identity sources for one lyric row.

    Content identity is intentionally orthogonal to timestamp evidence.  Raw ASR
    or WhisperX may prove *which lyric occurrence* this row is even when their
    onset estimate is too far from the selected timing candidate to participate
    in timing consensus.  Existing occurrence binding, lyric digest, score and
    evidence-revision validation remains mandatory via the canonical accessors.
    """
    entries = report.get(_RUNTIME_LYRIC_ENTRIES_KEY)
    if not isinstance(entries, tuple) or not entries:
        return ()
    if not 0 <= entry_index < len(entries) or not all(isinstance(item, LyricEntry) for item in entries):
        return ()
    lyric_entries = list(entries)
    sources: list[str] = []
    if runtime_raw_content_identity_for_entry(report, lyric_entries, entry_index) is not None:
        sources.append("raw-asr-content-identity")
    if runtime_whisperx_row_evidence_for_entry(report, lyric_entries, entry_index) is not None:
        sources.append("whisperx-row-evidence")
    if runtime_local_whisper_evidence_for_entry(report, lyric_entries, entry_index) is not None:
        sources.append("local-whisper-aligner")
    return tuple(sorted(sources))


def runtime_content_identity_projection(report: dict[str, object]) -> list[dict[str, object]]:
    """Canonical digestable projection of runtime content evidence used by central trust."""
    entries = report.get(_RUNTIME_LYRIC_ENTRIES_KEY)
    if not isinstance(entries, tuple):
        return []
    projected: list[dict[str, object]] = []
    raw_runtime = report.get(_RUNTIME_RAW_CONTENT_IDENTITY_KEY)
    whisper_runtime = report.get(_RUNTIME_WHISPERX_ROW_EVIDENCE_KEY)
    local_whisper_runtime = report.get(_RUNTIME_LOCAL_WHISPER_EVIDENCE_KEY)
    for index in range(len(entries)):
        sources = runtime_independent_content_identity_sources_for_entry(report, index)
        if not sources:
            continue
        revisions: dict[str, str] = {}
        if "raw-asr-content-identity" in sources and isinstance(raw_runtime, dict):
            item = raw_runtime.get(index)
            if isinstance(item, dict):
                revisions["raw-asr-content-identity"] = str(item.get("evidence_revision") or "")
        if "whisperx-row-evidence" in sources and isinstance(whisper_runtime, dict):
            item = whisper_runtime.get(index)
            if isinstance(item, dict):
                revisions["whisperx-row-evidence"] = str(item.get("evidence_revision") or "")
        if "local-whisper-aligner" in sources and isinstance(local_whisper_runtime, dict):
            item = local_whisper_runtime.get(index)
            if isinstance(item, dict):
                revisions["local-whisper-aligner"] = str(item.get("evidence_revision") or "")
        projected.append({
            "entry": index + 1,
            "sources": list(sources),
            "evidence_revisions": dict(sorted(revisions.items())),
        })
    return projected


def runtime_independent_tail_evidence(
    report: dict[str, object],
    count: int,
    tail_evidence_context: TailEvidenceContext | tuple[TailEvidenceContext, ...] | None = None,
) -> RuntimeTailEvidence:
    if tail_evidence_context is None:
        tail_evidence_context = _tail_evidence_context_from_report(report)
    runtime = _runtime_tail_observation_map(report)
    rows: list[TailObservationSet | None] = []
    for index in range(count):
        observations = tuple(
            item for item in runtime.get(index, [])
            if _runtime_tail_observation_is_current(
                report, item, tail_evidence_context
            )
        )
        rows.append(observations or None)
    return tuple(rows)


def _runtime_tail_observation_map(
    report: dict[str, object],
) -> dict[int, list[IndependentTailEvidence]]:
    runtime = report.get(_RUNTIME_INDEPENDENT_TAIL_EVIDENCE_KEY)
    if not isinstance(runtime, dict):
        return {}
    normalized: dict[int, list[IndependentTailEvidence]] = {}
    for raw_index, value in runtime.items():
        try:
            index = int(raw_index)
        except (TypeError, ValueError):
            continue
        if isinstance(value, IndependentTailEvidence):
            values = (value,)
        elif isinstance(value, (tuple, list)):
            values = tuple(item for item in value if isinstance(item, IndependentTailEvidence))
        else:
            values = ()
        if values:
            normalized.setdefault(index, []).extend(values)
    return normalized


def _freeze_runtime_tail_observation_map(
    observations: dict[int, list[IndependentTailEvidence]],
) -> dict[int, TailObservationSet]:
    frozen: dict[int, TailObservationSet] = {}
    for index, values in observations.items():
        unique: dict[str, IndependentTailEvidence] = {}
        for item in values:
            revision = (
                item.provenance.observation_revision
                if item.provenance is not None
                else item.source_revision
            )
            unique.setdefault(revision, item)
        if unique:
            frozen[index] = tuple(
                unique[key]
                for key in sorted(unique)
            )
    return frozen


def _runtime_tail_observation_is_current(
    report: dict[str, object],
    evidence: IndependentTailEvidence,
    tail_evidence_context: TailEvidenceContext | tuple[TailEvidenceContext, ...] | None = None,
) -> bool:
    if not _tail_provenance_is_valid(evidence):
        return False
    # Without a central context the observation may be inspected as a
    # diagnostic, but it must not be mistaken for authority.  The resolver
    # independently fails closed when this context is absent.
    if tail_evidence_context is None:
        return True
    if not _tail_provenance_matches_context(evidence, tail_evidence_context):
        return False
    provenance = evidence.provenance
    assert provenance is not None
    # A peer bundle validates each observation against its originating context.
    # There is no single report capability that can safely stand in for those
    # multiple executions, so the exact context match is the authority check.
    if isinstance(tail_evidence_context, tuple):
        return True
    if _tail_backend_family(provenance.backend_lineage) != "ctc":
        return True
    capability = report.get(_RUNTIME_BOUNDED_RETRY_CAPABILITY_KEY)
    if not isinstance(capability, BoundedRetryCapability):
        return False
    expected_context = {
        "backend_lineage": capability.backend_lineage,
        "model_identity": capability.model_identity,
        "helper_revision": _tail_helper_revision(
            capability.helper_sha256,
            capability.helper_protocol_revision,
        ),
        "capability_revision": capability.capability_revision,
        "audio_revision": capability.alignment_audio_sha256,
    }
    return _tail_provenance_is_valid(evidence, expected_context)


def merge_runtime_independent_tail_evidence(
    report: dict[str, object],
    evidence: IndependentTailEvidence | None,
) -> bool:
    """Append one immutable observation without cross-lineage replacement."""
    if evidence is None or evidence.entry_index < 0:
        return False
    merged = _runtime_tail_observation_map(report)
    before = _freeze_runtime_tail_observation_map(merged)
    merged.setdefault(evidence.entry_index, []).append(evidence)
    after = _freeze_runtime_tail_observation_map(merged)
    report[_RUNTIME_INDEPENDENT_TAIL_EVIDENCE_KEY] = after
    return before != after


def _independent_tail_evidence_payload(
    evidence: IndependentTailEvidence | None,
) -> dict[str, object] | None:
    if evidence is None:
        return None
    payload: dict[str, object] = {
        "entry_index": evidence.entry_index,
        "tail_start": round(evidence.tail_start, 6),
        "tail_end": round(evidence.tail_end, 6),
        "uncertainty_seconds": round(evidence.uncertainty_seconds, 6),
        "confidence": round(evidence.confidence, 6),
        "producer": evidence.producer,
        "source_revision": evidence.source_revision,
    }
    if evidence.provenance is None:
        payload["provenance_status"] = "missing"
        payload["authority_level"] = "DIAGNOSTIC_ONLY"
        payload["rejection_reason"] = "missing-tail-provenance"
    elif _tail_provenance_is_valid(evidence):
        payload["provenance_status"] = "valid"
        payload["authority_level"] = "PENDING_PREDECESSOR_LINEAGE_CHECK"
        payload["provenance"] = {
            **_tail_provenance_payload(evidence.provenance),
            "observation_revision": evidence.provenance.observation_revision,
        }
    else:
        payload["provenance_status"] = "invalid"
        payload["authority_level"] = "DIAGNOSTIC_ONLY"
        payload["rejection_reason"] = "invalid-tail-provenance"
    return payload


def independent_tail_evidence_payload(
    evidence: RuntimeTailEvidence | tuple[IndependentTailEvidence | None, ...],
) -> list[object]:
    payload: list[object] = []
    for item in evidence:
        observations = _normalize_tail_observations(item)  # type: ignore[arg-type]
        if not observations:
            payload.append(None)
        elif len(observations) == 1:
            payload.append(_independent_tail_evidence_payload(observations[0]))
        else:
            payload.append([
                _independent_tail_evidence_payload(observation)
                for observation in observations
            ])
    return payload


def _candidate_set_semantic_revision(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
) -> str:
    return _timing_content_digest([
        sorted(candidate.candidate_id for candidate in candidates)
        for candidates in candidate_sets
    ])


def _authoritative_tail_semantic_revision(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    independent_tail_evidence: RuntimeTailEvidence,
    tail_evidence_context: TailEvidenceContext | tuple[TailEvidenceContext, ...] | None = None,
) -> str:
    if len(candidate_sets) != len(independent_tail_evidence):
        return _timing_content_digest({"invalid_length": True})
    try:
        state = build_final_timing_state(
            candidate_sets,
            independent_tail_evidence=independent_tail_evidence,
            tail_evidence_context=tail_evidence_context,
        )
    except (TypeError, ValueError):
        return _timing_content_digest({"invalid_state": True})
    return _timing_content_digest([
        {
            "entry_index": decision.entry_index,
            "ownership_status": decision.evidence.ownership.status,
            "tail_revision": decision.evidence.referenced_tail_evidence_revision,
            "tail_validity": decision.evidence.ownership.previous_tail_validity,
            "tail_end": decision.evidence.ownership.reliable_tail_end,
            "tail_uncertainty": decision.evidence.ownership.uncertainty_seconds,
        }
        for decision in state.decisions
        if decision.entry_index > 0
    ])


def _retry_semantic_state_revision(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    independent_tail_evidence: RuntimeTailEvidence,
    tail_evidence_context: TailEvidenceContext | tuple[TailEvidenceContext, ...] | None = None,
) -> tuple[str, str]:
    return (
        _candidate_set_semantic_revision(candidate_sets),
        _authoritative_tail_semantic_revision(
            candidate_sets, independent_tail_evidence, tail_evidence_context
        ),
    )


def _tail_authority_diagnostics(
    candidate_sets: tuple[tuple[TimingCandidate, ...], ...],
    independent_tail_evidence: RuntimeTailEvidence,
    tail_evidence_context: TailEvidenceContext | tuple[TailEvidenceContext, ...] | None = None,
) -> list[dict[str, object]]:
    """Explain Contract-A acceptance/rejection without adding trust logic."""
    if len(candidate_sets) != len(independent_tail_evidence):
        return []
    try:
        state = build_final_timing_state(
            candidate_sets,
            independent_tail_evidence=independent_tail_evidence,
            tail_evidence_context=tail_evidence_context,
        )
    except (TypeError, ValueError):
        return []
    rows: list[dict[str, object]] = []
    for index, observations in enumerate(independent_tail_evidence):
        if not observations or index >= len(state.decisions):
            continue
        predecessor = state.decisions[index].candidate
        families = sorted(_candidate_support_families(predecessor))
        authoritative = _authoritative_tail_observations(
            predecessor, observations, tail_evidence_context
        )
        selected = authoritative[0] if authoritative else None
        intrinsic = derive_reliable_tail(predecessor)
        intrinsic_upper = (
            intrinsic.reliable_tail_end + (intrinsic.uncertainty_seconds or 0.0)
            if intrinsic.validity == "valid" and intrinsic.reliable_tail_end is not None
            else None
        )
        for observation in observations:
            provenance = observation.provenance
            family = _tail_backend_family(provenance.backend_lineage if provenance else None)
            if not _tail_provenance_is_valid(observation):
                authority, reason = "DIAGNOSTIC_ONLY", "invalid-or-missing-provenance"
            elif not _tail_contexts_are_valid(tail_evidence_context):
                authority, reason = "DIAGNOSTIC_ONLY", "missing-tail-evidence-context"
            elif not _tail_provenance_matches_context(observation, tail_evidence_context):
                authority, reason = "DIAGNOSTIC_ONLY", "stale-tail-evidence-context"
            elif not families:
                authority, reason = "REJECTED", "unknown-predecessor-support-family"
            elif family in families:
                authority, reason = "REJECTED", "same-lineage-overlap"
            elif selected is not observation:
                authority, reason = "VALID_NONSELECTED", "another-disjoint-bound-dominates"
            elif intrinsic_upper is not None and intrinsic_upper >= (
                observation.tail_end + observation.uncertainty_seconds
            ):
                authority, reason = "VALID_NONSELECTED", "intrinsic-bound-dominates"
            else:
                authority, reason = "ACCEPTED", "disjoint-lineage-authoritative-bound"
            rows.append({
                "entry": index + 1,
                "producer": observation.producer,
                "backend_lineage": provenance.backend_lineage if provenance else None,
                "candidate_source": predecessor.source,
                "candidate_support_families": families,
                "authority": authority,
                "reason": reason,
                "observation_revision": observation.source_revision,
                "tail_start": round(observation.tail_start, 6),
                "tail_end": round(observation.tail_end, 6),
                "uncertainty_seconds": round(observation.uncertainty_seconds, 6),
            })
    return rows


def bind_runtime_whisperx_ctc_consensus(
    report: dict[str, object],
    entries: list[LyricEntry],
    ctc_timestamps: list[float],
    evidence_candidates: list[tuple[list[float], dict[str, object], str]],
) -> None:
    """Preserve line-valid WhisperX evidence even when the backend fails globally."""
    best: dict[int, dict[str, object]] = {}
    for _candidate_times, candidate_report, _error in evidence_candidates:
        assignments = candidate_report.get("assignments")
        forced_times = candidate_report.get("whisperx_forced_first_times")
        if not isinstance(assignments, list) or not isinstance(forced_times, list):
            continue
        if len(assignments) != len(entries) or len(forced_times) != len(entries):
            continue
        suppress_nst = bool(candidate_report.get("whisper_suppress_nst"))
        for index, (assignment, forced_value) in enumerate(zip(assignments, forced_times)):
            if not isinstance(assignment, dict):
                continue
            occurrence_binding = _entry_occurrence_binding(entries, assignments, index)
            if occurrence_binding is None:
                continue
            try:
                score = float(assignment.get("score", 0.0) or 0.0)
                forced_time = float(forced_value)
                ctc_time = float(ctc_timestamps[index])
            except (TypeError, ValueError, IndexError):
                continue
            if (
                score < TRUSTED_ALIGNMENT_SCORE
                or bool(assignment.get("borrowed"))
                or assignment.get("segment") is None
                or not math.isfinite(forced_time)
                or abs(forced_time - ctc_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
            ):
                continue
            lyric_sha = hashlib.sha256(
                normalize_match_text(entry_sung_text(entries[index])).encode("utf-8")
            ).hexdigest()
            payload = {
                "entry_index": index,
                "lyric_sha256": lyric_sha,
                "whisperx_forced_time": round(forced_time, 6),
                "ctc_time": round(ctc_time, 6),
                "score": round(score, 6),
                "segment": assignment.get("segment"),
                "suppress_nst": suppress_nst,
                "occurrence_binding": occurrence_binding,
                "producer": "whisperx-consensus",
            }
            row = {**payload, "evidence_revision": _timing_content_digest(payload)}
            current = best.get(index)
            if current is None or (score, -abs(forced_time - ctc_time)) > (
                float(current.get("score", 0.0) or 0.0),
                -abs(float(current.get("whisperx_forced_time", 0.0)) - ctc_time),
            ):
                best[index] = row
    report[_RUNTIME_WHISPERX_CTC_CONSENSUS_KEY] = best
    report["whisperx_ctc_onset_consensus"] = {
        "status": "runtime-evidence-generated",
        "authoritative_serialized": False,
        "minimum_score": TRUSTED_ALIGNMENT_SCORE,
        "max_delta_seconds": PREFIX_ACOUSTIC_ASSOCIATION_SECONDS,
        "candidate_count": len(best),
        "entries": [index + 1 for index in sorted(best)],
    }


def runtime_whisperx_ctc_consensus_for_entry(
    report: dict[str, object],
    entries: list[LyricEntry],
    entry_index: int,
    current_time: float,
) -> dict[str, object] | None:
    runtime = report.get(_RUNTIME_WHISPERX_CTC_CONSENSUS_KEY)
    if not isinstance(runtime, dict):
        return None
    evidence = runtime.get(entry_index)
    if not isinstance(evidence, dict):
        return None
    try:
        forced_time = float(evidence.get("whisperx_forced_time"))
        ctc_time = float(evidence.get("ctc_time"))
        score = float(evidence.get("score"))
    except (TypeError, ValueError):
        return None
    lyric_sha = hashlib.sha256(
        normalize_match_text(entry_sung_text(entries[entry_index])).encode("utf-8")
    ).hexdigest()
    payload = {
        "entry_index": entry_index,
        "lyric_sha256": lyric_sha,
        "whisperx_forced_time": round(forced_time, 6),
        "ctc_time": round(ctc_time, 6),
        "score": round(score, 6),
        "segment": evidence.get("segment"),
        "suppress_nst": bool(evidence.get("suppress_nst")),
        "occurrence_binding": evidence.get("occurrence_binding"),
        "producer": "whisperx-consensus",
    }
    if (
        evidence.get("producer") != "whisperx-consensus"
        or score < TRUSTED_ALIGNMENT_SCORE
        or evidence.get("lyric_sha256") != lyric_sha
        or not _runtime_occurrence_binding_is_valid(
            entries, entry_index, evidence.get("occurrence_binding")
        )
        or abs(forced_time - ctc_time) > PREFIX_ACOUSTIC_ASSOCIATION_SECONDS
        or canonicalize_lrc_time(ctc_time).centiseconds
        != canonicalize_lrc_time(current_time).centiseconds
        or evidence.get("evidence_revision") != _timing_content_digest(payload)
    ):
        return None
    return dict(evidence)


def runtime_raw_ctc_consensus_for_entry(
    report: dict[str, object],
    entries: list[LyricEntry],
    entry_index: int,
    current_time: float,
) -> dict[str, object] | None:
    """Return fresh in-process raw/CTC onset agreement for one entry.

    The authority is deliberately non-serializable and is re-bound to the
    current CTC timestamp.  This prevents stale report metadata from being used
    as independent evidence on another run or after the baseline moved.
    """
    if str(report.get("backend") or "") != "ctc":
        return None
    runtime = report.get(_RUNTIME_RAW_CTC_CONSENSUS_KEY)
    if not isinstance(runtime, dict):
        return None
    evidence = runtime.get(entry_index)
    if not isinstance(evidence, dict):
        return None
    try:
        raw_time = float(evidence.get("raw_time"))
        ctc_time = float(evidence.get("ctc_time"))
        raw_score = float(evidence.get("raw_score"))
        max_delta = float(evidence.get("max_delta_seconds"))
    except (TypeError, ValueError):
        return None
    if (
        evidence.get("producer") != "raw-asr-consensus"
        or raw_score < RAW_CTC_CONSENSUS_MIN_SCORE
        or abs(max_delta - RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS) > 1e-9
        or abs(raw_time - ctc_time) > RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
        or canonicalize_lrc_time(ctc_time).centiseconds
        != canonicalize_lrc_time(current_time).centiseconds
    ):
        return None
    payload = {
        "entry_index": entry_index,
        "raw_time": round(raw_time, 6),
        "ctc_time": round(ctc_time, 6),
        "raw_score": round(raw_score, 6),
        "max_delta_seconds": RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS,
        "occurrence_binding": evidence.get("occurrence_binding"),
        "producer": "raw-asr-consensus",
    }
    if (
        not _runtime_occurrence_binding_is_valid(
            entries, entry_index, evidence.get("occurrence_binding")
        )
        or evidence.get("evidence_revision") != _timing_content_digest(payload)
    ):
        return None
    return dict(evidence)


def collect_central_timing_candidates(
    audio_path: Path,
    entries: list[LyricEntry],
    scratch_timestamps: list[float],
    report: dict[str, object],
    duration: float,
    args: argparse.Namespace,
    independent_evidence_audio_path: Path | None = None,
    retry_helper_cache: dict[str, tuple[str, object]] | None = None,
    vocal_onset_features: AudioFeatures | None = None,
) -> tuple[tuple[tuple[TimingCandidate, ...], ...], dict[str, object]]:
    """Collect immutable candidates without mutating final timing state.

    Inactive legacy boundary helpers are not called or imported here.
    """
    assignments = report.get("assignments")
    if not isinstance(assignments, list) or len(assignments) != len(entries):
        raise LrcError("Central timing finalizer requires one assignment per lyric entry")
    # Runtime-only immutable lyric objects are retained so content identity can
    # be validated independently from timing provenance during central summary
    # and commit.  This key is explicitly excluded from serialized reports.
    report[_RUNTIME_LYRIC_ENTRIES_KEY] = tuple(entries)
    assert_lyric_identity_contract(entries, report, initialize=True)

    # The legacy prefix guard remains available for historical diagnostics, but
    # it is not executed by production candidate generation and contributes no
    # candidate, trusted bit, recovery, or flag clearing.
    evidence_audio_path = independent_evidence_audio_path or audio_path
    fusion_audio_revision: str | None = None
    if vocal_onset_features is not None:
        try:
            fusion_audio_revision = _path_sha256(evidence_audio_path)
        except (OSError, LrcError):
            fusion_audio_revision = None
    candidate_sets: list[tuple[TimingCandidate, ...]] = []
    for index, (entry, raw_assignment) in enumerate(zip(entries, assignments)):
        if not isinstance(raw_assignment, dict):
            raise LrcError(f"Central timing finalizer received invalid assignment {index + 1}")
        # Re-bind the immutable backend baseline instead of trusting a scratch
        # timestamp that a pre-central heuristic may have shifted.  Legacy
        # scoring preserves the backend-selected path as a candidate row.
        baseline_time: float | None = None
        legacy_rows = raw_assignment.get("candidates")
        if isinstance(legacy_rows, list):
            for row in legacy_rows:
                if not isinstance(row, dict) or row.get("source") != "selected_path":
                    continue
                value = row.get("time")
                if isinstance(value, (int, float)) and math.isfinite(float(value)):
                    baseline_time = float(value)
                    break
        if baseline_time is None:
            raw_value = raw_assignment.get("timestamp", scratch_timestamps[index])
            baseline_time = float(raw_value if isinstance(raw_value, (int, float)) else scratch_timestamps[index])
        current_time = baseline_time
        spans = _timing_spans_from_value(raw_assignment.get("ctc_token_spans"))
        backend = str(report.get("backend") or "unknown")
        manual = bool(raw_assignment.get("manual_anchor_hint"))
        if manual:
            manual_value = raw_assignment.get("timestamp", scratch_timestamps[index])
            if isinstance(manual_value, (int, float)) and math.isfinite(float(manual_value)):
                current_time = float(manual_value)
            current_source = "manual-anchor"
        elif backend == "ctc":
            current_source = "ctc-current"
        elif backend == "whisperx":
            current_source = "whisperx-word"
        elif backend in {"lyrics", "checked_lrc"}:
            current_source = "checked-lrc" if backend == "checked_lrc" else "lyrics-source"
        else:
            current_source = f"{backend}-current"
        score = _candidate_confidence(raw_assignment)
        explicit_source = current_source in {"manual-anchor", "checked-lrc", "lyrics-source"}
        ctc_identity = bool(spans)
        aligned_non_ctc = backend == "whisperx" and score >= TRUSTED_ALIGNMENT_SCORE
        current_source_artifact = {
            "backend": backend,
            "timing_repair_source": raw_assignment.get("timing_repair_source"),
            "ctc_local_window": raw_assignment.get("ctc_local_window"),
            "spans": raw_assignment.get("ctc_token_spans"),
            "timestamp": current_time,
        }
        current_candidate = make_timing_candidate(
            entry_index=index,
            entry_text=entry_sung_text(entry),
            source=current_source,
            raw_time=current_time,
            spans=spans,
            confidence=score,
            identity_support="supported" if ctc_identity or aligned_non_ctc or explicit_source else "unavailable",
            sequence_support="supported",
            acoustic_support="unavailable",
            direct_onset_support=(
                "supported" if explicit_source else "unavailable"
            ),
            direct_onset_time=current_time if explicit_source else None,
            direct_onset_source_artifact=(
                current_source_artifact if explicit_source else None
            ),
            direct_onset_evidence_producer=(
                "external-reference" if explicit_source else None
            ),
            direct_onset_evidence_kind=(
                "external-reference" if explicit_source else "generic-onset"
            ),
            direct_onset_evidence_independent=explicit_source,
            current=True,
            right_edge_pileup=bool(raw_assignment.get("ctc_right_edge_pileup")),
            window_truncated=bool(raw_assignment.get("ctc_right_edge_truncation")),
            source_artifact=current_source_artifact,
        )
        candidates: list[TimingCandidate] = [current_candidate]

        raw_identity = runtime_raw_content_identity_for_entry(report, entries, index)
        consensus = runtime_raw_ctc_consensus_for_entry(
            report, entries, index, current_time
        )
        if consensus is not None and spans:
            raw_occurrence_evidence = candidate_occurrence_evidence_from_binding(
                entries,
                index,
                producer="raw-asr-consensus",
                occurrence_binding=consensus.get("occurrence_binding"),
                upstream_evidence_revision=consensus.get("evidence_revision"),
            )
            raw_consensus_time = float(consensus["raw_time"])
            raw_consensus_score = float(consensus["raw_score"])
            consensus_artifact = {
                "producer": "raw-asr-consensus",
                "evidence_revision": consensus["evidence_revision"],
                "raw_time": raw_consensus_time,
                "ctc_time": current_time,
                "raw_score": raw_consensus_score,
                "raw_content_identity_revision": (
                    raw_identity.get("evidence_revision") if isinstance(raw_identity, dict) else None
                ),
                "runtime_only": True,
            }
            candidates.append(
                make_timing_candidate(
                    entry_index=index,
                    entry_text=entry_sung_text(entry),
                    source="ctc-raw-independent-consensus",
                    raw_time=current_time,
                    spans=spans,
                    confidence=min(score, raw_consensus_score),
                    identity_support="supported",
                    sequence_support="supported",
                    acoustic_support="unavailable",
                    direct_onset_support="supported",
                    direct_onset_time=raw_consensus_time,
                    direct_onset_source_artifact=consensus_artifact,
                    direct_onset_evidence_producer="raw-asr-consensus",
                    direct_onset_evidence_kind="cross-backend-onset",
                    direct_onset_evidence_independent=True,
                    occurrence_evidence=raw_occurrence_evidence,
                    independent_content_identity=raw_occurrence_evidence is not None,
                    current=False,
                    right_edge_pileup=bool(raw_assignment.get("ctc_right_edge_pileup")),
                    window_truncated=bool(raw_assignment.get("ctc_right_edge_truncation")),
                    source_artifact=consensus_artifact,
                )
            )

        whisperx_consensus = runtime_whisperx_ctc_consensus_for_entry(
            report, entries, index, current_time
        )
        if whisperx_consensus is not None and spans:
            whisperx_occurrence_evidence = candidate_occurrence_evidence_from_binding(
                entries,
                index,
                producer="whisperx-consensus",
                occurrence_binding=whisperx_consensus.get("occurrence_binding"),
                upstream_evidence_revision=whisperx_consensus.get("evidence_revision"),
            )
            whisperx_time = float(whisperx_consensus["whisperx_forced_time"])
            whisperx_score = float(whisperx_consensus["score"])
            whisperx_artifact = {
                "producer": "whisperx-consensus",
                "evidence_revision": whisperx_consensus["evidence_revision"],
                "whisperx_forced_time": whisperx_time,
                "ctc_time": current_time,
                "score": whisperx_score,
                "runtime_only": True,
            }
            candidates.append(
                make_timing_candidate(
                    entry_index=index,
                    entry_text=entry_sung_text(entry),
                    source="ctc-whisperx-independent-consensus",
                    raw_time=current_time,
                    spans=spans,
                    confidence=min(score, whisperx_score),
                    identity_support="supported",
                    sequence_support="supported",
                    acoustic_support="unavailable",
                    direct_onset_support="supported",
                    direct_onset_time=whisperx_time,
                    direct_onset_source_artifact=whisperx_artifact,
                    direct_onset_evidence_producer="whisperx-consensus",
                    direct_onset_evidence_kind="cross-backend-onset",
                    direct_onset_evidence_independent=True,
                    occurrence_evidence=whisperx_occurrence_evidence,
                    independent_content_identity=whisperx_occurrence_evidence is not None,
                    current=False,
                    right_edge_pileup=bool(raw_assignment.get("ctc_right_edge_pileup")),
                    window_truncated=bool(raw_assignment.get("ctc_right_edge_truncation")),
                    source_artifact=whisperx_artifact,
                )
            )


        # Independent row-level backend identity can be fused with the isolated
        # vocal detector without requiring CTC to agree first.  This recovers
        # evidence that was previously thrown away when a backend failed only
        # at the whole-song aggregate level.  The runtime identity timestamp
        # must itself be close to the independently observed vocal onset.
        if isinstance(raw_identity, dict) and vocal_onset_features is not None and fusion_audio_revision:
            try:
                raw_identity_time = float(raw_identity.get("raw_time"))
                raw_identity_score = float(raw_identity.get("raw_score"))
            except (TypeError, ValueError):
                raw_identity_time = math.nan
                raw_identity_score = 0.0
            raw_peak = _strong_vocal_onset_near(vocal_onset_features, raw_identity_time)
            if raw_peak is not None and raw_identity_score >= TRUSTED_ALIGNMENT_SCORE:
                raw_occurrence_evidence = candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="raw-asr-vocal-fusion",
                    occurrence_binding=raw_identity.get("occurrence_binding"),
                    upstream_evidence_revision=raw_identity.get("evidence_revision"),
                )
                peak_time, peak_strength, peak_prominence = raw_peak
                artifact = {
                    "producer": "raw-asr-vocal-fusion",
                    "raw_content_identity_revision": raw_identity.get("evidence_revision"),
                    "raw_time": round(raw_identity_time, 6),
                    "raw_score": round(raw_identity_score, 6),
                    "vocal_onset_time": round(peak_time, 6),
                    "vocal_onset_strength": round(peak_strength, 8),
                    "vocal_onset_prominence": round(peak_prominence, 8),
                    "audio_sha256": fusion_audio_revision,
                    "feature_revision": "vocal-consonant-onset-v1",
                    "runtime_only": True,
                }
                candidates.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entry),
                        source="raw-vocal-independent-fusion",
                        raw_time=peak_time,
                        spans=(),
                        confidence=min(raw_identity_score, peak_strength),
                        identity_support="supported",
                        sequence_support="supported",
                        acoustic_support="supported",
                        direct_onset_support="supported",
                        acoustic_strength=peak_strength,
                        acoustic_onset_time=peak_time,
                        acoustic_source_artifact=artifact,
                        acoustic_evidence_producer="raw-asr-vocal-fusion",
                        acoustic_evidence_kind="vocal-onset",
                        acoustic_evidence_independent=True,
                        direct_onset_time=peak_time,
                        direct_onset_source_artifact=artifact,
                        direct_onset_evidence_producer="raw-asr-vocal-fusion",
                        direct_onset_evidence_kind="cross-backend-onset",
                        direct_onset_evidence_independent=True,
                        occurrence_evidence=raw_occurrence_evidence,
                        independent_content_identity=raw_occurrence_evidence is not None,
                        current=False,
                        source_artifact=artifact,
                    )
                )

        whisperx_row = runtime_whisperx_row_evidence_for_entry(report, entries, index)
        if isinstance(whisperx_row, dict) and vocal_onset_features is not None and fusion_audio_revision:
            try:
                whisperx_forced_time = float(whisperx_row.get("first_char_time"))
                whisperx_row_score = float(whisperx_row.get("score"))
            except (TypeError, ValueError):
                whisperx_forced_time = math.nan
                whisperx_row_score = 0.0
            whisperx_peak = _strong_vocal_onset_near(vocal_onset_features, whisperx_forced_time)
            if whisperx_peak is not None and whisperx_row_score >= TRUSTED_ALIGNMENT_SCORE:
                whisperx_occurrence_evidence = candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="whisperx-vocal-fusion",
                    occurrence_binding=whisperx_row.get("occurrence_binding"),
                    upstream_evidence_revision=whisperx_row.get("evidence_revision"),
                )
                peak_time, peak_strength, peak_prominence = whisperx_peak
                artifact = {
                    "producer": "whisperx-vocal-fusion",
                    "whisperx_row_revision": whisperx_row.get("evidence_revision"),
                    "whisperx_forced_time": round(whisperx_forced_time, 6),
                    "score": round(whisperx_row_score, 6),
                    "vocal_onset_time": round(peak_time, 6),
                    "vocal_onset_strength": round(peak_strength, 8),
                    "vocal_onset_prominence": round(peak_prominence, 8),
                    "audio_sha256": fusion_audio_revision,
                    "feature_revision": "vocal-consonant-onset-v1",
                    "runtime_only": True,
                }
                candidates.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entry),
                        source="whisperx-vocal-independent-fusion",
                        raw_time=whisperx_forced_time,
                        spans=(),
                        confidence=min(whisperx_row_score, peak_strength),
                        identity_support="supported",
                        sequence_support="supported",
                        acoustic_support="supported",
                        direct_onset_support="supported",
                        acoustic_strength=peak_strength,
                        acoustic_onset_time=peak_time,
                        acoustic_source_artifact=artifact,
                        acoustic_evidence_producer="whisperx-vocal-fusion",
                        acoustic_evidence_kind="vocal-onset",
                        acoustic_evidence_independent=True,
                        direct_onset_time=peak_time,
                        direct_onset_source_artifact=artifact,
                        direct_onset_evidence_producer="whisperx-vocal-fusion",
                        direct_onset_evidence_kind="cross-backend-onset",
                        direct_onset_evidence_independent=True,
                        occurrence_evidence=whisperx_occurrence_evidence,
                        independent_content_identity=whisperx_occurrence_evidence is not None,
                        current=False,
                        source_artifact=artifact,
                    )
                )

        local_whisper_identity = runtime_local_whisper_evidence_for_entry(
            report, entries, index
        )
        local_whisper_vocal = _local_whisper_vocal_fusion_candidate(
            entry_index=index,
            entry=entry,
            local_evidence=local_whisper_identity,
            vocal_onset_features=vocal_onset_features,
            audio_revision=fusion_audio_revision,
            occurrence_evidence=(
                candidate_occurrence_evidence_from_binding(
                    entries,
                    index,
                    producer="local-whisper-vocal-fusion",
                    occurrence_binding=local_whisper_identity.get("occurrence_binding"),
                    upstream_evidence_revision=local_whisper_identity.get("evidence_revision"),
                )
                if isinstance(local_whisper_identity, dict) else None
            ),
        )
        if local_whisper_vocal is not None:
            candidates.append(local_whisper_vocal)

        hypothesis_rows = raw_assignment.get("alignment_hypotheses")
        if isinstance(hypothesis_rows, list):
            for hypothesis in hypothesis_rows:
                if not isinstance(hypothesis, dict):
                    continue
                raw_time = hypothesis.get("raw_candidate_time")
                if not isinstance(raw_time, (int, float)) or not math.isfinite(float(raw_time)):
                    continue
                source = str(hypothesis.get("source") or "precentral-hypothesis")
                if source == "ctc-opening-local-retry-identity":
                    # Identity-only evidence is consumed by occurrence-level
                    # recurrence producers; it must never become a timing
                    # candidate merely because it contains helper spans.
                    continue
                independent_identity_bound = False
                independent_acoustic_bound = False
                independent_direct_bound = False
                acoustic_producer: str | None = None
                direct_producer: str | None = None
                composite_identity_revision: str | None = None
                opening_vocal_fusion_bound = False
                raw_vocal_occurrence_bound = False
                acoustic_kind = "generic-acoustic"
                direct_kind = "generic-onset"
                if source == "global-acoustic-recurrence":
                    independent_identity_bound = recurrence_hypothesis_provenance_is_valid(
                        hypothesis, entry, evidence_audio_path
                    )
                    if not independent_identity_bound:
                        continue
                    independent_acoustic_bound = True
                    independent_direct_bound = True
                    acoustic_producer = direct_producer = "global-recurrence-search"
                    acoustic_kind = direct_kind = "recurrence-onset"
                elif source == "mutual-acoustic-recurrence":
                    independent_identity_bound = mutual_recurrence_hypothesis_provenance_is_valid(
                        hypothesis,
                        entry,
                        evidence_audio_path,
                        assignments,
                        entries,
                        index,
                    )
                    if not independent_identity_bound:
                        continue
                    independent_acoustic_bound = True
                    independent_direct_bound = True
                    acoustic_producer = direct_producer = "mutual-recurrence-search"
                    acoustic_kind = direct_kind = "recurrence-onset"
                elif source == "ctc-phonetic-onset-fusion":
                    if not phonetic_onset_fusion_provenance_is_valid(
                        hypothesis, raw_assignment, evidence_audio_path
                    ):
                        continue
                    independent_acoustic_bound = True
                    independent_direct_bound = True
                    acoustic_producer = direct_producer = "phonetic-onset-fusion"
                    acoustic_kind = direct_kind = "phonetic-onset"
                elif source == "ctc-vocal-onset-confirmed":
                    if not vocal_onset_confirmation_provenance_is_valid(
                        hypothesis, raw_assignment, evidence_audio_path,
                        recomputed_features=vocal_onset_features,
                        evidence_audio_sha256=fusion_audio_revision,
                    ):
                        continue
                    independent_acoustic_bound = True
                    independent_direct_bound = True
                    acoustic_producer = "consonant-onset-detector"
                    acoustic_kind = "vocal-onset"
                    direct_producer = "consonant-onset-detector"
                    direct_kind = "vocal-onset"
                    opening_vocal_fusion_bound = ctc_opening_vocal_fusion_is_valid(
                        hypothesis, raw_assignment, evidence_audio_path,
                        vocal_provenance_validated=True,
                        recomputed_features=vocal_onset_features,
                        evidence_audio_sha256=fusion_audio_revision,
                    )
                    if isinstance(raw_identity, dict):
                        try:
                            raw_identity_time = float(raw_identity.get("raw_time"))
                            raw_identity_score = float(raw_identity.get("raw_score"))
                            hypothesis_onset = float(hypothesis.get("direct_onset_time"))
                        except (TypeError, ValueError):
                            raw_identity_time = math.nan
                            raw_identity_score = 0.0
                            hypothesis_onset = math.nan
                        raw_vocal_occurrence_bound = bool(
                            math.isfinite(raw_identity_time)
                            and math.isfinite(hypothesis_onset)
                            and raw_identity_score >= RAW_CTC_CONSENSUS_MIN_SCORE
                            and abs(raw_identity_time - hypothesis_onset)
                            <= RAW_CTC_CONSENSUS_MAX_DELTA_SECONDS
                        )
                        if raw_vocal_occurrence_bound:
                            composite_identity_revision = str(
                                raw_identity.get("evidence_revision") or ""
                            )
                elif source == "ctc-vocal-activity-reentry":
                    if not vocal_activity_reentry_provenance_is_valid(
                        hypothesis, raw_assignment, evidence_audio_path
                    ):
                        continue
                    independent_direct_bound = True
                    direct_producer = "vocal-activity-detector"
                    direct_kind = "vocal-activity-reentry"
                elif source == "trusted-tail-release-onset":
                    if not trusted_tail_release_provenance_is_valid(
                        hypothesis,
                        evidence_audio_path,
                        assignments,
                        index,
                    ):
                        continue
                    # A post-tail energy cluster is useful evidence, but it is not
                    # phonetic proof of the next lyric's first mora.  It may rank
                    # candidates, never bypass unknown ownership.
                    independent_acoustic_bound = True
                    acoustic_producer = "tail-release-acoustic-search"
                    acoustic_kind = "generic-acoustic"
                spans_value = _timing_spans_from_value(hypothesis.get("spans"))
                acoustic_strength = hypothesis.get("acoustic_strength")
                acoustic_onset_time = hypothesis.get("acoustic_onset_time")
                direct_onset_time = hypothesis.get("direct_onset_time")
                source_artifact = {
                    "hypothesis_id": hypothesis.get("hypothesis_id"),
                    "stage": hypothesis.get("stage"),
                    "parent": hypothesis.get("parent"),
                    "window": hypothesis.get("window"),
                    "mode": hypothesis.get("mode"),
                    "raw_content_identity_revision": composite_identity_revision,
                    "authoritative": False,
                }
                candidates.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entry),
                        source=source,
                        raw_time=float(raw_time),
                        spans=spans_value,
                        confidence=float(hypothesis.get("confidence", 0.0) or 0.0),
                        identity_support=str(hypothesis.get("identity_support") or "unavailable"),  # type: ignore[arg-type]
                        sequence_support=str(hypothesis.get("sequence_support") or "unavailable"),  # type: ignore[arg-type]
                        acoustic_support=str(hypothesis.get("acoustic_support") or "unavailable"),  # type: ignore[arg-type]
                        direct_onset_support=(
                            "supported"
                            if independent_direct_bound and isinstance(direct_onset_time, (int, float))
                            else "unavailable"
                        ),
                        acoustic_strength=(float(acoustic_strength) if isinstance(acoustic_strength, (int, float)) else None),
                        acoustic_onset_time=(float(acoustic_onset_time) if isinstance(acoustic_onset_time, (int, float)) else None),
                        acoustic_source_artifact=source_artifact,
                        acoustic_evidence_producer=acoustic_producer,
                        acoustic_evidence_kind=acoustic_kind,
                        acoustic_evidence_independent=independent_acoustic_bound,
                        direct_onset_time=(
                            float(direct_onset_time)
                            if independent_direct_bound and isinstance(direct_onset_time, (int, float))
                            else None
                        ),
                        direct_onset_source_artifact=(
                            source_artifact
                            if independent_direct_bound and isinstance(direct_onset_time, (int, float))
                            else None
                        ),
                        direct_onset_evidence_producer=direct_producer,
                        direct_onset_evidence_kind=direct_kind,
                        direct_onset_evidence_independent=independent_direct_bound,
                        independent_content_identity=independent_identity_bound,
                        current=False,
                        right_edge_pileup=bool(hypothesis.get("right_edge_pileup")),
                        window_truncated=bool(hypothesis.get("window_truncated")),
                        source_artifact=source_artifact,
                    )
                )

                if source == "ctc-vocal-onset-confirmed" and opening_vocal_fusion_bound:
                    fusion_artifact = {
                        **source_artifact,
                        "producer": "ctc-opening-vocal-fusion",
                        "ctc_geometry_revision": _timing_content_digest({
                            "spans": hypothesis.get("spans"),
                            "assignment_time": raw_assignment.get("timestamp"),
                        }),
                    }
                    candidates.append(
                        make_timing_candidate(
                            entry_index=index,
                            entry_text=entry_sung_text(entry),
                            source="ctc-opening-vocal-fusion",
                            raw_time=float(raw_time),
                            spans=spans_value,
                            confidence=float(hypothesis.get("confidence", 0.0) or 0.0),
                            identity_support="supported",
                            sequence_support="supported",
                            acoustic_support="supported",
                            direct_onset_support="supported",
                            acoustic_strength=(float(acoustic_strength) if isinstance(acoustic_strength, (int, float)) else None),
                            acoustic_onset_time=(float(acoustic_onset_time) if isinstance(acoustic_onset_time, (int, float)) else None),
                            acoustic_source_artifact=fusion_artifact,
                            acoustic_evidence_producer="consonant-onset-detector",
                            acoustic_evidence_kind="vocal-onset",
                            acoustic_evidence_independent=True,
                            direct_onset_time=(float(direct_onset_time) if isinstance(direct_onset_time, (int, float)) else None),
                            direct_onset_source_artifact=fusion_artifact,
                            # CTC opening geometry belongs to the candidate itself.
                            # Combining it with an independent vocal peak improves
                            # current-line opening support, but does not make that
                            # peak independently lyric-specific.  Keep this generic
                            # so it can never cross UNKNOWN/VIOLATION ownership.
                            direct_onset_evidence_producer="consonant-onset-detector",
                            direct_onset_evidence_kind="vocal-onset",
                            direct_onset_evidence_independent=True,
                            independent_content_identity=False,
                            current=False,
                            right_edge_pileup=bool(hypothesis.get("right_edge_pileup")),
                            window_truncated=bool(hypothesis.get("window_truncated")),
                            source_artifact=fusion_artifact,
                        )
                    )
                if source == "ctc-vocal-onset-confirmed" and raw_vocal_occurrence_bound:
                    raw_occurrence_evidence = candidate_occurrence_evidence_from_binding(
                        entries,
                        index,
                        producer="raw-asr-vocal-fusion",
                        occurrence_binding=raw_identity.get("occurrence_binding"),
                        upstream_evidence_revision=raw_identity.get("evidence_revision"),
                    )
                    raw_fusion_artifact = {
                        **source_artifact,
                        "producer": "raw-asr-vocal-fusion",
                        "raw_content_identity_revision": composite_identity_revision,
                        "raw_time": round(float(raw_identity.get("raw_time")), 6),
                        "raw_score": round(float(raw_identity.get("raw_score")), 6),
                    }
                    candidates.append(
                        make_timing_candidate(
                            entry_index=index,
                            entry_text=entry_sung_text(entry),
                            source="ctc-raw-vocal-independent-fusion",
                            raw_time=float(raw_time),
                            spans=spans_value,
                            confidence=min(
                                float(hypothesis.get("confidence", 0.0) or 0.0),
                                float(raw_identity.get("raw_score", 0.0) or 0.0),
                            ),
                            identity_support="supported",
                            sequence_support="supported",
                            acoustic_support="supported",
                            direct_onset_support="supported",
                            acoustic_strength=(float(acoustic_strength) if isinstance(acoustic_strength, (int, float)) else None),
                            acoustic_onset_time=(float(acoustic_onset_time) if isinstance(acoustic_onset_time, (int, float)) else None),
                            acoustic_source_artifact=raw_fusion_artifact,
                            acoustic_evidence_producer="consonant-onset-detector",
                            acoustic_evidence_kind="vocal-onset",
                            acoustic_evidence_independent=True,
                            direct_onset_time=(float(direct_onset_time) if isinstance(direct_onset_time, (int, float)) else None),
                            direct_onset_source_artifact=raw_fusion_artifact,
                            direct_onset_evidence_producer="raw-asr-vocal-fusion",
                            direct_onset_evidence_kind="cross-backend-onset",
                            direct_onset_evidence_independent=True,
                            occurrence_evidence=raw_occurrence_evidence,
                            independent_content_identity=raw_occurrence_evidence is not None,
                            current=False,
                            right_edge_pileup=bool(hypothesis.get("right_edge_pileup")),
                            window_truncated=bool(hypothesis.get("window_truncated")),
                            source_artifact=raw_fusion_artifact,
                        )
                    )

        first_token_candidates = raw_assignment.get("ctc_first_token_candidates")
        if isinstance(first_token_candidates, list):
            for raw_candidate in first_token_candidates:
                if not isinstance(raw_candidate, dict):
                    continue
                try:
                    raw_time = float(raw_candidate.get("time"))
                    raw_score = float(raw_candidate.get("score", 0.0) or 0.0)
                except (TypeError, ValueError):
                    continue
                # A first-token posterior is identity evidence, not by itself
                # a complete onset proof.  Its one-token span therefore enters
                # normalization and ownership gating but cannot become valid
                # until another producer contributes coherent prefix/acoustic
                # support for the same written time.
                posterior_span = TimingTokenSpan(
                    canonicalize_lrc_time(raw_time).seconds,
                    canonicalize_lrc_time(raw_time).seconds + HOP_SECONDS,
                    raw_score,
                    "",
                )
                candidates.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entry),
                        source="ctc-first-token-posterior",
                        raw_time=raw_time,
                        spans=(posterior_span,),
                        confidence=raw_score,
                        identity_support="supported",
                        sequence_support="supported",
                        source_artifact=raw_candidate,
                    )
                )

        legacy_candidates = raw_assignment.get("candidates")
        if isinstance(legacy_candidates, list):
            for legacy in legacy_candidates:
                if not isinstance(legacy, dict) or legacy.get("source") == "selected_path":
                    continue
                raw_time = legacy.get("time")
                if not isinstance(raw_time, (int, float)):
                    continue
                source = str(legacy.get("source") or "legacy-candidate")
                direct_onset = False
                identity = source in {"raw_asr", "whisperx_forced_first", "whisperx_word"}
                candidates.append(
                    make_timing_candidate(
                        entry_index=index,
                        entry_text=entry_sung_text(entry),
                        source=source.replace("_", "-"),
                        raw_time=float(raw_time),
                        confidence=float(legacy.get("score", 0.0) or 0.0),
                        identity_support="supported" if identity else "unavailable",
                        sequence_support="supported",
                        acoustic_support="unavailable",
                        direct_onset_support="supported" if direct_onset else "unavailable",
                        direct_onset_time=float(raw_time) if direct_onset else None,
                        direct_onset_source_artifact=legacy if direct_onset else None,
                        source_artifact=legacy,
                    )
                )

        unique = {candidate.candidate_id: candidate for candidate in candidates}
        candidate_sets.append(tuple(unique[key] for key in sorted(unique)))

    ordinary_candidate_sets = _augment_local_ctc_candidates_with_runtime_backend_consensus(
        tuple(candidate_sets), report, entries
    )
    independent_tail_evidence = runtime_independent_tail_evidence(report, len(entries))
    independent_tail_payload = independent_tail_evidence_payload(independent_tail_evidence)
    fusion_source_counts = collections.Counter(
        candidate.source
        for candidates in ordinary_candidate_sets
        for candidate in candidates
        if candidate.source in {
            "raw-vocal-independent-fusion",
            "whisperx-vocal-independent-fusion",
            "ctc-opening-vocal-fusion",
            "ctc-raw-vocal-independent-fusion",
            "ctc-local-raw-independent-consensus",
            "ctc-local-whisperx-independent-consensus",
        }
    )
    hypothesis_count = sum(
        len(item.get("alignment_hypotheses", []))
        for item in assignments
        if isinstance(item, dict) and isinstance(item.get("alignment_hypotheses"), list)
    )
    diagnostics = {
        "ctc_prefix_probes": [],
        "ctc_prefix_probe_count": 0,
        "legacy_final_guard_changes_discarded": [],
        "legacy_final_guard_change_count": 0,
        "independent_tail_evidence": independent_tail_payload,
        "runtime_evidence_fusion_candidate_counts": dict(sorted(fusion_source_counts.items())),
        "alignment_hypothesis_layer": {
            "status": "active",
            "authoritative_precentral_mutation": False,
            "hypothesis_count": hypothesis_count,
            "central_commit_only": True,
        },
        **inactive_legacy_timing_diagnostics(),
    }
    capability = build_bounded_retry_capability(report, audio_path, args)
    tail_evidence_context = _tail_evidence_context_from_report(
        report, entries=entries, capability=capability
    )
    if tail_evidence_context is not None:
        report[_RUNTIME_TAIL_EVIDENCE_CONTEXT_KEY] = tail_evidence_context
    independent_tail_evidence = runtime_independent_tail_evidence(
        report, len(entries), tail_evidence_context
    )
    independent_tail_payload = independent_tail_evidence_payload(independent_tail_evidence)
    if retry_helper_cache is None:
        retry_helper_cache = {}
    try:
        retry_timeout_seconds = float(getattr(args, "crossline_retry_timeout", 180.0))
    except (TypeError, ValueError):
        retry_timeout_seconds = 180.0
    if not math.isfinite(retry_timeout_seconds) or retry_timeout_seconds <= 0.0:
        retry_timeout_seconds = 180.0
    retry_runtime_stats: dict[str, int] = {
        "cache_hits": 0,
        "cache_misses": 0,
        "helper_invocations": 0,
        "timeouts": 0,
    }
    # Bounded fixed-point retry: resolving one boundary can make the next line's
    # previous-tail ownership provable. Re-plan from the newly evaluated state,
    # but cap passes so recovery can never become an unbounded heuristic loop.
    candidate_sets = ordinary_candidate_sets
    retry_passes: list[dict[str, object]] = []
    all_requests: list[CrossLineRetryRequest] = []
    all_outcomes: list[CrossLineRetryOutcome] = []
    processed_retry_semantics: set[str] = set()
    max_retry_passes = 4
    last_epoch_revision: str | None = None
    tail_evidence_changes = 0
    for pass_index in range(1, max_retry_passes + 1):
        before_candidate_revision, before_tail_revision = _retry_semantic_state_revision(
            candidate_sets, independent_tail_evidence, tail_evidence_context
        )
        epoch = freeze_base_retry_epoch(
            str(report.get("backend") or "unknown"),
            report,
            candidate_sets,
            diagnostics,
            capability,
        )
        last_epoch_revision = epoch.retry_epoch_revision
        requests = plan_crossline_retry_requests(
            epoch,
            capability,
            entries,
            candidate_sets,
            duration,
            independent_tail_evidence,
            tail_evidence_context,
        )
        if capability is None:
            novel_requests: tuple[CrossLineRetryRequest, ...] = ()
            novel_semantics: tuple[str, ...] = ()
        else:
            novel_requests, novel_semantics = _novel_crossline_retry_requests(
                requests, capability, processed_retry_semantics
            )
        progress_log(
            f"crossline retry pass {pass_index}: requests={len(requests)} "
            f"new_semantic={len(novel_requests)} cache_entries={len(retry_helper_cache)}"
        )
        if not requests:
            retry_passes.append({
                "pass": pass_index,
                "retry_epoch_revision": epoch.retry_epoch_revision,
                "request_count": 0,
                "executed_request_count": 0,
                "new_semantic_request_count": 0,
                "outcome_count": 0,
                "new_candidate_count": 0,
                "semantic_fixed_point": True,
            })
            break
        if not novel_requests:
            progress_log(
                f"crossline retry pass {pass_index}: semantic fixed point; "
                "all planned helper inputs were already evaluated"
            )
            retry_passes.append({
                "pass": pass_index,
                "retry_epoch_revision": epoch.retry_epoch_revision,
                "request_count": len(requests),
                "executed_request_count": 0,
                "new_semantic_request_count": 0,
                "outcome_count": 0,
                "new_candidate_count": 0,
                "semantic_fixed_point": True,
            })
            break
        outcomes = execute_crossline_retry_epoch(
            epoch, capability, entries, candidate_sets, duration, novel_requests,
            helper_cache=retry_helper_cache,
            timeout_seconds=retry_timeout_seconds,
            pass_index=pass_index,
            runtime_stats=retry_runtime_stats,
            independent_tail_evidence=independent_tail_evidence,
            tail_evidence_context=tail_evidence_context,
            worker_count=DEFAULT_EVIDENCE_WORKERS,
        )
        processed_retry_semantics.update(novel_semantics)
        tail_evidence_changes = sum(
            int(merge_runtime_independent_tail_evidence(
                report, outcome.previous_tail_evidence
            ))
            for outcome in outcomes
            if outcome.previous_tail_evidence is not None
        )
        if tail_evidence_changes:
            independent_tail_evidence = runtime_independent_tail_evidence(
                report, len(entries), tail_evidence_context
            )
        augmented = [list(items) for items in candidate_sets]
        existing_ids = {item.candidate_id for items in candidate_sets for item in items}
        new_candidate_count = 0
        for outcome in outcomes:
            record_crossline_retry_identity_hypothesis(report, outcome)
            if (
                outcome.status == "candidate"
                and outcome.candidate is not None
                and outcome.candidate.candidate_id not in existing_ids
            ):
                augmented[outcome.entry_index].append(outcome.candidate)
                existing_ids.add(outcome.candidate.candidate_id)
                new_candidate_count += 1
        candidate_sets = tuple(
            tuple({item.candidate_id: item for item in items}[key] for key in sorted(
                {item.candidate_id: item for item in items}
            ))
            for items in augmented
        )
        candidate_sets = _augment_local_ctc_candidates_with_runtime_backend_consensus(
            candidate_sets, report, entries
        )
        after_candidate_revision, after_tail_revision = _retry_semantic_state_revision(
            candidate_sets, independent_tail_evidence, tail_evidence_context
        )
        semantic_state_changed = bool(
            before_candidate_revision != after_candidate_revision
            or before_tail_revision != after_tail_revision
        )
        all_requests.extend(novel_requests)
        all_outcomes.extend(outcomes)
        retry_passes.append({
            "pass": pass_index,
            "retry_epoch_revision": epoch.retry_epoch_revision,
            "request_count": len(requests),
            "executed_request_count": len(novel_requests),
            "new_semantic_request_count": len(novel_requests),
            "outcome_count": len(outcomes),
            "new_candidate_count": new_candidate_count,
            "previous_tail_evidence_change_count": tail_evidence_changes,
            "candidate_semantic_revision": after_candidate_revision,
            "authoritative_tail_semantic_revision": after_tail_revision,
            "semantic_fixed_point": not semantic_state_changed,
        })
        if new_candidate_count == 0 and not semantic_state_changed:
            break

    # Architectural recovery: after current-line retry reaches its bounded
    # fixed point, obtain a separate joint previous+current boundary observation
    # for every still-unresolved boundary.  The observation cannot be selected
    # directly; it must converge with an already-existing current candidate.
    joint_boundary_requests: tuple[CrossLineRetryRequest, ...] = ()
    joint_boundary_outcomes: tuple[CrossLineRetryOutcome, ...] = ()
    joint_boundary_added = 0
    if capability is not None:
        joint_epoch = freeze_base_retry_epoch(
            str(report.get("backend") or "unknown"),
            report,
            candidate_sets,
            diagnostics,
            capability,
        )
        joint_boundary_requests = plan_joint_boundary_retry_requests(
            joint_epoch, capability, entries, candidate_sets, duration,
            independent_tail_evidence,
            tail_evidence_context,
        )
        progress_log(
            f"joint boundary retry: requests={len(joint_boundary_requests)} "
            f"cache_entries={len(retry_helper_cache)}"
        )
        if joint_boundary_requests:
            joint_boundary_outcomes = execute_crossline_retry_epoch(
                joint_epoch, capability, entries, candidate_sets, duration,
                joint_boundary_requests,
                helper_cache=retry_helper_cache,
                timeout_seconds=retry_timeout_seconds,
                pass_index="joint",
                runtime_stats=retry_runtime_stats,
                independent_tail_evidence=independent_tail_evidence,
                tail_evidence_context=tail_evidence_context,
                worker_count=DEFAULT_EVIDENCE_WORKERS,
            )
            joint_tail_evidence_changes = sum(
                int(merge_runtime_independent_tail_evidence(
                    report, outcome.previous_tail_evidence
                ))
                for outcome in joint_boundary_outcomes
                if outcome.previous_tail_evidence is not None
            )
            if joint_tail_evidence_changes:
                independent_tail_evidence = runtime_independent_tail_evidence(
                    report, len(entries), tail_evidence_context
                )
            before_ids = {
                item.candidate_id for items in candidate_sets for item in items
            }
            candidate_sets = _augment_candidates_with_joint_boundary_consensus(
                candidate_sets, joint_boundary_outcomes, entries
            )
            after_ids = {
                item.candidate_id for items in candidate_sets for item in items
            }
            joint_boundary_added = len(after_ids - before_ids)
            if joint_boundary_added:
                candidate_sets = _augment_local_ctc_candidates_with_runtime_backend_consensus(
                    candidate_sets, report, entries
                )
            progress_log(
                f"joint boundary retry: observations={len(joint_boundary_outcomes)} "
                f"new_consensus_candidates={joint_boundary_added}"
            )

    # The bounded CTC retry/joint phase is complete for this collection epoch.
    # Park resident MMS_FA workers on CPU before local whisper.cpp/WhisperX work.
    _park_persistent_helper_mode("ctc", reason="bounded-ctc-evidence-complete")

    # v14.6: the CTC graph is now rich enough that the remaining ceiling is
    # usually lack of an *independent* lyric-specific opening/occurrence witness.
    # Run whisper.cpp + WhisperX only for those unresolved/content-untrusted/review
    # rows.  The local observation is never selectable by itself; central may use
    # it only by fusing its onset/identity into an already-existing non-Whisper
    # candidate within the unchanged 0.18 s cross-backend tolerance.
    local_whisper_capability = build_local_whisper_capability(evidence_audio_path, args)
    local_whisper_requests: tuple[LocalWhisperRequest, ...] = ()
    local_whisper_outcomes: tuple[LocalWhisperOutcome, ...] = ()
    local_whisper_added = 0
    local_whisper_stats: dict[str, int] = {
        "cache_hits": 0, "cache_misses": 0, "helper_invocations": 0,
    }
    if local_whisper_capability is not None:
        local_whisper_requests = plan_local_whisper_requests(
            report, local_whisper_capability, entries, candidate_sets, duration,
            independent_tail_evidence,
            tail_evidence_context,
        )
        progress_log(
            f"local Whisper evidence: requests={len(local_whisper_requests)} "
            f"cache_entries={len(retry_helper_cache)}"
        )
        local_whisper_workers = DEFAULT_EVIDENCE_WORKERS
        if local_whisper_workers == 1 or len(local_whisper_requests) <= 1:
            outcomes: list[LocalWhisperOutcome] = []
            for ordinal, request in enumerate(local_whisper_requests, start=1):
                progress_log(
                    f"local Whisper evidence: {ordinal}/{len(local_whisper_requests)} "
                    f"entry={request.entry_index + 1} "
                    f"window={request.window_start:.2f}-{request.window_end:.2f}s"
                )
                outcome = execute_local_whisper_request(
                    request, local_whisper_capability, entries, args,
                    cache=retry_helper_cache, runtime_stats=local_whisper_stats,
                )
                outcomes.append(outcome)
                progress_log(
                    f"local Whisper evidence: entry={request.entry_index + 1} "
                    f"status={outcome.status} reason={outcome.reason}"
                )
            local_whisper_outcomes = tuple(outcomes)
        else:
            # Requests are planned from one frozen pre-local-whisper graph and are
            # bound only after every outcome is collected.  They can therefore be
            # executed concurrently without changing Central selection semantics.
            # Preserve deterministic result ordering and legacy cache statistics.
            grouped: dict[str, list[tuple[int, LocalWhisperRequest]]] = {}
            for ordinal, request in enumerate(local_whisper_requests, start=1):
                key = _local_whisper_cache_key(request, local_whisper_capability)
                grouped.setdefault(key, []).append((ordinal, request))

            outcomes_by_ordinal: dict[int, LocalWhisperOutcome] = {}
            work: list[tuple[str, int, LocalWhisperRequest]] = []
            for key, group in grouped.items():
                cached = retry_helper_cache.get(key)
                if (
                    isinstance(cached, tuple)
                    and len(cached) == 2
                    and isinstance(cached[1], LocalWhisperOutcome)
                ):
                    for ordinal, _request in group:
                        outcomes_by_ordinal[ordinal] = cached[1]
                    local_whisper_stats["cache_hits"] += len(group)
                    continue
                first_ordinal, first_request = group[0]
                work.append((key, first_ordinal, first_request))
                local_whisper_stats["cache_misses"] += 1
                if len(group) > 1:
                    local_whisper_stats["cache_hits"] += len(group) - 1

            progress_log(
                f"local Whisper evidence: internal_workers={local_whisper_workers} "
                f"unique_exec={len(work)}"
            )
            prepared_local, preparation_errors = _prepare_local_whisper_batch(
                work, local_whisper_capability, args
            )

            def _run_local_parallel(
                item: tuple[str, int, LocalWhisperRequest],
            ) -> tuple[str, int, LocalWhisperOutcome, dict[str, int], dict[str, tuple[str, object]]]:
                key, ordinal, request = item
                private_cache: dict[str, tuple[str, object]] = {}
                private_stats: dict[str, int] = {}
                progress_log(
                    f"local Whisper evidence: start {ordinal}/{len(local_whisper_requests)} "
                    f"entry={request.entry_index + 1} "
                    f"window={request.window_start:.2f}-{request.window_end:.2f}s"
                )
                outcome = execute_local_whisper_request(
                    request, local_whisper_capability, entries, args,
                    cache=private_cache, runtime_stats=private_stats,
                    prepared=prepared_local.get(key),
                    preparation_error=preparation_errors.get(key),
                )
                return key, ordinal, outcome, private_stats, private_cache

            with concurrent.futures.ThreadPoolExecutor(
                max_workers=min(local_whisper_workers, len(work) or 1),
                thread_name_prefix="lrc-local-whisper",
            ) as pool:
                future_map = {pool.submit(_run_local_parallel, item): item for item in work}
                for future in concurrent.futures.as_completed(future_map):
                    key, ordinal, outcome, private_stats, private_cache = future.result()
                    retry_helper_cache.update(private_cache)
                    local_whisper_stats["helper_invocations"] += private_stats.get(
                        "helper_invocations", 0
                    )
                    for grouped_ordinal, _request in grouped[key]:
                        outcomes_by_ordinal[grouped_ordinal] = outcome
                    progress_log(
                        f"local Whisper evidence: done {ordinal}/{len(local_whisper_requests)} "
                        f"entry={outcome.entry_index + 1} "
                        f"status={outcome.status} reason={outcome.reason}"
                    )

            local_whisper_outcomes = tuple(
                outcomes_by_ordinal[ordinal]
                for ordinal in range(1, len(local_whisper_requests) + 1)
            )
        bind_runtime_local_whisper_evidence(
            report, entries, local_whisper_capability,
            local_whisper_requests, local_whisper_outcomes,
        )
        before_ids = {
            item.candidate_id for items in candidate_sets for item in items
        }
        candidate_sets = _augment_candidates_with_local_whisper_vocal_consensus(
            candidate_sets, report, entries, vocal_onset_features, fusion_audio_revision
        )
        candidate_sets = _augment_candidates_with_local_whisper_consensus(
            candidate_sets, report, entries
        )
        after_ids = {
            item.candidate_id for items in candidate_sets for item in items
        }
        local_whisper_added = len(after_ids - before_ids)
        progress_log(
            f"local Whisper evidence: trusted_observations="
            f"{sum(item.status == 'evidence' for item in local_whisper_outcomes)} "
            f"new_consensus_candidates={local_whisper_added}"
        )

    # v14.7: same-model global/local Whisper contradictions are not independent
    # votes.  A weaker whole-song occurrence may be excluded only when the
    # bounded observation is sequence-bracketed and independently corroborated
    # by CTC at the competing onset.
    candidate_sets, hypothesis_falsifications = (
        _apply_context_conditioned_whisper_hypothesis_arbitration(
            candidate_sets, report, entries
        )
    )
    if hypothesis_falsifications:
        progress_log(
            "hypothesis arbitration: falsified_global_whisper_candidates="
            f"{sum(len(item.get('falsified_candidate_ids', [])) for item in hypothesis_falsifications)} "
            f"entries={','.join(str(item.get('entry')) for item in hypothesis_falsifications)}"
        )

    diagnostics = {
        **diagnostics,
        "independent_tail_evidence": independent_tail_evidence_payload(
            runtime_independent_tail_evidence(report, len(entries))
        ),
        "independent_tail_authority": _tail_authority_diagnostics(
            candidate_sets,
            runtime_independent_tail_evidence(report, len(entries)),
            tail_evidence_context,
        ),
        "crossline_retry": {
            "retry_epoch_revision": last_epoch_revision,
            "capability_revision": capability.capability_revision if capability else None,
            "capability": _retry_capability_diagnostic_payload(capability),
            "requests": [_retry_diagnostic_payload(item) for item in all_requests],
            "outcomes": [_retry_diagnostic_payload(item) for item in all_outcomes],
            "invocation_count": len(all_outcomes),
            "previous_tail_evidence_count": sum(
                item.previous_tail_evidence is not None for item in all_outcomes
            ),
            "helper_invocation_count": retry_runtime_stats["helper_invocations"],
            "helper_cache_hit_count": retry_runtime_stats["cache_hits"],
            "helper_cache_miss_count": retry_runtime_stats["cache_misses"],
            "helper_cache_entry_count": len(retry_helper_cache),
            "helper_timeout_count": retry_runtime_stats["timeouts"],
            "helper_timeout_seconds": retry_timeout_seconds,
            "processed_semantic_request_count": len(processed_retry_semantics),
            "semantic_fixed_point": bool(retry_passes and retry_passes[-1].get("semantic_fixed_point")),
            "recursive_planning": True,
            "max_passes": max_retry_passes,
            "passes": retry_passes,
        },
        "joint_boundary_retry": {
            "capability_revision": capability.capability_revision if capability else None,
            "requests": [_retry_diagnostic_payload(item) for item in joint_boundary_requests],
            "outcomes": [_retry_diagnostic_payload(item) for item in joint_boundary_outcomes],
            "request_count": len(joint_boundary_requests),
            "outcome_count": len(joint_boundary_outcomes),
            "previous_tail_evidence_count": sum(
                item.previous_tail_evidence is not None
                for item in joint_boundary_outcomes
            ),
            "strong_observation_count": sum(
                1
                for item in joint_boundary_outcomes
                if (
                    item.status == "candidate"
                    and item.candidate is not None
                    and item.candidate.source == "ctc-joint-boundary-observation"
                )
            ),
            "new_consensus_candidate_count": joint_boundary_added,
            "previous_tail_evidence_change_count": (
                joint_tail_evidence_changes
                if joint_boundary_requests
                else 0
            ),
            "central_commit_only": True,
            "observation_selectable_directly": False,
        },
        "local_whisper_evidence": {
            "available": local_whisper_capability is not None,
            "capability_revision": (
                local_whisper_capability.capability_revision
                if local_whisper_capability is not None else None
            ),
            "protocol_revision": (
                local_whisper_capability.protocol_revision
                if local_whisper_capability is not None else None
            ),
            "request_count": len(local_whisper_requests),
            "outcome_count": len(local_whisper_outcomes),
            "trusted_observation_count": sum(
                item.status == "evidence" for item in local_whisper_outcomes
            ),
            "invalid_count": sum(
                item.status == "invalid" for item in local_whisper_outcomes
            ),
            "error_count": sum(
                item.status == "error" for item in local_whisper_outcomes
            ),
            "new_consensus_candidate_count": local_whisper_added,
            "cache_hit_count": local_whisper_stats["cache_hits"],
            "cache_miss_count": local_whisper_stats["cache_misses"],
            "helper_invocation_count": local_whisper_stats["helper_invocations"],
            "entries": [
                {
                    "entry": item.entry_index + 1,
                    "status": item.status,
                    "reason": item.reason,
                    "onset_time": (
                        round(item.onset_time, 6) if item.onset_time is not None else None
                    ),
                    "score": (round(item.score, 6) if item.score is not None else None),
                    "evidence_revision": item.evidence_revision,
                    "occurrence_binding_mode": (
                        item.occurrence_binding.get("mode")
                        if isinstance(item.occurrence_binding, dict) else None
                    ),
                }
                for item in local_whisper_outcomes
            ],
            "central_commit_only": True,
            "observation_selectable_directly": False,
            "whispercpp_and_whisperx_count_as_one_lineage": True,
            "global_raw_and_local_whisper_count_as_one_family": True,
        },
        "hypothesis_arbitration": {
            "mode": "context-conditioned-falsification",
            "falsification_count": sum(
                len(item.get("falsified_candidate_ids", []))
                for item in hypothesis_falsifications
            ),
            "entry_count": len(hypothesis_falsifications),
            "entries": list(hypothesis_falsifications),
            "majority_vote_allowed": False,
            "central_commit_only": True,
        },
    }
    return candidate_sets, diagnostics


